C ===== axprnt.f =====
      SUBROUTINE AXPRNT(A,AIN,CDFI,CDFO,CDO,CDF,XW,NN,NM,XL,SC,XBN)
C
C     PRINT AUXILIARY PANEL OUTPUTS
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      DIMENSION A(195),AIN(154),WTYPE(4),FOR(38),DATA(9),
     1          P(1),Q(1),R(1),S(1),T(1),ICAR(9)
      LOGICAL NN,NM
	CHARACTER*4 FOR
      DATA WTYPE / 4HSTRA, 4HDOUB, 4HCRAN, 4HCURV /
      DATA FOR /
     1 4H(1H+, 4H,19X, 4H,1X,, 4HE11., 4H4,1X, 4H,1X , 4H,1X,, 4HF6. ,
     2 4H3,1X, 4H,1X , 4H,1X,, 4HE11., 4H4,1X, 4H,1X , 4H,1X,, 4HF7. ,
     3 4H3,1X, 4H,1X , 4H,1X,, 4HE10., 4H3,1X, 4H,1X , 4H,1X,, 4HE10.,
     4 4H3,1X, 4H,1X , 4H,1X,, 4HE10., 4H3,1X, 4H,1X , 4H,1X,, 4HE10.,
     5 4H3,1X, 4H,1X , 4H,1X,, 4HE10., 4H3   , 4H)   /
      DATA ICAR / 13,8,13,9,5*12 /
C
C     INBOARD THEORITICAL
C
      SOT=0.
      IF(AIN(15) .EQ. WTYPE(1)) GO TO 1000
      DATA(1)=(AIN(6)+AIN(5))*(AIN(4)-AIN(2))
      SOT=DATA(1)
      DATA(1)=DATA(1)*XL*XL/(SC*SC)
      DATA(2)=AIN(5)/AIN(6)
      DATA(3)=(2.*(AIN(4)-AIN(2)))**2/DATA(1)
      DATA(4)=A(64)
      DATA(5)=2.*AIN(6)*(1.+DATA(2)*(1.+DATA(2)))/(3.*(1.+DATA(2)))
      DATA(7)=(AIN(4)-AIN(2))*(1.+2.*DATA(2))/(3.*(1.+DATA(2)))
      DATA(6)=A(62)*DATA(7)+XW+0.25*DATA(5)+XBN
      DATA(5)=DATA(5)*XL/SC
      DATA(6)=DATA(6)*XL/SC
      DATA(7)=DATA(7)*XL/SC
      DATA(8)=-UNUSED
      DATA(9)=-UNUSED
      WRITE(6,1010)
      CALL SWRITE(9,FOR,38,ICAR,1,DATA(1),DATA(2),DATA(3),DATA(4),
     1 DATA(5),DATA(6),DATA(7),DATA(8),DATA(9),P,Q,R,S,T,NN,NM)
C
C     INBOARD EXPOSED
C
      DATA(1)=A(1)
      DATA(1)=DATA(1)*XL*XL/(SC*SC)
      DATA(2)=A(26)
      DATA(3)=A(5)
      DATA(4)=A(64)
      DATA(5)=A(15)
      DATA(7)=A(32)+AIN(4)-AIN(3)
      DATA(6)=A(62)*DATA(7)+XW+0.25*DATA(5)+XBN
      DATA(5)=DATA(5)*XL/SC
      DATA(6)=DATA(6)*XL/SC
      DATA(7)=DATA(7)*XL/SC
      DATA(8)=-UNUSED
      DATA(9)=CDFI
      IF(CDFI .EQ. UNUSED) DATA(9)=2.*UNUSED
      WRITE(6,1020)
      CALL SWRITE(9,FOR,38,ICAR,1,DATA(1),DATA(2),DATA(3),DATA(4),
     1 DATA(5),DATA(6),DATA(7),DATA(8),DATA(9),P,Q,R,S,T,NN,NM)
C
C     OUTBOARD PANEL
C
      DATA(1)=A(2)
      DATA(1)=DATA(1)*XL*XL/(SC*SC)
      DATA(2)=A(28)
      DATA(3)=A(6)
      DATA(4)=A(88)
      DATA(5)=A(17)
      DATA(7)=A(33)
      DATA(6)=A(86)*DATA(7)+XW+0.25*DATA(5)+XBN
      DATA(5)=DATA(5)*XL/SC
      DATA(6)=DATA(6)*XL/SC
      DATA(7)=DATA(7)*XL/SC
      DATA(8)=-UNUSED
      DATA(9)=CDFO
      IF(CDFO .EQ. UNUSED) DATA(9)=2.*UNUSED
      WRITE(6,1030)
      CALL SWRITE(9,FOR,38,ICAR,1,DATA(1),DATA(2),DATA(3),DATA(4),
     1 DATA(5),DATA(6),DATA(7),DATA(8),DATA(9),P,Q,R,S,T,NN,NM)
 1000 CONTINUE
C
C     TOTAL THEORITICAL
C
      DATA(1)=A(4)
      DATA(1)=DATA(1)*XL*XL/(SC*SC)
      DATA(2)=A(118)
      DATA(3)=A(120)
      DATA(4)=ARCCOS((SOT*COS(A(64)/RAD)+A(2)*COS(A(88)/RAD))/A(4))*RAD
      IF(AIN(15) .EQ. WTYPE(1)) DATA(4)=A(40)
      DATA(5)=A(122)
      DATA(6)=A(161)+XW+XBN
      DATA(7)=A(136)
      DATA(5)=DATA(5)*XL/SC
      DATA(6)=DATA(6)*XL/SC
      DATA(7)=DATA(7)*XL/SC
      DATA(8)=-UNUSED
      DATA(9)=-UNUSED
      WRITE(6,1040)
      CALL SWRITE(9,FOR,38,ICAR,1,DATA(1),DATA(2),DATA(3),DATA(4),
     1 DATA(5),DATA(6),DATA(7),DATA(8),DATA(9),P,Q,R,S,T,NN,NM)
C
C     TOTAL EXPOSED
C
      DATA(1)=A(3)
      DATA(1)=DATA(1)*XL*XL/(SC*SC)
      DATA(2)=A(27)
      DATA(3)=A(7)
      DATA(4)=A(40)
      DATA(5)=A(16)
      DATA(6)=A(30)+XW+(A(21)-A(23))*TAN(A(35))-0.25*DATA(5)+XBN
      DATA(7)=A(31)+AIN(4)-AIN(3)
      DATA(5)=DATA(5)*XL/SC
      DATA(6)=DATA(6)*XL/SC
      DATA(7)=DATA(7)*XL/SC
      DATA(8)=CDO
      DATA(9)=CDF
      IF(CDO .EQ. UNUSED) DATA(8)=2.*UNUSED
      IF(CDF .EQ. UNUSED) DATA(9)=2.*UNUSED
      WRITE(6,1050)
      CALL SWRITE(9,FOR,38,ICAR,1,DATA(1),DATA(2),DATA(3),DATA(4),
     1 DATA(5),DATA(6),DATA(7),DATA(8),DATA(9),P,Q,R,S,T,NN,NM)
 1010 FORMAT(20H THEORITICAL INBOARD)
 1020 FORMAT(20H     EXPOSED INBOARD)
 1030 FORMAT(20H            OUTBOARD)
 1040 FORMAT(20H   TOTAL THEORITICAL)
 1050 FORMAT(20H       TOTAL EXPOSED)
      RETURN
      END
C ===== bdarea.f =====
      SUBROUTINE BDAREA(ABORT)
C
C***  EXECUTIVE FOR BODY PARTS SHADOWED BY MACH LINES
C
      LOGICAL ABORT
      DIMENSION A(3),X(4),Y(4),XL(42),YL(42),XLI(42),YLI(42),XT(42),
     1YT(42),XTI(42),YTI(42)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG
      COMMON /FLGTCD/ FLC(73)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /HTI/    HTIN(154)
      COMMON /HTDATA/ AHT(195)
      COMMON /BODYI/  XNX,XB(20),SB(20),PB(20),RB(20)
      COMMON /SYNTSS/ SYNA(10)
C
      NX=XNX
      ILI=0
      ILIE=0
      ITI=0
      ITIE=0
      SAXB=0
      SAYB=0
      AREA=0.
      AREAB=0.
 1000 AMUU=ATAN(1./SQRT(FLC(I+2)**2-1.))
      DO 1050 K=1,2
         IF(K.NE.1) GO TO 1020
 1010    A(1)=SYNA(6)+(HTIN(4)-HTIN(3))*AHT(62)*COS(SYNA(8)/RAD)
         A(2)=SYNA(7)-(A(1)-SYNA(6))*SIN(SYNA(8)/RAD)/COS(SYNA(8)/RAD)
         A(3)=SYNA(8)
         GO TO 1030
 1020    A(1)=A(1)+AHT(10)*COS(SYNA(8)/RAD)
         A(2)=A(2)-AHT(10)*SIN(SYNA(8)/RAD)
         GO TO 1040
 1030    CALL PTINT2(XB,RB,A,AMUU,XL,YL,XLI,YLI,NX,ILUI,ILLI,ILUIE,
     1               ILLIE,ABORT)
         IF(ABORT) RETURN
         GO TO 1050
 1040    CALL PTINT2(XB,RB,A,AMUU,XT,YT,XTI,YTI,NX,ITUI,ITLI,ITUIE,
     1              ITLIE,ABORT)
         IF(ABORT) RETURN
 1050 CONTINUE
      DO 1210 K=1,2
         SAXB=0.
         SAYB=0.
         AREA=0.
         AREAB=0.
C
C     CHECK FOR UPPER OR LOWER AREA
C
         IF(K.NE.1) GO TO 1060
         ILI=ILUI
         ILIE=ILUIE
         ITI=ITUI
         ITIE=ITUIE
         GO TO 1070
 1060    ILI=ILLI
         ILIE=ILLIE
         ITI=ITLI
         ITIE=ITLIE
         NX=NX+21
 1070    IF(ITIE.NE.0) GO TO 1080
C
C**** NEITHER MACH LINE INTERSECTS BODY PROFILE EXTENSION ****
C
         KIND=1
         GO TO 1100
 1080    IF(ILIE.NE.0) GO TO 1090
C
C**** ONLY THE TRAILING EDGE MACH LINE INTERSECTS BODY PROFILE EXTENSION
C
         KIND=2
         GO TO 1100
C
C**** BOTH MACH LINES INTERSECT BODY PROFILE EXTENSION ****
C
 1090    KIND=3
 1100    GO TO (1110,1150,1180) KIND
 1110    IF(ILI.NE.ITI) GO TO 1120
         X(1)=0.
         X(2)=XLI(ILI)
         X(3)=XTI(ITI)+AHT(10)
         X(4)=AHT(10)
         Y(1)=0.
         Y(2)=YLI(ILI)
         Y(3)=YTI(ITI)
         Y(4)=0.
         CALL AREA2(X,Y,SAREA,2,AX,AY)
         AREA=SAREA
         AREAB=AREA
         SAXB=AX
         SAYB=AY
         GO TO 1190
 1120    II=1
         X(1)=0.
         X(2)=XLI(ILI)
         X(3)=XL(ILI+II)
         X(4)=AHT(10)
         Y(1)=0.
         Y(2)=YLI(ILI)
         Y(3)=YL(ILI+II)
         Y(4)=0.
         CALL AREA2(X,Y,SAREA,2,AX,AY)
         AREA=AREA+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
 1130    II=II+1
         IF(XL(ILI+II).GT.(XTI(ITI)+AHT(10))) GO TO 1140
         X(1)=XL(ILI+II-1)
         X(2)=XL(ILI+II)
         X(3)=AHT(10)
         Y(1)=YL(ILI+II-1)
         Y(2)=YL(ILI+II)
         Y(3)=0.
         CALL AREA2(X,Y,SAREA,3,AX,AY)
         AREA=AREA+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
         GO TO 1130
 1140    X(1)=XL(ILI+II-1)
         X(2)=XTI(ITI)+AHT(10)
         X(3)=AHT(10)
         Y(1)=YL(ILI+II-1)
         Y(2)=YTI(ITI)
         Y(3)=0.
         CALL AREA2(X,Y,SAREA,3,AX,AY)
         AREA=AREA+SAREA
         AREAB=AREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
         GO TO 1190
 1150    II=1
         X(1)=0.
         X(2)=XLI(ILI)
         X(3)=XL(ILI+II)
         X(4)=AHT(10)
         Y(1)=0.
         Y(2)=YLI(ILI)
         Y(3)=YL(ILI+II)
         Y(4)=0.
         CALL AREA2(X,Y,SAREA,2,AX,AY)
         AREA=AREA+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
 1160    IF((ILI+II).EQ.NX) GO TO 1170
         X(1)=XL(ILI+II)
         X(2)=XL(ILI+II+1)
         X(3)=AHT(10)
         Y(1)=YL(ILI+II)
         Y(2)=YL(ILI+II+1)
         Y(3)=0.
         CALL AREA2(X,Y,SAREA,3,AX,AY)
         AREA=AREA+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
         II=II+1
         GO TO 1160
 1170    X(1)=XL(ILI+II)
         X(2)=XTI(ITIE)+AHT(10)
         X(3)=AHT(10)
         Y(1)=YL(ILI+II)
         Y(2)=YTI(ITIE)
         Y(3)=0.
         CALL AREA2(X,Y,SAREA,3,AX,AY)
         AREA=AREA+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
         X(3)=XTI(ITI)+AHT(10)
         Y(3)=YTI(ITI)
         CALL AREA2(X,Y,EXTARE,3,AX,AY)
         AREAB=AREA-EXTARE
         SAXB=SAXB-AX
         SAYB=SAYB-AY
         GO TO 1190
 1180    X(1)=0.
         X(2)=XLI(ILIE)
         X(3)=XTI(ITIE)+AHT(10)
         Y(1)=0.
         Y(2)=YLI(ILIE)
         Y(3)=YTI(ITIE)
         X(4)=AHT(10)
         Y(4)=0.
         CALL AREA2(X,Y,SAREA,2,AX,AY)
         AREA=AREA+SAREA
         X(2)=XLI(ILI)
         X(3)=XTI(ITI)+AHT(10)
         Y(2)=YLI(ILI)
         Y(3)=YTI(ITI)
         CALL AREA2(X,Y,SAREA,2,AX,AY)
         AREAB=AREAB+SAREA
         SAXB=SAXB+AX
         SAYB=SAYB+AY
 1190    IF(K.EQ.2) GO TO 1200
         AREAU=AREA
         AREAUB=AREAB
         SAXUB=SAXB
         SAYUB=SAYB
         GO TO 1210
 1200    AREAL=AREA
         AREALB=AREAB
         SAXLB=SAXB
         SAYLB=SAYB
 1210 CONTINUE
      HTIN(114+I)=AREAUB+AREALB
      HTIN(134+I)=AREAU+AREAL
      AXTB=SAXUB+SAXLB
      AYTB=SAYUB+SAYLB
      XCB=AXTB/HTIN(114+I)
      YCB=AYTB/HTIN(114+I)
      XBARB=XCB*COS(-SYNA(8)/RAD)-YCB*SIN(-SYNA(8)/RAD)+SYNA(6)
     1      +(HTIN(4)-HTIN(3))*AHT(62)*COS(SYNA(8)/RAD)
      HTIN(94+I)=XBARB-SYNA(1)
      RETURN
      END
