      COMMON /VTDATA/ LFIGN(121),LFIGO(121),IOVLY,IOVL,NSTQ,NSTP,FINALR,
     1                NFIG,IFIGN
      COMMON /WHAERO/ LFIGS(121), IFIGST(20), IEXCD(4), MSSCL(2),
     1                ROUT(2), XLL(4), XUL(4), IEXTRL(4,2),
     2                IEXTRU(4,2), XVAL(4), LDUM(121)
      DIMENSION IFIG(20,121)
      DATA IHBL/4H    /
      DO 1000 I=1,121
      AFIG01(I)=0.
      AFIG02(I)=0.
      AFIG03(I)=0.
      AFIG04(I)=0.
      AFIG05(I)=0.
      AFIG06(I)=0.
      AFIG07(I)=0.
      AFIG08(I)=0.
      AFIG09(I)=0.
      AFIG10(I)=0.
      AFIG11(I)=0.
      AFIG12(I)=0.
      AFIG13(I)=0.
      AFIG14(I)=0.
      JFIG01(I)=0
      JFIG02(I)=0
      JFIG03(I)=0
      JFIG04(I)=0
      JFIG05(I)=0
      JFIG06(I)=0
      JFIG07(I)=0
      JFIG08(I)=0
      JFIG09(I)=0
      JFIG10(I)=0
      JFIG11(I)=0
      JFIG12(I)=0
      JFIG13(I)=0
      JFIG14(I)=0
      JFIG15(I)=0
      JFIG16(I)=0
      JFIG17(I)=0
      JFIG18(I)=0
      JFIG19(I)=0
      JFIG20(I)=0
      LFIGN(I)=0
      LFIGO(I)=0
      LFIGS(I)=0
      LDUM(121)=0
 1000 CONTINUE
      DO 1010 I=1,4
         IEXCD(I)=0
         XLL(I)=0.
         XUL(I)=0.
         IEXTRL(I,1)=0
         IEXTRU(I,1)=0
         IEXTRL(I,2)=0
         IEXTRU(I,2)=0
         XVAL(I)=0.
 1010 CONTINUE
      DO 1020 I=1,2
         ROUT(I)=IHBL
         MSSCL(I)=IHBL
 1020 CONTINUE
      DO 1030 I=1,20
         IFIGST(I)=IHBL
 1030 CONTINUE
      IOVLY=999
      IOVL=0
      NSTQ=0
      NSTP=0
      FINALR=0.
      NFIG=0
      IFIGN=0
      ROUTL=IHBL
      MSSCLL=IHBL
      DO 1040 I=1,121
         DO 1040 J=1,20
            IFIG(J,I)=IHBL
 1040 CONTINUE
      RETURN
      END
C ===== clmch0.f =====
      SUBROUTINE CLMCH0(A,B,CLALPA,CLMAX,CLMAXL,CLAMO,WING,ITTY)
C
C***  COMPUTES LIFTING SURFACE CL AT MACH=0
C
      COMMON /OVERLY/ NLOG,NMACH,M,NALPHA,IG
      COMMON /FLGTCD/ FLC(93)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1      HEAD,PRPOWR,JEQPOW,LOASRT,TVTPAN,SUPERS,SUBSON,TRANSN,HYPERS
      LOGICAL       FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1      HEAD,PRPOWR,JEQPOW,LOASRT,TVTPAN,SUPERS,SUBSON,TRANSN,HYPERS
      DIMENSION A(1),B(1),CLALPA(1),CLMAX(1),WING(1)
C
C     ----COMPUTE CLW S FOR MACH=0.
C
      B(1)=0.
      A(131)=CLALPA(1)
      IF(TRANSN)A(131)=CLAMO
      A(132)=CLMAXL
      B(2)=1.0
      WSAVE=CLMAX(1)
      CLMAX(1)=CLMAXL
      DO 1000 K=1,20
         WING(K)=0.0
 1000 CONTINUE
      M=1
      IF(ITTY .EQ. 0) CALL M15O17
      IF(ITTY .NE. 0) CALL M16O20
C
C     ----STORE ALL CLWS FOR MACH=0.
C
      B(48)=WING(101)
      NALPHA=FLC(2)+.5
      DO 1010 J=1,NALPHA
         B(J+2)=WING(J+20)
 1010 CONTINUE
      A(127)=B(43)
      A(126)=B(49)
      CLMAX(1)=WSAVE
      RETURN
      END
