     3-.16,.05,.35,.43,.452,.454,.438,.4,.325,.215,.038,-.056,-.115,
     4-.150 , .13,.062,-.003,-.064,-.118,-.14,-.16,-.178,-.19,-.193,
     5-.186,-.175,.04,.2,.27,.312,.328,.322,.275,.17,0.,-.2,-.303,-.376,
     6-.430 ,.07,.058,.04,.012,-.018,-.035,-.052,-.067,-.08,-.088,-.089,
     7-.067,-.014,.045,.095,.124,.132,.116,.073,0.,-.093,-.18,-.21,-.23,
     8-.25 , .13,.08,.06,.045,.03,.0275,.025,.0225,.02,.0175,.015,.0125,
     9.01,.0075,.005,.0025,.0,-.01,-.02,-.03,-.04,-.05,-.06,-.07,-.08,
     A25*0.0/
C
C---------FIGURE 4.1.4.3-23B
C--------- X112B2= TAN(ALPHA(CLMAX))/TAN(ALPHA)  X212B2= STABILITY INDEX
C--------- Y12B2= DEL(XCP/CR)(3)
C
      DATA X112B2 /.60,.80,1./
      DATA X212B2/ 4.0,3.5,3.0,2.75,2.50,2.25,2.0,1.5,1.0,.50,.25,0.0,
     1-.25,-.50,-1.0,-1.5,-2.0,-2.5,-3.0,-3.5,-4.0/
      DATA Y12B2 /-.12,-.2,-.27,-.285,-.29,-.287,-.268,-.178,-.072,0.,
     1.025,.04,.048,.05,.037,.011,-.01,-.02,-.03,-.039,-.04,-.085,-.11,
     2-.13,2*-.135,-.13,-.12,-.09,-.052,-.01,.017,.04,.058,.068,.065,
     3.05,.03,.02,.029,.03,.02, 21*0./
C
C---------     FIGURE 4.1.4.3-24A
C----     X213A= TAPER RATIO       X113A= A COS(L.E.S.A)
C----     Y13A=  ASPECT RATIO INDEX
C
      DATA X213A /0.,.1,.15,.2,.25,.3,.4,.45,.5,.55,.6,.7,.8,.9,1.0/
      DATA X113A/.25,.5,1.,1.5,2.,3.,4.,5.,6./
      DATA Y13A /0.,.17,.235,.28,.297,.282,.242,.215,.21,.227,.262,.378,
     1.56,.80,1.04 , .14,.24,.276,.3,.31,.298,.242,.215,.193,.193,.218,
     2.287,.383,.50,.63 , .14,.24,.264,.28,.29,.277,.197,.132,.082,.045,
     3.03,.02,.03,.063,.10 , 0.1,.2,.228,.24,.228,.2,.097,.022,-.05,
     4-.095,-.12,-.13,-.128,-.125,-.12 , 0.0,.14,.155,.154,.138,.105,
     50.0,-.085,-.162,-.195,-.214,-.235,-.240,-.240,-.230 , -.10,-.022,
     6-.002,0.0,-.02,-.058,-.195,-.257,-.30,-.336,-.362,-.388,2*-.40,
     7-.39 , -.24,-.20,-.19,-.198,-.223,-.26,-.355,-.392,-.418,-.442,
     8-.46,-.487,-.50,-.507,-.51 , -.38,-.37,-.382,-.397,-.417,-.436,
     9-.483,-.505,-.526,-.54,-.552,-.57,-.58,-.582,-.58 , -.50,-.513,
     A-.522,-.53,-.54,-.55,-.568,-.577,-.585,-.59,-.60,-.612,-.62,-.625,
     B-.63 /
C
C---------     FIGURE 4.1.4.3-24B-1          ---------------------------
C----     X213B1= ASPECT RATIO INDEX    X113B1= TAN(ALPHA)/TAN(ALPHA)CL-
C----     Y13B1=  DEL(XCP/CR(4))
C
      DATA X213B1 /1.0,.8,.6,.4,.2,0.,-.2,-.4,-.6/
      DATA X113B1 /.2,.3,.4,.6,.8,1./
      DATA Y13B1 / 1.,.8,.6,.4,.2,0.,-.2,-.4,-.6 , .64,.482,.35,.23,.12,
     10.0,-.16,-.36,-.59 , .38,.26,.15,.07,.02,0.,-.1,-.23,-.42 , .12,
     2.048,0.0,-.032,-.035,-.030,-.12,-.31,-.56 , .05,-.02,-.05,-.06,
     3-.058,-.050,-.068,-.110,-.170, 9*0./
C
C---------     FIGURE 4.1.4.3-24B-2          ---------------------------
C----     X213B2= ASPECT RATIO INDEX    X113B2= TAN(ALPHA)CL-MAX/TAN(ALP
C----     Y13B2=  DEL(XCP/CR(4))
C
      DATA X213B2 /1.0,.8,.6,.4,.2,0.,-.2,-.4,-.6/
      DATA X113B2 /.6,.8,1./
      DATA Y13B2 / .3,.29,.29,.28,.26,.20,.23,.25,.28,  5*.14,.10,.11,
     1.13,.14,  9*0./
C
C
C*********     PAGE NO. 2-1
C
      C(1) = WINGIN(61)
      C(2)=WINGIN(67)
      A(170)=A(173)/A(10)
      C(48)=A(10)/CBARR
      CONST=.FALSE.
C
C-----IF WING IS CONSTANT SECTION,SET CONST EQUAL TO TRUE
C
      IF( ABS(C(1)).LT.1.E-10.OR.ABS(C(2)).LT.1.E-10) CONST=.TRUE.
      IF(.NOT.CONST) C(1)= 0.50*(C(1)+C(2))
      IF(.NOT.CONST) ATOVCA=0.50*(WINGIN(16)+WINGIN(65))
      IF(.NOT.CONST) GO TO 1000
      ATOVCA=WINGIN(16)
 1000 CONTINUE
      CALL TBFUNX(B(1), CALM, DYDX, 15, XCMOM, YCMOM, CCMOM,ICMOM,
     1            MI, NG, 0, 0, QCMOM, 3, ROUTID)
      CALM = A(3)*A(16)*CALM/(SREF*CBARR)
      C(5)=(A(7)*A(43)**2/(A(7)+2.0*A(43)))*C(1)*CALM
C
C     DETERMINE IF WING IS TWISTED
C
      IF(ABS(WINGIN(11)).LT.1.E-20) GO TO 1010
C
C     CALL TABLE LOOK-UP FOR CMO/THETA FROM MODIFIED FIG 4.1.4.1-5
C
      CALL TLIN3X(X11412,X21412,X31412,Y41412,5,22,3,A(7),A(40),
     1            A(27),C(4),2,2,0,2,2,0,Q41412,3,ROUTID)
C
C     COMPUTE CMOTH (FOR TWISTED WING)
C
      C(5)=C(5)+C(4)*WINGIN(11)*CALM
 1010 CONTINUE
      C(3)=CALM
      B(47)=C(5)
C
C*********     TEST FOR WING TYPE
C
      C(9)=A(7)*A(38)
      TYPE=WINGIN(15)
      IF(WINGIN(15).NE.WTYPE(1)) GO TO 1030
C
C*********     PAGE NUMBER 2-2                    **********************
C+++++++++     STRAIGHT TAPERED OR CONVENTIONAL   ++++++++++++++++++++++
C
      IF(A(38) .EQ. 0.) A(38)=0.0001
      C(10)=A(38)/B(2)
      C(11)=B(2)/A(38)
      IF(A(7) .GT. A(125)) GO TO 1025
C
C ***** IF WING HAS FORWARD SWEEP, GO TO SUBROUTINE FWDXAC
C
      IF (A(38) .LT. 0.0) GO TO 1075
C
C--------- IF C(10).GE.1.0 USE FIG. 4.1.4.2-26B
C
      IF(C(10).GE.1.0) GO TO 1020
C
C---------     FIGURE 4.1.4.2-26A       --------------------------------
C
      CALL TLIN3X(X122A,X222A,X322A,Y22A,6,6,6,C(9),C(10),A(27),C(6),
     1            2,0,0,2,0,0,Q4222A,3,ROUTID)
      GO TO 1080
C
C---------     FIGURE 4.1.4.2-26B       --------------------------------
C
 1020 CALL TLIN3X(X122B,X222B,X322B,Y22B,6,6,6,C(9),C(11),A(27),C(6),
     1            2,0,0,2,0,0,Q4222B,3,ROUTID)
      GO TO 1080
C
C***  COMPUTE XAC/CR AT QUARTER CHORD OF MAC OR
C***  USE INPUT SECTION AC ON MAC
C
 1025 CONTINUE
      C(6)=(A(30)-0.25*A(16))/A(10)
      IF(WINGIN(I+71) .NE. UNUSED) C(6)=C(6)+A(16)*
     1                                  (WINGIN(I+71)-0.25)/A(10)
      GO TO 1080
C
C*********     PAGE NUMBER 2-3                    **********************
C+++++++++     DOUBLE-DELTA,CRANKED,OR CURVED     ++++++++++++++++++++++
C
 1030 CONTINUE
      IF(A(62).EQ.0.0) A(62)=1.0E-15
      C(12)=A(5)*A(62)
      C(13)=A(62)/B(2)
      C(14)=1.0/C(13)
      C(15)= A(168)*A(86)
      C(16)=A(86)/B(2)
      C(17)= 1.0/C(16)
C
C ***** IF INBOARD PANEL HAS FORWARD SWEEP, GO TO SUBROUTINE FWDXAC
C
      IF (A(62) .LT. 0.0) GO TO 1045
C
C*     IF C(13).GE.1.0, USE FIGURE 4.1.4.2-26B (INBOARD DATA)
C
      IF(C(13).GE.1.0) GO TO 1040
C
C---------     FIGURE 4.1.4.2-26A       --------------------------------
C
      CALL TLIN3X(X122A,X222A,X322A,Y22A,6,6,6,C(12),C(13),A(26),C(18),
     1            2,0,0,2,0,0,Q4222A,3,ROUTID)
      GO TO 1050
C
C---------     FIGURE 4.1.4.2-26B       --------------------------------
C
 1040 CALL TLIN3X(X122B,X222B,X322B,Y22B,6,6,6,C(12),C(14),A(26),C(18),
     1            2,0,0,2,0,0,Q4222B,3,ROUTID)
      GO TO 1050
 1045 CALL FWDXAC (C(12),A(26),C(13),B(1),ROUTID,C(18))
C
C ***** IF OUTBOARD PANEL HAS FORWARD SWEEP, GO TO SUBROUTINE FWDXAC
C
      IF (A(86) .LT. 0.0) GO TO 1065
C
C**** IF C(16).GE.1.0 USE FIGURE 4.1.4.2-26B (OUTBOARD DATA)
C
 1050 IF(C(16).GE.1.0) GO TO 1060
C
C---------     FIGURE 4.1.4.2-26A
C
      CALL TLIN3X(X122A,X222A,X322A,Y22A,6,6,6,C(15),C(16),A(169),C(19),
     1            2,0,0,2,0,0,Q4222A,3,ROUTID)
      GO TO 1070
C
C---------     FIGURE 4.1.4.2-26B
C
 1060 CALL TLIN3X(X122B,X222B,X322B,Y22B,6,6,6,C(15),C(17),A(169),C(19),
     1            2,0,0,2,0,0,Q4222B,3,ROUTID)
      GO TO 1070
 1065 CALL FWDXAC (C(15),A(169),C(16),B(1),ROUTID,C(19))
 1070 C(20)= C(19)*A(166)/A(10)-A(164)*A(86)/A(10)+A(23)*A(62)/A(10)
      ANUM= A(171)*A(1)*C(18)+A(172)*A(167)*C(20)
      ADEN= A(171)*A(1)+A(172)*A(167)
      C(6)=ANUM/ADEN
      GO TO 1080
 1075 CALL FWDXAC (C(9),A(27),C(10),B(1),ROUTID,C(6))
C
C*********     COMPUTE DCM/DCL AND CMALPHA
C
 1080 C(7)= (A(170)-C(6))*(A(10)/CBARR)
      C(8)=C(7)*WING(101)
      WING(121)=C(8)
C
C*********     DETERMINE ASPECT RATIO             **********************
C
 1090 IF(A(7).GT.(6./A(124)))GO TO 1270
C
C*********     PAGE NO. 2-5 DATA
C
 1110 CONTINUE
      IF(A(34) .LT. 0.0)GO TO 1270
      C(21)=A(7)*(1.+A(27))*A(38)/4.0
      C(22)=(A(27)+C(21)+((1.+C(21)*A(27))/(1.+A(27))))/3.0
      IF(A(7) .GE. 6./A(124) .OR. WINGIN(15) .EQ. WTYPE(1))
     1  GO TO 1115
      YBSI=A(23)*(1.+2.*A(26))/(3.*(1.+A(26)))
      XBLE=(YBSI*A(1)*A(62)+(A(23)*A(62)+(A(133)-A(21))*A(86))*A(2))
     1      /A(3)
      C(22)=(XBLE+A(16)/2.0)/A(10)
 1115 CONTINUE
C
C---------     FIGURE 4.1.4.3-21B
C
      CALL TBFUNX(A(27),C(23),DYDX,7,X211B,Y11B,CC11B,IN11B,MI,NG,
     1            0,0,Q4311B,3,ROUTID)
      C(24)=(C(23)+1.0)*C(9)
C
C---------     FIGURE 4.1.4.3-22A
C
      CALL TLINEX(X111C,X211C,Y11C,4,15,A(7),C(24),C(25),
     1            2,0,2,1,Q4311C,3,ROUTID)
C
C---------     FIGURE 4.1.4.3-21A
C
      CALL TBFUNX(WINGIN(17),C(26),DYDX,12,X211A,Y11A,CC11A,IN11A,MI,NG,
     1            2,2,Q4311A,3,ROUTID)
      C(27)=C(25)+C(26)
C
C*********     COMPUTE (XCP/CR)REF, C(30)
C
      C(28)=SIN(B(43)/RAD)
      C(29)=TAN(B(43)/RAD)
      C(30)=C(27)/C(28)-C(6)/C(29)
      DO 1260 M=1,NALPHA
         C(31)=SIN(B(M+22)/RAD)
         C(32)=COS(B(M+22)/RAD)
         C(33)=C(31)/C(32)
         C(34)=A(7)*A(37)
         C(35)=ABS(C(33)/C(29))
         TANRAT = .FALSE.
C
C     ----TEST FOR TAN(ALPHA) .GT. TAN(ALPHA CLMAX)
C
         IF(C(33).GT.C(29)) TANRAT = .TRUE.
C
C***** TO COMPUTE (ALPHA) REF AND RELATED DATA ON FIRST PASS ONLY
C
         IF(M.GT.1) GO TO 1150
         C(36)=ATAN(TAN(B(43)/RAD)/0.6)
         TEMP2=C(29)/TAN(C(36))
         C(47)= TEMP2
C
C---------     FIGURE 4.1.4.3-22B
C
         CALL TLINEX(X112A,X212A,Y12A,11,6,C(9),A(27),C(40),
     1               1,0,1,0,Q4312A,3,ROUTID)
C
C---------     FIGURE 4.1.4.3-24A
C
         CALL TLINEX(X113A,X213A,Y13A,9,15,C(34),A(27),C(37),
     1               0,0,2,0,Q4313A,3,ROUTID)
C
C---------     FIGURE 4.1.4.3-24B2
C
 1120    CALL TLINEX(X113B2,X213B2,Y13B2,3,9,TEMP2,C(37),C(51),
     1               2,0,2,0,Q313B2,4,ROUTID)
C
C---------     FIGURE 4.1.4.3-23B
C
 1130    CALL TLINEX(X112B2,X212B2,Y12B2,3,21,TEMP2,C(40),C(50),
     1               2,0,2,0,Q312B2,4,ROUTID)
 1140    C(49)=C(6)*COS(C(36))+SIN(C(36))*(C(30)+C(51)+C(50))
C
C*********     IF ALPHA .GE. ALPHA(REF) GO TO PAGE 2-7
C
 1150    IF( B(M+22)/RAD.GT.C(36) ) GO TO 1220
C
C*********     PAGE NO. 2-6                       **********************
C
      IF(TANRAT) GO TO 1170
C
C---------     FIGURE 4.1.4.3-24B-1
C
 1160    CALL TLINEX(X113B1,X213B1,Y13B1,6,9,C(35),C(37),C(38),
     1               2,0,2,0,Q313B1,4,ROUTID)
         GO TO 1180
C
C---------     FIGURE 4.1.4.3-24B-2          ---------------------------
C
 1170    C(46) = C(29)/C(33)
         CALL TLINEX(X113B2,X213B2,Y13B2,3,9,C(46),C(37),C(38),
     1               2,0,2,0,Q313B2,4,ROUTID)
 1180    IF(TANRAT) GO TO 1200
C
C---------     FIGURE 4.1.4.3-23A
C
 1190    CALL TLINEX(X112B1,X212B1,Y12B1,6,25,C(35),C(40),C(39),
     1               2,0,2,0,Q312B1,4,ROUTID)
         GO TO 1210
C
C---------     FIGURE 4.1.4.3-23B            ---------------------------
C
 1200    CALL TLINEX(X112B2,X212B2,Y12B2,3,21,C(46),C(40),C(39),
     1               2,0,2,0,Q312B2,4,ROUTID)
C
C---------     COMPUTE C(44) AND C(45) FOR PAGE 2-6    -----------------
C
 1210    C(44)=C(6)*C(32)+(C(30)+C(39)+C(38))*C(31)
         WING(M+40)=WING(M+60)*(A(173)/A(10)-C(44))*C(48)+C(5)
         GO TO 1250
C
C*********     PAGE 2-7                      ***************************
C
 1220    C(41)=C(22)-C(49)
         C(42)=PI/2.-C(36)
         C(43)=C(41)/C(42)
C
C*********     COMPUTE CM(ALPHA)J
C
         C(44)=C(49)+C(43)*(B(M+22)/RAD-C(36))
 1230    WING(M+40)= WING(M+60)*(A(170)-C(44))*(A(10)/CBARR)+C(5)
 1250    CONTINUE
 1260 CONTINUE
C
      RETURN
C
 1270 DO 1280 N=1,NALPHA
 1280 WING(N+40)=WING(N+60)*C(7)+C(5)
C
      RETURN
      END
C ===== cmalpo.f =====
