      WRITE(IUNIT,1000)(NAME(I),I=1,8),(COMBLK(I),I=1,II)
C
      RETURN
C
 1000 FORMAT(1H0,8A1,8(13X,L1,1H,)/(9X,8(13X,L1,1H,)))
C
      END
C ===== forrea.f =====
      SUBROUTINE FORREA(IUNIT, NAME, COMBLK, II)
C
C***  FORCE A REAL PRINT ONTO UNIT IUNIT
