     1  .802E 01,  .998E 01,  .120E 02,  .140E 02,  .160E 02,  .180E 02,
     2  .200E 02/
      DATA Y3149F/  .100E 01,  .176E 01,  .199E 01,  .186E 01,
     1  .165E 01,  .144E 01,  .129E 01,  .127E 01,  .138E 01,  .150E 01,
     2  .156E 01,  .100E 01,  .154E 01,  .192E 01,  .199E 01,  .189E 01,
     3  .173E 01,  .158E 01,  .143E 01,  .133E 01,  .125E 01,  .123E 01/
C
      Q=MACH
      R=ALPH
      IF(ALT.LE.50000.)IT=1
      IF(ALT.GT.50000.AND.ALT.LE.100000.)IT=2
      IF(ALT.GT.100000.AND.ALT.LE.150000.)IT=3
      IF(ALT.GT.150000.AND.ALT.LE.200000.)IT=4
      IF(ALT.GT.200000.AND.ALT.LE.250000.)IT=5
      IF(ALT.GT.250000.AND.ALT.LE.300000.)IT=6
      IF(ALT.GT.300000.)IT=7
      DO 1060 K=1,2
         GO TO(1000,1010,1020,1030,1040,1050,1050),IT
 1000    CALL TLINEX(X13131,X23131,Y63131,2,11,Q,R,P(K),
     1               0,0,0,0,Q63131,3,ROUTID)
         CALL TLINEX(X1137A,X2137A,Y3137A,2,11,Q,R,T(K),
     1               0,0,0,0,Q3137A,3,ROUTID)
         CALL TLINEX(X1143A,X2143A,Y3143A,2,11,Q,R,M(K),
     1               0,0,0,0,Q3143A,3,ROUTID)
         CALL TLINEX(X1149A,X2149A,Y3149A,2,11,Q,R,S(K),
     1               0,0,0,0,Q3149A,3,ROUTID)
         GO TO 1060
C
C    ----HERE FOR ALT=100000
C
 1010    IF(IT.EQ.2.AND.K.EQ.1)GO TO 1000
         CALL TLINEX(X1131B,X2131B,Y3131B,3,11,Q,R,P(K),
     1               0,0,0,0,Q3131B,3,ROUTID)
         CALL TLINEX(X1137B,X2137B,Y3137B,2,11,Q,R,T(K),
     1               0,0,0,0,Q3137B,3,ROUTID)
         CALL TLINEX(X1143B,X2143B,Y3143B,3,11,Q,R,M(K),
     1               0,0,0,0,Q3143B,3,ROUTID)
         CALL TLINEX(X1149B,X2149B,Y3149B,3,11,Q,R,S(K),
     1               0,0,0,0,Q3149B,3,ROUTID)
         GO TO 1060
C
C    ----HERE FOR ALT=150000
C
 1020    IF(IT.EQ.3.AND.K.EQ.1)GO TO 1010
         CALL TLINEX(X1131C,X2131C,Y3131C,2,11,Q,R,P(K),
     1               0,0,0,0,Q3131C,3,ROUTID)
         CALL TLINEX(X1137C,X2137C,Y3137C,2,11,Q,R,T(K),
     1               0,0,0,0,Q3137C,3,ROUTID)
         CALL TLINEX(X1143C,X2143C,Y3143C,2,11,Q,R,M(K),
     1               0,0,0,0,Q3143C,3,ROUTID)
         CALL TLINEX(X1149C,X2149C,Y3149C,2,11,Q,R,S(K),
     1               0,0,0,0,Q3149C,3,ROUTID)
         GO TO 1060
C
C    ----HERE FOR ALT=200000
C
 1030    IF(IT.EQ.4.AND.K.EQ.1)GO TO 1020
         CALL TLINEX(X1131D,X2131D,Y3131D,3,11,Q,R,P(K),
     1               0,0,0,0,Q3131D,3,ROUTID)
         CALL TLINEX(X1137D,X2137D,Y3137D,3,11,Q,R,T(K),
     1               0,0,0,0,Q3137D,3,ROUTID)
         CALL TLINEX(X1143D,X2143D,Y3143D,3,11,Q,R,M(K),
     1               0,0,0,0,Q3143D,3,ROUTID)
         CALL TLINEX(X1149D,X2149D,Y3149D,3,11,Q,R,S(K),
     1               0,0,0,0,Q3149D,3,ROUTID)
         GO TO 1060
C
C    ----HERE FOR ALT=250000
C
 1040    IF(IT.EQ.5.AND.K.EQ.1)GO TO 1030
         CALL TLINEX(X1131E,X2131E,Y3131E,2,11,Q,R,P(K),
     1               0,0,0,0,Q3131E,3,ROUTID)
         CALL TLINEX(X1137E,X2137E,Y3137E,2,11,Q,R,T(K),
     1               0,0,0,0,Q3137E,3,ROUTID)
         CALL TLINEX(X1143E,X2143E,Y3143E,2,11,Q,R,M(K),
     1               0,0,0,0,Q3143E,3,ROUTID)
         CALL TLINEX(X1149E,X2149E,Y3149E,2,11,Q,R,S(K),
     1               0,0,0,0,Q3149E,3,ROUTID)
         GO TO 1060
C
C    ----HERE FOR ALT=300000
C
 1050    IF(IT.EQ.6.AND.K.EQ.1)GO TO 1040
         CALL TLINEX(X1131F,X2131F,Y3131F,2,11,Q,R,P(K),
     1               0,0,0,0,Q3131F,3,ROUTID)
         CALL TLINEX(X1137F,X2137F,Y3137F,2,11,Q,R,P(K),
     1               0,0,0,0,Q3137F,3,ROUTID)
         CALL TLINEX(X1143F,X2143F,Y3143F,2,11,Q,R,M(K),
     1               0,0,0,0,Q3143F,3,ROUTID)
         CALL TLINEX(X1149F,X2149F,Y3149F,2,11,Q,R,S(K),
     1               0,0,0,0,Q3149F,3,ROUTID)
 1060 CONTINUE
      X1=(IT-1)*5E4
      X2=IT*5E4
      ARG=(X2-X1)/(ALT-X1)
      PA   =P(1)+(P(2)-P(1))/ARG
      TA   =T(1)+(T(2)-T(1))/ARG
      MA   =M(1)+(M(2)-M(1))/ARG
      RA=S(1)+(S(2)-S(1))/ARG
      RETURN
      END
C ===== ideal.f =====
      SUBROUTINE IDEAL
C
C  CALCULATE THE SECTION IDEAL AERODYNAMIC PARAMETERS
C
      COMMON /IBODY/ PB,NACA(80)
      COMMON /IWING/ PW,X0(60)
      COMMON / IBW / PBW,M
      COMMON / IBH / PBH, THN(60),CAM(60),A0
      COMMON / IBV / PBV,ZTNU(32),ZCNU(32),ST1NU(32),ST2NU(32),ST3NU(32)
     1               ,ST4NU(32),ST5NU(32),X(32),THNU(32),THMU(32)
      COMMON /IBWH/  PBWH,AI,ALO,CLI,ALPMAX,CMCO4
      COMMON /IBWHV/ PBWHV, RHO,TMAX
      COMMON /CONSNT/PI,DEG,UNUSED,RAD
      INTEGER A4HS
      DIMENSION C(6)
      DATA A4HS/4HS   /
      XN=32.
      N=XN
      L=N-1
      DO 1000 J=1,L
         XMU=J
 1000 THMU(J)=XMU*PI/XN
      DO 1010 I=1,N
         XNU=I
         THNU(I)=XNU*PI/XN
 1010 X(I)=.5*(COS(THNU(I))+1.)
      A0=SQRT(2.*RHO)
C
C  OBTAIN THICKNESS AT CALCULATED X(I) FOR WEBER ANALYSIS
C
      IF(NACA(8).EQ.A4HS)GO TO 1020
      CALL ASMINT(M,X0,THN,N,X,ZTNU)
      GO TO 1040
 1020 CONTINUE
C
C  HERE FOR SUPERSONIC AIRFOILS
C
      IN=0
      MI=0
      NG=0
      DO 1030 I=1,N
         CALL TBFUNX(X(I),ZTNU(I),DYDX,60,X0,THN,C,IN,MI,NG,0,0,
     1               4HX..Y,1,4HX..Y)
 1030 CONTINUE
 1040 CONTINUE
C
C  DEFINE THE WEBER TERMS FOR THIS AIRFOIL
C
C    ST1NU DEFINES THE SOURCE DISTRIBUTION IN PARALLEL FLOW
C    ST2NU DEFINES THE SLOPE OF THE THICKNESS DISTRIBUTION
C
      DO 1070 I=1,N
         ST1NU(I)=0.0
         ST2NU(I)=0.0
         DO 1070 J=1,L
            IF(I.EQ.J)GO TO 1050
            S1=((-1.)**(J-I)-1.)/XN*2.*SIN(THMU(J))/
     1         (COS(THMU(J))-COS(THNU(I)))**2
            S2=-2.*(-1.)**(J-I)*SIN(THMU(J))/(SIN(THNU(I))*
     1          (COS(THMU(J))-COS(THNU(I))))
            GO TO 1060
 1050       S1=XN/SIN(THNU(I))
            S2=COS(THNU(I))/(SIN(THNU(I)))**2
 1060       YS1=S1*ZTNU(J)
            YS2=S2*ZTNU(J)
            ST2NU(I)=ST2NU(I)+YS2
 1070 ST1NU(I)=ST1NU(I)+YS1
      ST1NU(N)=ST1NU(N)+XN*A0
C
C    ST3NU DEFINES THE VORTEX DISTRIBUTION IN NORMAL FLOW
C
      DO 1100 I=1,N
         ST3NU(I)=0.0
         DO 1100 J=1,L
            IF(I.EQ.J) GO TO 1080
            S3=((-1.)**(J-I)-1.)/XN*2.*SIN(THMU(J))/
     1         (COS(THMU(J))-COS(THNU(I)))**2+2./XN*
     2         (1.-(-1.)**(J-I))/(SIN(THMU(J))*
     3         (COS(THMU(J))-COS(THNU(I))))
            GO TO 1090
 1080       S3=XN/SIN(THNU(I))
 1090       YS3=S3*ZTNU(J)
 1100 ST3NU(I)=ST3NU(I)+YS3
      DO 1130 I=1,N
         IF(I.EQ.N)GO TO 1110
         S3=((-1.)**I-1.)/(XN*(1.+COS(THNU(I))))
         GO TO 1120
 1110    S3=0.0
 1120    Y=S3*SQRT(RHO/2.)
         IF(I.NE.N) GO TO 1130
         Y=XN/2.*A0
 1130 ST3NU(I)=ST3NU(I)+Y
C
C  OBTAIN MEAN LINE DISTRIBUTION AT CALCULATED X(I) FOR WEBER ANALYSIS
C
      CALL ASMINT(M,X0,CAM,N,X,ZCNU)
C
C    ST4NU DEFINES THE VORTEX DISTRIBUTION DUE TO CAMBER
C    ST5NU DEFINES THE SLOPE OF THE MEAN LINE
C
      DO 1160 I=1,N
         ST4NU(I)=0.0
         ST5NU(I)=0.0
         DO 1160 J=1,L
            IF(I.EQ.J)GO TO 1140
            S4=2.*((-1.)**(J-I)-1.)/(XN*SIN(THNU(I)))*(1.-COS(THMU(J))*
     1         COS(THNU(I)))/(COS(THNU(I))-COS(THMU(J)))**2-2.*((-1.)
     2         **J-1.)/(XN*SIN(THNU(I))*(1.-COS(THMU(J))))
            S5=-2.*(-1.)**(J-I)/(COS(THMU(J))-COS(THNU(I)))
            GO TO 1150
 1140       S4=XN/SIN(THNU(I))-2.*((-1.)**J-1.)/(XN*SIN(THNU(I))*
     1         (1.-COS(THNU(I))))
            S5=-COS(THNU(I))/(SIN(THNU(I)))**2
 1150       YS4=S4*ZCNU(J)
            YS5=S5*ZCNU(J)
            ST4NU(I)=ST4NU(I)+YS4
 1160 ST5NU(I)=ST5NU(I)+YS5
C
C  GET PLANFORM IDEAL PARAMETERS
C
      IF(CLI .NE. UNUSED) GO TO 1190
      JN=N-4
      ZC95=ZCNU(4)
      ZC05=ZCNU(JN)
      DAI05= .3739*ZC05+.04745*ST5NU(N-1)
      DAI95=-.3739*ZC95+.04745*ST5NU(1)
      DA95=-.7834*ZC95+.09518*ST5NU(1)
      T1=.5*(-ZC95*COS(THNU(4))/(SIN(THNU(4))/2.)**2-ZC05*
     1  COS(THNU(JN))/(SIN(THNU(JN))/2.)**2)
      T2=.5*ZC95/(1.-COS(THNU(4)))
      NM5=N-5
      SUMAL=0.0
      SUMAI=0.0
      DO 1180 I=5,L
         IF(I .GT. NM5) GO TO 1170
         T3=-ZCNU(I)*COS(THNU(I))/(SIN(THNU(I))/2.)**2
         SUMAI=SUMAI+T3
 1170    T4=ZCNU(I)/(1.-COS(THNU(I)))
 1180 SUMAL=SUMAL+T4
C
C  IDEAL ANGLE OF ATTACK
C
      DAI=.5/XN*(T1+SUMAI)
      AI=RAD*(DAI05+DAI+DAI95)
C
C  ANGLE OF ATTACK FOR ZERO LIFT
C
      DALO=-2./XN*(T2+SUMAL)
      ALO=RAD*(DA95+DALO)
C
C  IDEAL LIFT COEFFICIENT
C
      CLI=2.*PI/RAD*(AI-ALO)
 1190 CONTINUE
C
C  PITCHING MOMENT ABOUT THE QUARTER CHORD
C
      SUMCM=0.0
      DO 1200 I=1,L
         T5=ZCNU(I)*COS(THNU(I))
 1200 SUMCM=SUMCM+T5
      XMUO=SUMCM*(-PI/XN)
      CMCO4=2.*XMUO+PI/2.*ALO/RAD
      RETURN
      END
C ===== inftgm.f =====
      SUBROUTINE INFTGM
C
C***  CALCULATE DOWNWASH SYNTHESIZING DIMENSIONS
C
      COMMON /WINGI/  CHRDTP,SSPNOP,SSPNE,SSPN,CHRDBP,CHRDR,SAVSI,SAVSO,
     1                CHSTAT,ALPHAO,TWISTA,SSPNDD,DHDADI,DHDADO,TYPE,
     2                TOVC,DELTAY,XOVC,CLI,ALPHAI,CLALPA(20),
     3                CLMAX(20),CMO,LERI,LERO,CAMBER,TOVCO,XOVCO,CMOT,
     4                CLMAXL,CLAMO,TCEFF,KSHARP,SLOPE(6)
      COMMON /WINGD/  A(195)
      COMMON /HTDATA/ ATH(195)
      COMMON /HTI/    HTIN(154)
      COMMON /CONSNT/ CONST(4)
      COMMON /SYNTSS/ XCG,XW,ZW,ALIW,ZCG,XH,ZH,ALIH,XV,VERTUP,HINAX,
     1                XVF,SCALE,ZV,ZVF,YV,YF,PHIV,PHIF
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT
      LOGICAL         FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT
      LOGICAL LOGCOM(10),VERTUP
      EQUIVALENCE (LOGCOM(1),FLTC)
      EQUIVALENCE (RAD,CONST(4)),(UNUSED,CONST(3))
C
      IF(.NOT.HTPL) GO TO 1010
      COSAIW=COS(ALIW/RAD)
      COSAIH=COS(ALIH/RAD)
      SINAIH=SIN(ALIH/RAD)
      SINAIW=SIN(ALIW/RAD)
      TANAIW=SINAIW/COSAIW
      IF(HINAX .EQ. UNUSED) GO TO 1000
      ZH=ZH+SINAIH*(HINAX-XH)
      XH=HINAX*(1.-COSAIH)+XH*COSAIH
 1000 XBRSTH=ATH(30)-ATH(16)/4.
      DXSTAR=(HTIN(4)-HTIN(3))*ATH(62)
      DXBH=XBRSTH+DXSTAR
      A(193)=XH-XW-CHRDR*COSAIW
      A(194)=A(193)+DXBH*COSAIH
      ZPH=ZH-DXBH*SINAIH-ZW+CHRDR*SINAIW
      DLH=ZPH*TANAIW
      A(24)=(A(194)-DLH)*COSAIW
      A(22)=CHRDR-A(195)
      A(9)=A(29)+(SSPN-SSPNE)*A(38)
      DHH1=ZPH/COSAIW
      DHH2=(A(194)-DLH)*SINAIW
      A(12)=DHH1+DHH2
      A(11)=ATAN(A(12)/A(24))
 1010 CONTINUE
C
C     ----DETERMINE LOCATION OF ZERO SWEEP ANGLE
C
      IF(A(52).LT.0.) GO TO 1020
      A(8)=1.
      RETURN
 1020 IF(A(112).NE.UNUSED) GO TO 1030
C
C     ----HERE IF INBOARD ONLY
C
      A(8)=A(110)/A(13)+CHSTAT
      RETURN
C
C     ----HERE IF INBOARD + OUTBOARD
C
 1030 IC=34
      DO 1050 I=1,3
         CP=I-1
         IF(ABS(A(IC)).GT.1.E-3) GO TO 1040
         A(8)=.25*CP
         RETURN
 1040    IP=IC
         IC=IC+6
         IF(A(IP).GT.0.0.AND.A(IC).LT.0.0) GO TO 1060
 1050 CONTINUE
 1060 A(8)= .25*(CP+(CP+1.)*A(IP)/(A(IP)-A(IC)))
      RETURN
      END
C ===== initz1.f =====
      SUBROUTINE INITZ1
C
C***  INITIALIZE ARRAYS FOR PROGRAM USE
C
C     IDEAL OUTPUT MATRIX
C             BLOCK    PRINT     IOM
C             NAME     FLAG     ARRAY
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
      COMMON /IPOWER/  PPOWER, POWER(200)
      COMMON /IDWASH/  PDWASH, DWASH(60)
C
      LOGICAL PBODY, PWING, PHT, PVT, PVF, PBW, PBH, PBV, PBWH, PBWV,
     1        PBWHV, PPOWER, PDWASH
C
C***  COMPUTATIONAL BLOCKS
C
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /WHWB/   FACT(182), WB(39), HB(39)
      COMMON /WBHCAL/ WBT(156)
      COMMON /WHAERO/ C(51), D(55), CHT(51), DHT(55), DVT(55), DVF(55)
      COMMON /POWR/   PW(315)
      COMMON /SUPWBB/  SWB(61), SHB(61)
      COMMON /SUPDW/  DWA(237)
      COMMON /SUPWH/  GR(303)
      COMMON /SUPBOD/ SBD(229)
C
      COMMON /CONSNT/CONST(4)
      EQUIVALENCE (CONST(3),UNUSED)
C
      DO 1000 I=1,51
 1000 C(I)=UNUSED
      DO 1010 I=1,55
 1010 D(I)=UNUSED
      DO 1020 I=1,39
         HB(I)=UNUSED
 1020 WB(I)=UNUSED
      DO 1030 I=1,182
 1030 FACT(I)=UNUSED
      DO 1040 I=1,156
 1040 WBT(I)=UNUSED
      DO 1050 I=1,315
 1050 PW(I)=UNUSED
      DO 1060 I=1,51
 1060 CHT(I)=UNUSED
      DO 1070 I=1,55
 1070 DHT(I)=UNUSED
      DO 1080 I=1,55
         DVF(I)=UNUSED
 1080 DVT(I)=UNUSED
      DO 1090 I=1,135
         STBH(I)=UNUSED
 1090 STB(I)=UNUSED
      DO 1100 I=1,229
 1100 SBD(I)=UNUSED
      DO 1110 I=1,303
 1110 GR(I)=UNUSED
      DO 1120 I=1,61
         SHB(I)=UNUSED
 1120 SWB(I)=UNUSED
      DO 1130 I=1,237
 1130 DWA(I)=UNUSED
      DO 1140 I=1,108
         TRAH(I)=UNUSED
 1140 TRA(I)=UNUSED
      DO 1150 I=1,400
         BODY(I)=UNUSED
 1150 WING(I)=UNUSED
      DO 1160 I=1,380
         HT(I)=UNUSED
         VT(I)=UNUSED
         VF(I)=UNUSED
         BW(I)=UNUSED
         BH(I)=UNUSED
         BV(I)=UNUSED
         BWH(I)=UNUSED
         BWV(I)=UNUSED
 1160 BWHV(I)=UNUSED
      DO 1170 I=1,200
 1170 POWER(I)=UNUSED
      DO 1180 I=1,60
 1180 DWASH(I)=UNUSED
      RETURN
      END
C ===== initz2.f =====
      SUBROUTINE INITZ2
C
C     REINITIALIZE ARRAYS FOR FLAP ROUTINES
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /POWR/   SPR(59),FLA(45),FLP(189),TRM(22)
      COMMON /SUPDW/  FHG(35),TCD(58)
      COMMON /SUPWH/  FCM(282)
      COMMON /IBODY/  PB, BODY(400)
      COMMON /IWING/  PW, WING(400)
      COMMON /IHT/    PH, HT(380)
      COMMON /IVT/    PV, VT(380)
      COMMON /IVF/    PF, VF(380)
C
      DIMENSION PWW(315),DW(93)
      EQUIVALENCE (PWW(1),SPR(1)), (DW(1),FHG(1))
C
      DO 1000 I=1,315
         PWW(I) = UNUSED
         IF(I .GT. 282) GO TO 1000
         FCM(I) = UNUSED
         IF(I .GT. 93) GO TO 1000
         DW(I) = UNUSED
 1000 CONTINUE
      DO 1010 I=1,200
         BODY(I+200) = UNUSED
         WING(I+200) = UNUSED
         IF(I .GT. 180) GO TO 1010
         HT(I+200) = UNUSED
         VF(I+200) = UNUSED
         VF(I+200) = UNUSED
 1010 CONTINUE
      RETURN
      END
C ===== initze.f =====
      SUBROUTINE INITZE
C
C***  IDEAL OUTPUT MATRIX
C
C             BLOCK    PRINT     IOM
C             NAME     FLAG     ARRAY
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
      COMMON /IPOWER/  PPOWER, POWER(200)
      COMMON /IDWASH/  PDWASH, DWASH(60)
C
      LOGICAL PBODY, PWING, PHT, PVT, PVF, PBW, PBH, PBV, PBWH, PBWV,
     1        PBWHV, PPOWER, PDWASH
C
C***  INPUT DATA BLOCKS
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /OPTION/ XX(4)
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /BODYI/  BODYIN(129)
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /POWER/  PWIN(29), LBIN(21)
      COMMON /FLAPIN/ F(138)
C
C***  COMPUTATIONAL BLOCKS
C
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /BDATA/  BD(762)
      COMMON /WHWB/   FACT(182), WB(39), HB(39)
      COMMON /WBHCAL/ WBT(156)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /WHAERO/ C(51), D(55), CHT(51), DHT(55), DVT(55), DVF(55)
      COMMON /POWR/   PW(315)
      COMMON /SUPWBB/  SWB(61), SHB(61)
      COMMON /SUPDW/  DWA(237)
      COMMON /SUPWH/  GR(303)
      COMMON /SUPBOD/ SBD(229)
      COMMON /LEVEL2/ SECOND(23)
C
      COMMON /CONSNT/CONST(4)
      EQUIVALENCE (CONST(3),UNUSED),(DONE,SECOND(15)),(DOL2,SECOND(16))
      LOGICAL BLF,ROUNDN,VERTUP,DONE,DOL2
      REAL LBIN
      DIMENSION X(19)
      EQUIVALENCE (BLF,LBIN(14)),(ROUNDN,LBIN(17)),(X(1),XCG)
C
C     ----FIX WITH ENTRIES TO INITIALIZE DIFFERENT PARTS
C
      DO 1000 I=1,195
 1000 A(I)=UNUSED
      DO 1010 I=1,49
 1010 B(I) = UNUSED
      DO 1020 I=1,51
 1020 C(I)=UNUSED
      DO 1030 I=1,55
 1030 D(I)=UNUSED
      DO 1040 I=1,762
 1040 BD(I)=UNUSED
      DO 1050 I=1,39
      HB(I)=UNUSED
 1050 WB(I)=UNUSED
      DO 1060 I=1,4
 1060 XX(I)=UNUSED
      DO 1070 I=1,19
      IF(I .NE. 10)X(I)=UNUSED
 1070 CONTINUE
      VERTUP=.TRUE.
      DO 1080 I=1,160
 1080 FLC(I)=UNUSED
      DO 1090 I=1,182
 1090 FACT(I)=UNUSED
      DO 1100 I=1,156
 1100 WBT(I)=UNUSED
      DO 1110 I=1,49
 1110 BHT(I)=UNUSED
      DO 1120 I=1,195
      AVF(I)=UNUSED
 1120 AVT(I)=UNUSED
      DO 1130 I=1,195
 1130 AHT(I)=UNUSED
      DO 1140 I=1,315
 1140 PW(I)=UNUSED
      DO 1170 I=1,51
 1170 CHT(I)=UNUSED
      DO 1180 I=1,55
 1180 DHT(I)=UNUSED
      DO 1190 I=1,55
      DVF(I)=UNUSED
 1190 DVT(I)=UNUSED
      DO 1200 I=1,135
      STBH(I)=UNUSED
 1200 STB(I)=UNUSED
      DO 1210 I=1,229
 1210 SBD(I)=UNUSED
      DO 1215 I=1,23
 1215 SECOND(I)=UNUSED
      DO 1220 I=1,303
 1220 GR(I)=UNUSED
      DO 1230 I=1,61
      SHB(I)=UNUSED
1230  SWB(I)=UNUSED
      DO 1240 I=1,29
 1240 PWIN(I)=UNUSED
      DO 1250 I=1,237
 1250 DWA(I)=UNUSED
      DO 1260 I=1,129
 1260 BODYIN(I)=UNUSED
      DO 1270 I=1,101
 1270 WINGIN(I)=UNUSED
      WINGIN(7) = 0.
      WINGIN(8) = 0.
      DO 1280 I=1,108
      TRAH(I)=UNUSED
 1280 TRA(I)=UNUSED
      DO 1290 I=1,138
 1290 F(I)=UNUSED
      DO 1300 I=1,154
      HTIN(I) = UNUSED
      VTIN(I) = UNUSED
      VFIN(I) = UNUSED
      IF(I .GT. 21) GO TO 1300
      LBIN(I) = UNUSED
      IF(I .GT. 8) GO TO 1300
      TVTIN(I) = UNUSED
 1300 CONTINUE
      VTIN(7) = 0.
      VTIN(8) = 0.
      VFIN(7) = 0.
      VFIN(8) = 0.
      HTIN(7) = 0.
      HTIN(8) = 0.
      BLF=.FALSE.
      ROUNDN=.FALSE.
      CALL ZERANG(A(106))
      CALL ZERANG(A(112))
      CALL ZERANG(A(138))
      CALL ZERANG(AHT(106))
      CALL ZERANG(AVT(106))
      CALL ZERANG(AVF(106))
      CALL ZERANG(AHT(112))
      CALL ZERANG(AVT(112))
      CALL ZERANG(AVF(112))
      CALL ZERANG(AHT(138))
      CALL ZERANG(AVT(138))
      CALL ZERANG(AVF(138))
      CALL ZERANG(A(153))
      CALL ZERANG(A(147))
      CALL ZERANG(AHT(153))
      CALL ZERANG(AHT(147))
      CALL ZERANG(AVT(153))
      CALL ZERANG(AVT(147))
      CALL ZERANG(AVF(153))
      CALL ZERANG(AVF(147))
      DO 1310 I=1,400
         BODY(I)=UNUSED
 1310 WING(I)=UNUSED
      DO 1320 I=1,380
      HT(I)=UNUSED
      VT(I)=UNUSED
      VF(I)=UNUSED
      BW(I)=UNUSED
      BH(I)=UNUSED
      BV(I)=UNUSED
      BWH(I)=UNUSED
      BWV(I)=UNUSED
 1320 BWHV(I)=UNUSED
      DO 1330 I=1,200
 1330 POWER(I)=UNUSED
      DO 1340 I=1,60
 1340 DWASH(I)=UNUSED
      PBODY=.FALSE.
      PWING=.FALSE.
      PHT=.FALSE.
      PVT=.FALSE.
      PVF=.FALSE.
      PBW=.FALSE.
      PBH=.FALSE.
      PBV=.FALSE.
      PBWH=.FALSE.
      PBWV=.FALSE.
      PBWHV=.FALSE.
      PPOWER=.FALSE.
      PDWASH=.FALSE.
      DONE=.FALSE.
      DOL2=.FALSE.
      RETURN
      END
C ===== iniz.f =====
      SUBROUTINE INIZ
C
C  INITIZE FOR REUSE OF THE COMMON BLOCKS
C
      COMMON /CONSNT/PI,DEG,UNUSED,RAD
      COMMON /IBWH/  PBWH, X(47)
      COMMON /IBWHV/ PBWHV, Y(7)
      COMMON /IBH/   PBH, Z(144)
      DO 1000 I=1,144
         Z(I)=UNUSED
         IF(I.GT.47) GO TO 1000
         X(I)=UNUSED
         IF(I.GT.7) GO TO 1000
         Y(I)=UNUSED
 1000 CONTINUE
      RETURN
      END
