     1                YUPPER(50),YLOWER(50)
      COMMON /IBH/    PBH(131),HTYPE,NACAH(80)
      COMMON /IBV/    PBV(131),VTYPE,NACAV(80)
      COMMON /IVF/    PVF(131),VFTYP,NACAF(80)
