     1            (CHRDFI,F(12)),(CHRDFO,F(13)),(SPANFI,F(14)),
     2            (SPANFO,F(15)),(NDELTA,F(16)),(FTYPE,F(17)),
     3            (STYPE,F(18)),(SCLD(1),DELTAL(1),F(19)),
     4            (SCMD(1),DELTAR(1),F(29)),(CPRMEI(1),DELTAS(1),F(39)),
