     10.0,.092,.13,.176,.21,.236,.257,.275,.294,.314,.33,.347,
     20.0,.054,.074,.105,.125,.139,.152,.168,.179,.188,.199,.204,
     30.0,.035,.050,.07,.08,.09,.101,.110,.120,.130,.138,.144,
     40.0,.024,.033,.05,.059,.066,.071,.08,.086,.09,.100,.102,
     50.0,.019,.025,.036,.042,.048,.052,.06,.063,.067,.072,.076/
C
