C ===== m17o21.f =====
      SUBROUTINE M17O21
C
C***  EXEC FOR OVERLAY 17, SUBSONIC LATERAL STABILITY
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
C
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF,K,NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL  FLAG, TEST
C
      NOVLY=17
      FLAG = .FALSE.
      TEST = WGPL .OR. VTPL .OR. TVTPAN
      IF(TEST) CALL SUBLAT(STB,WING,WINGIN,BW,A,B,AHT,
     1                     AVT,VT,VTIN,VTPL,TVTPAN,HTPL,WGPL,0)
      TEST = HTPL .OR. VFPL
      IF(TEST) CALL SUBLAT(STBH,HT,HTIN,BH,AHT,BHT,AHT,
     1                     AVF,VF,VFIN,VFPL,FLAG,FLAG,HTPL,1)
C
C     SET IOM VALUES FOR CYB, CNB, AND CLB
C
      DO 1050 J=1,NALPHA
C
C     VT DATA
C
         IF(J .EQ. 1) GO TO 1000
         VT(J+140) = -UNUSED
         VT(J+160) = -UNUSED
         VF(J+140) = -UNUSED
         VF(J+160) = -UNUSED
C
C     B-W  DATA
C
         BW(J+140) = -UNUSED
         BW(J+160) = -UNUSED
C
C     B-H  DATA
C
         BH(J+140) = -UNUSED
         BH(J+160) = -UNUSED
 1000    CONTINUE
C
C     B-V  DATA
C
         BV(J+140) = -UNUSED
         BV(J+160) = -UNUSED
         IF(J .GT. 1) GO TO 1010
         BV(J+140) = BODY(J+140) + VT(J+140) + VF(J+140)
         BV(J+160) = BODY(J+160) + VT(J+160) + VF(J+160)
 1010    CONTINUE
         BV(J+180) = BODY(J+180) + VT(J+180) + VF(J+180)
C
C     B-W-H  DATA
C
         BWH(J+140) = -UNUSED
         BWH(J+160) = -UNUSED
         IF(J .GT. 1) GO TO 1020
         BWH(J+140) = BW(J+140) + HT(J+140)
         BWH(J+160) = BW(J+160) + HT(J+160)
 1020    BWH(J+180) = BW(J+180) + HT(J+180)
C
C     B-W-V  DATA
C
         BWV(J+140) = -UNUSED
         BWV(J+160) = -UNUSED
         IF(J .GT. 1) GO TO 1030
         BWV(J+140) = BW(J+140) + VT(J+140) + VF(J+140)
         BWV(J+160) = BW(J+160) + VT(J+160) + VF(J+160)
 1030    CONTINUE
         BWV(J+180) = BW(J+180) + VT(J+180) + VF(J+180)
C
C     B-W-H-V  DATA
C
         BWHV(J+140) = -UNUSED
         BWHV(J+160) = -UNUSED
         IF(J .GT. 1) GO TO 1040
         BWHV(J+140) = BWH(J+140) + VT(J+140) + VF(J+140)
         BWHV(J+160) = BWH(J+160) + VT(J+160) + VF(J+160)
 1040    CONTINUE
         BWHV(J+180) = BWH(J+180) + VT(J+180) + VF(J+180)
 1050 CONTINUE
      IF(.NOT. TRANSN) GO TO 1070
      VT(141) = UNUSED
      VT(161) = UNUSED
      VF(141) = UNUSED
      VF(161) = UNUSED
      BV(141) = UNUSED
      BV(161) = UNUSED
      BWH(141) = UNUSED
      BWH(161) = UNUSED
      BWHV(141) = UNUSED
      BWHV(161) = UNUSED
      WING(141) = UNUSED
      WING(161) = UNUSED
      HT(141) = UNUSED
      HT(161) = UNUSED
      DO 1060 J=1,NALPHA
         BV(J+180) = UNUSED
         BWH(J+180) = UNUSED
         BWV(J+180) = UNUSED
         BWHV(J+180) = UNUSED
 1060 CONTINUE
 1070 CONTINUE
      RETURN
      END
C ===== m18o22.f =====
      SUBROUTINE M18O22
C
C***  EXEC FOR OVERLAY 18, SUPERSONIC WING DRAG
C
      COMMON /OVERLY/  IJKDUM(8),NOVLY
      COMMON /OPTION/ SREF, CBARR, ROUGFC, BLREF
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZVT, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /WINGD/  A(195), B(49)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      DIMENSION INDX(12)
      DATA INDX/1,2,3,4,5,6,7,119,120,163,167,168/
C
      NOVLY=18
      CALL SETUP1
C
C     ----SET SURFACE GEOMETRY IF PRESENR
C
      IF(WGPL) CALL WTGEOM(A,WINGIN)
      IF(HTPL) CALL WTGEOM(AHT,HTIN)
      IF(VTPL) CALL WTGEOM(AVT,VTIN)
      DO 1000 I=1,12
         II=INDX(I)
         IF(AVT(II).NE.UNUSED)AVT(II)=AVT(II)/2.
 1000 CONTINUE
      IF(VFPL) CALL WTGEOM(AVF,VFIN)
      DO 1010 I=1,12
         II=INDX(I)
         IF(AVF(II).NE.UNUSED)AVF(II)=AVF(II)/2.
 1010 CONTINUE
      AVT(130) = AVT(130)+ZVT
      AVT(133) = AVT(133)+ZVT
      AVT(136) = AVT(136)+ZVT
      AVF(130) = AVF(130)+ZVF
      AVF(133) = AVF(133)+ZVF
      AVF(136) = AVF(136)+ZVF
C
C     ----SET /OPTION/ PARAMETERS IF NOT INPUT
C
      IF(SREF.EQ.UNUSED) SREF=A(4)
      IF(CBARR.EQ.UNUSED) CBARR=A(122)
      IF(ROUGFC.LT.1.0E-10)ROUGFC=1.6E-4
C
      IF(TRANSN)RETURN
      IF(WGPL) CALL SUPDRG
      RETURN
      END
C ===== m19o23.f =====
      SUBROUTINE M19O23
C
C***  EXEC FOR OVERLAY 19, SUPERSONIC BODY AERO
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /IBODY/  PBODY,BODY(400)
      COMMON /OPTION/ SREF,CBARR,ROUGFC,BLREF
      COMMON /FLGTCD/ FLC(93),STMACH,TSMACH,TR
      COMMON /WINGD/  A(195)
      COMMON /WINGI/  WINGIN(100)
      COMMON /SUPBOD/ SBD(229)
      COMMON /BODYI/  XNX,X(20),S(20),P(20),R(20),
     1                ZU(20),ZL(20),BNOSE,BTAIL,RLN,RLA,DS
      COMMON /SYNTSS/ XCG,XW,ZW,ALIW,ZCG,XH,ZH,ALIHXV,VERTUP,HINAX,
     1                XVF,SCALE,ZV,ZVF,YV,YF,PHIV,PHIF
      COMMON /HTI/    HTIN(154)
      COMMON /HTDATA/ AHT(195)
      COMMON /BDATA/  BD(275),BOD(120)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
C
      LOGICAL       FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      DIMENSION CR(6), DR(6), ROUTID(2)
      DIMENSION XS(20),SS(20),PS(20),RS(20),XI(3)
      DATA ROUTID / 4HM19O, 4H23   /
C
      NOVLY=19
      IF(SREF   .EQ. UNUSED) SREF   = A(4)
      IF(CBARR  .EQ. UNUSED) CBARR  = A(122)
      IF(ROUGFC .EQ. UNUSED) ROUGFC = 1.6E-4
      IF(BLREF  .EQ. UNUSED) BLREF  = 2.0*WINGIN(4)
      CALL SYPBOD(I)
      CALL EXSUBT
C
C
      IF(FLC(I+2) .LT. TSMACH) RETURN
C
C      CALCULATE CLA, CMA,CYB, CNB, AND CLB
C
      BFACT = CBARR/BLREF
      IN = 0
      IM = 0
      DO 1000 J=1,NALPHA
         CALL TBFUNX(FLC(J+22),XX,BODY(J+100),NALPHA,FLC(23),BODY(21),
     1               CR,IN,MI,NG,0,0,4HCLAB,1,ROUTID)
         CALL TBFUNX(FLC(J+22),XX,BODY(J+120),NALPHA,FLC(23),BODY(41),
     1               DR,IM,MI,NG,0,0,4HCMAB,1,ROUTID)
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         BODY(J+60) = BODY(J+20)*CA + BODY(J)*SA
         BODY(J+80) = BODY(J)*CA - BODY(J+20)*SA
         BODY(J+140) = -BODY(J+100)
         BODY(J+160) = -BFACT*BODY(J+120)
         BODY(J+180) = 0.0
 1000 CONTINUE
      RETURN
      END
C ===== m20o24.f =====
      SUBROUTINE M20O24
C
C***  EXEC FOR OVERLAY 20, SUPERSONIC WING-BODY AERO
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWV/    PBWV,   BWV(380)
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /WBHCAL/ STP(156)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF,L,NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
C
      DIMENSION CR(6), DR(6), ROUTID(2)
      DATA ROUTID / 4HM20O, 4H24   /
C
      NOVLY=20
      IF(WGPL .AND. BO)CALL SUPWB
      IF(HTPL .AND. BO) CALL SUPHB
      DO 1000 J=1,NALPHA
 1000 BWV(J) = BW(J)
      IF(VTPL) CALL VRTCDO(I)
      IF(VFPL) CALL VFCDO(I)
      CALL SUPCM0
C
C     VT DATA
C
      IF(VT(1) .EQ. UNUSED) VT(1) = STP(1)
      VT(21) = 0.0
      VT(41) = 0.0
      VT(61) = 0.0
      VT(81) = VT(1)
      VT(101) = 0.0
      VT(121) = 0.0
      IF(VF(1) .EQ. UNUSED) VF(1) = STP(156)
      VF(21) = 0.0
      VF(41) = 0.0
      VF(61) = 0.0
      VF(81) = VF(1)
      VF(101) = 0.0
      VF(121) = 0.0
      DO 1010 J=1,NALPHA
         IF(J .EQ. 1) GO TO 1010
         VT(J) = -UNUSED
         VT(J+20) = -UNUSED
         VT(J+40) = -UNUSED
         VT(J+60) = -UNUSED
         VT(J+80) = -UNUSED
         VT(J+100) = -UNUSED
         VT(J+120) = -UNUSED
         VF(J) = -UNUSED
         VF(J+20) = -UNUSED
         VF(J+40) = -UNUSED
         VF(J+60) = -UNUSED
         VF(J+80) = -UNUSED
         VF(J+100) = -UNUSED
         VF(J+120) = -UNUSED
 1010 CONTINUE
      IF( .NOT. BO) GO TO 1060
      IF(.NOT. WGPL) GO TO 1040
C
C     B-W  DATA
C
      IN = 0
      DO 1020 J=1,NALPHA
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         BW(J+60) = BW(J+20)*CA + BW(J)*SA
         BW(J+80) = BW(J)*CA - BW(J+20)*SA
         IF(J .EQ. 1) GO TO 1020
        CALL TBFUNX(FLC(J+22),X,BW(J+100),NALPHA,FLC(23),BW(21),
     1               CR,IN,MI,NG,0,0,4HCLA ,1,ROUTID)
         BW(J+120) = -UNUSED
 1020 CONTINUE
C
C     B-W-V  DATA
C
      IN = 0
      DO 1030 J=1,NALPHA
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         BWV(J+20) = BW(J+20)
         BWV(J+40) = BW(J+40)
         BWV(J+60) = BWV(J+20)*CA + BWV(J)*SA
         BWV(J+80) = BWV(J)*CA - BWV(J+20)*SA
         BWV(J+100)= BW(J+100)
         BWV(J+120)= BW(J+120)
 1030 CONTINUE
 1040 IF(.NOT. HTPL) GO TO 1060
C
C     B-H  DATA
C
      IN = 0
      DO 1050 J=1,NALPHA
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         BH(J+60) = BH(J+20)*CA + BH(J)*SA
         BH(J+80) = BH(J)*CA - BH(J+20)*SA
         IF(J .EQ. 1) GO TO 1050
         CALL TBFUNX(FLC(J+22),X,BH(J+100),NALPHA,FLC(23),BH(21),
     1               CR,IN,MI,NG,0,0,4HCLA ,1,ROUTID)
         BH(J+120) = -UNUSED
 1050 CONTINUE
 1060 IF(.NOT. (BO .AND. VTPL)) GO TO 1080
C
C     B-V DATA
C
      DO 1070 J=1,NALPHA
         DO 1070 K=1,7
            KK=(K-1)*20
            IF(K .EQ. 1) BV(J+KK)=BODY(J+KK)+VT(1) + VF(1)
            IF(K .NE. 1) BV(J+KK)=BODY(J+KK)
 1070 CONTINUE
 1080 CONTINUE
      RETURN
      END
C ===== m21o25.f =====
      SUBROUTINE M21O25
C
C***  EXEC FOR OVERLAY 21, SUPERSONIC WING FLOW FIELDS
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      EQUIVALENCE (KDWASH(2),KEPSLN)
      LOGICAL KEPSLN
      KEY = 0
      IF(KEPSLN) KEY = 1
      NOVLY=21
      IF(KEPSLN) CALL EXSUBT
      CALL SDWASH(I,KEY)
      CALL EXSUBT
      RETURN
      END
C ===== m22o26.f =====
      SUBROUTINE M22O26
C
C***  EXEC FOR OVERLAY 22, SUPERSONIC HORIZONTAL-TAIL AERO
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /IHT/    PHT, HT(380)
      COMMON /CONSNT/ CONST(4)
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      EQUIVALENCE (CONST(3),UNUSED)
      COMMON /FLGTCD/ FLC(93)
      DIMENSION CR(6), ROUTID(2)
      EQUIVALENCE (KDWASH(2), KEPSLN)
      LOGICAL KEPSLN
      DATA ROUTID / 4HM22O, 4H26   /
      KEY = 0
      IF(KEPSLN) KEY = 1
      NOVLY=22
      CALL SUPLTG(KEY)
C
C     CALCULATE CLA AND CMA
C
      IN = 0
      DO 1000 J=2,NALPHA
         CALL TBFUNX(FLC(J+22),X,HT(J+100),NALPHA,FLC(23),HT(21),
     1               CR,IN,MI,NG,0,0,4HCLA ,1,ROUTID)
         HT(J+120) = -UNUSED
 1000 CONTINUE
      RETURN
      END
C ===== m23o27.f =====
      SUBROUTINE M23O27
C
C***  EXEC FOR OVERLAY 23, SUPERSONIC LATERAL STABILITY
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /FLGTCD/ FLC(95)
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /IWING/  PW, WING(400)
      COMMON /IHT/    PHT, HT(380)
      COMMON /IVT/    PVT, VT(380)
      COMMON /IVF/    PVF, VF(380)
      COMMON /IBODY/  PBODY, BODY(400)
      COMMON /IBH/    PBH, BH(380)
      COMMON /IBV/    PBV, BV(380)
      COMMON /IBW/    PBW, BW(380)
      COMMON /IBWH/   PBWH, BWH(380)
      COMMON /IBWV/   PBWV, BWV(380)
      COMMON /IBWHV/  PBWHV, BWHV(380)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
C
      NOVLY=23
      NALPHA=FLC(2)+0.5
      IF(WGPL) CALL SUPLAT
      IF(HTPL) CALL SUPLAH
      IF(VTPL) CALL SUPLAV
      IF(VFPL) CALL SUPLAF
C
C  CALCULATE V.T. INCREMENTS FOR LATERAL DERIVATIVES
C
      DO 1000 J=2,NALPHA
         WING(J+140) = -UNUSED
         WING(J+160) = -UNUSED
         HT(J+140) = -UNUSED
         HT(J+160) = -UNUSED
         VT(J+140) = -UNUSED
         VT(J+160) = -UNUSED
         VF(J+140) = -UNUSED
         VF(J+160) = -UNUSED
 1000 CONTINUE
C
C  SET IOM FOR CYB, CNB AND CLB
C
      DO 1010 J=2,NALPHA
         BW(J+140) =  -UNUSED
         BW(J+160) = -UNUSED
         BWH(J+140) = -UNUSED
         BWH(J+160) = -UNUSED
         BWV(J+140) = -UNUSED
         BWV(J+160) = -UNUSED
         BWHV(J+140) = -UNUSED
         BWHV(J+160) = -UNUSED
 1010 CONTINUE
      BV(141) = BODY(141) + VT(141) + VF(141)
      BV(161) = BODY(161) + VT(161) + VF(161)
      BV(181) = BODY(181) + VT(181) + VF(181)
      DO 1020 J=2,NALPHA
         BV(J+140) = -UNUSED
         BV(J+160) = -UNUSED
         BV(J+180) = BODY(J+180) + VT(J+180) + VF(J+180)
         BH(J+140) = -UNUSED
         BH(J+160) = -UNUSED
 1020 CONTINUE
      RETURN
      END
C ===== m24o30.f =====
      SUBROUTINE M24O30
C
C***  EXEC FOR OVERLAY 24, TRANSONIC WING AERO AND BODY STABILITY DATA
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ CONST(4)
      COMMON /IBODY/  PB, BODY(380)
      COMMON /OPTION/ SREF,CBARR,ROUGFC,BLREF
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      LOGICAL       FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      EQUIVALENCE (CONST(3),UNUSED)
C
      NOVLY=24
C
      IF(WGPL) CALL TRANWB
      IF(HTPL) CALL TRANHB
      CALL EXSUBT
C
C     SET BODY IOM
C
      BODY(141) = -BODY(101)
      BODY(161) = -BODY(121)*CBARR/BLREF
      DO 1010 J=1,NALPHA
         BODY(J+60) = UNUSED
         BODY(J+80) = UNUSED
         IF(J .EQ. 1) GO TO 1000
         BODY(J+20)  = -UNUSED
         BODY(J+40)  = -UNUSED
         BODY(J+60)  = -UNUSED
         BODY(J+80)  = -UNUSED
         BODY(J+100) = -UNUSED
         BODY(J+120) = -UNUSED
         BODY(J+140) = -UNUSED
         BODY(J+160) = -UNUSED
 1000    BODY(J+180) = 0.0
 1010 CONTINUE
      CALL TRANCD
      RETURN
      END
C ===== m25o31.f =====
      SUBROUTINE M25O31
C
C***  EXEC FOR OVERLAY 25, TRANSONIC WING, WING-BODY CMA
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      LOGICAL         FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      NOVLY=25
      IF(WGPL) CALL TRANCM
      IF(HTPL) CALL TRHTCM
      IF(BO)   CALL TRACM0
      RETURN
      END
C ===== m26o32.f =====
      SUBROUTINE M26O32
C
C***  EXEC FOR OVERLAY 26, HYPERSONIC BODY AERO
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /IBODY/  PB, BODY(400)
      COMMON /FLGTCD/ FLC(93)
      COMMON /OPTION/ SREF,CBARR,ROUGFC,BLREF
      DIMENSION C1(6),C2(6),ROUTID(2)
      DATA ROUTID/ 4HM26O, 4H32  /
      NOVLY=26
      CALL HYPBOD(I)
      BFACT = CBARR/BLREF
      IN = 0
      IM = 0
      DO 1000 J=1,NALPHA
         CALL TBFUNX(FLC(J+22),X,BODY(J+100),NALPHA,FLC(23),BODY(21),
     1               C1,IN,MI,NG,0,0,4HCLAB,1,ROUTID)
         CALL TBFUNX(FLC(J+22),X,BODY(J+120),NALPHA,FLC(23),BODY(41),
     1               C2,IM,MI,NG,0,0,4HCMAB,1,ROUTID)
         BODY(J+140) = -BODY(J+100)
         BODY(J+160) = -BFACT*BODY(J+120)
         BODY(J+180) = 0.0
 1000 CONTINUE
      RETURN
      END
C ===== m27o33.f =====
      SUBROUTINE M27O33
C
C***  EXEC FOR OVERLAY 27, SUPERSONIC WING STABILITY
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ CONST(4)
      COMMON /IWING/  PWING,WING(400)
      COMMON /FLGTCD/ FLC(93)
      COMMON /WINGI/  WGIN(100)
      EQUIVALENCE (CONST(3),UNUSED)
      LOGICAL FLAG
      DIMENSION CR(6),ROUTID(2)
      DATA ROUTID/ 4HM27O, 4H33  /
      DATA A4HSTR/4HSTRA/
      NOVLY=27
      CALL SUPLNG
C
C   GET WING CLA AND CMA FOR ANGLES-OF-ATTACK OTHER THAN THE FIRST
C
      FLAG = (WGIN(15) .EQ. A4HSTR)
      IN=0
      INN=0
      DO 1000 J=2,NALPHA
         CALL TBFUNX(FLC(J+22),X,WING(J+100),NALPHA,FLC(23),WING(21),
     1                CR,IN,MI,NG,0,0,4HCLAW,1,ROUTID)
         IF(J .EQ. 1) GO TO 1000
         WING(J+120) = -UNUSED
         IF(FLAG) GO TO 1000
         WING(J)    = -UNUSED
         WING(J+20) = -UNUSED
         WING(J+40) = -UNUSED
         WING(J+60) = -UNUSED
         WING(J+80) = -UNUSED
         WING(J+100)= -UNUSED
         WING(J+180)= -UNUSED
 1000 CONTINUE
      IF(.NOT. FLAG)WING(81)=WING(1)
      RETURN
      END
C ===== m28o34.f =====
      SUBROUTINE M28O34
C
C***  EXEC FOR OVERLAY 28, SUPERSONIC WING-BODY-TAIL AERO
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /IBWH/   PBWH, BWH(380)
      COMMON /IBWHV/  PBWHV, BWHV(380)
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      DIMENSION KEY(3)
      LOGICAL KDWASH
      EQUIVALENCE (KEY(1),KQOQIN), (KEY(2),KEPSLN), (KEY(3),KDEODA)
      NOVLY=28
      CALL EXSUBT
      DO 1000 J=1,3
         KEY(J) = 0
         IF(KDWASH(J)) KEY(J) = 1
 1000 CONTINUE
      CALL SUPWBT(KDEODA,KQOQIN,KEPSLN)
      DO 1010 J=1,NALPHA
         BWHV(J+ 20) = BWH(J+ 20)
         BWHV(J+100) = BWH(J+100)
         BWHV(J+120) = BWH(J+120)
 1010 CONTINUE
      RETURN
      END
C ===== m29o35.f =====
      SUBROUTINE M29O35
C
C***  EXEC FOR OVERLAY 29, LATERAL STABILITY GEOMETRY DATA
C
      COMMON /OVERLY/  IJKDUM(8),NOVLY
      LOGICAL VERTUP
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /WINGD/  A(195),B(49)
      COMMON /SBETA/  STB(135),TRA(108),TRAH(108),STBH(135)
      COMMON /BDATA/  BD(762)
      COMMON /HTDATA/ AHT(195),BHT(48)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /WINGI/  WINGIN(77)
      COMMON /HTI/    HTIN(154)
      COMMON /BODYI/  BODYIN(126)
      DIMENSION ROUTID(2),BODYDP(20)
      DIMENSION WTYPE(4),C1(6),C2(6)
      EQUIVALENCE (SYNA(10),VERTUP)
      DATA ROUTID/4HM29O,4H35  /
      DATA WTYPE/4HSTRA,4HDOUB,4HCRAN,4HCURV/
      DATA I1,I2/2*0/
      NOVLY=29
C
C---------       LATERAL STABILITY GEOMETRY CALCULATIONS         -------
C
      STB(2)= (WINGIN(4)-WINGIN(12))/WINGIN(4)
      STB(3)=1.0
      IF(WGPL.AND.(.NOT.BO)) GO TO 1050
      IF(.NOT.WGPL)GO TO 1060
      SINSYN=SIN(SYNA(4)/RAD)
      STB(1)=-SYNA(3)+(.25*A(10)+BD(66))*SINSYN-(WINGIN(4)-WINGIN(3))
     1       *TAN(WINGIN(13)/RAD)
      STB(4)=-SYNA(3)+WINGIN(6)/4.0*SINSYN
      STB(72)=(WINGIN(4)-WINGIN(3))*2.0
      STB(63)=SYNA(2)+BD(66)+WINGIN(2)*A(86)+A(23)*A(62)+WINGIN(1)/2.
      NV=BODYIN(1)+.5
      IF(BODYIN(82).EQ.UNUSED) GO TO 1010
      CALL TRAPZ(BODYIN(82),NV,BODYIN(2),VARU,1)
      CALL TRAPZ(BODYIN(102),NV,BODYIN(2),VARL,1)
      STB(62)=VARU-VARL
      QL=BD(1)*.25
      TFL=BD(1)*.75
      DO 1000 I=1,NV
 1000 BODYDP(I)=BODYIN(I+81)-BODYIN(I+101)
      CALL TBFUNX(QL,STB(61),DYDX,NV,BODYIN(2),BODYDP(1),C1,I1,MI,NG,
     1            0,0,4HQL  ,1,ROUTID)
      CALL TBFUNX(TFL,STB(60),DYDX,NV,BODYIN(2),BODYDP(1),C2,I2,MI,NG,
     1            0,0,4HTFL ,1,ROUTID)
      CALL GETMAX(BODYIN(2),BODYDP(1),NV,XMAX,STB(59),IMAX)
      GO TO 1020
 1010 CONTINUE
      CALL TRAPZ(BODYIN(62),NV,BODYIN(2),VAR,1)
      STB(62)=2.0*VAR
      QL=BD(1)*.25
      TFL=BD(1)*.75
      CALL TBFUNX(QL,VAR,DYDX,NV,BODYIN(2),BODYIN(62),C1,I1,MI,NG,
     1            0,0,4HQL  ,1,ROUTID)
      STB(61)=2.*VAR
      CALL TBFUNX(TFL,VAR,DYDX,NV,BODYIN(2),BODYIN(62),C2,I2,MI,NG,
     1            0,0,4HTFL ,1,ROUTID)
      STB(60)=2.*VAR
      CALL GETMAX(BODYIN(2),BODYIN(62),NV,XMAX,RMAX,IMAX)
      STB(59)=2.*RMAX
 1020 CONTINUE
      CALL GETMAX(BODYIN(2),BODYIN(62),NV,XMAX,RMAX,IMAX)
      STB(123)=2.*RMAX
      IF(.NOT.VTPL)GO TO 1050
      STB(11)=(SYNA(9)-SYNA(1))+AVT(195)+AVT(122)/4.0
      STB(12)=-SYNA(5)+AVT(136)
      IF(.NOT.VERTUP)STB(12)=-SYNA(5)-AVT(136)
      IF(.NOT.HTPL.OR.SYNA(7).LT.0.0) GO TO 1050
      XPART=SYNA(6)+AHT(161)-SYNA(9)
      IF(VTIN(15).NE.WTYPE(1)) GO TO 1030
      STB(9)=XPART-SYNA(7)*AVT(62)
      STB(10)=VTIN(6)-(VTIN(6)-VTIN(1))*SYNA(7)/VTIN(4)
      GO TO 1050
 1030 IF(SYNA(7).GT.(VTIN(4)-VTIN(2))) GO TO 1040
      STB(9)=XPART-SYNA(7)*AVT(62)
      STB(10)=VTIN(6)-(VTIN(6)-VTIN(5))*SYNA(7)/(VTIN(4)-VTIN(2))
      GO TO 1050
 1040 STB(9)=XPART-(VTIN(4)-VTIN(2))*AVT(62)-(SYNA(7)+VTIN(2)
     1       -VTIN(4))*AVT(86)
      STB(10)=VTIN(1)+(VTIN(5)-VTIN(1))*(VTIN(4)-SYNA(7))/VTIN(2)
 1050 CONTINUE
C
C     CALCULATION OF EFFECTIVE DIHEDRAL ANGLE
C
      IF(WINGIN(13).EQ.UNUSED)WINGIN(13)=0.0
      IF(WINGIN(12).EQ.UNUSED)WINGIN(12)=0.0
      IF(WINGIN(14).EQ.UNUSED)WINGIN(14)=WINGIN(13)
      STB(122)=(WINGIN(13)*(WINGIN(3)-WINGIN(12))+WINGIN(14)*WINGIN(12))
     1         /WINGIN(3)
C
      IF(WGPL.AND.(.NOT.BO).AND.(.NOT.HTPL))RETURN
 1060 IF(.NOT.HTPL) RETURN
      STBH(2)= (HTIN(4)-HTIN(12))/HTIN(4)
      STBH(3)=1.0
      IF(HTPL.AND.(.NOT.BO)) GO TO 1120
      SINSYN=SIN(SYNA(8)/RAD)
      STBH(1)=-SYNA(7)+(.25*A(10)+BD(66))*SINSYN-(HTIN(4)-HTIN(3))
     1        *TAN(HTIN(13)/RAD)
      STBH(4)=-SYNA(7)+HTIN(6)/4.0*SINSYN
      STBH(72)=(HTIN(4)-HTIN(3))*2.0
      STBH(63)=SYNA(6)+BD(66)+HTIN(2)*AHT(86)+AHT(23)*AHT(62)+HTIN(1)/2.
      NV=BODYIN(1)+.5
      IF(BODYIN(82).EQ.UNUSED) GO TO 1080
      CALL TRAPZ(BODYIN(82),NV,BODYIN(2),VARU,1)
      CALL TRAPZ(BODYIN(102),NV,BODYIN(2),VARL,1)
      STBH(62)=VARU-VARL
      QL=BD(1)*.25
      TFL=BD(1)*.75
      DO 1070 I=1,NV
 1070 BODYDP(I)=BODYIN(I+81)-BODYIN(I+101)
      CALL TBFUNX(QL,STBH(61),DYDX,NV,BODYIN(2),BODYDP(1),C1,I1,MI,NG,
     1            0,0,4HQL  ,1,ROUTID)
      CALL TBFUNX(TFL,STBH(60),DYDX,NV,BODYIN(2),BODYDP(1),C2,I2,MI,NG,
     1            0,0,4HTFL ,1,ROUTID)
      CALL GETMAX(BODYIN(2),BODYDP(1),NV,XMAX,STBH(59),IMAX)
      GO TO 1090
 1080 CONTINUE
      CALL TRAPZ(BODYIN(62),NV,BODYIN(2),VAR,1)
      STBH(62)=2.0*VAR
      QL=BD(1)*.25
      TFL=BD(1)*.75
      CALL TBFUNX(QL,VAR,DYDX,NV,BODYIN(2),BODYIN(62),C1,I1,MI,NG,
     1            0,0,4HQL  ,1,ROUTID)
      STBH(61)=2.*VAR
      CALL TBFUNX(TFL,VAR,DYDX,NV,BODYIN(2),BODYIN(62),C2,I2,MI,NG,
     1            0,0,4HTFL ,1,ROUTID)
      STBH(60)=2.*VAR
      CALL GETMAX(BODYIN(2),BODYIN(62),NV,XMAX,RMAX,IMAX)
      STBH(59)=2.*RMAX
 1090 CONTINUE
      CALL GETMAX(BODYIN(2),BODYIN(62),NV,XMAX,RMAX,IMAX)
      STBH(123)=2.*RMAX
      IF(.NOT.VFPL)GO TO 1120
      STBH(11)=(SYNA(12)-SYNA(1))+AVF(195)+AVF(122)/4.0
      STBH(12)=-SYNA(5)+AVF(136)
      IF(VERTUP)STBH(12)=-SYNA(5)-AVF(136)
      IF(.NOT.HTPL.OR.SYNA(7).LT.0.0) GO TO 1120
      XPART=SYNA(6)+AHT(161)-SYNA(12)
      IF(VFIN(15).NE.WTYPE(1)) GO TO 1100
      STBH(9)=XPART-SYNA(7)*AVF(62)
      STBH(10)=VFIN(6)-(VFIN(6)-VFIN(1))*SYNA(7)/VFIN(4)
      GO TO 1120
 1100 IF(SYNA(7).GT.(VFIN(4)-VFIN(2))) GO TO 1110
      STBH(9)=XPART-SYNA(7)*AVF(62)
      STBH(10)=VFIN(6)-(VFIN(6)-VFIN(5))*SYNA(7)/(VFIN(4)-VFIN(2))
      GO TO 1120
 1110 STBH(9)=XPART-(VFIN(4)-VFIN(2))*AVF(62)-(SYNA(7)+VFIN(2)
     1        -VFIN(4))*AVF(86)
      STBH(10)=VFIN(1)+(VFIN(5)-VFIN(1))*(VFIN(4)-SYNA(7))/VFIN(2)
 1120 CONTINUE
C
C     CALCULATION OF EFFECTIVE DIHEDRAL ANGLE
C
      IF(HTIN(13).EQ.UNUSED)HTIN(13)=0.0
      IF(HTIN(12).EQ.UNUSED)HTIN(12)=0.0
      IF(HTIN(14).EQ.UNUSED)HTIN(14)=HTIN(13)
      STBH(122)=(HTIN(13)*(HTIN(3)-HTIN(12))+HTIN(14)*HTIN(12))
     1          /HTIN(3)
      STBH(123) = STB(123)
      RETURN
      END
C ===== m30o36.f =====
      SUBROUTINE M30O36
C
C***  EXEC FOR OVERLAY 30, JET POWER EFFECTS
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /POWR/   PW(315)
      COMMON /IPOWER/ PP, POWER(200)
      COMMON /FLGTCD/ FLC(93)
      COMMON /CONSNT/ CONST(4)
      EQUIVALENCE(CONST(4),RAD)
      DIMENSION CR(6),CRR(6),ROUTID(2)
      DATA ROUTID/ 4HM30O, 4H36  /
      NOVLY=30
      CALL JETPWE
C
C  SET IOM FOR CLA AND CMA AND BODY AXES CN AND CA
C
      IN = 0
      IM = 0
      DO 1000 J=1,NALPHA
         SA = SIN(FLC(J+22)/RAD)
         CA = COS(FLC(J+22)/RAD)
         POWER(J+60) = POWER(J+20)*CA + POWER(J)*SA
         POWER(J+80) = POWER(J)*CA - POWER(J+20)*SA
         CALL TBFUNX(FLC(J+22),X,POWER(J+100),NALPHA,FLC(23),POWER(21),
     1               CR,IN,MI,NG,0,0,4HCLA ,1,ROUTID)
         CALL TBFUNX(FLC(J+22),X,POWER(J+120),NALPHA,FLC(23),POWER(41),
     1               CRR,IM,MI,NG,0,0,4HCMA ,1,ROUTID)
 1000 CONTINUE
      RETURN
      END
C ===== m31o37.f =====
      SUBROUTINE M31O37
C
C***  EXEC FOR OVERLAY 31, SUBSONIC WING CM, BODY CA,CN
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /IWING/  PWING, WING(400)
      COMMON /WINGI/  WINGIN(100)
      COMMON /WINGD/  A(195),B(49)
      COMMON /WHAERO/ C(51)
      COMMON /FLGTCD/ FLC(95)
      COMMON /EXPER/  KK(105),KWING
      DIMENSION C1(6),C3(6),ROUTID(2)
      LOGICAL FLAG,KWING
      DATA ROUTID/ 4HM31O, 4H37  /
      DATA STRA/ 4HSTRA /
      NOVLY=31
      CALL CMALPH(A,B,C,WINGIN,WING)
      CALL CACALC(B,WING)
C
C     SET IOM CN, CA, CLA, AND CMA
C
      CALL EXSUBT
      IN = 0
      IM = 0
      CLA=WING(101)
      CMA=WING(121)
      DO 1000 J=1,NALPHA
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         WING(J+60) = WING(J+20)*CA + WING(J)*SA
         WING(J+80) = WING(J)*CA - WING(J+20)*SA
         CALL TBFUNX(FLC(J+22),X,WING(J+100),NALPHA,FLC(23),WING(21),
     1               C1,IN,MI,NG,0,0,4HCLAW,1,ROUTID)
         CALL TBFUNX(FLC(J+22),X,WING(J+120),NALPHA,FLC(23),WING(41),
     1               C3,IM,MI,NG,0,0,4HCMAW,1,ROUTID)
 1000 CONTINUE
      IN=0
      IM=0
      IF(KWING)CALL TBFUNX(0.,X,CLA,NALPHA,FLC(23),
     1              WING(21),C1,IN,MI,NG,0,0,4HCLAW,1,ROUTID)
      IF(KWING)CALL TBFUNX(0.,X,CMA,NALPHA,FLC(23),
     1              WING(41),C3,IM,MI,NG,0,0,4HCMAW,1,ROUTID)
C
C***  IF THE WING LIFT DEVIATES FROM THE LINEAR VALUE BY
C***  15 PERCENT OR MORE SET CM AND CMA TO NA (2*UNUSED)
C
      IF(A(7) .LE. (6./A(124)) .AND. WINGIN(15) .EQ. STRA) GO TO 1020
      IF(KWING) GO TO 1020
      FLAG=.FALSE.
      DO 1010 J=2,NALPHA
         DEL = 100.*ABS((WING(J+100)/CLA-1.0))
      IF(DEL.GT.90.0) FLAG=.TRUE.
         IF(FLAG) WING(J+40)  = 2.0*UNUSED
         IF(FLAG) WING(J+120) = 2.0*UNUSED
 1010 CONTINUE
 1020 CONTINUE
      WING(101)=CLA
      WING(121)=CMA
      RETURN
      END
C ===== m32o40.f =====
      SUBROUTINE M32O40
C
C***  EXEC FOR OVERLAY 32, SUPERSONIC VERTICAL TAIL LIFT
C
      COMMON /OVERLY/  IJKDUM(8),NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      NOVLY=32
      IF(VTPL) CALL VTLIFT
      IF(VFPL) CALL VFLIFT
      RETURN
      END
C ===== m33o41.f =====
      SUBROUTINE M33O41
C
C**  EXEX FOR OVERLAY 33, SUBSONIC HORIZONTAL TAIL CM
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /HTDATA/ AHT(195),BHT(49)
      COMMON /WHAERO/ C(51),D(55),CHT(51)
      COMMON /IHT/    PHT, HT(380)
      COMMON /HTI/    HTIN(154)
      COMMON /FLGTCD/ FLC(95)
      COMMON /EXPER/  KK(106),KHT
      DIMENSION C1(6), C3(6), ROUTID(2)
      LOGICAL FLAG,KHT
      DATA ROUTID / 4HM33O, 4H41   /
      DATA STRA/ 4HSTRA /
      NOVLY=33
      CALL CMALPH(AHT,BHT,CHT,HTIN,HT)
      CALL CACALC(BHT,HT)
      CALL EXSUBT
      IN = 0
      CLA=HT(101)
      CMA=HT(121)
      IM = 0
      DO 1010 J=1,NALPHA
         CA = COS(FLC(J+22)/RAD)
         SA = SIN(FLC(J+22)/RAD)
         HT(J+60) = HT(J+20)*CA + HT(J)*SA
         HT(J+80) = HT(J)*CA - HT(J+20)*SA
         CALL TBFUNX(FLC(J+22),X,HT(J+100),NALPHA,FLC(23),HT(21),
     1               C1,IN,MI,NG,0,0,4HCLA ,1,ROUTID)
         CALL TBFUNX(FLC(J+22),X,HT(J+120),NALPHA,FLC(23),HT(41),
     1               C3,IM,MI,NG,0,0,4HCMA ,1,ROUTID)
 1010 CONTINUE
      IN=0
      IM=0
      IF(KHT)CALL TBFUNX(0.,X,CLA,NALPHA,FLC(23),HT(21),C1,IN,MI,NG,
     1 0,0,4HCLAH,1,ROUTID)
      IF(KHT)CALL TBFUNX(0.,X,CMA,NALPHA,FLC(23),HT(41),C1,IM,MI,NG,
     1 0,0,4HCMAH,1,ROUTID)
C
C***  IF THE H.T. LIFT DEVIATES FROM THE LINEAR VALUE BY
C***  7.5 PERCENT OR MORE SET CM AND CMA TO NA (2*UNUSED)
C
      IF(AHT(7) .LE. (6./AHT(124)) .AND. HTIN(15) .EQ. STRA) GO TO 1030
      IF(KHT) GO TO 1030
      FLAG=.FALSE.
      DO 1020 J=2,NALPHA
         DEL = 100.*ABS(HT(J+100)/HT(101)-1.0)
         IF(DEL .GT. 7.5) FLAG=.TRUE.
         IF(FLAG) HT(J+40)  = 2.0*UNUSED
         IF(FLAG) HT(J+120)=2.0*UNUSED
 1020 CONTINUE
      HT(101)=CLA
      HT(121)=CMA
 1030 CONTINUE
      RETURN
      END
C ===== m34o42.f =====
      SUBROUTINE M34O42
C
C***  EXEC FOR OVERLAY 34, DEFINE EXPERIMENTAL DATA INPUT
C
      COMMON /OVERLY/  IJKDUM(8),NOVLY
      COMMON /EXPER/ KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1               KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2               ALPOW, ALPLW, ALPOH, ALPLH
C
      NOVLY=34
      IF(KLIST .GE. 1) CALL XPERNM
      RETURN
      END
C ===== m35o43.f =====
      SUBROUTINE M35O43
C
C***  EXEC FOR OVERLAY 35, TRANSONIC AERO
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,IJKDUM(2),NOVLY
C
      NOVLY=35
C
      IF(NF .LT. 0) CALL SETUP2
      IF(NF .GT. 0) CALL WBTRA
      IF(NF .GT. 0) CALL SECLEV
      RETURN
      END
C ===== m36o44.f =====
      SUBROUTINE M36O44
C
C***  EXEC FOR OVERLAY 36, FLAP LIFT AND HINGE MOMENTS
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      COMMON /FLAPIN/ F(69)
      COMMON /IWING/  PWING, WING(400)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      NOVLY=36
      CALL LIFTFP
      IF(TRANSN)RETURN
      IF(F(17).EQ.1.0.OR.F(17).EQ.5.0)CALL HINGE
      DO 1010 J=2,10
 1010 WING(J+250) = -UNUSED
      IF(CTAB) CALL CTABS
      RETURN
      END
C ===== m37o45.f =====
      SUBROUTINE M37O45
C
C***  EXEC FOR OVERLAY 37, FLAP PITCHING MOMENTS
C
      DIMENSION BOC(4)
      LOGICAL ASYFP
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IJKDUM(4),NOVLY
      COMMON /HTDATA/ AHT(195)
      COMMON /FLOLOG/ X(20),ASYFP
      COMMON /FLGTCD/ FLC(93)
      COMMON /FLAPIN/ F(69)
      NOVLY=37
      IF(ASYFP.AND.(F(18).EQ.5.))GO TO 1000
      CALL FLAPCM
      RETURN
 1000 RACH=FLC(I+2)
      BETA=SQRT(1.-RACH**2)
      ARG=AHT(68)/BETA
      SB=ATAN(ARG)*RAD
      CALL GDELTA(GDF,GDI,GDO,ETI,ETO,BOC,SB)
      RETURN
      END
C ===== m38o46.f =====
      SUBROUTINE M38O46
C
C***  EXEC FOR OVERLAY 38, SUBSONIC FLAP DRAG AND TRIM AERO
C
      LOGICAL FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1        HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2        TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /FLAPIN/ F(69)
      COMMON /CONSNT/ CONST(4)
      COMMON /IWING/  PWING, WING(400)
      COMMON /IVT/    PVT, VT(380)
      COMMON /WINGI/  WINGIN(101)
      COMMON /HTI/    HTIN(131)
      EQUIVALENCE (CONST(3),UNUSED)
      NOVLY=38
      IF(TRIM.AND.HTPL.AND.(.NOT.SYMFP ))GO TO 1010
      IF(F(17).LE.6.)CALL DRAGFP
      IF(TRIM)CALL TRIMRT
      VT(301) = WING(251)
      DO 1000 J=2,NALPHA
 1000 VT(J+300) = -UNUSED
      RETURN
C
C     ---- IF CANARD, RETURN
C
 1010 IF(WINGIN(101).GT.2.0) RETURN
      CALL TRIMR2
      VT(301) = WING(251)
      DO 1020 J=2,NALPHA
 1020 VT(J+300) = -UNUSED
      RETURN
      END
C ===== m39o47.f =====
      SUBROUTINE M39O47
C
C***  EXEC FOR OVERLAY 39, PRINT HIGH LIFT AND CONTROL DATA
C
      COMMON /FLAPIN/ F(138)
      COMMON /IBODY/  PBODY,  BODY(400)
      COMMON /IWING/  PWING,  WING(400)
      COMMON /IHT/    PHT,    HT(380)
      COMMON /IVT/    PVT,    VT(380)
      COMMON /OVERLY/ IJKDUM(8),NOVLY
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB,PLOT
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB,PLOT
C
      NOVLY=39
      CALL DUMP2
      CALL OUTPT2
      IF(.NOT. PLOT) GO TO 1000
        WRITE(13,1010) F
        WRITE(13,1010)(BODY(J),J=201,400)
        WRITE(13,1010)(WING(J),J=201,400)
        WRITE(13,1010) (HT(J), J=201,380)
        WRITE(13,1010) (VT(J), J=201,380)
 1000 CONTINUE
 1010 FORMAT(1P,10E12.4)
      RETURN
      END
C ===== m40o50.f =====
      SUBROUTINE M40O50
C
C***  EXEC FOR OVERLAY 40, TRANSONIC LATERAL CONTROL/FLAP AERO
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /FLOLOG/ LOG(19),SYMFLP,ASYFLP
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /IWING/  PW, WING(400)
      LOGICAL SYMFLP,ASYFLP
      NOVLY=40
      CALL TRNYRL
      IF(ASYFLP) GO TO 1010
      DO 1000 J=1,10
         WING(J+220) = UNUSED
         IF(J .EQ. 1) GO TO 1000
         WING(J+250) = -UNUSED
 1000 CONTINUE
 1010 CONTINUE
      RETURN
      END
C ===== m41o51.f =====
      SUBROUTINE M41O51
C
C***  EXEC FOR OVERLAY 41, SUPERSONIC HIGH LIFT AND CONTROL AERO
C
      COMMON /OVERLY/ IJKDUM(8),NOVLY
