C ===== m42o52.f =====
      SUBROUTINE M42O52
C
C***  EXEC FOR OVERLAY 42, HYPERSONIC FLAP AERO
C
      COMMON /IBODY/  PB, BODY(200)
      COMMON /IWING/  PW, WING(200)
      COMMON /IHT/    PHT, HT(200)
      COMMON /IVT/    PVT, VT(200)
      COMMON /FLAPIN/ F(16)
      COMMON /BDATA/  HYP(80)
      COMMON /CONSNT/ CONST(4)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /ERROR/  LL
      LOGICAL LL(46),DMPCSE,DPHYP
      EQUIVALENCE (LL(21),DMPCSE),(LL(46),DPHYP)
      NOVLY=42
      CALL HYPFLP
      IF(DMPCSE .OR. DPHYP) CALL DMPARY(   F, 16,4H   F,4)
      IF(DMPCSE .OR. DPHYP) CALL DMPARY(BODY,200,4HBODY,4)
      IF(DMPCSE .OR. DPHYP) CALL DMPARY(  HT,200,4H  HT,4)
      IF(DMPCSE .OR. DPHYP) CALL DMPARY( HYP, 80,4H HYP,4)
      IF(DMPCSE .OR. DPHYP) CALL DMPARY(  VT,200,4H  VT,4)
      IF(DMPCSE .OR. DPHYP) CALL DMPARY(WING,200,4HWING,4)
C      CALL OUTPT4
      RETURN
      END
C ===== m43o53.f =====
      SUBROUTINE M43O53
C
C***  EXEC FOR OVERLAY 43, DYNAMIC DERIVATIVES
C
      COMMON /CONSNT/ CONST(4)
      COMMON /IWING/  PWING, WING(400)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /WINGD/  A(195),B(49)
      COMMON /WINGI/  WINGIN(101)
      COMMON /POWR/   DYN(213)
      COMMON /IHT/    PHT,HT(380)
      COMMON /HTDATA/ AHT(195),BHT(49)
      COMMON /HTI/    HTIN(154)
      COMMON /BDATA/  BD(300),DYNH(213)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM
      LOGICAL FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1        HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2        TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM
      EQUIVALENCE (CONST(3),UNUSED)
      NOVLY=43
      IF(HYPERS) GO TO 1020
      CALL CMALPO(A,B,WINGIN,DYN)
      IF(SUBSON .OR. TRANSN)CALL SUBPAW
      IF(SUBSON) GO TO 1000
      IF(TRANSN)CALL SUPPAW
      IF(SUPERS) CALL SUPPAW
      IF(TRANSN .OR. SUPERS) CALL SUPCMQ
 1000 CONTINUE
C
C     ONLY FIRST LOCATION COMPUTED, SET REST TO BLANK
C
      DO 1010 J=2,NALPHA
         WING(J+200) = -UNUSED
         WING(J+220) = -UNUSED
         WING(J+240) = -UNUSED
         WING(J+260) = -UNUSED
 1010 CONTINUE
 1020 CONTINUE
      IF(HYPERS) GO TO 1050
      IF(.NOT. HTPL) GO TO 1050
      CALL CMALPO(AHT,BHT,HTIN,DYNH)
      IF(SUBSON .OR. TRANSN)CALL SUBPAH
      IF(SUBSON) GO TO 1030
      IF(TRANSN)CALL SUPPAH
      IF(SUPERS) CALL SUPPAH
      IF(TRANSN .OR. SUPERS) CALL SUPHMQ
 1030 CONTINUE
C
C     ONLY FIRST LOCATION COMPUTED, SET REST TO BLANK
C
      DO 1040 J=2,NALPHA
         HT(J+200) = -UNUSED
         HT(J+220) = -UNUSED
         HT(J+240) = -UNUSED
         HT(J+260) = -UNUSED
 1040 CONTINUE
 1050 CONTINUE
      RETURN
      END
C ===== m44o54.f =====
      SUBROUTINE M44O54
C
C***  EXEC FOR OVERLAY 44, SUPERSONIC WING ALPHA DOT DERIVS
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /IWING/  PWING,WING(400)
      COMMON /IHT/    PHT,HT(380)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,
     2                SUPERS,SUBSON,TRANSN,HYPERS,
     3                SYMFP,ASYFP,TRIMC,TRIM
      LOGICAL FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1        HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,
     2        SUPERS,SUBSON,TRANSN,HYPERS,
     3        SYMFP,ASYFP,TRIMC,TRIM
      NOVLY=44
      IF(WGPL)CALL SUPCLD
      IF(HTPL)CALL SUPHLD
C
C  FIRST LOCATION COMPUTED, SET IOM WITH BLANKS
C
      DO 1000 J=2,NALPHA
        WING(J+240) = -UNUSED
        HT(J+240) = -UNUSED
 1000 CONTINUE
      RETURN
      END
