C ===== m56o70.f =====
      SUBROUTINE M56O70
C
C***  EXEC FOR OVERLAY 56, MACH SHADOWING DATA
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,IJKDUM(3),NOVLY
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /HTI/    HTIN(154)
      COMMON /VTI/    VTIN(154),TVTIN(8),VFIN(154)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON/CONSNT/CONST(4)
      EQUIVALENCE (CONST(3),UNUSED),(VERTUP,SYNA(10))
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL ABORT,VERTUP,FINUP,FLAG
      DATA A/4H****/
      NOVLY=56
      IG=0
      FINUP=.NOT. VERTUP
      SYNA6=SYNA(6)
      SYNA7=SYNA(7)
      FLAG=VTPL.AND.(VTIN(I+94).EQ.UNUSED).OR.(VTIN(I+114).EQ.UNUSED)
     1     .OR.(VTIN(I+134).EQ.UNUSED)
      IF(FLAG)CALL VTAREA(VTIN,AVT,VERTUP,SYNA(9),SYNA(14))
      FLAG=VFPL.AND.(VFIN(I+94).EQ.UNUSED).OR.(VFIN(I+114).EQ.UNUSED)
     1     .OR.(VFIN(I+134).EQ.UNUSED)
      IF(FLAG)CALL VTAREA(VFIN,AVF,FINUP,SYNA(12),SYNA(15))
      IF(.NOT.HTPL) GO TO 1070
      IF(HTIN(94+I).NE.UNUSED.AND.HTIN(114+I).NE.UNUSED.AND.
     1   HTIN(134+I).NE.UNUSED) GO TO 1070
      CALL BDAREA(ABORT)
      IF(.NOT.ABORT) GO TO 1070
      DO 1020 JK=1,5
 1020 WRITE(6,1030) (A,K=1,32)
 1030 FORMAT(3X,32A4)
      WRITE(6,1040)
 1040 FORMAT(//////)
      WRITE(6,1050)
 1050 FORMAT(8X,42HLATERAL STABILITY DERIVATIVES ARE DELETED ,
     1      43HBECAUSE ALL OR PART OF THE HORIZONTAL TAIL ,
     2      34HEXPOSED ROOT CHORD LIES OFF OF THE,//,8X,
     3      44HFUSELAGE. FOR THIS CASE THE NAMELIST HTPLNF ,
     4      45HPARAMETERS SHB, SEXT, AND RLPH MUST BE INPUT ,
     5      12HBY THE USER.)
      WRITE(6,1040)
      DO 1060 JK=1,5
 1060 WRITE(6,1030) (A,K=1,32)
      IG=1
 1070 CONTINUE
      SYNA(6)=SYNA6
      SYNA(7)=SYNA7
      RETURN
      END
C ===== m57o71.f =====
      SUBROUTINE M57O71                                                 M57O71
C                                                                       M57O71
C  PROGRAM TO READ EXTRAPOLATION MESSAGES FROM UNIT 12                  M57O71
C  AND PRINT IN A READABLE FORMAT                                       M57O71
C                                                                       M57O71
      INTEGER ROUT,ROUTL                                                M57O71
      LOGICAL PAIR,PAIRX                                                M57O71
C                                                                       M57O71
C   ROUTINE USES THE IOM AND WORKING DATA ARRAYS TO                     M57O71
C   CONSERVE CORE.  ROUTINE EXECUTES AFTER COMPLETION OF ALL            M57O71
C   CASE COMPUTATIONS.                                                  M57O71
C                                                                       M57O71
      COMMON /IBODY/   PB, AFIG01(121), AFIG02(121)                     M57O71
      COMMON /IWING/   PW, AFIG03(121), AFIG04(121)                     M57O71
      COMMON /IHT/    PHT, AFIG05(121), AFIG06(121)                     M57O71
      COMMON /IVT/    PVT, AFIG07(121), AFIG08(121)                     M57O71
      COMMON /IVF/    PVF, AFIG09(121), AFIG10(121)                     M57O71
      COMMON /IBW/    PBW, AFIG11(121), AFIG12(121)                     M57O71
      COMMON /IBH/    PBH, AFIG13(121), AFIG14(121)                     M57O71
      COMMON /IBV/    PBV, JFIG01(121), JFIG02(121)                     M57O71
      COMMON /IBWH/  PBWH, JFIG03(121), JFIG04(121)                     M57O71
      COMMON /IBWV/  PBWV, JFIG05(121), JFIG06(121)                     M57O71
      COMMON /IBWHV/PBWHV, JFIG07(121), JFIG08(121)                     M57O71
      COMMON /WINGD/       JFIG09(121)                                  M57O71
      COMMON /SBETA/       JFIG10(121), JFIG11(121), JFIG12(121)        M57O71
      COMMON /BDATA/       JFIG13(121), JFIG14(121), JFIG15(121),       M57O71
     1                     JFIG16(121), JFIG17(121)                     M57O71
      COMMON /WHWB/        JFIG18(121)                                  M57O71
      COMMON /WBHCAL/      JFIG19(121)                                  M57O71
      COMMON /HTDATA/      JFIG20(121)                                  M57O71
      COMMON /VTDATA/ LFIGN(121),LFIGO(121),IOVLY,IOVL,NSTQ,NSTP,FINALR,M57O71
     1                NFIG,IFIGN                                        M57O71
      COMMON /WHAERO/ LFIGS(121), IFIGST(20), IEXCD(4), MSSCL(2),       M57O71
     1                ROUT(2), XLL(4), XUL(4), IEXTRL(4,2),             M57O71
     2                IEXTRU(4,2), XVAL(4), LDUM(121), PAIRX            M57O71
      COMMON /ERROR/ DERROR(82),LEXTRP                                  M57O71
      LOGICAL DERROR,LEXTRP                                             M57O71
      DIMENSION IFIG(20,121)                                            M57O71
C                                                                       M57O71
C*** IF PRINT EXTRAP CARD NOT INPUT REURN AND DO NOT DUMP EXTRAPOLATION M57O71
C       MESSAGES                                                        M57O71
      IF(.NOT. LEXTRP)RETURN                                            M57O71
C                                                                       M57O71
C  INITIALIZE ALL ARRAYS AND VARIABLES TO BE USED                       M57O71
C                                                                       M57O71
      CALL CLEARA(IFIG,ROUTL,MSSCLL)                                    M57O71
C                                                                       M57O71
C  WRITE OVERLAY NUMBER OF 999 TO UNIT 12 TO SIGNIFY END OF DATA        M57O71
C  THIS OVERLAY NUMBER HAS BEEN PRE-SET IN SUBROUTINE CLEARA            M57O71
C                                                                       M57O71
      WRITE(12,1090)IOVLY,IOVLY,IOVLY                                   M57O71
C                                                                       M57O71
C   REWIND UNIT 12 AND START READING EXTRAPOLATION MESSAGES             M57O71
C                                                                       M57O71
      REWIND 12                                                         M57O71
      IPRT=60                                                           M57O71
 1000 CALL READXM(IFIG)                                                 M57O71
      IF(IOVLY.NE.IOVL .OR. NFIG.GE.120 .OR. IOVL.EQ.999) GO TO 1020    M57O71
 1010 CONTINUE                                                          M57O71
C                                                                       M57O71
C  TRANSLATE FIGURE NUMBER INTO 9 DIGIT INTEGER WORD                    M57O71
C                                                                       M57O71
      CALL DECFIG(IFIG(1,NFIG),20,IFIGN)                                M57O71
C                                                                       M57O71
C  STORE FIGURE DATA FOR LATER USE                                      M57O71
C                                                                       M57O71
      CALL STORXM                                                       M57O71
      GO TO 1000                                                        M57O71
C                                                                       M57O71
C  SORT FIGURE NUMBERS FOR THIS OVERLAY IN ASCENDING ORDER              M57O71
C                                                                       M57O71
 1020 CONTINUE                                                          M57O71
      IOVM=IOVL                                                         M57O71
      NFIG=NFIG-1                                                       M57O71
      IF(NFIG.LE.0 .AND. IOVLY.EQ.999)GO TO 1060                        M57O71
      CALL SORTER(LFIGN,NFIG,1,0,1,LFIGS,LFIGO,LDUM,IFLAG)              M57O71
C                                                                       M57O71
C  PULL FIGURES IN ASCENDING ORDER                                      M57O71
C                                                                       M57O71
      PAIRX=.TRUE.                                                      M57O71
      DO 1040 I=1,NFIG                                                  M57O71
         IF(IPRT.GE.54)WRITE(6,1070)                                    M57O71
         IF(IPRT.GE.54)WRITE(6,1080)                                    M57O71
         IF(IPRT.GE.54)PAIR=.TRUE.                                      M57O71
         IF(IPRT.GE.54)IPRT=6                                           M57O71
C                                                                       M57O71
C  FIND WHERE THIS FIGURE IS STORED IN THE ARRAYS                       M57O71
C                                                                       M57O71
         JJ=LFIGO(I)                                                    M57O71
         JK=AFIG01(JJ)+0.5                                              M57O71
         CALL WRITXM(IFIG,IPRT,JK,JJ,IOVM,ROUTL,JJ,MSSCLL)              M57O71
         IF(IPRT.GE.54)WRITE(6,1100)                                    M57O71
         IF(IPRT.GE.54)PAIR=.FALSE.                                     M57O71
C                                                                       M57O71
C  SET TEST ARRAYS TO PRESENT FIGURE NUMBER AND ROUTINES                M57O71
C                                                                       M57O71
         DO 1030 K=1,20                                                 M57O71
            IFIGST(K)=IFIG(K,JJ)                                        M57O71
 1030    CONTINUE                                                       M57O71
         MSSCLL=JFIG01(JJ)                                              M57O71
         ROUTL=JFIG03(JJ)                                               M57O71
 1040 CONTINUE                                                          M57O71
      IF(IOVLY.EQ.999 .OR. IOVLY.LE.0)GO TO 1060                        M57O71
      NFIG=NFIG+1                                                       M57O71
      DO 1050 L=1,20                                                    M57O71
         IFIG(L,1)=IFIG(L,NFIG)                                         M57O71
 1050 CONTINUE                                                          M57O71
      NFIG=1                                                            M57O71
C                                                                       M57O71
C  CONTINUE PROCESSING WITH LAST FIGURE READ FROM UNIT 12               M57O71
C                                                                       M57O71
      GO TO 1010                                                        M57O71
 1060 CONTINUE                                                          M57O71
C                                                                       M57O71
C  COMPLETED THE DUMP OF EXTRAPOLATION MESSAGES FOR THIS CASE           M57O71
C  REWIND UNIT 12 TO BEGIN NEXT CASE                                    M57O71
C                                                                       M57O71
      REWIND 12                                                         M57O71
      IF(PAIR)WRITE(6,1100)                                             M57O71
 1070 FORMAT(1H1,50X,29HEXTRAPOLATION MESSAGE SUMMARY/)                 M57O71
 1080 FORMAT(1X,7HOVERLAY,2X,13HFIGURE NUMBER,                          M57O71
     1 26X,35HTYPE OF EXTRAPOLATION (LOWER UPPER)/                      M57O71
     2 11X,11HSUBROUTINES,32X,27HFIGURE LIMITS (LOWER UPPER)/           M57O71
     3 25X,12HFINAL RESULT,20X,21HINDEPENDENT VARIABLES)                M57O71
 1090 FORMAT(3I3)                                                       M57O71
 1100 FORMAT(107H0*NOTE*   MESSAGES HAVE BEEN SORTED WITHIN EACH OVERLAYM57O71
     1 BY FIGURE NUMBER AND DO NOT NECESSARILY CORRESPOND               M57O71
     2 /10X,34HTO THE PROGRAM EXECUTION SEQUENCE.                       M57O71
     3 /9X,53H ** DENOTES THE INDEPENDENT VARIABLE EXCEEDED IN CALL)    M57O71
      RETURN                                                            M57O71
      END                                                               M57O71
C ===== mach2.f =====
      SUBROUTINE MACH2(DNU,XM,IER)
C
C     THIS SUBROUTINE TAKES THE PRANDTL-MEYER ANGLE (DNU) AND SOLVES THE
C     TRANSCENDENTIAL EQUATION FOR THE FLOW MACH NUMBER USING NEWTONS
C     METHOD
C
C     DESCRIPTION OF PARAMETERS -
C       DNU - ARGUMENT VALUE OF PRANDTL-MEYER ANGLE IN DEGREES
C       XM  - RESULTING MACH NUMBER
C       IER - RESULTING ERROR PARAMETER
C           IER=0   NO ERROR
C           IER=1   DNU .LT. 0.0, NO MACH NUMBER SOLUTION, XM=1.0
C           IER=2   DNU .GT. 130 DEG.,  NO NUMERICAL SOLUTION, XM=1000.
C           IER=3   ITERATION DID NOT CONVERGE,DIFFERENCE BETWEEN
C                        CALCULATED AND REQUESTED DNU .GT. 2.0E-6 DEG.
C
C     METHOD -
C         THE EQUATION FOR THE PRANDTL-MEYER EXPANSION ANGLE, FROM
C         NACA REPT. 1135, IS - DNU = SQR6*ATAN(B/SQR6)-ATAN(B), WHERE
C         B = SQRT(XM**2 - 1), AND SQR6 = SQRT(6) = 2.44948974. FOR
C         PROGRAM OPERATIONS DNU IS CONVERTED FROM DEGREES TO RADIANS
C         AND NAMED RNU. IN NEWTONS METHOD, THE EQUATION FOR F(B)
C         IS DEFINED AND BY ITERATION SOLVED FOR B SUCH THAT F(B)=0.0.
C         THE ITERATION FORM IS - B(I+1) = B(I) -F/(DF/DB), WHERE
C              F = F(B) -THE INCREMENT BETWEEN THE PRANDTL-MEYER
C                         ANGLE FOR B(I) AND RNU
C                = SQR6*ATAN(B/SQR6) - ATAN(B) -RNU
C
C              DF/DB - THE FIRST DERIVATIVE OF F(B) WITH RESPECT
C                      TO B
C                    = (5*B**2)/((1+B**2)*(6+B**2))
C
      COMMON /CONSNT/ PI,DEG,UNUSED,DR
      DATA EPS,SQR6 / 2.0E-6, 2.44948974 /
      IER=0
      IF(DNU .LT. 0.0) GO TO 1020
      IF(DNU .EQ. 0.0) GO TO 1030
      IF(DNU.GT.130.) GO TO 1040
      RNU=DNU/DR
      B=1.0
      DO 1000 I=1,30
         F=SQR6*ATAN(B/SQR6)-ATAN(B)-RNU
         IF(ABS(F).LE.EPS) GO TO 1010
         DB=F*(1.+B*B)*(6.+B*B)/(5.*B*B)
         B=B-DB
 1000 CONTINUE
      IER=3
 1010 XM=SQRT(B*B+1.0)
      RETURN
 1020 IER=1
 1030 XM=1.0
      RETURN
 1040 IER=2
      XM=1000.
      RETURN
      END
C ===== main00.f =====
      SUBROUTINE MAIN00
C
C***  TOP LEVEL EXECUTIVE
C
C             IDEAL OUTPUT MATRIX
C
C             BLOCK    PRINT     IOM
C             NAME     FLAG     ARRAY
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
      COMMON /IPOWER/  PPOWER, POWER(200)
      COMMON /IDWASH/  PDWASH, DWASH(60)
C
      LOGICAL PBODY, PWING, PHT, PVT, PVF, PBW, PBH, PBV, PBWH, PBWV,
     1        PBWHV, PPOWER, PDWASH
C
C***  INPUT DATA BLOCKS
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /OPTION/ SREF, CBARR, ROUGFC, BLREF
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /BODYI/  BODYIN(128)
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /POWER/  PWIN(29), LBIN(21)
      COMMON /FLAPIN/ F(138)
C
      DIMENSION ZL(20)
      EQUIVALENCE (ZL(1),BODYIN(102))
      EQUIVALENCE (STMACH,FLC(94)), (TSMACH,FLC(95))
      LOGICAL VERTUP
C
C***  COMPUTATIONAL BLOCKS
C
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /BDATA/  BD(762)
      COMMON /WHWB/   FACT(182), WB(39), HB(39)
      COMMON /WBHCAL/ WBT(156)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /WHAERO/ C(51), D(55), CHT(51), DHT(55), DVT(55), DVF(55)
      COMMON /POWR/   PW(315)
      COMMON /SUPWBB/  SWB(61), SHB(61)
      COMMON /SUPDW/  DWA(237)
      COMMON /SUPWH/  GR(303)
      COMMON /SUPBOD/ SBD(229)
      COMMON /LEVEL2/ SECOND(23)
C
      DIMENSION SLG(141), STG(141), FCM(287), LB(200), DYN(213)
      DIMENSION SPR(59),FLA(45), FLP(189), STP(156), JET(26), SLA(31)
      DIMENSION FHG(35), TCD(58), TRM(22), TRM2(22), TRN(7), DYNH(213)
      DIMENSION SLAH(31)
C
      EQUIVALENCE (GR(1), FCM(1), SLG(1)), (GR(142), STG(1))
      EQUIVALENCE (DWA(1), LB(1), JET(1), FHG(1)), (WBT(1), STP(1))
      EQUIVALENCE (PW(1), DYN(1), SPR(1)), (PW(60), FLA(1))
      EQUIVALENCE (PW(105), FLP(1)), (PW(294), TRM(1), TRM2(1), TRN(1))
      EQUIVALENCE (STB(1), SLA(1)), (DWA(36), TCD(1)), (DYNH(1),BD(301))
      EQUIVALENCE (STB(32), SLAH(1))
C
C***   CONTROL DATA BLOCKS
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF,K
      COMMON /CASEID/ IDCASE(74),KOUNT,NAMSV(100),IDIM
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON /ERROR/  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1                DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2                DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3                DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4                DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5                DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6                DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7                DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8                DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9                DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A                DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1         DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2         DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3         DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4         DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5         DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6         DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7         DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8         DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9         DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A         DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL FLAG
C
C***  HYPERSONIC CONTROLS
C
      FLAG = HYPEF .AND. HYPERS .AND. (FLC(I+2) .GE. 5.0)
      IF(.NOT. (FLAG .OR. TRAJET)) GO TO 1010
C
C***  INITALIZE IOM AND COMPUTATIONAL ARRAYS
C
        IG = 1
        IF(I .NE. 1) CALL M51O63
        IF(FLAG)   CALL M42O52
        IF(TRAJET) CALL M47O57
        GO TO 1050
 1010 CONTINUE
C
C***  SET MACH DATA AND FLAGS, SET EXPERIMENTAL DATA NAMELISTS
C
      SUBSON = .FALSE.
      TRANSN = .FALSE.
      SUPERS = .FALSE.
      TRIM   = .FALSE.
      IF(FLC(I+2) .GE. TSMACH) SUPERS = .TRUE.
      IF(FLC(I+2) .LE. STMACH) SUBSON = .TRUE.
      FLAG = SUPERS .OR. SUBSON
      IF(.NOT. FLAG)           TRANSN = .TRUE.
      B(1) = FLC(I+2)
      B(2) = SQRT(ABS(1.-FLC(I+2)**2))
      BHT(1) = B(1)
      BHT(2) = B(2)
      A(129)   = FLC(I+42)
      AHT(129) = FLC(I+42)
      AVT(129) = FLC(I+42)
      AVF(129) = FLC(I+42)
      NF = 1
      IG = 1
      IF(KLIST .GT. 0) CALL M51O63
      IF(KLIST .GT. 0) CALL M48O60
C
C***  CALCULATE SUBSONIC DATA
C
      IF(.NOT. SUBSON) GO TO 1030
        IF(.NOT. LOASRT) GO TO 1020
          CALL M14O16
          CALL M49O61
          CALL M12O14
 1020   CONTINUE
        IF(LOASRT) GO TO 1030
          CALL MAIN01
 1030 CONTINUE
C
C***  CALCULATE TRANSONIC AND SUPERSONIC DATA
C
      IF(LOASRT) GO TO 1040
      IF(TRANSN) CALL MAIN03
      IF(SUPERS) CALL MAIN04
C
C***  HIGH LIFT AND CONTROL DATA
C
      TRIM = TRIMC
      FLAG = SYMFP .OR. ASYFP .OR. (TRIM .AND. HTPL .AND. SUBSON)
      IF(.NOT. FLAG) GO TO 1040
        IG = 2
        CALL M51O63
        IF(SUBSON) CALL MAIN05
        IF(TRANSN) CALL MAIN06
        IF(SUPERS) CALL MAIN07
        CALL M39O47
 1040 CONTINUE
C
C***  GROUND EFFECTS DATA
C
      FLAG= SUBSON .AND. (FLC(63) .NE. UNUSED) .AND. (.NOT. LOASRT)
      IF(FLAG) CALL MAIN02
 1050 CONTINUE
      RETURN
      END
C ===== main01.f =====
      SUBROUTINE MAIN01
C
C***  DIGITAL DATCOM SUBSONIC AERO EXECUTIVE
C
C***  IDEAL OUTPUT MATRIX
C
C             BLOCK    PRINT     IOM
C             NAME     FLAG     ARRAY
C
      COMMON /IBODY/   PBODY,  BODY(400)
      COMMON /IWING/   PWING,  WING(400)
      COMMON /IHT/     PHT,    HT(380)
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IVF/     PVF,    VF(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
      COMMON /IPOWER/  PPOWER, POWER(200)
      COMMON /IDWASH/  PDWASH, DWASH(60)
C
      LOGICAL PBODY, PWING, PHT, PVT, PVF, PBW, PBH, PBV, PBWH, PBWV,
     1        PBWHV, PPOWER, PDWASH
C
C***  INPUT DATA BLOCKS
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /OPTION/ SREF, CBARR, ROUGFC, BLREF
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /BODYI/  BODYIN(128)
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /POWER/  PWIN(29), LBIN(21)
      COMMON /FLAPIN/ F(116)
C
      DIMENSION ZL(20)
      EQUIVALENCE (ZL(1),BODYIN(102))
      LOGICAL VERTUP
C
C***  COMPUTATIONAL BLOCKS
C
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /BDATA/  BD(762)
      COMMON /WHWB/   FACT(182), WB(39), HB(39)
      COMMON /WBHCAL/ WBT(156)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /WHAERO/ C(51), D(55), CHT(51), DHT(55), DVT(55)
      COMMON /POWR/   PW(315)
      COMMON /SUPWBB/  SWB(61), SHB(61)
      COMMON /SUPDW/  DWA(237)
      COMMON /SUPWH/  GR(303)
      COMMON /SUPBOD/ SBD(229)
C
C
C***   CONTROL DATA BLOCKS
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF
      COMMON /CASEID/ IDCASE(74),KOUNT,NAMSV(100)
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON /ERROR/  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1                DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2                DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3                DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4                DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5                DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6                DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7                DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8                DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9                DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A                DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1         DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2         DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3         DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4         DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5         DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6         DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7         DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8         DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9         DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A         DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL FLAG, KDWASH
      DATA STRA/4HSTRA/
C
C***  INITALIZE IOM AND COMPUTATIONAL ARRAYS
C
      IG = 1
      CALL M51O63
      CALL EXSUBT
C
C***  SET REYNOLDS NO., CLALPA, AND CLMAX IN A-ARRAYS
C
      A(131)   = WINGIN(I+20)
      AHT(131) = HTIN(I+20)
      AVT(131) = VTIN(I+20)
      AVF(131) = VFIN(I+20)
      A(132)   = WINGIN(I+40)
      AHT(132) = HTIN(I+40)
      AVT(132) = VTIN(I+40)
      AVF(132) = VFIN(I+40)
C
C***  SINGLE COMPONENT AERO - BODY, WING, HT, AND VT
C
      IF(.NOT. BO) GO TO 1010
        FLAG = (ZL(1) .EQ. UNUSED) .OR. (BODYIN(128) .GT. 1.50)
        IF(.NOT. FLAG) CALL M04O04
        IF(   FLAG   ) CALL M06O06
 1010 CONTINUE
      IF(.NOT. WGPL) GO TO 1020
        CALL M15O17
        CALL M03O03
        CALL M31O37
        BD(69) = C(6)*A(10)
        BD(70) = BD(68)-BD(69)*BD(78)-BD(82)
        BD(71) = BD(67)-BD(69)*BD(79)
        BD(72) = (BD(71)+BD(70)*BD(80))*BD(79)
        BD(73) = (BD(70)/BD(79))-(BD(71)+BD(70)*BD(80))*BD(78)
 1020 CONTINUE
      IF(.NOT. HTPL) GO TO 1030
        CALL M16O20
        CALL M05O05
        CALL M33O41
 1030 CONTINUE
      IF(VTPL .OR. VFPL) CALL M08O10
      CALL EXSUBT
C
C***  CALCULATE B-W, B-H, AND B-V DATA
C
      FLAG = BO .AND. (WGPL .OR. HTPL .OR. VTPL .OR. VFPL)
      BD(83) = A(161) + XW
      IF(FLAG) CALL M07O07
      IF(FLAG) CALL EXSUBT
C
C***  CALCULATE B-W-H, B-W-V, AND B-W-H-V
C
      FLAG = BO .AND. WGPL .AND. (HTPL .OR. VTPL .OR. VFPL)
      IF(.NOT. FLAG) GO TO 1060
        FLAG = (KDWASH(1) .AND. KDWASH(2) .AND. KDWASH(3)) .OR.
     1         (WINGIN(15) .EQ. STRA)
        IF(.NOT. FLAG) GO TO 1040
          IF(WINGIN(15) .EQ. STRA .AND. HTPL)
     1      CALL M09O11
          CALL M10O12
 1040   CONTINUE
        IF( FLAG) GO TO 1050
          BUILD = .TRUE.
          PART  = .TRUE.
 1050   CONTINUE
 1060 CONTINUE
C
C***  LATERAL STABILITY DERIVATIVES AND POWER EFFECTS
C
      CALL M29O35
      CALL M17O21
      IF(NF .LT. 0) GO TO 1080
      IF(PRPOWR) CALL M13O15
      IF(JETPOW) CALL M30O36
      CALL M49O61
C
C***  DYNAMIC STABILITY
C
      IF(.NOT. DAMP) GO TO 1070
        IG = 3
        CALL M51O63
        IF(WGPL) CALL M43O53
        IF(WGPL .OR. HTPL) CALL M45O55
        CALL M46O56
 1070 CONTINUE
C
C***  PRINT DATA, RETURN TO MAIN00
C
      CALL M12O14
 1080 CONTINUE
      RETURN
      END
C ===== main02.f =====
      SUBROUTINE MAIN02
C
C***  SUBSONIC GROUND EFFECTS DATA EXECUTIVE
C
      COMMON /FLGTCD/ FLC(93), STMACH, TSMACH, TR
      COMMON /FLAPIN/ F(116)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF
C
C***  FLAP AND GROUND HEIGHT LOOPS
C
      NGR = FLC(63)+0.5
      NFP = F(16)+0.5
      IF(NFP .EQ. 0)NFP=1
C
C     THIS WAS DONE IN CASE NFP=0, WITH FTN 77 (V) LOOP DOES NOT EXECUTE
C
      DO 1020 NF=1,NFP
        DO 1010 IG=1,NGR
          CALL M11O13
          CALL M12O14
 1010   CONTINUE
 1020 CONTINUE
      RETURN
      END
C ===== main03.f =====
      SUBROUTINE MAIN03
C
C***  TRANSONIC AERO EXECUTIVE
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /WINGI/  WINGIN(101)
      COMMON /HTI/    HTIN(154)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /LEVEL2/ SECOND(23)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
C
      LOGICAL DONE, DOL2, FLAG
      EQUIVALENCE (SECOND(15),DONE), (SECOND(16),DOL2)
C
      DATA STRA / 4HSTRA /
C
      DOL2 = ((WINGIN(15) .EQ. STRA) .OR. (.NOT. WGPL)) .AND.
     1       ((HTIN(15)   .EQ. STRA) .OR. (.NOT. HTPL))
      IF(DONE .OR. .NOT. DOL2) GO TO 1020
        NF = -1
        CALL M24O30
 1010   CONTINUE
        CALL M35O43
        IF(NF .GE. -5)                 CALL MAIN01
        IF(NF .EQ. -6 .OR. NF .EQ. -7) CALL MAIN04
        IF(NF .GE. -7)                 GO TO 1010
 1020 CONTINUE
      NF = 1
      IG = 1
      CALL M51O63
      CALL EXSUBT
      CALL M18O22
      IF(.NOT. BO) GO TO 1030
        CALL M06O06
        CALL M19O23
 1030 CONTINUE
      CALL M24O30
      FLAG = BO .AND. (WGPL .OR. HTPL)
      IF(DOL2) CALL M25O31
      CALL EXSUBT
      IF(FLAG) CALL M29O35
      IF(FLAG) CALL M17O21
      CALL M35O43
      CALL M49O61
C
C***  DYNAMIC STABILITY
C
      IF(.NOT. DAMP) GO TO 1040
        IG = 3
        CALL M51O63
        IF(WGPL) CALL M43O53
        CALL M46O56
 1040 CONTINUE
C
C***  PRINT DATA, RETURN TO MAIN00
C
      CALL M12O14
      DOL2 = .FALSE.
      RETURN
      END
C ===== main04.f =====
      SUBROUTINE MAIN04
C
