      COMMON /BODYI/  BODYIN(128)
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /POWER/  PWIN(29), LBIN(21)
      COMMON /FLAPIN/ F(116)
C
      DIMENSION ZL(20)
      EQUIVALENCE (ZL(1),BODYIN(102))
      LOGICAL VERTUP
C
C***  COMPUTATIONAL BLOCKS
C
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /BDATA/  BD(762)
      COMMON /WHWB/   FACT(182), WB(39), HB(39)
      COMMON /WBHCAL/ WBT(156)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /WHAERO/ C(51), D(55), CHT(51), DHT(55), DVT(55), DVF(55)
      COMMON /POWR/   PW(315)
      COMMON /SUPWBB/  SWB(61), SHB(61)
      COMMON /SUPDW/  DWA(237)
      COMMON /SUPWH/  GR(303)
      COMMON /SUPBOD/ SBD(229)
C
      EQUIVALENCE (DWA(237),JDETCH)
C
C***   CONTROL DATA BLOCKS
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF
      COMMON /CASEID/ IDCASE(74),KOUNT,NAMSV(100)
      COMMON /EXPER/  KLIST, NLIST(100), NNAMES, IMACH, MDATA,
     1                KBODY, KWING, KHT, KVT, KWB, KDWASH(3),
     2                ALPOW, ALPLW, ALPOH, ALPLH
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON /ERROR/  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1                DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2                DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3                DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4                DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5                DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6                DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7                DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8                DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9                DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A                DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1         DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2         DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3         DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4         DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5         DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6         DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7         DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8         DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9         DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A         DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL FLAG, KDWASH
      DATA STRA/4HSTRA/
C
C***  INITALIZE IOM AND COMPUTATIONAL ARRAYS
C
      IG = 1
      CALL M51O63
      CALL EXSUBT
C
C***  BYPASS SUPERSONIC AERO IF GROUND OR POWER EFFECTS PRESENT
C
      FLAG = (FLC(63) .NE. UNUSED) .OR. PRPOWR .OR. JETPOW
      IF(FLAG) GO TO 1080
C
C***  SINGLE COMPONENT AERO - BODY, WING, AND HT
C
      IF(.NOT. BO) GO TO 1010
        METHOD = BODYIN(128)+0.5
        FLAG = HYPERS .AND. (METHOD .EQ. 1)
        IF(.NOT. FLAG) CALL M19O23
        IF(FLAG)       CALL M26O32
 1010 CONTINUE
      FLAG = WGPL .OR. HTPL .OR. VTPL .OR. VFPL
      IF(FLAG) CALL M18O22
      IF(WGPL) CALL M27O33
      IF(HTPL) CALL M22O26
      CALL EXSUBT
C
C***  CALCULATE VT, B-W, B-H, B-V, AND B-W-V DATA
C
      FLAG = (VTPL .OR. VFPL) .OR. (BO .AND. (WGPL .OR. HTPL))
      IF(FLAG) CALL M20O24
      IF(FLAG) CALL EXSUBT
C
C***  CALCULATE B-W-H AND B-W-H-V
C
      FLAG = BO .AND. WGPL .AND. HTPL
      IF(.NOT. FLAG) GO TO 1040
        FLAG = (KDWASH(1) .OR. KDWASH(2) .OR. KDWASH(3)) .OR.
     1         (WINGIN(15) .EQ. STRA)
        IF(.NOT. FLAG) GO TO 1020
          CALL M21O25
          CALL M28O34
 1020   CONTINUE
        IF(FLAG) GO TO 1030
          BUILD = .TRUE.
          PART  = .TRUE.
          JDETCH = 0
 1030   CONTINUE
 1040 CONTINUE
C
C***  LATERAL STABILITY DERIVATIVES
C
      CALL M56O70
      LF = 0
      IF(IG .EQ. 1) GO TO 1050
        FLAG = WGPL .OR. HTPL .OR. VTPL .OR. VFPL
        IF(VTPL .OR. VFPL) CALL M32O40
        IF(FLAG)           CALL M23O27
 1050 CONTINUE
      IF(NF .LT. 0) GO TO 1080
      CALL M49O61
C
C***  DYNAMIC STABILITY
C
      IF(.NOT. DAMP) GO TO 1070
        IG = 3
        CALL M51O63
        IF(HYPERS .OR. .NOT. WGPL) GO TO 1060
          CALL M43O53
          CALL M44O54
          CALL M54O66
          CALL M45O55
 1060   CONTINUE
        CALL M46O56
 1070 CONTINUE
C
C***  PRINT DATA, RETURN TO MAIN00
C
      CALL M12O14
 1080 CONTINUE
      RETURN
      END
C ===== main05.f =====
      SUBROUTINE MAIN05
C
C***  SUBSONIC HIGH LIFT AND CONTROL DEVICES EXECUTIVE
C
      COMMON /FLAPIN/ F(116)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART
      LOGICAL FLAG
C
C***  SYMMETRICAL FLAPS
C
      IF(.NOT. SYMFP) GO TO 1010
        JETFLP=F(74)+0.5
        IF(JETFLP .GE. 1) CALL M55O67
        IF(JETFLP .GE. 1) GO TO 1010
        F(16) = F(16)+1.0
        NDELTA = F(16)+0.5
        F(NDELTA) = 0.0
        CALL M36O44
        CALL M37O45
        CALL M38O46
        F(16) = F(16)-1.0
 1010 CONTINUE
C
C***  ASYMETRICAL FLAPS
C
      IF(.NOT. ASYFP) GO TO 1020
        IF(F(18) .EQ. 5.0) CALL M37O45
        CALL M52O64
 1020 CONTINUE
C
C***  ALL MOVEABLE HORIZONTAL TAIL TRIM
C
      FLAG = .NOT.(SYMFP .OR. ASYFP) .AND. (TRIM .AND. HTPL)
      IF(FLAG) CALL M38O46
      RETURN
      END
C ===== main06.f =====
      SUBROUTINE MAIN06
C
C***  TRANSONIC HIGH LIFT AND CONTROL DEVICES EXECUTIVE
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF
      COMMON /FLGTCD/ FLC(95)
      COMMON /FLAPIN/ F(116)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART
      LOGICAL FLAG
C
C***  FLAP DATA
C
      IF(SYMFP) CALL M36O44
      IF(.NOT. ASYFP) GO TO 1000
        CALL M52O64
        FLAG = (F(18) .EQ. 5.0) .AND. (FLC(I+2) .LT. 1.0)
        IF(FLAG) CALL M37O45
 1000 CONTINUE
      CALL M40O50
      RETURN
      END
C ===== main07.f =====
      SUBROUTINE MAIN07                                                 MAIN07
C                                                                       MAIN07
C***  SUPERSONIC HIGH LIFT AND CONTROL DEVICES EXECUTIVE                MAIN07
C                                                                       MAIN07
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,  MAIN07
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,   MAIN07
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,        MAIN07
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART              MAIN07
C                                                                       MAIN07
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,         MAIN07
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,          MAIN07
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,               MAIN07
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART                     MAIN07
C                                                                       MAIN07
      IF(SYMFP) CALL M41O51                                             MAIN07
      IF(ASYFP) CALL M53O65                                             MAIN07
      RETURN                                                            MAIN07
      END                                                               MAIN07
C ===== majerr.f =====
      SUBROUTINE MAJERR
C
C     ----TESTS FOR MISSING ESSENTIAL NAMELISTS
C
      COMMON /FLAPIN/ F(138)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      COMMON /ERROR/  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1                DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2                DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3                DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4                DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5                DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6                DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7                DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8                DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9                DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A                DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL  IERR,GONOGO,IEND,DMPALL,DPB,DPA,DPBD,DPAVF,
     1         DPFACT,DPWBT,DPBHT,DPAVT,DPAHT,DPC,DPD,DPWB,
     2         DPCHT,DPDHT,DPDYNH,SAVE,DMPCSE,DPDVT,DPGR,DPLB,
     3         DPPW,DPSTB,DPSBD,DPSLG,DPSWB,DPSTP,DPDWA,DPSTG,
     4         DPSLA,DPTRA,DPEXPD,DPDVF,DPFLP,DPFHG,DPFCM,DPTCD,
     5         DPFLA,DPTRM,DPSPR,DPTRN,DPTRM2,DPHYP,DPDYN,DPJET,
     6         DPHB,DPSHB,DPTRAH,DPSTBH,DPSEC,DPSLAH,DPINPT,
     7         DPFLC,DPOPTN,DPSYN,DPBDIN,DPWGIN,DPVTIN,DPTVT,
     8         DPVFIN,DPHTIN,DPPWIN,DPLBIN,DPF,DPIOM,
     9         DPIBDY,DPIWG,DPIHT,DPIVT,DPIVF,DPIBW,DPIBH,DPIBV,
     A         DPIBWH,DPIBWV,DPITOT,DPIPWR,DPIDWH
      LOGICAL LOGCOM(10)
      EQUIVALENCE (LOGCOM(1),FLTC)
C
C     ----TEST FOR FLIGHT CONDITIONS IF ABSENT CANNOT RUN.
C
      IF(FLTC) GO TO 1010
      WRITE(6,1000)
 1000 FORMAT(57H0ERROR-FLIGHT CONDITIONS NOT PRESENT-MISSING NAME*FLTCON
     1* )
      IERR=.TRUE.
C
C     ----TEST FOR SYNTHESIS QUANTITIES.IF ABSENT NO RUN.
C
 1010 IF(SYNT) GO TO 1030
      WRITE(6,1020)
 1020 FORMAT(50H0ERROR-SYNTHESIS DATA MISSING-MISSING NAME*SYNTHS* )
      IERR=.TRUE.
C
C     ----TEST FOR WING
C
 1030 IF(WGPL.AND.WGSC) GO TO 1070
C
C     ----TEST FOR PLANFORM OR SECTION CHARACTERISTICS PRESENT.
C
      IF(WGPL.OR.WGSC) GO TO 1040
      GO TO 1070
C
C     ----HERE FOR PART OF WING DATA MISSING.
C
 1040 IF(WGPL) WRITE(6,1050)
 1050 FORMAT(84H0ERROR-WING PLANFORM PRESENT BUT SECTION CHARACTERISTICS
     1 ABSENT-MISSING NAME*WGSCHR* )
      IF(WGSC) WRITE(6,1060)
 1060 FORMAT(84H0ERROR-WING SECTION CHARACTERISTICS PRESENT BUT PLANFORM
     1 ABSENT-MISSING NAME*WGPLNF* )
      IERR=.TRUE.
C
C     ----TEST FOR HORIZONTAL TAIL.
C
 1070 IF(HTSC.AND.HTPL)GO TO 1110
      IF(HTSC.OR.HTPL)GO TO 1080
      GO TO 1110
C
C     ----TEST FOR
C
 1080 IF(HTSC) WRITE(6,1090)
 1090 FORMAT(61H0MISSING PLANFORM FOR HORIZONTAL TAIL-MISSING NAME IS*HT
     1PLNF* )
      IF(HTPL) WRITE(6,1100)
 1100 FORMAT(68H0MISSING SECTION CHARACTERISTICS FOR HORIZONTAL TAIL-NAM
     1E IS*HTSCHR* )
      IERR=.TRUE.
C
C     ----HAVE HORIZONTAL TAIL-TEST FOR WING AND BODY
C
 1110 IF(.NOT.VTSC)GO TO 1130
      IF(VTPL) GO TO 1130
      WRITE(6,1120)
 1120 FORMAT(80H0ERROR-MUST HAVE VERTICAL TAIL PLANFORM WHEN V.T.PRESENT
     1-MISSING NAME IS*VTPLNF* )
      IERR=.TRUE.
 1130 IF(IERR) WRITE(6,1140)
 1140 FORMAT(42H0THIS CASE ABORTED FOR THE ABOVE REASON(S) /
     1  34H ALL NAMES REFER TO NAMELIST NAMES )
C
      IF(.NOT. CTAB) GO TO 1160
      ITYPE = F(17)+0.5
      IF(SYMFP .AND. (ITYPE .EQ. 1)) GO TO 1160
        CTAB = .FALSE.
        WRITE(6,1150)
 1150   FORMAT(45H0 ERROR - MUST HAVE PLAIN TRAILING EDGE FLAP ,
     1         27HWHEN CONTROL TABS ARE INPUT,/
     2         9X,40H CONTROL TAB DATA WILL NOT BE CALCULATED/)
 1160 CONTINUE
      RETURN
      END
C ===== masrat.f =====
      SUBROUTINE MASRAT(R2OBO2,R1OBA,ZHOR1,AMRK)
C
C     ----ROUTINE USES DATCOM METHOD 3 TO COMPUTE APPARENT MASS RATIO K
C
      DIMENSION ROUTID(2),Q1125B(3),Q1125C(3),Q1125E(3),Q1125F(3),
     1          Q1125H(3),Q1125I(3),Q1125J(3),Q1125K(3),Q1125M(3)
      LOGICAL EXACTP
      DIMENSION AN(5),C25B(6),C225U(6),R225U(5),CK(6),AK(3),ZK(3)
      DIMENSION R1125B(6),F1125B(6)
      DIMENSION R1125H(8),F1125H(8),C25H(6),R1125I(8),F1125I(8),C25I(6),
     1          R1125J(7),F1125J(7),C25J(6),R1125K(6),F1125K(6),C25K(6)
      DIMENSION F1125M(2),R1125M(2),C25M(6)
      DIMENSION F1125C(9),R1125C(9),C25C(6),
     1          F1125E(9),R1125E(9),C25E(6),F1125F(9),R1125F(9),C25F(6)
      DATA ROUTID/4HMASR,4HAT  /,
     1 Q1125B /4H5.3.,4H1.1-,4H25B /,
     2 Q1125C /4H5.3.,4H1.1-,4H25C /,
     3 Q1125E /4H5.3.,4H1.1-,4H25E /,
     4 Q1125F /4H5.3.,4H1.1-,4H25F /,
     5 Q1125H /4H5.3.,4H1.1-,4H25H /,
     6 Q1125I /4H5.3.,4H1.1-,4H25I /,
     7 Q1125J /4H5.3.,4H1.1-,4H25J /,
     8 Q1125K /4H5.3.,4H1.1-,4H25K /,
     9 Q1125M /4H5.3.,4H1.1-,4H25M /
      DATA R225U /0.,0.2,0.4,0.6,0.8/
C
C     ----FIGURE 5.3.1.1-25B
C
      DATA F1125B / 1.,1.44,1.97,2.58,3.25,4.0/
      DATA R1125B / 0.,.2,.4,.6,.8,1.0/
      DATA I25B/0/
C
C     ----FIGURE 5.3.1.1-25C (PARTIAL - R1/B = 1. ONLY)
C
      DATA F1125C /.39,.96,1.3,1.9,2.28,2.56,2.77,3.0,3.9/ ,I25C /0/
      DATA R1125C/0.,.1,.2,.4,.525,.61,.675,.74,1.0/
C
C     ----FIGURE 5.3.1.1-25E (PARTIAL - R1/B = 1. ONLY)
C
      DATA R1125E /0.,.23,.33,.41,.53,.68,.7,.745,1.0/,I25E/0/
      DATA F1125E /.51,1.23,1.6,1.83,2.25,2.75,2.85,3.0,4.0/
C
C     ----FIGURE 5.3.1.1-25F (PARTIAL - R1/B = 1. ONLY)
C
      DATA R1125F /0.,.22,.32,.4,.52,.66,.7,.735,1.0/,I25F/0/
      DATA F1125F /.505,1.19,1.5,1.79,2.2,2.68,2.84,3.0,4.0/
C
C     ----FIGURE 5.3.1.1-25M (FOR R1/B=1.0 ONLY)
C
      DATA R1125M/0.,1./,F1125M/.5,5.75/,I25M/0/
C
C     -----FIGURE 5.9.1.1-25H (ONLY INCLUDES R1/B=1.)
C
      DATA R1125H/0.,.1,.15,.2,.25,.3,.5,1.0/,I25H/0/
      DATA F1125H /.5,.84,.93,.99,1.01,1.02,1.06,1.06/
C
C     -----FIGURE 5.9.1.1-25I (ONLY INCLUDES R1/B=1.)
C
      DATA R1125I /0.,.1,.2,.3,.4,.5,.6,1./,I25I/0/
      DATA F1125I /.5,.8,1.,1.1,1.18,1.2,1.22,1.23/
C
C     -----FIGURE 5.9.1.1-25J (ONLY INCLUDES R1/B=1.)
C
      DATA R1125J / 0.,.2,.3,.4,.5,.7,1.0/,I25J/0/
      DATA F1125J /.5,1.02,1.2,1.33,1.4,1.45,1.45/
C
C     -----FIGURE 5.9.1.1-25K (ONLY INCLUDES R1/B=1.)
C
      DATA R1125K /0.,.3,.4,.5,.7,1.0/,I25K/0/
      DATA F1125K /.5,1.26,1.43,1.55,1.66,1.7/
      DATA ZK/-1.,0.,1./
C
C     ----FUNCTION COMPUTES STRAIGHT LINE.
C
      PLINE(X1,X2,Y1,Y2,XV)=Y1+(XV-X1)*(Y2-Y1)/(X2-X1)
      EXACTP=.TRUE.
C
C     ----TEST FOR HORIZONTAL SURFACE POSITION ON CENTER LINE.
C
      IF(ZHOR1.EQ.0.0)GO TO 1000
C
C     ----TEST FOR HORIZONTAL SURFACE TANGENT ON SAME SIDE AS PANEL
C
      IF(ZHOR1.EQ.1.0)GO TO 1010
C
C     ----TEST FOR HORIZONTAL SURFACE TANGENT ON OPPOSITE SIDE OF PANEL.
C
      IF(ZHOR1.EQ.-1.0)GO TO 1020
      EXACTP=.FALSE.
C
C     ----HERE FOR MID POSITION OF HORIZONTAL SURFACE
C
 1000 CALL TBFUNX(R1OBA,AN(1),DMM, 6,R1125B,F1125B,C25B,I25B,M0,NG,
     1            0,0,Q1125B,3,ROUTID)
      CALL TBFUNX(R1OBA,AN(2),DMM, 9,R1125C,F1125C,C25C,I25C,M1,NG,
     1            0,0,Q1125C,3,ROUTID)
C
C     ----FIGURE 5.3.1.1-25D FOR R1/B=1. ONLY.USE 2 ST. LINES.
C
      IF(R1OBA.LE.0.74)AN(3)=PLINE(0.,.74,.52,3.0,R1OBA)
      IF(R1OBA.GT.0.74)AN(3)=PLINE(.74,1.0,3.0,4.,R1OBA)
      IF(R1OBA.LT.0.)AN(3)=.52
      IF(R1OBA.GT. 1.)AN(3)=4.
      CALL TBFUNX(R1OBA,AN(4),DMM, 9,R1125E,F1125E,C25E,I25E,M3,NG,
     1            0,0,Q1125E,3,ROUTID)
      CALL TBFUNX(R1OBA,AN(5),DMM, 9,R1125F,F1125F,C25F,I25F,M4,NG,
     1            0,0,Q1125F,3,ROUTID)
      I225U=0
      CALL TBFUNX(R2OBO2,AMRK,DMM, 5,R225U,AN,C225U,I225U,M5,NG,
     1            0,0,4HMID ,1,ROUTID)
      IF(EXACTP)RETURN
      AK(2)=AMRK
C
C     ----HERE FOR TAIL SAME SIDE AS ADDED PANEL
C     ----DO TABLE 5.3.1.1-25G USING EQUATION
C
 1010 AN(1)=1.0
      CALL TBFUNX(R1OBA,AN(2),DMM, 8,R1125H,F1125H,C25H,I25H,M6,NG,
     1            0,0,Q1125H,3,ROUTID)
      CALL TBFUNX(R1OBA,AN(3),DMM, 8,R1125I,F1125I,C25I,I25I,M7,NG,
     1            0,0,Q1125I,3,ROUTID)
      CALL TBFUNX(R1OBA,AN(4),DMM, 7,R1125J,F1125J,C25J,I25J,M8,NG,
     1            0,0,Q1125J,3,ROUTID)
      CALL TBFUNX(R1OBA,AN(5),DMM, 6,R1125K,F1125K,C25K,I25K,M9,NG,
     1            0,0,Q1125K,3,ROUTID)
      I225U=0
      CALL TBFUNX(R2OBO2,AMRK,DMM, 5,R225U,AN,C225U,I225U,MA,NG,
     1            0,0,4HSAME,1,ROUTID)
C
C     ----TEST FOR TANGENT TO BODY
C
      IF(EXACTP)RETURN
C
C     ----HERE IF NOT TANGENT TO BODY
C
      AK(3)=AMRK
C
C     ----HERE FOR TAIL LOW (OPPOSITE SIDE AS ADDED PANEL.)
C     ----FIGURE 5.3.1.1-25L . USE 2 ST. LINES
C
 1020 IF(R1OBA.LE.0.45)AN(1)=PLINE(0.,.45,1.03,3.,R1OBA)
      IF(R1OBA.GT.0.45)AN(1)=PLINE(.45,1.0,3.,6.,R1OBA)
      IF(R1OBA.LT.0.0)AN(1)=1.03
      IF(R1OBA.GT.1.0)AN(1)=6.0
      CALL TBFUNX(R1OBA,AN(2),DMM,2,R1125M,F1125M,C25M,I25M,MC,NG,
     1            0,0,Q1125M,3,ROUTID)
C
C     ----FIGURE 5.3.1.1-25N
C
      IF(R1OBA.LE.0.56)AN(3)=PLINE(0.,.56,.5,3.0,R1OBA)
      IF(R1OBA.GT.0.56)AN(3)=PLINE(.56,1.0,3.,5.2,R1OBA)
      IF(R1OBA.LT.0.0)AN(3)=.5
      IF(R1OBA.GT.1.0)AN(3)=5.2
C
C     ----FIGURE 5.3.1.1-25O FOR R1/B=1.0 ONLY
C
      IF(R1OBA.LE.0.63)AN(4)=PLINE(0.,.63,.5,3.,R1OBA)
      IF(R1OBA.GT.0.63)AN(4)=PLINE(.63,1.0,3.,4.7,R1OBA)
      IF(R1OBA.LT.0.)AN(4)=.5
      IF(R1OBA.GT.1.0)AN(4)=4.7
C
C     ----FIGURE 5.3.1.1-25P
C
      IF(R1OBA.LE.0.67)AN(5)=PLINE(0.,.67,.5,3.,R1OBA)
      IF(R1OBA.GT.0.67)AN(5)=PLINE(.67,1.,3.,4.5,R1OBA)
      IF(R1OBA.LT.0.)AN(5)=.5
      IF(R1OBA.GT.1.)AN(5)=4.5
      I225U=0
      CALL TBFUNX(R2OBO2,AMRK,DMM, 5,R225U,AN,C225U,I225U,MI,NG,
     1            0,0,4HOPST,1,ROUTID)
C
C     ----TEST FOR TANGENT TO BODY
C
      IF(EXACTP)RETURN
C
C     ----HERE IF NOT TANGENT TO BODY
C
      AK(1)=AMRK
      IK=0
C
C     ----INTERPOLATE USING 3 POINTS.
C
      CALL TBFUNX(ZHOR1,AMRK,DMM,3,ZK,AK,CK,IK,MI,NG,
     1            0,0,4H3 PT,1,ROUTID)
      RETURN
      END
C ===== maxcl.f =====
      SUBROUTINE MAXCL
C
C  CALCULATE CLMAX AT FLIGHT CONDITIONS
C
      COMMON /IBODY/ PB, NACA(80), BF(232), CBAR
      COMMON /IBWH/   PBWH,AI,ALO,CLI,ASEP,CMCO4,CLA0,CLA(20),CLMAX0,
     1                CLMAX(20)
      COMMON /IBWHV/  PBWHV, RHO,TMAX,DELTAY,XOVC,TOVC,COVC,CXVC,CAMBER
      COMMON /FLGTCD/ FLC(93)
C
      DIMENSION PARM58(26),EVAL58(52),PARM59(30),EVAL59(160),
     1          PARM60(20),EVAL60(30),PARM61(16),EVAL61(32),
     2          PARM62(8),EVAL62(8),VAR(4),LEN(4),ROUT(2),C(6)
      LOGICAL CAMBER
C
      DATA PARM58 /0.,1.,1.1,1.25,1.50,2.00,2.25,2.50,3.00,3.50,4.00,
     1    4.50,5.00,.3,.35,.4,.45,9*0./
      DATA EVAL58 /2*.8,.81,.85,.98,1.2,1.31,1.43,1.58,1.59,1.55,1.47,
     1    1.42,2*.8,.81,.85,.98,1.2,1.31,1.43,1.51,1.52,1.48,1.41,1.41,
     2    2*.8,.81,.85,.98,1.2,1.31,1.39,1.44,1.45,1.43,1.35,1.35,
     3    2*.8,.81,.85,.98,1.2,1.29,1.33,1.35,1.35,1.35,1.35,1.35/
      DATA PARM59 /0.,1.,1.5,2.,2.5,3.,3.5,4.,4.5,5.,0.,.02,.04,.06,
     1    6*0.,.15,.30,.40,.50,6*0./
      DATA EVAL59 /10*0.,
     1 0.,.12,.23,.32,.23,.12,.07,.07,.06,.03,
     2 0.,.27,.36,.40,.30,.16,3*.1,.06,
     3 0.,.27,.36,.40,.30,.16,3*.1,.06,
     4 10*0.,
     5 2*0.,.17,.22,.25,.15,.08,.06,.08,.02,
     6 0.,.15,.27,.40,.33,.18,.08,.06,.07,.01,
     7 0.,.53,.64,.56,.38,.22,.10,2*.06,0.,
     8 10*0.,
     9 2*0.,.05,.19,.23,.14,.07,2*.06,.02,
     A 0.,.16,.27,.37,.34,.19,.10,.07,.09,.05,
     B 0.,.39,.50,.50,.40,.25,.13,.10,.13,.09,
     C 10*0.,
     D 2*0.,.04,.10,.15,.14,.09,.07,.10,.08,
     E 0.,.10,.19,.27,.30,.22,.15,.13,.18,.12,
     F 0.,.26,.36,.43,.45,.30,.21,.20,.23,.20 /
      DATA PARM60 /0.,.25,1.,1.75,2.,2.75,3.,3.5,4.,4.5,.35,.4,.45,7*0./
      DATA EVAL60 /0.,.16,.19,.20,.18,.08,.05,-.01,-.03,-.04,
     1             0.,.16,.19,.20,.18,.08,.05,.03,.04,.02,
     2             0.,.16,.19,.20,.18,.08,.08,.10,.12,.08 /
      DATA PARM61 /0.,1.,1.5,2.,2.5,3.,3.5,4.,3.E06,6.E06,9.E06,2.5E07,
     1    4*0./
      DATA EVAL61 /0.,-.09,2*-.13,-.09,-.11,-.20,-.24,
     1             2*0.,-.08,-.07,2*-.03,-.07,-.10,
     2             8*0.,0.,.12,.14,.07,.01,.11,.18,.20 /
      DATA PARM62 /0.,1.,1.5,2.,2.5,3.,3.5,4./
      DATA EVAL62 /2*0.,-.19,-.37,-.46,3*-.5/
      DATA ROUT /4HMAXC, 4HL   /
C
C  CLMAX BASE
C
      IF(ABS(XOVC-.3) .LE. 1.E-5) XOVC = .3
      VAR(1)=DELTAY
      VAR(2)=XOVC
      LEN(1)=13
      LEN(2)=4
      CALL INTERX(2,PARM58,VAR,LEN,EVAL58,CLBASE,13,52,0,0,0,0,0,0,0,0,
     1            4HBASE,1,ROUT)
C
C  DELTA CLMAX
C
      DEL1=0.0
      DEL2=0.0
      IF(.NOT.CAMBER) GO TO 1000
      VAR(2)=COVC
      VAR(3)=CXVC
      LEN(1)=10
      LEN(2)=4
      LEN(3)=4
      CALL INTERX(3,PARM59,VAR,LEN,EVAL59,DEL1,10,200,0,0,0,0,0,0,0,0,
     1            4HDEL1,1,ROUT)
      IF(XOVC .EQ. 0.30) GO TO 1000
      VAR(2)=XOVC
      LEN(1)=10
      LEN(2)=3
      CALL INTERX(2,PARM60,VAR,LEN,EVAL60,DEL2,10,30,0,0,0,0,0,0,0,0,
     1            4HDEL2,1,ROUT)
 1000 NMACH=FLC(1)+0.5
      IN=0
      DO 1010 I=1,NMACH
         RN=FLC(I+42)*CBAR
         VAR(2)=RN
         IF(RN .LT. 1.0) VAR(2)=9.0E6
         LEN(1)=8
         LEN(2)=4
         CALL INTERX(2,PARM61,VAR,LEN,EVAL61,DEL3,8,32,0,0,0,0,0,0,0,0,
     1               4HDEL3,1,ROUT)
         CALL TBFUNX(DELTAY,DEL4,DYDX,8,PARM62,EVAL62,C,IN,MI,NG,0,0,
     1               4HDEL4,1,ROUT)
         CLMAX0=CLBASE+DEL1+DEL2+DEL3
         CLMAX(I)=CLMAX0
 1010 CONTINUE
      RETURN
      END
C ===== messge.f =====
      SUBROUTINE MESSGE(ROUT,MESS,X1,X2,X3,X4,MSSCL)
C
C     ----THIS SUBROUTINE WRITES TO UNIT 12 WHEN EXTRAPOLATION IS
C         REQUIRED IN THE TABLE LOOKUP SUBROUTINES.
C
      COMMON /OVERLY/ NN(5),NF,NM(2),IOVLY
      DIMENSION ROUT(2),MESS(1),X1(1),X2(1),X3(1),X4(1),MSSCL(21),
     1          RL(21),ML(13)
      EQUIVALENCE (RL(1),ML(1))
      IF(NF .LT. 0) RETURN
      NSTQ=MSSCL(3)
      ML(1)=MSSCL(4)
      NSTP=MSSCL(5)
      ML(2)=MSSCL(6)
      II=MSSCL(7)
      RL(6)=X1(1)
      RL(10)=X1(II)
      IF(NSTP.EQ.1)GO TO 1000
      ML(3)=MSSCL(10)
      II=MSSCL(11)
      RL(7)=X2(1)
      RL(11)=X2(II)
      IF(NSTP.EQ.2)GO TO 1000
      ML(4)=MSSCL(14)
      II=MSSCL(15)
      RL(8)=X3(1)
      RL(12)=X3(II)
      IF(NSTP.EQ.3)GO TO 1000
      ML(5)=MSSCL(18)
      II=MSSCL(19)
      RL(9)=X4(1)
      RL(13)=X4(II)
 1000 WRITE(12,1020) IOVLY,NSTQ,NSTP
      WRITE(12,1030)MSSCL(1),MSSCL(2),ROUT(1),ROUT(2),(MESS(L),L=1,NSTQ)
      DO 1010 L=1,NSTP
         WRITE(12,1040)RL(L+1),RL(L+5),RL(L+9),MSSCL(4*L+4),
     1        MSSCL(4*L+5)
 1010 CONTINUE
      WRITE(12,1050) RL(1)
 1020 FORMAT(3I3)
 1030 FORMAT(24A4)
 1040 FORMAT(3E12.5,2I2)
 1050 FORMAT(E12.5)
      RETURN
      END
C ===== namer.f =====
      SUBROUTINE NAMER(KAND,IUNIT,NLNAME,LENNLN,VNAME,DVNAME,LENVN,
     1                 NUMVN,VDIME,COMBLK,MAXCOM,LOC,IEOF)
C
C***  SIMULATE NAMELIST INPUT.  THE FILE ON IUNIT IS READ UNTIL THE
C***  NAMELIST DEFINED IN NLNAME IS FOUND.  IF FOUND, IT IS READ AND
C***  THE CONSTANTS ASSOCIATED WITH EACH VARIABLE ARE SET INTO THE
C***  ARRAY COMBLK.  IUNIT IS NOT REWOUND BEFORE OR AFTER EXECUTION.
C***  ALL ERROR MESSAGES ARE PRINTED TO UNIT IO (SET TO 6).
C
C   KAND - NAMELIST DELIMITER ($ ON CDC AND VAX, & ON IBM AND OTHER)
C          (BUT CAN BE SPECIFIED TO BE ANY UNIQUE CHARACTER)
C  IUNIT - TAPE UNIT FOR READING
C NLNAME - NAMELIST NAME TO FIND AND READ
C LENNLN - NUMBER OF CHARACTERS IN NAMELIST NAME (DIMENSION OF NLNAME)
C  VNAME - VARIABLE NAMES FOR THIS NAMELIST (AN ARRAY)
C DVNAME - DIMENSION OF VNAME ARRAY
C  LENVN - ARRAY WHICH DEFINES THE NUMBER OF CHARACTERS IN EACH
C          VARIABLE NAME
C  NUMVN - NUMBER OF VARIABLE NAMES DEFINED
C  VDIME - NUMBER OF CONSTANTS PERMITTED FOR EACH VARIABLE
C          (DIMENSION OF EACH VARIABLE; USE NEGATIVE FOR LOGICAL
C           VARIABLES)
C COMBLK - STARTING LOCATION FOR STORING INPUTS
C          (USUALLY THE FIRST LOCATION OF A COMMON BLOCK)
C MAXCOM - MAXIMUM DIMENSION OF STORAGE ARRAY
C          (USUALLY THE LENGTH OF THE COMMON BLOCK)
C    LOC - POINTER TO STORAGE ARRAY FOR THE STARTING LOCATION
C          OF EACH INPUT VARIABLE (IF ZERO THE CONSTANT IS NOT STORED)
C   IEOF - .TRUE. IF AN END-OF-FILE WAS DETECTED DURING READ
C
C***  NOTES -
C
C***  ALL INPUT STRING ARRAYS MUST BE DECLARED INTEGER
C
C***  ALL VARIABLES ARE ASSUMMED TO BE REAL; IF VDIME IS NEGATIVE
C***  THE VARIABLE IS ASSUMMED TO BE LOGICAL.  ALTHOUGH THE CODE IS
C***  DESIGNED TO HANDLE INTEGERS AS WELL, THIS OPTION IS NOT
C***  CURRENTLY USED.  IT CAN BE ACTIVATED BY PASSING ANOTHER ARRAY,
C***  VTYPE, TO DEFINE THE TYPE OF VARIABLE, WITH THE CODE
C***  0=LOGICAL, 1=INTEGER, OR 2=REAL; THEN REPLACE THE NAME VTYPE
C***  WITH THE NAME VTYPE(NVN) IN THE REMAINING CODE.
C
C***  THIS ROUTINE CAN BE USED AS A NAMELIST ERROR CHECKER BY SETTING
C***  THE ARRAY LOC TO ALL ZEROS.  THE VARIABELS AND CONSTANTS WILL
C***  BE READ, BUT THE CONSTANTS NOT STORED.
C
      INTEGER EQUAL,COMMA,BLANK,VNAME,DVNAME,VTYPE,VDIME,PARL,PARR,
     1        CARET
C
      LOGICAL IEOF,LANS,SEARCH,FOUND,IEND
C
      DIMENSION NLNAME(LENNLN),VNAME(DVNAME),LENVN(NUMVN),
     1          VDIME(NUMVN),COMBLK(MAXCOM),LOC(NUMVN)
      DIMENSION INUMS(13),KOL(80),INAME(80),IDIM(80),INLN(80),
     1          ICONST(80),KERR(80)
C
      DATA BLANK / 4H     /
      DATA EQUAL / 4H=    /
      DATA COMMA / 4H,    /
      DATA PARL  / 4H(    /
      DATA PARR  / 4H)    /
      DATA CARET / 4H
   /
      DATA INUMS / 4H0   ,4H1   ,4H2   ,4H3   ,4H4   ,4H5   ,4H6   ,
     1             4H7   ,4H8   ,4H9   ,4H+   ,4H-   ,4H.   /
      DATA IO    / 6 /
C
C******************************************************************
C***  STAGE 1 - READ CARD AND CHECK FOR KAND AS FIRST CHARACTER ***
C******************************************************************
C
 1000 IEND=.FALSE.
      DO 1010 I=1,80
         INLN(I)=BLANK
         KERR(I)=BLANK
 1010 CONTINUE
C
C***  READ CARD FROM IUNIT
C
 1020 CALL READCD(IUNIT, KOL, IEOF)
      IF(IEOF)GO TO 1290
C
C***  SKIP LEADING BLANKS
C
      ICOL=1
      CALL SKIPBL(KOL, ICOL)
      IF(ICOL .GT. 80)GO TO 1020
C
C***  LOOK FOR KAND FIRST, ELSE READ NEXT CARD
C
      IF(KOL(ICOL) .NE. KAND)GO TO 1020
C
C********************************************************
C***  STAGE 2 - CHECK IF NAMELIST READ IS ONE DESIRED ***
C********************************************************
C
C ... EXTRACT NAMELIST NAME TO BLANK
C
      ICOL=ICOL+1
      LCOL=ICOL
      IECOL=ICOL
      CALL FINDCH(KOL, BLANK, LCOL)
      IF(LCOL .EQ. ICOL)GO TO 1040
C
      CALL EXTRST(KOL, ICOL, LCOL-1, INLN)
C
C ... CHECK FOR NAME MATCH
C
      DO 1030 I=1,LENNLN
         IF(INLN(I) .NE. NLNAME(I))GO TO 1050
 1030 CONTINUE
      ICOL=LCOL
      GO TO 1060
C
C***  KAND FOUND BUT NO NAMELIST NAME FOUND
C
 1040 CONTINUE
C
      WRITE(IO,1310)(KOL(I),I=1,80)
      KERR(IECOL)=CARET
      WRITE(IO,1410)(KERR(I),I=1,80)
      GO TO 1300
C
C***  NAMELIST NAME DESIRED NOT FOUND, READ UNTIL KAND SEEN AGAIN
C***  (SKIP UNTIL END OF THIS NAMELIST INPUT)
C
 1050 CALL FINDCH(KOL, KAND, ICOL)
      IF(ICOL .LE. 80)GO TO 1000
C
C ... READ CARD FROM IUNIT
C
      CALL READCD(IUNIT, KOL, IEOF)
      IF(IEOF)GO TO 1290
      ICOL=1
      GO TO 1050
C
C****************************************
C***  STAGE 3 - EXTRACT VARIABLE NAME ***
C****************************************
C
 1060 SEARCH=.TRUE.
      IOFF=0
C
      DO 1070 I=1,80
         INAME(I)=BLANK
         IDIM(I)=BLANK
         KERR(I)=BLANK
 1070 CONTINUE
C
C ... SKIP BLANKS
C
      CALL SKIPBL(KOL, ICOL)
C
      IF(ICOL .LT. 81)GO TO 1080
C
C ... READ CARD FROM IUNIT
C
      CALL READCD(IUNIT, KOL, IEOF)
      IF(IEOF)GO TO 1290
      ICOL=1
C
      CALL SKIPBL(KOL, ICOL)
C
 1080 IF(KOL(ICOL) .EQ. KAND .OR. IEND)GO TO 1290
C
C ... EXTRACT TO =
C
      LCOL=ICOL
      IECOL=ICOL
      CALL FINDCH(KOL, EQUAL, LCOL)
C
      IF(LCOL .LT. 81)GO TO 1090
C
         WRITE(IO,1320)(KOL(I),I=1,80)
         KERR(IECOL)=CARET
         WRITE(IO,1410)(KERR(I),I=1,80)
         GO TO 1300
C
 1090 KNAME=ICOL
      IECOL=KNAME
      CALL EXTRST(KOL, ICOL, LCOL-1, INAME)
C
C ... LOOK FOR ( IN VARIABLE STRING
C
      KK=1
      CALL FINDCH(INAME, PARL, KK)
      IF(KK .GT. 80)GO TO 1130
C
C ... HAVE SUBSCRIPT DEFINED, NOW LOOK FOR )
C
      LL=KK
      CALL FINDCH(INAME, PARR, LL)
C
      IF(LL .LT. 81)GO TO 1100
C
         WRITE(IO,1330)(KOL(I),I=1,80)
         KERR(IECOL)=CARET
         WRITE(IO,1410)(KERR(I),I=1,80)
         GO TO 1300
C
C ... EXTRACT SUBSCRIPT (OFFSET)
C
 1100 CALL EXTRST(INAME, KK+1, LL-1, IDIM)
      KSUB=KNAME+KK
      IECOL=KSUB
C
C ... BLANK ( TO ) IN VARIABLE NAME
C
      DO 1110 I=KK,LL
         INAME(I)=BLANK
 1110 CONTINUE
C
C ... CONVERT OFFSET
C
      CALL TOINT(IDIM, IOFF, IERR)
C
C ... CHECK IF SUBSCRIPT VALID
C
      IF(.NOT.(IERR .NE. 0 .OR. IOFF .LT. 1))GO TO 1120
C
      WRITE(IO,1370)(KOL(I),I=1,80)
      KERR(IECOL)=CARET
      WRITE(IO,1410)(KERR(I),I=1,80)
      GO TO 1300
C
 1120 IOFF=IOFF-1
C
 1130 CONTINUE
C
      ICOL=LCOL+1
C
 1140 IF(KOL(ICOL) .EQ. KAND)IEND=.TRUE.
C
      DO 1150 I=1,80
         ICONST(I)=BLANK
 1150 CONTINUE
C
C***********************************
C***  STAGE 4 - EXTRACT CONSTANT ***
C***********************************
C
C ... EXTRACT TO COMMA OR KAND
C
      LCOL=ICOL
      KCONS=ICOL
      IECOL=KCONS
      CALL FINDCH(KOL, COMMA, LCOL)
C
      IF(LCOL .LT. 81)GO TO 1160
C
C ... COMMA NOT THERE, SEARCH FOR KAND
C
         LCOL=ICOL
         CALL FINDCH(KOL, KAND, LCOL)
C
         IF(LCOL .LT. 81)IEND=.TRUE.
         IF(LCOL .LT. 81)GO TO 1160
C
C ...    NEITHER COMMA NOR KAND, ASSUME COMMA
C
C           CALL FINDCH(KOL, BLANK, IECOL)
C           WRITE(IO,1340)KAND,(KOL(I),I=1,80)
C           KERR(IECOL)=CARET
C           WRITE(IO,1410)(KERR(I),I=1,80)
C
 1160 CALL EXTRST(KOL, ICOL, LCOL-1, ICONST)
C
C ... EXTRACT REPEAT COUNT SPECIFIED IN CONSTANT
C
      IECOL=KCONS
      CALL REPTCT(ICONST, IREPT, IERR)
C
      IF(IERR .EQ. 0 .AND. IREPT .GT. 0)GO TO 1170
C
      WRITE(IO,1390)(KOL(I),I=1,80)
      KERR(IECOL)=CARET
      WRITE(IO,1410)(KERR(I),I=1,80)
      GO TO 1300
C
 1170 ICOL=LCOL+1
C
C*************************************
C***  STAGE 5 - FIND VARIABLE NAME ***
C*************************************
C
C ... SEARCH FOR VARIABLE NAME IN VNAME ARRAY
C
      IECOL=KNAME
      IF(SEARCH)CALL FINDVN(NUMVN, LENVN, INAME, VNAME, DVNAME, NVN,
     1 FOUND)
C
      IF(.NOT.(SEARCH .AND. .NOT. FOUND))GO TO 1180
C
      WRITE(IO,1350)(KOL(I),I=1,80)
      KERR(IECOL)=CARET
      WRITE(IO,1410)(KERR(I),I=1,80)
      GO TO 1300
C
C ... CHECK VARIABLE DIMENSION LIMIT
C
 1180 IECOL=KCONS
C
      IF(.NOT.((IOFF+1) .GT. IABS(VDIME(NVN))))GO TO 1190
C
      WRITE(IO,1370)(KOL(I),I=1,80)
      KERR(IECOL)=CARET
      WRITE(IO,1410)(KERR(I),I=1,80)
      GO TO 1300
C
 1190 LANS=.FALSE.
      IANS=0
      ANS=0.
C
C**************************************
C***  STAGE 6 - SUBSTITUTE CONSTANT ***
C**************************************
C
C ... CONVERT CONSTANT DEPENDING ON TYPE
C
      IECOL=KCONS
C
C ... A NEGATIVE DIMENSION MEANS LOGICAL
C ... ELSE VARIABLE TYPE IS REAL
C
      IF(VDIME(NVN) .LT. 0)VTYPE=0
      IF(VDIME(NVN) .GT. 0)VTYPE=2
C
      IF(VTYPE .EQ. 0)CALL TOLOG(ICONST, LANS, IERR)
      IF(VTYPE .EQ. 1)CALL TOINT(ICONST, IANS, IERR)
      IF(VTYPE .EQ. 2)CALL TODEC(ICONST,  ANS, IERR)
C
      IF(IERR .EQ. 0)GO TO 1220
C
      IF(VTYPE .EQ. 1)GO TO 1200
C
         WRITE(IO,1390)(KOL(I),I=1,80)
         KERR(IECOL)=CARET
         WRITE(IO,1410)(KERR(I),I=1,80)
         GO TO 1300
C
 1200 IF(IERR .EQ. 1 .AND. VTYPE .NE. 1)GO TO 1210
C
         WRITE(IO,1390)(KOL(I),I=1,80)
         KERR(IECOL)=CARET
         WRITE(IO,1410)(KERR(I),I=1,80)
         GO TO 1300
C
 1210 IF(IERR .EQ. 2 .AND. VTYPE .NE. 1)GO TO 1220
C
C        WRITE(IO,1400)(KOL(I),I=1,80)
C        KERR(IECOL)=CARET
C        WRITE(IO,1410)(KERR(I),I=1,80)
C
C ... SUBSTITUTE CONSTANT
C
 1220 DO 1250 I=1,IREPT
C
C ...    CHECK VARIABLE DIMENSION LIMIT
C
         IF((I+IOFF) .LE. IABS(VDIME(NVN)))GO TO 1230
C
            IECOL=KCONS
            WRITE(IO,1380)(KOL(J),J=1,80)
            KERR(IECOL)=CARET
            WRITE(IO,1410)(KERR(J),J=1,80)
            GO TO 1300
C
 1230    IF(LOC(NVN) .LT. 1)GO TO 1250
         II=LOC(NVN)+I+IOFF-1
C
C ...    CHECK DATA BLOCK SIZE LIMIT
C
         IF(II .LE. MAXCOM)GO TO 1240
C
            WRITE(IO,1360)(KOL(J),J=1,80)
            KERR(IECOL)=CARET
            WRITE(IO,1410)(KERR(J),J=1,80)
            GO TO 1300
C
C ...    SUBSTITUTE CONSTANT DEPENDING ON TYPE
C
 1240    IF(VTYPE .EQ. 0)CALL SUBLOG(COMBLK(II), LANS)
         IF(VTYPE .EQ. 1)CALL SUBINT(COMBLK(II), IANS)
         IF(VTYPE .EQ. 2)CALL SUBREA(COMBLK(II),  ANS)
C
 1250 CONTINUE
C
C ... UPDATE OFFSET IN CASE NEXT INPUT IS A CONSTANT INSTEAD OF A
C ... VARIABLE NAME
C
      IOFF=IOFF+IREPT
C
C ... CHECK IF NEXT INPUT IS A NUMERIC OR LOGICAL
C
      CALL SKIPBL(KOL, ICOL)
C
C ... IF KAND PREVIOUSLY DETECTED, EXIT
C
      IF(IEND)GO TO 1290
C
      IF(ICOL .LT. 81)GO TO 1260
C
C ... READ NEXT CARD
C
      CALL READCD(IUNIT, KOL, IEOF)
      IF(IEOF)GO TO 1290
      ICOL=1
C
      CALL SKIPBL(KOL, ICOL)
C
C ... CHECK IF NEXT NON-BLANK CHARACTER SPECIFIES A NUMERIC OR
C ... LOGICAL INPUT
C
 1260 DO 1270 I=1,13
         IF(KOL(ICOL) .EQ. INUMS(I))GO TO 1280
 1270 CONTINUE
C
C ... NO, SEARCH FOR NEXT VARIABLE NAME INPUT
C
      IERR=0
      GO TO 1060
C
C ... YES, SEARCH FOR NEXT INPUT CONSTANT
C
 1280 SEARCH=.FALSE.
      IERR=0
      GO TO 1140
C
 1290 CONTINUE
C
      RETURN
C
 1300 WRITE(IO,1420)
      STOP
C
 1310 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 51H  ILLEGAL/INCORRECT SPECIFICATION OF NAMELIST NAME.,
     2 /,1X,80A1)
 1320 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 36H  NO EQUALS FOLLOWING VARIABLE NAME.,/,1X,80A1)
 1330 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 51H  NO CLOSING RIGHT PARENTHESIS IN ARRAY DEFINITION.,
     2 /,1X,80A1)
C1340 FORMAT(26H0*** NAMELIST INPUT ERROR.,
C    1 26H  NO TERMINATING COMMA OR ,A1,16H AFTER CONSTANT.,
C    2 27H  A COMMA HAS BEEN ASSUMED.,/,1X,80A1)
 1350 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 32H  VARIABLE NAME NOT IN NAMELIST.,/,1X,80A1)
 1360 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 57H  ARRAY SUBSCRIPT OR NUMBER OF CONSTANTS EXCEEDS VARIABLE,
     2 32H DIMENSION OR COMMON BLOCK SIZE.,/,1X,80A1)
 1370 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 34H  ILLEGAL/INVALID ARRAY SUBSCRIPT.,/,1X,80A1)
 1380 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 48H  REPEAT COUNT EXCEEDS VARIABLE ARRAY DIMENSION.,/,1X,80A1)
 1390 FORMAT(26H0*** NAMELIST INPUT ERROR.,
     1 49H  CONSTANT DOES NOT MATCH TYPE OF INPUT REQUIRED.,/,1X,80A1)
C1400 FORMAT(26H0*** NAMELIST INPUT ERROR.,
C    1 47H  REAL NUMBER SPECIFIED FOR INTEGER, CONVERTED.,/,1X,80A1)
 1410 FORMAT(1X,80A1)
 1420 FORMAT(49H0*** EXECUTION TERMINATING DUE TO NAMELIST ERROR.)
C
      END
C ===== namew.f =====
      SUBROUTINE NAMEW(KAND,IUNIT,NLNAME,LENNLN,VNAME,DVNAME,LENVN,
     1                 NUMVN,VDIME,COMBLK,MAXCOM,LOC)
C
C***  SIMULATE NAMELIST OUTPUT.
C
C   KAND - NAMELIST DELIMITER ($ ON CDC AND VAX, & ON IBM AND OTHER)
C          (BUT CAN BE SPECIFIED TO BE ANY UNIQUE CHARACTER)
C  IUNIT - TAPE UNIT FOR WRITING NAMELIST DATA
C NLNAME - NAMELIST NAME TO WRITE
C LENNLN - NUMBER OF CHARACTERS IN NAMELIST NAME (DIMENSION OF NLNAME)
C  VNAME - VARIABLE NAMES FOR THIS NAMELIST (AN ARRAY)
C DVNAME - DIMENSION OF VNAME ARRAY
C  LENVN - ARRAY WHICH DEFINES THE NUMBER OF CHARACTERS IN EACH
C          VARIABLE NAME
C  NUMVN - NUMBER OF VARIABLE NAMES DEFINED
C  VDIME - NUMBER OF CONSTANTS PERMITTED FOR EACH VARIABLE
C          (DIMENSION OF EACH VARIABLE; USE NEGATIVE FOR LOGICAL
C           VARIABLES)
C COMBLK - STARTING LOCATION FOR RESULTS
C          (USUALLY THE FIRST LOCATION OF A COMMON BLOCK)
C MAXCOM - MAXIMUM DIMENSION OF STORAGE ARRAY
C          (USUALLY THE LENGTH OF THE COMMON BLOCK)
C    LOC - POINTER TO STORAGE ARRAY FOR THE STARTING LOCATION
C          OF EACH INPUT VARIABLE (IF ZERO THE CONSTANT IS NOT PRINTED)
C
C***  NOTES -
C
C***  ALL INPUT STRING ARRAYS MUST BE DECLARED INTEGER
C
C***  ALL VARIABLES ARE ASSUMMED TO BE REAL; IF VDIME IS NEGATIVE
C***  THE VARIABLE IS ASSUMMED TO BE LOGICAL.  ALTHOUGH THE CODE IS
C***  DESIGNED TO HANDLE INTEGERS AS WELL, THIS OPTION IS NOT
C***  CURRENTLY USED.  IT CAN BE ACTIVATED BY PASSING ANOTHER ARRAY,
C***  VTYPE, TO DEFINE THE TYPE OF VARIABLE, WITH THE CODE
C***  0=LOGICAL, 1=INTEGER, OR 2=REAL; THEN REPLACE THE NAME VTYPE
C***  WITH THE NAME VTYPE(NVN) IN THE REMAINING CODE.
C
C***  IF ANY ELEMENT OF ARRAY LOC IS ZERO, THAT VARIABLE WILL NOT
C***  BE INCLUDED IN THE LISTING.
C
      INTEGER VNAME,DVNAME,VTYPE,VDIME,BLANK,EQUAL
C
      DIMENSION NLNAME(LENNLN),VNAME(DVNAME),LENVN(NUMVN),
     1          VDIME(NUMVN),COMBLK(MAXCOM),LOC(NUMVN)
      DIMENSION KOL(8)
C
      DATA BLANK / 4H     /
      DATA EQUAL / 4H=    /
C
      WRITE(IUNIT,1030)KAND,(NLNAME(I),I=1,LENNLN)
C
      INDX=1
C
      DO 1020 NVN=1,NUMVN
C
         IF(NVN .GT. 1)INDX=INDX+MAXC
C
         MAXC=LENVN(NVN)
C
         DO 1000 J=1,8
            KOL(J)=BLANK
 1000    CONTINUE
C
         DO 1010 I=1,MAXC
            KOL(I)=VNAME(I+INDX-1)
 1010    CONTINUE
C
         KOL(8)=EQUAL
C
         KK=LOC(NVN)
         IF(KK .LT. 1)GO TO 1020
         JJ=IABS(VDIME(NVN))
C
C ... A NEGATIVE DIMENSION MEANS LOGICAL
C ... ELSE VARIABLE TYPE IS REAL
C
         IF(VDIME(NVN) .LT. 0)VTYPE=0
         IF(VDIME(NVN) .GT. 0)VTYPE=2
C
         IF(VTYPE .EQ. 0)CALL FORLOG(IUNIT, KOL, COMBLK(KK), JJ)
         IF(VTYPE .EQ. 1)CALL FORINT(IUNIT, KOL, COMBLK(KK), JJ)
         IF(VTYPE .EQ. 2)CALL FORREA(IUNIT, KOL, COMBLK(KK), JJ)
C
 1020 CONTINUE
C
      WRITE(IUNIT,1040)KAND
C
      RETURN
C
 1030 FORMAT(1H1,8A1)
 1040 FORMAT(1H0,A1,3HEND)
C
      END
C ===== nmlist.f =====
      SUBROUTINE NMLIST(KOL,L,NAME,K,IER)
C
C***  PASS NAMELIST NAMES TO TESTOR FOR CHECKING
C
      DIMENSION KOL(80)
      COMMON /IBODY/   PBODY, LEN2(18),LDM2(18),FLTCON(81)
      COMMON /BODYI/          LEN3(4) ,LDM3(4) ,OPTINS(20)
      COMMON /IHT/     PHT,   LEN4(15),LDM4(15),BODY(44)
      COMMON /IVT/     PVT,   LEN5(21),LDM5(21),PLNF(103)
      COMMON /IBW/     PBW,   LEN6(36),LDM6(36),SCHR(170)
      COMMON /IBH/     PBH,   LEN7(19),LDM7(19),SYNTHS(60)
      COMMON /IBV/     PBV,   LENC(14),LDMC(14),PRPOWR(78)
      COMMON /IBWH/    PBWH,  LEND(15),LDMD(15),JETPWR(89)
      COMMON /IBWV/    PBWV,  LENE(21),LDME(21),LARWB(89)
      COMMON /IPOWER/  PPOWR, LENF(2) ,LDMF(2) ,GRNDEF(8)
      COMMON /IDWASH/  PDWAS, LENG(8) ,LDMG(8) ,TVTPAN(23)
      COMMON /IBWHV/   PBWHV, LENH(32),LDMH(32),EXPR(131)
      COMMON /IWING/   PWING, LENI(27),LDMI(27),SYMFLP(139)
      COMMON /VTI/            LENJ(14),LDMJ(14),ASYFLP(78)
      COMMON /WINGI/          LENK(7) ,LDMK(7) ,HYPEFF(32)
      COMMON /HTI/            LENL(12),LDML(12),TRNJET(38)
      COMMON /IVF/     PVF,   LENM(22),LDMM(22),CONTAB(76)
C
      INTEGER FLTCON, OPTINS, BODY, PLNF, SCHR, PRPOWR, SYNTHS,
     1        JETPWR, LARWB, GRNDEF, TVTPAN, EXPR, SYMFLP,
     2        ASYFLP, HYPEFF, TRNJET
C
C***  PASS CORRECT NAMELIST VARIABLES TO TESTOR FOR NAME
C***  AND SYNTAX VERIFICATION
C
      IF(IER .EQ. 1) NAME = 1
      GO TO (1010, 1010, 1020, 1030, 1040, 1050, 1060,
     1       1040, 1050, 1040, 1050, 1070, 1080, 1090,
     2       1100, 1110, 1120, 1130, 1140, 1150, 1160,
     3       1165, 1050, 1040) , NAME
C
 1010 CALL TESTOR(KOL,L,NAME,K,IER,LEN2,LDM2,18,FLTCON)
      GO TO 1170
C
 1020 CALL TESTOR(KOL,L,NAME,K,IER,LEN3,LDM3, 4,OPTINS)
      GO TO 1170
C
 1030 CALL TESTOR(KOL,L,NAME,K,IER,LEN4,LDM4,15,BODY)
      GO TO 1170
C
 1040 CALL TESTOR(KOL,L,NAME,K,IER,LEN5,LDM5,21,PLNF)
      GO TO 1170
C
 1050 CALL TESTOR(KOL,L,NAME,K,IER,LEN6,LDM6,36,SCHR)
      GO TO 1170
C
 1060 CALL TESTOR(KOL,L,NAME,K,IER,LEN7,LDM7,19,SYNTHS)
      GO TO 1170
C
 1070 CALL TESTOR(KOL,L,NAME,K,IER,LENC,LDMC,14,PRPOWR)
      GO TO 1170
C
 1080 CALL TESTOR(KOL,L,NAME,K,IER,LEND,LDMD,15,JETPWR)
      GO TO 1170
C
 1090 CALL TESTOR(KOL,L,NAME,K,IER,LENE,LDME,21,LARWB)
      GO TO 1170
C
 1100 CALL TESTOR(KOL,L,NAME,K,IER,LENF,LDMF, 2,GRNDEF)
      GO TO 1170
C
 1110 CALL TESTOR(KOL,L,NAME,K,IER,LENG,LDMG, 8,TVTPAN)
      GO TO 1170
C
 1120 CALL TESTOR(KOL,L,NAME,K,IER,LENH,LDMH,32,EXPR)
      GO TO 1170
C
 1130 CALL TESTOR(KOL,L,NAME,K,IER,LENI,LDMI,27,SYMFLP)
      GO TO 1170
C
 1140 CALL TESTOR(KOL,L,NAME,K,IER,LENJ,LDMJ,14,ASYFLP)
      GO TO 1170
C
 1150 CALL TESTOR(KOL,L,NAME,K,IER,LENK,LDMK, 7,HYPEFF)
      GO TO 1170
C
 1160 CALL TESTOR(KOL,L,NAME,K,IER,LENL,LDML,12,TRNJET)
      GO TO 1170
C
 1165 CALL TESTOR(KOL,L,NAME,K,IER,LENM,LDMM,22,CONTAB)
C
 1170 CONTINUE
      RETURN
      END
      LOGICAL FUNCTION NMTEST(KOL,KEY,NCHAR)
C
C***  CHECK NAMELIST NAMES
C
      INTEGER KOL(1) , KEY(1)
C
C     ----TEST FOR NAME IN KEY = NAME IN KOL, NCHAR = NO. OF CHARACTERS
C
      DO 1000 I=1,NCHAR
         IF(KOL(I).NE.KEY(I)) GO TO 1010
 1000 CONTINUE
C
C     ----HERE IF NAME CHECKS
C
      NMTEST=.TRUE.
      RETURN
C
C     ----HERE IF NAME DOES NOT CHECK
C
 1010 NMTEST=.FALSE.
      RETURN
      END
C ===== outpt2.f =====
      SUBROUTINE OUTPT2
C
C     THIS SUBROUTINE WRITES THE HIGH LIFT AND CONTROL DATA
C
      COMMON /FLAPIN/ F(138)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /FLGTCD/ FLC(160)
      COMMON /OPTION/ OPT(4)
      COMMON /CONSNT/ PI, DEG, UNUSED, RAD
      COMMON /POWR/   PW(315)
      COMMON /OVERLY/ NLOG,NMACH,M,NALPHA,IG,NF,LF,K
      COMMON /WINGI/  WINGIN(101)
      COMMON /HTI/    HTIN(131)
      COMMON /BDATA/  BD(762)
      COMMON /CASEID/ IDCASE(74),KOUNT,NAMSV(100),IDIM
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      DIMENSION TRM(22), TRM2(22), ALPHA(20)
      EQUIVALENCE (TRM(1),TRM2(1),PW(294)), (ALPHA(1),FLC(23))
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL NDMF,NAF,FLAG
C
      COMMON /IBODY/  PBODY, BODY(400)
      COMMON /IWING/  PWING, WING(400)
      COMMON /IHT/    PHT,   HT(380)
      COMMON /IVT/    PVT,   VT(380)
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /IBV/     PBV,    BV(380)
      COMMON /IBWH/    PBWH,   BWH(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
C
C     SYMMETRICAL FLAP DATA DEFINITION
C
      DIMENSION DCDI(200), DCL(10), DCM(10), DCLMAX(10), DCDMIN(10),
     1          DCLAD(10), CHA(10), CHD(10)
      DIMENSION DELTA(10)
      EQUIVALENCE (DCDI(1),BODY(201)), (DCL(1),WING(201)),
     1          (DCM(1),WING(211)), (DCLMAX(1),WING(221)),
     2          (DCDMIN(1),WING(231)), (DCLAD(1),WING(241)),
     3          (CHA(1),WING(251)), (CHD(1),WING(261))
      EQUIVALENCE (DELTA(1),F(1)), (FTYPE,F(17))
C
C     CONTROL TAB DATA DEFINITION
C
      DIMENSION CHCTF(20,9),CHCTL(20,9),DCHCG(20,9),CFC(20,9),
     1          FC(20,9),DTT(20,9)
      EQUIVALENCE (CFC(1,1),FC(1,1),BW(201)),(CHCTF(1,1),BH(201)),
     1            (CHCTL(1,1),BV(201)),(DCHCG(1,1),BWH(201)),
     2            (DTT(1,1),BWHV(201))
C
C     ASYMMETRICAL FLAP DATA DEFINITION
C
      DIMENSION CNAD(200), CLAD(200), DDELTA(10), CLD(10), CND(10)
      DIMENSION DELTAD(10), DELTAL(10), DELTAR(10), DELTAS(10),
     1          XSOC(10), HSOC(10)
      EQUIVALENCE (CNAD(1),BODY(201)), (CLAD(1),WING(201)),
     1          (DELTAD(1),F(1)), (STYPE,F(18)), (DELTAL(1),F(19)),
     2          (DELTAR(1),F(29)), (DELTAS(1),F(39)),
     3          (XSOC(1),F(49)), (HSOC(1),F(60)), (DDELTA(1),HT(201)),
     4          (CLD(1),HT(211)), (CND(1),HT(221))
C
C     TRIM DATA DEFINITION
C
      DIMENSION CLUT(20), CDUT(20), CMUT(20), DELT(20), DCLT(20),
     1          DCLMT(20), DCDIT(20), DCDMT(20), CHAT(20), CHDT(20)
      DIMENSION HMUNT(20), ALINT(20), CDTRM(20), CLTRM(20), CMTRM(20),
     1          HMTRM(20), CDWBT(20), CLWBT(20)
      EQUIVALENCE (CLUT(1),HT(201)), (CDUT(1),HT(221)),
     1          (CMUT(1),HT(241)), (DELT(1),VT(201)), (DCLT(1),VT(221)),
     2          (DCLMT(1),VT(241)), (DCDIT(1),VT(261)),
     3          (DCDMT(1),VT(281)), (CHAT(1),VT(301)),
     4          (CHDT(1),VT(321))
      EQUIVALENCE (HMUNT(1),HT(201)), (ALINT(1),HT(221)),
     1          (CDTRM(1),HT(241)), (CLTRM(1),HT(261)),
     2          (CMTRM(1),HT(281)), (HMTRM(1),HT(301)),
     3          (CDWBT(1),VT(201)), (CLWBT(1),VT(221))
      DIMENSION FOR(34), IFOR(8)
      DIMENSION FOT(46), IFOT(11)
      DIMENSION IFOH(11), FOH(46)
	CHARACTER*4 FOR,FOT,FOH
C
      DATA FOR /
     1  4H(0P ,   4H5X  ,   4H,1X ,   4H,F5.,   4H1,1X,   4H,2X ,
     2  4H,1X ,   4H,F6.,   4H3   ,   4H,4X ,
     3  4H    ,   4H,F7.,   4H4   ,   4H,3X ,
     4  4H,1X ,   4H,F6.,   4H3   ,   4H,6X ,
     5  4H    ,   4H,F7.,   4H5   ,   4H,15X,
     6  4H,1P ,   4H E10,   4H.3  ,   4H,2X ,
     7  4H,1P ,   4H E10,   4H.3  ,   4H,2X ,
     8  4H,1P ,   4H E10,   4H.3  ,   4H)   /
      DATA IFOR / 5*7, 3*10 /
C
      DATA FOT /
     1  4H(0P ,   4H4X  ,   4H,1X ,   4H,F5.,   4H1,1X,   4H,1X ,
     2  4H,1X ,   4H,F6.,   4H3   ,   4H,3X ,
     3  4H,1X ,   4H,F6.,   4H3   ,   4H,3X ,
     4  4H    ,   4H,F7.,   4H4   ,   4H,2X ,
     5  4H,1X ,   4H,F5.,   4H1,1X,   4H,1X ,
     6  4H,1X ,   4H,F6.,   4H3   ,   4H,4X ,
     7  4H,1X ,   4H,F6.,   4H3   ,   4H,5X ,
     8  4H,1P ,   4H E9.,   4H2   ,   4H,2X ,
     9  4H,0P ,   4H F8.,   4H5,1X,   4H,2X ,
     A  4H,1P ,   4H E10,   4H.3  ,   4H,3X ,
     B  4H,1P ,   4H E10,   4H.3  ,   4H)   /
      DATA IFOT / 7*7, 2*9, 2*10 /
      DATA IFOH / 8, 10*10 /
      DATA FOH   /    4H(   ,4H1H0 ,
     1  4H,0P ,4HF6.3,4H,1X ,4H,1X ,  4H,1X,,4HF8.2,4H,1X ,4H,1X ,
     2  4H,1X,,4HF8.2,4H,1X ,4H,2X ,  4H,1P ,4HE10.,4H4   ,4H,3X ,
     3  4H,0P ,4HF9.3,4H,1X ,4H,4X ,  4H,1P ,4HE10.,4H4   ,4H,9X ,
     4  4H,0P ,4HF9.3,4H,1X ,4H,1X ,  4H,1X,,4HF8.3,4H,1X ,4H    ,
     5  4H,1X,,4HF8.3,4H,1X ,4H    ,  4H,1X,,4HF8.3,4H,1X ,4H    ,
     6  4H,1X,,4HF8.3,4H,1X ,4H)   /
C
C
      DATA WINGP / 4HWING /, TAILP / 4HTAIL /, STRA / 4HSTRA /
C
      NDELTA = F(16)+0.5
      SC = SYNA(13)
      XL = 1.0
      XR = 1.0
      XP = 1.0
      XT = 1.0
      IF(IDIM .EQ. 2) XL = 12.0
      IF(IDIM .EQ. 2) XP = 144.0
      IF(IDIM .GE. 3) XP = 0.0208854
      IF(IDIM .GE. 3) XR = 0.3048
      IF(IDIM .GE. 3) XT = 1.8
      IF(IDIM .EQ. 3) XL = 0.3048
      IF(IDIM .EQ. 4) XL = 30.48
      ALT  = FLC(K+96)
      VINF = FLC(M+136)
      PINF = FLC(K+73)
      TINF = FLC(K+116)
      IF(ALT  .NE. -UNUSED) ALT  = ALT *XL
      IF(VINF .NE. -UNUSED) VINF = VINF*XL
      IF(PINF .NE. -UNUSED) PINF = PINF*XP
      IF(TINF .NE. -UNUSED) TINF = TINF*XT
      RN   = FLC(M+42)*XR
      SREF = OPT(1)*XL*XL/(SC*SC)
      CBAR = OPT(2)*XL/SC
      BLRF = OPT(4)*XL/SC
      XCG  = SYNA(1)
      ZCG  = SYNA(5)
      IF(XCG .EQ. UNUSED) XCG = 0.0
      IF(ZCG .EQ. UNUSED) ZCG = 0.0
      IF(BD(11) .NE. UNUSED) XCG = XCG+BD(11)
      XCG  = XCG*XL/SC
      ZCG  = ZCG*XL/SC
C
C      SYMMETRICAL FLAP DATA
C
      FLAG = (FLC(157) .NE. UNUSED) .AND. (FLC(K+72) .NE. UNUSED)
      NDMF = .FALSE.
      NAF  = .FALSE.
      IF (.NOT. SYMFP) GO TO 1020
          WRITE(6,1340)
          VWGTL = WINGP
          IF(WGPL .AND. HTPL) VWGTL = TAILP
          IF(FTYPE .EQ. 1.0)  WRITE(6,1350) VWGTL
          IF(FTYPE .EQ. 2.0)  WRITE(6,1360) VWGTL
          IF(FTYPE .EQ. 3.0)  WRITE(6,1370) VWGTL
          IF(FTYPE .EQ. 4.0)  WRITE(6,1380) VWGTL
          IF(FTYPE .EQ. 5.0)  WRITE(6,1390) VWGTL
          IF(FTYPE .EQ. 6.0)  WRITE(6,1400) VWGTL
          IF(FTYPE .EQ. 7.0)  WRITE(6,1410) VWGTL
          IF(HEAD) CALL PRCSID
          WRITE(6,1420)
          IF(IDIM .EQ. 1) WRITE(6,1430)
          IF(IDIM .EQ. 2) WRITE(6,1440)
          IF(IDIM .EQ. 3) WRITE(6,1450)
          IF(IDIM .EQ. 4) WRITE(6,1460)
          CALL SWRITE(11,FOH,46,IFOH,1,FLC(M+2),ALT,VINF,PINF,
     1                TINF,RN,SREF,CBAR,BLRF,XCG,ZCG,DUM,
     2                DUM,DUM,NDMF,NAF)
C
          WRITE(6,1470)
          CALL SWRITE(8,FOR,34,IFOR,NDELTA,DELTA,DCL,DCM,DCLMAX,
     1               DCDMIN,DCLAD,CHA,CHD,X,X,X,X,X,X,NDMF,NAF)
          IF(.NOT. SUBSON .OR. FTYPE .GE. 7) GO TO 1010
          WRITE(6,1480)
          WRITE(6,1490) (DELTA(I),I=1,NDELTA)
          WRITE(6,1500)
          IS = NALPHA*NDELTA
          DO 1000 I=1,NALPHA
             WRITE(6,1510) ALPHA(I), (DCDI(J),J=I,IS,NALPHA)
 1000     CONTINUE
 1010     IF(.NOT. SUPERS) GO TO 1020
          WRITE(6,1310)
          WRITE(6,1320)
          WRITE(6,1330)
 1020 CONTINUE
C
C      CONTROL TAB OUTPUT
C
      IF(.NOT. CTAB) GO TO 1030
        ITYPE=F(116)+0.5
        WRITE(6,1340)
        IF(ITYPE .EQ. 1)WRITE(6,1770)
        IF(ITYPE .EQ. 2)WRITE(6,1780)
        IF(ITYPE .EQ. 3)WRITE(6,1790)
        IF(HEAD)CALL PRCSID
        WRITE(6,1420)
        IF(IDIM .EQ. 1) WRITE(6,1430)
        IF(IDIM .EQ. 2) WRITE(6,1440)
        IF(IDIM .EQ. 3) WRITE(6,1450)
        IF(IDIM .EQ. 4) WRITE(6,1460)
        CALL SWRITE(11,FOH,46,IFOH,1,FLC(M+2),ALT,VINF,PINF,
     1              TINF,RN,SREF,CBAR,BLRF,XCG,ZCG,DUM,
     2              DUM,DUM,NDMF,NAF)
        IF(FLC(M+73) .NE. UNUSED) WRITE(6,1800)
        IF(FLC(M+73) .EQ. UNUSED) WRITE(6,1810)
        WRITE(6,1490) (DELTA(I),I=1,NDELTA)
        WRITE(6,1500)
        WRITE(6,1510) ((FC(I,J),J=1,NDELTA), I=1,NALPHA)
        WRITE(6,1820)
C
        WRITE(6,1830)
        WRITE(6,1490) (DELTA(I), I=1,NDELTA)
        WRITE(6,1500)
        WRITE(6,1510) ((CHCTF(I,J), J=1,NDELTA), I=1,NALPHA)
C
        WRITE(6,1340)
        IF(ITYPE .EQ. 1)WRITE(6,1770)
        IF(ITYPE .EQ. 2)WRITE(6,1780)
        IF(ITYPE .EQ. 3)WRITE(6,1790)
        IF(HEAD)CALL PRCSID
        WRITE(6,1420)
        IF(IDIM .EQ. 1) WRITE(6,1430)
        IF(IDIM .EQ. 2) WRITE(6,1440)
        IF(IDIM .EQ. 3) WRITE(6,1450)
        IF(IDIM .EQ. 4) WRITE(6,1460)
        CALL SWRITE(11,FOH,46,IFOH,1,FLC(M+2),ALT,VINF,PINF,
     1              TINF,RN,SREF,CBAR,BLRF,XCG,ZCG,DUM,
     2              DUM,DUM,NDMF,NAF)
        WRITE(6,1840)
        WRITE(6,1490) (DELTA(I), I=1,NDELTA)
        WRITE(6,1500)
        WRITE(6,1510) ((CHCTL(I,J), J=1,NDELTA), I=1,NALPHA)
        WRITE(6,1820)
C
        WRITE(6,1850)
        WRITE(6,1490) (DELTA(I), I=1,NDELTA)
        WRITE(6,1500)
        WRITE(6,1510) ((DCHCG(I,J), J=1,NDELTA), I=1,NALPHA)
C
        IF(ITYPE .EQ. 1) GO TO 1030
        WRITE(6,1340)
        IF(ITYPE .EQ. 1)WRITE(6,1770)
        IF(ITYPE .EQ. 2)WRITE(6,1780)
        IF(ITYPE .EQ. 3)WRITE(6,1790)
        IF(HEAD)CALL PRCSID
        WRITE(6,1420)
        IF(IDIM .EQ. 1) WRITE(6,1430)
        IF(IDIM .EQ. 2) WRITE(6,1440)
        IF(IDIM .EQ. 3) WRITE(6,1450)
        IF(IDIM .EQ. 4) WRITE(6,1460)
        CALL SWRITE(11,FOH,46,IFOH,1,FLC(M+2),ALT,VINF,PINF,
     1              TINF,RN,SREF,CBAR,BLRF,XCG,ZCG,DUM,
     2              DUM,DUM,NDMF,NAF)
        WRITE(6,1860)
        WRITE(6,1490) (DELTA(I), I=1,NDELTA)
        WRITE(6,1500)
        WRITE(6,1510) ((DTT(I,J), J=1,NDELTA), I=1,NALPHA)
 1030 CONTINUE
C
C     ASYMMETRICAL FLAP OUTPUT
C
      IF(.NOT. ASYFP) GO TO 1120
          WRITE(6,1340)
          IF(STYPE .EQ. 1.0) WRITE(6,1570)
          IF(STYPE .EQ. 2.0) WRITE(6,1580)
          IF(STYPE .EQ. 3.0) WRITE(6,1590)
          IF(STYPE .EQ. 4.0) WRITE(6,1600)
          IF(STYPE .EQ. 5.0) WRITE(6,1520)
          IF(HEAD) CALL PRCSID
          WRITE(6,1420)
          IF(IDIM .EQ. 1) WRITE(6,1430)
          IF(IDIM .EQ. 2) WRITE(6,1440)
          IF(IDIM .EQ. 3) WRITE(6,1450)
          IF(IDIM .EQ. 4) WRITE(6,1460)
          CALL SWRITE(11,FOH,46,IFOH,1,FLC(M+2),ALT,VINF,PINF,
     1                TINF,RN,SREF,CBAR,BLRF,XCG,ZCG,DUM,
     2                DUM,DUM,NDMF,NAF)
C
          IF(STYPE .GT. 2) GO TO 1050
               IF(SUPERS) GO TO 1040
               WRITE(6,1700)
               IF(SUBSON) WRITE(6,1710) (XSOC(I), HSOC(I),
     1                        DELTAS(I), CLD(I), CND(I), I=1,NDELTA)
               IF(TRANSN) WRITE(6,1290) (XSOC(I), HSOC(I),
     1                        DELTAS(I), CLD(I), I=1,NDELTA)
               GO TO 1050
 1040          WRITE(6,1260)
               WRITE(6,1270) (DELTAS(I), CLD(I), CND(I), I=1,NDELTA)
 1050     CONTINUE
          IF(STYPE .NE. 3.0) GO TO 1060
               IF(SUPERS) WRITE(6,1280)
               IF(SUPERS) GO TO 1060
               WRITE(6,1680)
               IF(SUBSON) WRITE(6,1690) (XSOC(I), HSOC(I), DELTAD(I),
     1                        DELTAS(I), CLD(I), CND(I), I=1,NDELTA)
               IF(TRANSN) WRITE(6,1300) (XSOC(I), HSOC(I), DELTAD(I),
     1                        DELTAS(I), CLD(I), I=1,NDELTA)
 1060     CONTINUE
          IF(STYPE .NE. 4.0) GO TO 1090
               WRITE(6,1610)
               WRITE(6,1540) (DDELTA(I), I=1,NDELTA)
               WRITE(6,1550)
               IF(CLD(1) .EQ. UNUSED) GO TO 1080
