     1                             DCLT,DCLMT,DCDIT,DCDMT,CHDT,CLWBT,
     2                             CDWBT,1)
               IF((TRM(22) .EQ. 1.0) .OR. (NTRIM .EQ. 0)) WRITE(6,1720)
               ITRM = TRM(22) + 0.5
               IF(ITRM .EQ. 2) WRITE(6,1730)
 1130     CONTINUE
          IF(SYMFP .OR. .NOT. HTPL) GO TO 1160
      IF(WINGIN(101).GT.2.0) GO TO 1160
               WRITE(6,1340)
               IF(VTPL)       WRITE(6,1180)
