 1150          CONTINUE
               IF(FLAG) CALL FLTCL(FOT,IFOT,NTM,CLUT,CDUT,CMUT,DELT,
     1                             DCLT,DCLMT,DCDIT,DCDMT,CHDT,CLWBT,
     2                             CDWBT,2)
               IF(TRM2(22).EQ.1.) WRITE(6,1250)
               IF(TRM2(22).EQ.2.) WRITE(6,1730)
               IF(TRM2(22).EQ.3.) WRITE(6,1735)
 1160 CONTINUE
      IF(NDMF) WRITE(6,1740)
      IF(NAF)  WRITE(6,1750)
