      CALL INTERX(2, XD2, VAR, LGH, YD2, DUM, 5, 20,
     1            0, 2, 0, 0, 1, 2, 0, 0, QD2, 3, ROUTID)
C
C***  TABLE LOOK UP - FIGURE 4.4.1-76D3 AND 76D4 AT TAPER = 0.00
