      NNALPH=NALPHA+1
      IF(CL(1).LT.0.) GO TO 1002
      CLSUB(1)=0.
      ALSCH2(1)=ALSD
      DO 1001 J=1,NALPHA
         CLSUB(J+1)=CL(J)
 1001 ALSCH2(J+1)=ALSCHD(J)
      GO TO 1004
 1002 CLSUB(NNALPH)=0.
      ALSCH2(NNALPH)=ALSD
      DO 1003 J=1,NALPHA
         CLSUB(J)=CL(J)
 1003 ALSCH2(J)=ALSCHD(J)
