     6-1133255189,-1133325330,-1133334334,-1133331324,-1133310299,
     7-1133247190,-1133300304,-1133312307,-1133305301,-1133288270,
     8-1133237183,-1133278280,-1133282282,-1133281276,-1133268251,
     9-1133221178,-1133245248,-1133251251,-1133250248,-1133241232,
     A-1133208167,-1133221221,-1133222221,-1133220217,-1133215206,
     B-1133192161,-1133183182,-1133182181,-1133180180,-1133178174,
     C-1133162140,-1133138139,-1133141141,-1133141141,-1133142141,
     D-1133134124/
      DATA Y2220C/-1133523535,-1133539534,-1133519496,-1133456407,
     1-1133337245,-1133503509,-1133513505,-1133499475,-1133441390,
     2-1133317234,-1133470483,-1133486483,-1133470454,-1133421375,
     3-1133312228,-1133445451,-1133453451,-1133445428,-1133400355,
     4-1133298223,-1133410415,-1133420414,-1133409392,-1133370338,
     5-1133287213,-1133371376,-1133377375,-1133371358,-1133338314,
     6-1133269204,-1133343349,-1133354353,-1133349339,-1133321299,
     7-1133260204,-1133320320,-1133322322,-1133319316,-1133300280,
     8-1133245199,-1133293297,-1133298297,-1133295286,-1133278264,
     9-1133238189,-1133264264,-1133263264,-1133262259,-1133248239,
     A-1133220180,-1133226226,-1133225226,-1133224222,-1133219207,
     B-1133191165,-1133188188,-1133189187,-1133186186,-1133180172,
     C-1133163145,-1133149149,-1133149149,-1133148147,-1133146142,
     D-1133134121/
      DATA D1220D/-1133560573,-1133575575,-1133573567,-1133560546,
     1-1133539520,-1133502481,-1133461430,-1133398367,-1133335280,
     2-1133538545,-1133546546,-1133544542,-1133537525,-1133518501,
     3-1133484464,-1133446415,-1133384353,-1133319269,-1133508517,
     4-1133519517,-1133515512,-1133507499,-1133487475,-1133462442,
     5-1133425396,-1133367339,-1133305266,-1133469477,-1133480480,
     6-1133477471,-1133469463,-1133454448,-1133434418,-1133401376,
     7-1133350321,-1133290246,-1133431434,-1133435435,-1133433431,
     8-1133428423,-1133416409,-1133397383,-1133371350,-1133322299,
     9-1133273232,-1133385390,-1133391390,-1133389386,-1133384378,
     A-1133375368,-1133360353,-1133340325,-1133304284,-1133260224,
     B-1133359361,-1133361362,-1133362360,-1133360356,-1133354347,
     C-1133339334,-1133323307,-1133288271,-1133249216,-1133332334,
     D-1133334334,-1133333333,-1133331329,-1133325322,-1133317310,
     E-1133302290,-1133276257,-1133237208,-1133265266,-1133266266,
     F-1133266265,-1133265264,-1133262261,-1133258255,-1133250246,
     G-1133234222,-1133209183,-1133298300,-1133302302,-1133302301,
     H-1133300298,-1133298293,-1133289284,-1133280267,-1133255243,
     I-1133225197,-1133230230,-1133230230,-1133230231,-1133230230,
     J-1133229228,-1133224223,-1133219216/
      DATA D2220D/-1133208198,-1133188170,-1133189190,-1133190190,
     1-1133190189,-1133188187,-1133187184,-1133183181,-1133179175,
     2-1133171163,-1133156143,-1133148146,-1133146145,-1133145145,
     3-1133146146,-1133145145,-1133144142,-1133142141,-1133141139,
     4-1133135122/
      DATA Y12224/-1133407331,-1133278240,-1133216175,-1133146127,
     1-1134112891,-1133171137,-1133116103,-1144901734,-1144620532,
     2-1144456365,-1144918736,-1144606535,-1144467381,-1144344280,
     3-1144239183,-1144567428,-1144382349,-1144297232,-1144183177,
     4-1144160125,-1144400303,-1144267223,-1144193165,-1144149120,
     5-1144114103,-1144302225,-1144199187,-1144159131,-1145103856,
     6-1155683804,-1144230201,-1144165141,-1145136843,-1155686624,
     7-1155338463,-1144221179,-1144153141,-1145113850,-1155687398,
     8-1155341456/
      DATA Y12312/-1166968781,-1166626494,-1166388197, -176319113,
     1-1166941724,-1166541382, -168238339,  166218422,-1166885655,
     2-1166450256, -176949195,  166454705,-1166777520,-1166300113,
     3  176533337,  166590825,-1166548303, -177979781,  166231499,
     4  166724919, -176387127,  166264371,  166473661,  166827994/
      DATA Y1219B/ 122468642 , 122368554 , 122300494 , 122176413,
     1 122111372 , 132160292 , -132680236 ,-122168172/
      DATA Y1219C/ 1123153677, 1123161573 , 1123182380 /
      DATA Y7133A/-133110100,-134127830/
      BETA=B(2)
      IF( WGPL.AND.(.NOT.BO))GO TO 1000
      DB=(SSPN-SSPNE)/SSPN
      IF(DB.GT.0.3)RETURN
 1000 K=BETA*WINGIN(IM+20)*RAD/(2.*PI)
      MACH=FLC(IM+2)
      XYZ=0.
C
C     WING-BODY ROLLING DERIVATIVE,CLP---
C
      CALL TBFUNX(XYZ,ALSD,DYDX,NALPHA,CL,ALSCHD,Y,IN,MI,NG,1,1,QEXPD,5,
     1            ROUTID)
      CALL TBFUNX(XYZ,CDO,DYDX,NALPHA,CL,CD,D,IO,MI,NG,2,2,
     1            QEXPD,5,ROUTID)
      IF(CL(1).LE.0..AND.CL(NALPHA).GE.0.) GO TO 1050
      NNALPH=NALPHA+1
      IF(CL(1).LT.0.) GO TO 1020
      CLSUB(1)=0.
      ALSCH2(1)=ALSD
      DO 1010 J=1,NALPHA
         CLSUB(J+1)=CL(J)
 1010 ALSCH2(J+1)=ALSCHD(J)
      GO TO 1040
 1020 CLSUB(NNALPH)=0.
      ALSCH2(NNALPH)=ALSD
      DO 1030 J=1,NALPHA
         CLSUB(J)=CL(J)
 1030 ALSCH2(J)=ALSCHD(J)
 1040 CALL TBFUNX(ALSD,ABCD,CLACLO,NNALPH,ALSCH2,CLSUB,E,IX,MI,
     1            NG,1,1,QEXPD,5,ROUTID)
      GO TO 1060
 1050 CALL TBFUNX(ALSD,ABCD,CLACLO,NALPHA,ALSCHD,CL,Z,IX,MI,
     1            NG,1,1,QEXPD,5,ROUTID)
 1060 CONTINUE
      XBOCB=-DCMDCL*CBARR/MACOE
      DO 1070 I=1,NALPHA
         CALL TBFUNX(ALSCHD(I),CDEF,CLA(I),NALPHA,ALSCHD,CL,G,IQ,MI,NG,
     1               0,0,QEXPD,5,ROUTID)
 1070 CONTINUE
      ZEE=ZW-ZCG
      SINGEG=SIN(GEG/RAD)
      CLPCLP=1.-2.*ZEE*SINGEG/SSPN+3.*(ZEE/SSPN)**2*SINGEG**2
      LAMB=RAD*ATAN(TANCO4/BETA)
C
C           -- FIGURE 7.1.2.2-24 --
C
      CALL TLIP2X(X12224,X22224,Y12224,8,10,LAMCO4,ASTRW,CLPCL2,
     1            1,1,1,1,Q12224,3,ROUTID)
      SRSW=SR/SW
      AAAA=4.*SSPN**2/(RAD*SRSW*BLREF**2)
      BAOK  =BETA*ASTRW/K
C
C              FIGURE 7.1.2.2-20 A-D
C
      CALL INTEP3(BAOK,LAMB,LAMDA,X1220A,X2220A,Y2220A,13,17,Q2220A,
     1            X1220B,X2220B,Y2220B,13,10,Q2220B,
     2            X1220C,X2220C,Y2220C,13,10,Q2220C,
     3            1,1,1,1,1,1,
     4            X1220D,X2220D,Y2220D,13,18,Q2220D,BCLPCL)
      BBBB=AAAA*BCLPCL*K*CLPCLP/(BETA*CLACLO)
      DO 1080 I=1,NALPHA
         CLT=CL(I)*SRSW
         DCLPD(I)=CLPCL2*CLT**2-CDO/8.*SRSW
         CLPWBS(I)=BBBB*CLA(I)+AAAA*DCLPD(I)
 1080 CONTINUE
C
C     ---WING-BODY ROLLING DERIVATIVE,CNP---
C
      DO 1090 I=1,NALPHA
 1090 ALMALO(I) = ALSCHD(I)-ALSD
      BEE=SQRT(1.-MACH**2*COSLO4**2)
      CCCC=(ASTRW+4.*COSLO4)/(ASTRW*BEE+4.*COSLO4)
      DDDD=(ASTRW*BEE+.5*(ASTRW*BEE+COSLO4)*TANCO4**2)
      EEEE=ASTRW+.5*(ASTRW+COSLO4)*TANCO4**2
      IF(CL(I).EQ.0.0)GO TO 1100
      CNPCLO=-(ASTRW+6.*(ASTRW+COSLO4)*(XBOCB*TANCO4/ASTRW+TANCO4**2/12.
     1        ))/((ASTRW+4.*COSLO4)*6.)
      CNPCLM   =CCCC*DDDD*CNPCLO/EEEE
      GO TO 1110
 1100 CNPCLM=0.
 1110 CONTINUE
      DO 1120 I=1,NALPHA
         CLTAN(I)=CL(I)*SRSW*TAN(ALMALO(I)/RAD)
         CDCDO(I)=(CD(I)-CDO)*SRSW
         CL2PAW(I)=(CL(I)*SRSW)**2/(ASTRW*PI)
 1120 CONTINUE
C
C           -- FIGURE 7.1.2.3-12 --
C
      CALL TLIP2X(X12312,X22312,Y12312,6, 8,LAMDA,ASTRW,CNPTHE,2,1,2,1,
     1            Q12312,3,ROUTID)
      CNP=CNPTHE*THETA
      FFFF=AAAA*BLREF/(2.*SSPN)
      DO 1150 I=1,NALPHA
         CLPTAN(I)=CLPWBS(I)*TAN(ALMALO(I)/RAD)
         IF(CL(I).EQ.0.0)GO TO 1130
         CALL TBFUNX(ALSCHD(I),ABC,DCLDA(I),NALPHA,ALSCHD,CLTAN,H,IR,
     1               MI,NG,1,1,QIMPR1,4,ROUTID)
         CALL TBFUNX(ALSCHD(I),ABC,DCDDA(I),NALPHA,ALSCHD,CDCDO,O,IS,
     1               MI,NG,1,1,QIMPR2,4,ROUTID)
         CALL TBFUNX(ALSCHD(I),ABC,DCADA(I),NALPHA,ALSCHD,CL2PAW,P,IT,
     1               MI,NG,1,1,QIMPR3,4,ROUTID)
         KAY(I)=(DCLDA(I)-DCDDA(I))/(DCLDA(I)-DCADA(I))
         GO TO 1140
 1130    CONTINUE
         KAY(I)=1.
 1140    CONTINUE
         CNPWBS(I)=(KAY(I)-1.)*CLPTAN(I)+(KAY(I)*(CNPCLM*CL(I)*SRSW)
     1             +CNP)*AAAA
 1150 CONTINUE
C
C     WING-BODY YAWING DERIVATIVE,CYP---
C
      CLPG=BCLPCL*K/BETA
      DCYPG=(3.*SINGEG*(1.-2.*ZEE*SINGEG/SSPN))*CLPG
C
C           -- FIGURE 7.1.2.1-9  --
C
      CALL INTERX(1,X1219A,ASTRW,I2A219,Y1219A,TRANS,10,10,1,0,0,0,0,0
     1           ,0,0,Q1219A,3,ROUTID)
      CALL TLIP2X(X1219B,X2219B,Y1219B,8,2,LAMCO4,TRANS,CHANGE,1
     1           ,1,1,1,Q1219B,3,ROUTID)
      CALL TLIP2X(X1219C,X2219C,Y1219C,3,2,LAMDA,CHANGE,CYPCLO,
     1            0,0,1,1,Q1219C,3,ROUTID)
      AABB=ASTRW+4.*COSLO4
      BBCC=ASTRW*BEE+4.*COSLO4
      CCDD=ASTRW*BEE+COSLO4
      DDEE=ASTRW+COSLO4
      CYPCLM=AABB*CCDD*CYPCLO/(BBCC*DDEE)
      FFPG=FFFF*DCYPG
      DO 1160 I=1,NALPHA
         CYPWBS(I)=FFPG+FFFF*CYPCLM*SRSW*KAY(I)*CL(I)
 1160 CONTINUE
C
C     WING-BODY ROLLING DERIVATIVE,CNR---
C          --- FIGURE 7.1.3.3-7  --
C           -- FIGURE 7.1.3.3-6  --
C
      CALL TLIP3X(X11336,X21336,X31336,Y71336,4,15,3,LAMCO4,ASTRW,XBOCB,
     1            TRADE,0,1,0,2,1,1,Q71336,3,ROUTID)
      CALL TLIP2X(X1133A,X2133A,Y7133A,2,2,LAMDA,TRADE,CNRCL2,0,1,0,1,
     1            Q71336,3,ROUTID)
      CALL TLIP3X(X11337,X21337,X31337,Y71337,4, 9,3,ABS(LAMCO4),
     1            ASTRW,XBOCB,CNRCDO,0,1,0,2,1,1,Q71337,3,ROUTID)
      DO 1170 I=1,NALPHA
         CDOO(I)=CD(I)*SRSW-CL2PAW(I)
         CNRWBS(I)=AAAA*((CNRCL2*(CL(I)*SRSW)**2)+CNRCDO*CDOO(I))
 1170 CONTINUE
      RETURN
      END
C ===== subwbt.f =====
      SUBROUTINE SUBWBT
C
C     THIS ROUTINE YIELDS THE FOLLOWING WING-BODY-TAIL DERIVATIVES-
C       SUBSONIC    CYP    (YAW)
C                   CNP    (ROLL)
C                   CNR    (ROLL)
C
      REAL MACH,LP,LPF
      COMMON /OVERLY/ NLOG,NMACH,IM,NALPHA
      COMMON /OPTION/ SREF,CBARR,RUFF,BLREF
      COMMON /FLGTCD/ FLC(93)
      COMMON /SBETA/  STB(135),TRA(108),TRAH(108),STBH(135)
      COMMON /IBWHV/  PBWHV,BWHV(380)
      COMMON /IBWV/   PBWV,BWV(380)
      COMMON /IBWH/   PBWH,BWH(380)
      COMMON /IHT/    PHT,HT(380)
      COMMON /IBW/    PBW,BW(380)
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /IVT/    PVT,VT(380)
      COMMON /IVF/    PVF,VF(380)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      DIMENSION ROUTID(2)
      DIMENSION ALSCHD(20),CYPWBT(20),CYPWBS(20),CNPWBT(20),
     1          CNPWBS(20),CNRWBT(20),CNRWBS(20)
      EQUIVALENCE(CYPWBT(1),BWHV(301)),(CNPWBT(1),BWHV(321)),
     1  (CNRWBT(1),BWHV(341)),(CYPWBS(1),BW(301)),(CNPWBS(1),BW(321)),
     2  (CNRWBS(1),BW(341))
      EQUIVALENCE (ALSCHD(1),FLC(23)),(ZP,STB(12)),(LP,STB(11)),
     1  (DYBV,VT(141)),(ZPF,STBH(12)),(LPF,STBH(11)),(DYBF,VF(141))
      DATA ROUTID/4HSUBW,4HBT  /
      DO 1030 I=1,NALPHA
         COSAL=COS(ALSCHD(I)/RAD)
         SINAL=SIN(ALSCHD(I)/RAD)
         IF(.NOT. VTPL) GO TO 1010
         ZEE=ZP*COSAL-LP*SINAL
         VT(I+300)=2.*(ZEE-ZP)*DYBV/BLREF
         ABCDE=LP*COSAL+ZP*SINAL
         VT(I+320)=-(ABCDE*2.*(ZEE-ZP))*DYBV/BLREF**2
         VT(I+340)=2.* ABCDE**2*DYBV/BLREF**2
 1010    CONTINUE
         IF(.NOT. VFPL)GO TO 1020
         ZEE=ZPF*COSAL-LPF*SINAL
         VF(I+300)=(2.*ZEE-ZPF)*DYBF/BLREF
         ABCDE=LPF*COSAL+ZPF*SINAL
         VF(I+320)=-(2.*ABCDE*(ZEE-ZPF))*DYBF/BLREF**2
         VF(I+340)= 2.*ABCDE**2*DYBV/BLREF**2
 1020    CONTINUE
C
C   GET IOM INCREMENT FOR V.T. TO CYP, CNP AND CNR
C   SET IOM INCREMENT FOR H.T. TO ZERO
C
         BWHV(I+300) = BW(I+300) + VT(I+300) + VF(I+300)
         BWHV(I+320) = BW(I+320) + VT(I+320) + VF(I+320)
         BWHV(I+340) = BW(I+340) + VT(I+340) + VF(I+340)
         HT(I+300) = 0.0
         HT(I+320) = 0.0
         HT(I+340) = 0.0
C
C   ACTUALLY B-W-H-V IS THE SAME AS B-W-V
C
         BWV(I+300) = BWHV(I+300)
         BWV(I+320) = BWHV(I+320)
         BWV(I+340) = BWHV(I+340)
C
C   ACTUALLY B-W-H IS THE SAME AS B-W
C
         BWH(I+300) = BW(I+300)
         BWH(I+320) = BW(I+320)
         BWH(I+340) = BW(I+340)
 1030 CONTINUE
      RETURN
      END
C ===== supcld.f =====
      SUBROUTINE SUPCLD
C
C  THIS ROUTINE YIELDS THE SUPERSONIC WING ACCELERATION DERIVATIVE,CLAD
C
      INTEGER Y14111,D14111,D24111,D34111,D3A111,Y1A111,D1A111,D2A111
      REAL MACOE
      REAL MACH,LSTAR,LAMDA
      COMMON /OVERLY/ NLOG,NMACH,IM,NALPHA
      COMMON /OPTION/ SR,CBARR,RUFF,BLREF
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /FLGTCD/ FLC(93)
      COMMON /SUPWH/  SLG(141)
      COMMON /POWR/   DYN(213)
      COMMON /WINGD/  A(195)
      COMMON /IWING/  PWING, WING(400)
      COMMON /WINGI/  WINGIN(101)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,
     2                SUPERS,SUBSON,TRANSN,HYPERS,
     3                SYMFP,ASYFP,TRIMC,TRIM
      LOGICAL FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1        HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,
     2        SUPERS,SUBSON,TRANSN,HYPERS,
     3        SYMFP,ASYFP,TRIMC,TRIM
      DIMENSION ROUTID(2)
      DIMENSION Q71417(3),Q14111(3)
      DIMENSION I2A417(4),I2B417(4),I2C417(4)
      DIMENSION X2A417(16),Y1A417(16)
      DIMENSION X2B417(26),Y1B417(26)
      DIMENSION X2C417(15),Y1C417(15)
      DIMENSION X24111(15),X14111(7),X34111(5),Y14111(263)
      DIMENSION D14111( 99),D24111( 95),D34111(69)
      DIMENSION X2A111(15),X1A111(7),X3A111(5),Y1A111(263)
      DIMENSION D1A111( 99),D2A111( 95),D3A111( 69)
      EQUIVALENCE (D14111(1),Y14111(1)),(D24111(1),Y14111(100))
      EQUIVALENCE (D34111(1),Y14111(195))
      EQUIVALENCE (D1A111(1),Y1A111(1)),(D2A111(1),Y1A111(100))
      EQUIVALENCE (D3A111(1),Y1A111(195))
      EQUIVALENCE (MACOE,A(16)),(LSTAR,A(29)),
     1            (XACCR,SLG(134)),(CRSTR,A(10)),
     2            (ASTRW,A(7)),(LAMDA ,A(27)),(BETA,SLG(1)),
     3            (TANLE,A(62)),(SW,A(3))
      EQUIVALENCE (EPPBC,DYN(9)),(GBC,DYN(10)),(XACCRB,DYN(14)),
     1       (F2N,DYN(24)),(F3X,DYN(25)),(F1N,DYN(23)),(CLAD1,DYN(22)),
     2       (CLAD2,DYN(16)),(CLADWH,WING(241))
      DATA Q71417 /4H7.1.,4H4.1-,4H7   /
      DATA Q14111 /4H7.1.,4H4.1-,4H11  /
      DATA I2A417 /16,3*0/, I2B417 /26,3*0/, I2C417 /15,3*0/
C
C                       FIGURE 7141-7  F1(N)
C
      DATA X2A417
     1 / -1., -.8, -.6, -.4, -.2, 0., .2, .4, .5, .6, .7, .8, .85, .9,
     2    .95, 1.0  /
      DATA Y1A417
     1 / 1.7, 1.57, 1.42, 1.3, 1.17, 1., .87, .7, .65, .56, .45, .37,
     2   .33, .23, .2, 0. /
C
C                      FIGURE 7141-7  F2(N)
C
      DATA X2B417
     1 / -1., -.9, -.8, -.7, -.6, -.5, -.4, -.3, -.2, -.1, 0., .1, .2,
     2   .3, .4, .45, .5, .55, .6, .65, .7, .75, .8, .85, .9, .95 /
      DATA Y1B417
     1 / 1.2, 1.19, 1.18, 1.17, 1.16, 1.14, 1.13, 1.1, 1.08, 1.05, 1.,
     2   1., 1., 1., 1.01, 1.03, 1.05, 1.07, 1.12, 1.15, 1.2, 1.28,
     3   1.37, 1.5, 1.75, 2.5  /
C
C                       FIGURE 7141-7 F3(X)
C
      DATA X2C417
     1 / -1.0, -.8, -.6, -.4, -.2, 0., .2, .3, .4, .5, .6, .7, .8, .85 ,
     2     1./
      DATA Y1C417
     1 /.66, .7, .75, .83, .92,1.02,1.19,1.34,1.52,1.83,2.3,3.2,5.25,
     2 7.3 , 14. /
      DATA X24111/0.,8.,12.,16.,20.,24.,28.,32.,34.,36.,38.,40.,42.,44.,
     145./
      DATA X14111/3.,4.,5.,6.,8.,12.,20./
      DATA X34111/0.,.25,.5,.75,1./
      DATA X2A111/0.,8.,12.,16.,20.,24.,28.,32.,34.,36.,38.,40.,42.,44.,
     145./
      DATA X1A111/3.,4.,5.,6.,8.,12.,20./
