      IF(QLAMDA.LT.5.)GO TO 1040
      GO TO 1070
 1010 IF(LAMDA.LT.0.25)GO TO 1030
 1020 CONTINUE
      CMADPP=SAVE*MACOE/(BETA**2*CBARR*RAD)*(MACH**2*CMAD1-CMAD2)
      IF(QLAMDA.LT.0.25)GO TO 1050
      GO TO 1070
 1030 CONTINUE
      QLAMDA=LAMDA
      LAMDA=0.
      GO TO 1000
 1040 CMDD1=CMADWH
      LAMDA=.25
      GO TO 1020
 1050 CMADPP=(CMADPP-CMDD1)*4.*LAMDA+CMDD1
      GO TO 1070
