 1000 ASTAN2=AW*TANCO2
      BAW=BETA*AW
C
C     ---SUPER WING,WING-BODY ROLLING  DERIVATIVE,CLP---
C              FIGURE 7.1.2.2-25 A-E
C
      CALL INTEP3(ASTAN2,BAW,LAMDA,X1225A,X2225A,Y2225A,7,17,Q2225A,
     1            X1225B,X2225B,Y2225B,7,13,Q2225B,
     2            X1225C,X2225C,Y2225C,7,13,Q2225C,
     3            X1225D,X2225D,Y2225D,7,14,Q2225D,
     4            X1225E,X2225E,Y2225E,7,17,Q2225E,CLPA)
