     1-.0960,-.0915,-.0881,-.0860,-.0794,-.076,-.0681,-.062,-.057      ,
     2-.098,-.112,-.1255,-.1265,-.1230,-.1190,-.1090,-.100,-.096,-.0915,
     3-.0881,-.0860,-.0794,-.076,-.0681,-.062,-.057    ,-.098,-.1051,
