     9,-.067,-.0672,-.067,-.0663,-.065,-.0647,-.064,-.063,-.0627,-.0610,
     A-.060,-.0497,-.0425,-.037    ,-.0575,-.0585,-.06,-.0605,-.0614,
     B-.0616,-.0626,-.062,-.0615,-.061,-.060,-.0599,-.0582,-.058,-.0558,
     C-.0454,-.040 /
      DATA Y2225B /-.0985,-.116,-.135,-.1285,-.1185,-.113,-.098,-.0865,
     1-.081,-.077,-.072,-.0695,-.0635,-.061,-.054,-.049,-.0445        ,
     2-.0985,-.1115,-.125,-.123,-.1165,-.110,-.101,-.0895,-.0833,-.080,
     3-.073,-.071,-.0645,-.062,-.055,-.0495,-.045    ,-.0985,-.1058,
     4-.113,-.112,-.1108,-.110,-.101,-.0905,-.085,-.0815,-.075,-.0728,
     5-.0655,-.063,-.056,-.05,-.0455    ,-.092,-.097,-.1025,-.1028,-.102
     6,-.101,-.098,-.0925,-.088,-.0845,-.079,-.076,-.069,-.0655,-.058,
     7-.0516,-.0465    ,-.084,-.0871,-.0905,-.092,-.0936,-.0931,-.0913,
     8-.089,-.088,-.087,-.082,-.0795,-.0725,-.069,-.061,-.0542,-.049
     9,-.0765,-.0776,-.0788,-.081,-.083,-.084,-.086,-.0843,-.0835,-.083,
     A-.0814,-.0806,-.076,-.0731,-.0644,-.057,-.0509   ,-.069,-.0696,
     B-.070,-.072,-.0739,-.0746,-.077,-.0786,-.0789,-.0783,-.0773,-.077,
     C-.075,-.0735,-.0684,-.0606,-.0536 /
      DATA Y2225C /-.098,-.119,-.1375,-.131,-.123,-.118,-.1055,-.095,
     1-.090,-.086,-.0815,-.0777,-.0712,-.0682,-.0619,-.056,-.0512,
     2-.098,-.114,-.131,-.127,-.121,-.1175,-.1055,-.0977,-.0938,-.086,
     3-.0815,-.0782,-.0721,-.069,-.062,-.056,-.0512     ,-.098,-.1088,
     4-.119,-.1182,-.1155,-.1133,-.1055,-.0977,-.0940,-.089,-.0842,-.081
     5,-.0730,-.0692,-.0620,-.056,-.0512     ,-.095,-.1011,-.1075,-.1091
     6,-.1081,-.1078,-.104,-.0977,-.0950,-.0905,-.086,-.0831,-.076,-.073
     7,-.0645,-.0576,-.052    ,-.0875,-.091,-.094,-.0958,-.0982,-.0996,
     8-.0985,-.0977,-.0950,-.0915,-.0879,-.0855,-.0791,-.076,-.0675,
     9-.0605,-.0548      ,-.0816,-.0822,-.0826,-.0843,-.0865,-.0875,
     A-.0905,-.0906,-.0899,-.0886,-.0879,-.0855,-.0806,-.0778,-.070,
     B-.063,-.056     ,-.0738,-.073,-.0725,-.0740,-.076,-.0770,-.08,
     C-.0827,-.084,-.085,-.0845,-.0841,-.083,-.081,-.073,-.0657,-.059  /
      DATA Y2225D /-.0989,-.120,-.1415,-.1335,-.124,-.119,-.108,-.099,
     1-.094,-.090,-.0861,-.083,-.0775,-.074,-.066,-.060,-.0545         ,
     2-.0989,-.1145,-.1311,-.1265,-.120,-.117,-.108,-.099,-.094,-.090,
     3-.0861,-.083,-.0775,-.074,-.066,-.060,-.0545     ,-.0989,-.108,
     4-.1171,-.121,-.117,-.1144,-.107,-.100,-.096,-.093,-.0882,-.085,
     5-.0795,-.075,-.067,-.0605,-.055     ,-.0959,-.0999,-.1038,-.1056,
     6-.1085,-.111,-.1054,-.100,-.097,-.0935,-.090,-.0865,-.0816,-.0775,
     7-.069,-.0623,-.0565     ,-.0899,-.0906,-.0915,-.096,-.098,-.099,
     8-.101,-.100,-.0972,-.0950,-.092,-.089,-.0841,-.0806,-.0725,-.065,
     9-.0585     ,-.083,-.082,-.081,-.0845,-.088,-.0898,-.093,-.094,
     A-.0935,-.0934,-.092,-.0900,-.086,-.0825,-.0745,-.067,-.060       ,
     B-.0765,-.0746,-.073,-.076,-.0798,-.0815,-.0846,-.086,-.0867,-.0875
     C,-.0875,-.0865,-.0841,-.0825,-.0755,-.0686,-.062  /
      DATA Y2225E /-.098,-.1135,-.1283,-.130,-.1245,-.1200,-.1090,-.100,
     1-.0960,-.0915,-.0881,-.0860,-.0794,-.076,-.0681,-.062,-.057      ,
     2-.098,-.112,-.1255,-.1265,-.1230,-.1190,-.1090,-.100,-.096,-.0915,
     3-.0881,-.0860,-.0794,-.076,-.0681,-.062,-.057    ,-.098,-.1051,
     4-.1125,-.1180,-.1178,-.1160,-.1090,-.102,-.0985,-.0935,-.09,-.0868
     5,-.0815,-.0775,-.0695,-.063,-.0578    ,-.100,-.091,-.1040,-.1083,
     6-.114,-.1128,-.1075,-.1020,-.0985,-.0950,-.092,-.089,-.0831,-.0795
     7,-.072,-.065,-.059     ,-.090,-.0912,-.0920,-.0955,-.0994,-.1010,
     8-.1045,-.102,-.0980,-.0950,-.0930,-.09,-.0850,-.0811,-.073,-.066,
     9-.0606     ,-.0832,-.0823,-.0815,-.0850,-.0889,-.0910,-.094,-.0956
     A,-.096,-.096,-.093,-.0905,-.0860,-.083,-.075,-.0682,-.0625       ,
     B-.076,-.0743,-.0725,-.0751,-.0787,-.0810,-.084,-.0870,-.088,-.089,
     C-.0895,-.090,-.0867,-.084,-.0767,-.0705,-.065   /
C
C  *** CYB WING ALONE ***
C
      LF = 0
      ZH = ZHH-((HTIN(4)-HTIN(3))*AHT(62)+AHT(30))*SIN(ALIH/RAD)
      SCALE=2.*WINGIN(4)/BLREF
      MACH=FLC(I +2)
      BETA=SQRT(MACH**2-1.)
      NX=BODYIN(1)+.5
      RLB=BODYIN(NX+1)
      RM=MACH**2
      RB=BETA**2
      IF(WINGIN(13).EQ.UNUSED)WINGIN(13)=0.0
      IF(WINGIN(12).EQ.UNUSED)WINGIN(12)=0.0
      IF(WINGIN(14).EQ.UNUSED)WINGIN(14)=0.0
      ARG=WINGIN(3)-WINGIN(12)
      DIHEQ=(WINGIN(13)*ARG+WINGIN(14)*WINGIN(12))/WINGIN(3)
      IF(WINGIN(15).NE.WTYPE(1)) GO TO 1060
      IF(SWEPE.EQ.0.AND.TAPR.EQ.1.AND.(AR*BETA.GE.1.0))GO TO 1000
      ARG=BETA/.00001
      IF(TANLE.NE.0.0)ARG=BETA/TANLE
      IF(TAPR .EQ. 0.0 .AND. (ARG .LT. .998))GO TO 1020
      GO TO 1040
 1000 CONTINUE
      X=XW+0.5*CR-XCG
      ARG1= 1./(PI*AR**2*RB)
      ARG2=4.*RM/3.+8.*RM*X/CRBAR
      ARG3=PI* AR*(1.-RB)*(3.+RB)/(3.*BETA**3)
      DO 1010 J=1,NALPHA
         ALP= (ALPHA(J)/RAD)**2
         CYBW(J)=-ALP*8.0*RM/(RAD*PI*RB*AR) -.0001*ABS(DIHEQ)
C
C  *** CNB WING ALONE ***
C
         CNBW(J)=SCALE*ALP*ARG1*(ARG2-ARG3)/RAD
 1010 CONTINUE
      GO TO 1040
 1020 CONTINUE
C                        FIGURE 5.1.1.1-6 (1./Q(BC))
      VAR(1)=ARG
      LGH(1)=16
      CALL INTERX(1,X51116,VAR,LGH,Y51116,QBC,16,16,
     10,0,0,0,0,0,0,0,Q51116,3,ROUTID)
C
C                            FIGURE 7.1.1.1-8 (EBC)
C
      LGH(1)=8
      CALL INTERX(1,X71118,VAR,LGH,Y71118,EBC,8,8,
     10,0,0,0,0,0,0,0,Q71118,3,ROUTID)
      ARG1= PI*AR*RM/(4.*RAD*QBC)
      X=XW+.6666*SPAN*TANLE-XCG
      ARG2=PI/3.*(EBC+(AR**2/16.+X/CRBAR)*RM/QBC)/RAD
      DO 1030 J=1,NALPHA
         ALP= (ALPHA(J)/RAD)**2
         CYBW(J)=-ALP*ARG1-.0001*ABS(DIHEQ)
         CNBW(J)=SCALE*ALP*ARG2
 1030 CONTINUE
 1040 CONTINUE
C
C *** CLB WING ALONE ***
C                      FIGURE 7.1.2.2-25A-E  (CLPTOA)
      VAR(1)=BETA*AR
      VAR(2)=AR*TANMID
      VAR(3)=TAPR
      LGH(1)=17
      LGH(2)=7
      LGH(3)=5
      CALL INTERX(3,X12225,VAR,LGH,Y12225,CLPTOA,17,597,
     10,0,0,0,2,2,0,0,Q225AE,3,ROUTID)
      CLP= CLPTOA*AR*CLPCTY
      CLBD=2.*DIHEQ*(1.+2.*TAPR)*CLP/(RAD**2.*(1.+3.*TAPR))
      ARG1=(1.+TAPR*(1.+SWEPE))*(1.+SWEPE/2.)*TANLE/BETA
      ARG2= RM*COSLE**2/AR+(ABS(TANLE/4.))**1.3333
      DO 1050 J=1,NALPHA
         CLBW(J)=SCALE*(CLBD-0.061*CNW(J)*CNAW*ARG1*ARG2/RAD)
 1050 CONTINUE
C
C  *** CYB WING-BODY ***
C
 1060 IF(.NOT.BO)RETURN
      SPANIN=SPAN-SPANO
      ARG=SIN(SYNA(4)/RAD)
      ZW=-SYNA(3)+(.25*A(10)+BD(66))*ARG-SPANIN*TAN(WINGIN(13)/RAD)
      ARG=ZW/(SPANIN)
      RKI= 1.0+.49*ARG
      IF(ARG.LT.0.0)RKI=1.0-.85*ARG
      CYBWB=-RKI*CLAB-0.0001*ABS(DIHEQ)
C
C  *** CNB WING-BODY ***
C
      RNN=FLC(I +42)*RLB
C                          EQUATION FOR FIGURE 5.2.3.1-9 KRL
      RKRL=1.+ALOG(1.E-6*RNN)/4.86
      ARG11=1.0
      NV=BODYIN(1)+.5
      QL=RLB*.25
      TFL=RLB*.75
      I1=0
      I2=0
      CALL TBFUNX(QL,RH1,DYDX,NV,BODYIN(2),BODYIN(62),C1,I1,MI,NG,
     10,0,4HRH1 ,1,ROUTID)
      RH1=2.*RH1
      CALL TBFUNX(TFL,RH2,DYDX,NV,BODYIN(2),BODYIN(62),C2,I2,MI,NG,
     10,0,4HRH2 ,1,ROUTID)
      RH2=2.*RH2
      ARG12=SQRT(RH1/RH2)
      CALL TRAPZ(BODYIN(62),NV,BODYIN(2),SBS,1)
      SBS=2.*SBS
      ARG13=RLB**2/SBS
      ARG14=XCG/RLB
C
C                   FIGURE 5.2.3.1-8 (KN)
C
      CALL TLINEX(X158A,X258A,Y58A,10,2,ARG13,ARG14,YDUMY,
     1           2,1,2,1,Q52318,3,ROUTID)
      CALL TLINEX(X158B,X258B,Y58B,5,3,ARG12,YDUMY,YDUMY2,
     1           2,0,2,1,Q52318,3,ROUTID)
      CALL TLINEX(X158C,X258C,Y58C,5,2,ARG11,YDUMY2,RKN,
     1          2,0,2,1,Q52318,3,ROUTID)
      CNBWB=-RKN*RKRL*SBS*RLB/(SR*BLREF)
      IF(WINGIN(15).NE.WTYPE(1)) GO TO 1080
C
C  *** CLB WING-BODY ***
C
      ZWP= ZW+CR*SIN(ALPHAI/RAD)/4.0
      ARG1=SQRT(AR)
      DBODY = 2.0*SPANIN
      CLBZW =  0.6*ARG1*ZWP*DBODY/(RAD*SPAN**2)
      ARG= (DBODY/(2.*SPAN))**2*DIHEQ
      DCLB=-0.0005*ARG1*ARG
      ARG2=CLBZW+DCLB
      DO 1070 J=1,NALPHA
      CLBWB(J)=CLBW(J)+ARG2*SCALE
      BWV(J+180)=BWI(J+180)
 1070 CONTINUE
      BWV(141)=BWI(141)
      BWV(161)=BWI(161)
 1080 CONTINUE
C
C       ***HORIZONTAL TAIL ADDED TO WING-BODY***
C
      IF(.NOT.HTPL)GO TO 1110
      RH= HTIN(4)-HTIN(3)
C
C              FIGURE 5.3.1.1-25OO (KH(B))HL=RKHBHL
C
      IF(ABS(ZH).GT.RH.OR.(ZH/RH.EQ.0.0))GO TO 1110
      ARG=RH/HTIN(4)
      IF(ARG.LT.1.0)GO TO 1090
      VAR(1)=1./ARG
      LGH(1)=6
      CALL INTERX(1,XA25OO,VAR,LGH,YA25OO,RKHBHL,6,6,
     1            0,0,0,0,0,0,0,0,Q125OO,3,ROUTID)
      GO TO 1100
 1090 VAR(1)=ARG
      LGH(1)=8
      CALL INTERX(1,XB25OO,VAR,LGH,YB25OO,RKHBHL,8,8,
     1            0,0,0,0,0,0,0,0,Q125OO,3,ROUTID)
 1100 RKHB=RKHBHL*(1.-(1.-(ZH/RH)**2)**0.5)
      DCYHWB=-RKHB*CLAB*SHB(I)/SEXT(I)
      GO TO 1120
 1110 DCYHWB=0.0
      IF(.NOT. HTPL) GO TO 1120
      IF((ZH/RH) .NE. 0.0) LF = 1
 1120 CONTINUE
      IF(.NOT. HTPL) GO TO 1140
      BWH(141)=CYBWB+DCYHWB
      BWH(161)=CNBWB-DCYHWB*RLPH(I)/BLREF
      BWHV(141) = BWH(141)
      BWHV(161) = BWH(161)
      IF(WINGIN(15).NE.WTYPE(1)) GO TO 1140
      DO 1130 J=1,NALPHA
         BWH(J+180)=CLBWB(J)
         BWV(J+180)=BWI(J+180)
         BWHV(J+180)=BWH(J+180)
 1130 CONTINUE
 1140 CONTINUE
      RETURN
      END
C ===== suplav.f =====
      SUBROUTINE SUPLAV
C
C***  SUPERSONIC VERTICAL TAIL LATERAL STABILITY
C
      COMMON /IVT/     PVT,    VT(380)
      COMMON /IBW/     PBW,    BWI(380)
      COMMON /IBWV/    PBWV,   BWV(380)
      COMMON /IBWHV/   PBWHV,  BWHV(380)
C
      COMMON /FLGTCD/ FLC(160)
      COMMON /OPTION/ SREF, CBARR, ROUGFC, BLREF
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZHH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SC, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /WINGI/  WINGIN(101)
      COMMON /VTI/    VTIN(154), TVTIN(8), VFIN(154)
      COMMON /HTI/    HTIN(154)
      COMMON /SBETA/  SLA(31)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /VTDATA/ AVT(195), AVF(195)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF,K
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      LOGICAL VHPLA, VERTUP
C
      DIMENSION ROUTID(2), QAMF(3), XAMF(3), YAMF(3), CC(6)
      DIMENSION ALPHA(20), SYNA(19)
      DIMENSION RLPH(20), SVB(20), SVWB(20), SVHB(20)
C
      EQUIVALENCE (ALPHA(1),FLC(23))
      EQUIVALENCE (DCYHWB,SLA(23))
      EQUIVALENCE (RKVWB,SLA(24)), (RKVB,SLA(25)), (RKPVWB,SLA(26))
      EQUIVALENCE (DCYBV,SLA(27)), (RKVHB,SLA(28)), (ZP,SLA(29))
      EQUIVALENCE (RLP,SLA(30)), (CNAV,SLA(31))
      EQUIVALENCE (SYNA(1),XCG), (SPAN,WINGIN(4))
      EQUIVALENCE (RLPH(1),HTIN(95)), (SVWB(1),VTIN(95))
      EQUIVALENCE (SVB(1),VTIN(115)), (SVHB(1),VTIN(135))
C
      DATA WTYPE  / 4HSTRA /
      DATA ROUTID / 4HSUPL, 4HAV   /
      DATA QAMF   / 4H5.3., 4H1.1-, 4H25A  /
      DATA XAMF   / 0.0, 0.40, 1.0 /
      DATA YAMF   / 0.5, 1.79, 4.0 /
C
      ZH = ZHH-((HTIN(4)-HTIN(3))*AHT(62)+AHT(30))*SIN(ALIH/RAD)
      SVSTAR = AVT(3)
      VHPLA  = .FALSE.
      SCALE  = 2.0*SPAN/BLREF
C
C       ***VERTICAL TAIL ADDED TO WING-BODY***
C
      R1=VTIN(4)-VTIN(3)
      R1OBA=R1/VTIN(4)
      R2OBO2=R1/WINGIN(4)
      ZHOR1=-ZW/R1
 1000 IF(.NOT.VERTUP)ZHOR1=-ZHOR1
C
C         CALL  SUBROUTINE MASRAT FOR FIG.5.3.1.1-25B-P
C
      CALL MASRAT(R2OBO2,R1OBA,ZHOR1,ARG1)
      IF(VHPLA)GO TO 1010
C
C              FIGURE 5.3.1.1-25A KV(B)
C
      IN = 0
      CALL TBFUNX(R1OBA, RKVB, DYDX, 3, XAMF, YAMF, CC,
     1            IN, MI, NG, 0, 1, QAMF, 3, ROUTID)
      RKVWB=ARG1
      RKPVWB= (RKVB*SVB(I)+RKVWB*SVWB(I))/SVSTAR
      DCYBV=-RKPVWB*CNAV
C
C       ***VERTICAL PANEL ADDED TO WING-BODY-HORIZONTAL TAIL***
C
      IF(.NOT. HTPL) GO TO 1020
      R2OBO2=R1/HTIN(4)
      ZHOR1=ZH/R1
      VHPLA=.TRUE.
      GO TO 1000
 1010 RKVHB=ARG1
      DCVWHB=DCYBV-RKVHB*SVHB(I)/SVSTAR*CNAV
 1020 CONTINUE
C
C  *** WING-BODY-TAIL DERIVATIVES ***
C
      BW=2.*SPAN
      DELX=AVT(62)*(VTIN(4)-VTIN(3))
      RLP=SYNA(9)-SYNA(1)+DELX+AVT(30)
      ZP=-SYNA(5)+VTIN(4)-VTIN(3)+AVT(31)+SYNA(14)
      VT(141) = DCYBV
      VT(161) = -DCYBV*RLP/BLREF
      BWV(141) = BWV(141)+VT(141)
      BWV(161) = BWV(161)+VT(161)
      IF(WINGIN(15).NE.WTYPE) GO TO 1050
      DO 1030 J=1,NALPHA
         ALP=ALPHA(J)/RAD
         DZ=(ZP*COS(ALP)-RLP*SIN(ALP))/BW
      VT(J+180)=DCYBV*DZ*SCALE
      BWV(J+180)=BWV(J+180)+VT(J+180)
 1030 CONTINUE
      IF(.NOT. HTPL) GO TO 1050
      VT(141)=DCVWHB
      VT(161)=-DCVWHB*RLP/BLREF
      BWHV(141)=BWHV(141)+DCVWHB
      BWHV(161)=BWHV(161)-DCVWHB*RLP/BLREF
      DO 1040 J=1,NALPHA
         ALP=ALPHA(J)/RAD
         DZ=(ZP*COS(ALP)-RLP*SIN(ALP))/BW
         VT(J+180) = DCVWHB*DZ*SCALE
         BWHV(J+180)=BWHV(J+180)+VT(J+180)
 1040 CONTINUE
 1050 CONTINUE
      RETURN
      END
C ===== suplng.f =====
      SUBROUTINE SUPLNG
C
C***  CALCULATES SUPERSONIC WING CL, CLA AND CMA
C
      DIMENSION ROUTID(2),Q3250A(3),Q3250B(3),Q3246A(3),Q3246G(3),
     1 Q3359A(3),Q3359B(3),Q3361A(3),Q3360A(3),Q246AF(4),
     2 Q13252(3),Q13253(3),Q13251(3),Q222AF(4),Q15127(3),Q15258(3)
      REAL MACH,KSHARP
      REAL LHS,LERBW,LERI,LERO
      DIMENSION T13246(52),D13246(1104),VAA(4),LGA(4),VAB(4),LGB(4),
     1 A1350(17), B1350(19),DA50(72),DB50(88),G13246(9),DG3246(9),
     2A13359(22),D13359(99),ALSCHD(20),BR3359(21),DR3359(110),BL3359(20)
     3,DL3359(50),ALPHAJ(20),CNAAA(20),T61A(9),
     4SLOPE(9)
      DIMENSION DS5258(5),DR5258(5),T15258 (5)
      DIMENSION R13252(12),DRND52(12),S13252(12),DSHP52(12),T13251(12),
     1D13251(12)
      DIMENSION WTYPE(4)
      DIMENSION CAF(20)
      DIMENSION CN(20),CL(20),DUMY4(184),DR360A(156),SUPAF(216),SUBAF(21
     16)
      DIMENSION DUMYC(108),DUMYD(108)
      DIMENSION TL360A(24),DL360A(72),TR360A(25),T13253(24),D13253(140),
     1T422AF(18),DUMY7(65),DUMY8(91),DUMYA(108),DUMYB(108)
      DIMENSION T455(10),D455(10),CD(20),CDL(20)
      DIMENSION DUMY1(184),DUMY2(184),DUMY3(184),DUMY5(184),DUMY6(184)
      DIMENSION EPSLON(20),CM(20)
      DIMENSION X27M(4),X27I(4),C27(6)
      COMMON /OVERLY/ NLOG,NMACH,MIDX,NALPHA
      COMMON /FLGTCD/ FLC(95)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /OPTION/ SW,CBARR,RUFF,BLREF
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /SUPWH/  SLG(141)
      COMMON /WINGD/  A(195)
      COMMON /WINGI/  HTIN(100)
C
C********* HTIN CORRESPONDS TO WINGIN ELSEWHERE ***********************
C
      COMMON /IWING/ PWING,HT(400)
C
C********* HT CORRESPONDS TO WING ELSEWHERE ***************************
C
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1    HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,TRANSN,HYPERS
