      SAVE=MACOE*SW/(CBARR*SR)
      BA=BETA*ASTRW
      QLAMDA=10.
      IF(BCOTLE.GT.1.)GO TO 1060
 1000 IF(LAMDA .NE.0.)GO TO 1010
C
C    ---- SUPERSONIC WING PITCHING DERIVATIVE,CLQ ----
C
      DUMM=1.
C
C           -- FIGURE 7.1.1.1-8 --
