      CALL TLIP3X(X11110,X21110,X31110,Y11110,8,37,3,BA,BCOTLE,LAMDA,BCL
     1            Q,1,0,0,2,0,0,Q11110,3,ROUTID)
      CLQPP=BCLQ/BETA
      CLQPWH=(CLQPP*SAVE-2.*XACCRB*CNA1)/RAD
      IF(QLAMDA.LT.0.25)GO TO 1050
      GO TO 1070
 1030 QLAMDA=LAMDA
      LAMDA=0.
      GO TO 1000
 1040 CLQPW1=CLQPWH
      LAMDA=.25
      GO TO 1020
 1050 CLQPWH=((CLQPWH-CLQPW1)/.25)*QLAMDA+CLQPW1
      LAMDA=QLAMDA
      GO TO 1070
 1060 CONTINUE
