      CALL TLIP3X(X11111,X21111,X31111,Y11111,9,24,5,BA,BCOTLE,LAMDA,
     1            BCLQPP,1,0,0,2,1,0,Q11111,3,ROUTID)
      CLQPWH=BCLQPP*SAVE/(BETA*RAD)
 1070 CONTINUE
      IF(TRANSN)RETURN
      CLQWH=CLQPWH-2.*DCMDCL*CNA1/RAD
      IF(TANLE.EQ..00001)TANLE=0.
      RETURN
      END
