     1            Q,1,0,0,2,0,0,Q11110,3,ROUTID)
      CLQPP=BCLQ/BETA
      CLQPWH=(CLQPP*SAVE-2.*XACCRB*CNA1)/RAD
      IF(QLAMDA.LT.0.25)GO TO 1050
      GO TO 1070
 1030 QLAMDA=LAMDA
      LAMDA=0.
      GO TO 1000
 1040 CLQPW1=CLQPWH
      LAMDA=.25
      GO TO 1020
 1050 CLQPWH=((CLQPWH-CLQPW1)/.25)*QLAMDA+CLQPW1
      LAMDA=QLAMDA
      GO TO 1070
 1060 CONTINUE
C
C           -- FIGURE 7.1.1.1-11A,B,C,D,E,F,G,H,I,J,K, --
C
      CALL TLIP3X(X11111,X21111,X31111,Y11111,9,24,5,BA,BCOTLE,LAMDA,
     1            BCLQPP,1,0,0,2,1,0,Q11111,3,ROUTID)
      CLQPWH=BCLQPP*SAVE/(BETA*RAD)
 1070 CONTINUE
      IF(TRANSN)RETURN
      CLQWH=CLQPWH-2.*DCMDCL*CNA1/RAD
      IF(TANLE.EQ..00001)TANLE=0.
      RETURN
      END
