     C -4.9618E-03,  2.6880E-03,  1.0089E-02,  9.4275E-03,
     D -9.7535E-03, -2.3881E-03,  7.4312E-04,  1.2306E-03,  2.1653E-03,
     E  3.7542E-03,  1.1703E-04, -1.1616E-04,  1.7132E-03,  5.7507E-04,
     F  1.1079E-03, -2.3730E-05, -1.8213E-03,  5.7215E-04 /
