     3  1.1693E-03,  3.2272E-03,  4.5941E-03,  2.6961E-03,
     4  1.2683E+00, -1.7713E-02, -3.9115E-03, -9.2493E-03,  6.5923E-03,
     5  7.4832E-03,  2.5312E-02, -3.7542E-02,  1.7427E-02,  2.0635E-02,
     6  1.8158E-02,  1.6570E-02, -6.3330E-04, -1.6885E-02,
     7 -1.6503E-01, -5.2268E-02, -4.3905E-02, -5.1001E-02, -1.0221E-01,
     8 -1.9949E-02, -5.3897E-02,  6.3401E-03, -1.3287E-01, -1.3673E-01,
     9 -8.0305E-02, -1.8294E-01, -1.1299E-01, -6.8530E-02,
     A -7.7192E-04,  2.5439E-04, -1.2391E-03, -1.1483E-03, -7.8181E-04,
     B -1.0290E-03, -1.3250E-03, -5.1180E-04, -1.3416E-03, -2.3095E-03,
