      DO 1000 I=1,19
        IN = 0
        ID = 1+14*(I-1)
        CALL TBFUNX(XM,C(I),DYDX,14,ZM,CCM(ID),CR,IN,MI,NG,
     1              0,0,QTAB,4,ROUTID)
