C
C***  SET COEFFICIENTS IN BT ARRAY
C
      L = (IA-2)*16
      IF(IM .GE. 2) L = L+(IM-2)*288
      IF(IA .EQ. 1) GO TO 1020
        DO 1010 K=1,16
           BT(I,J,K) = BSUB(K+L)
 1010   CONTINUE
 1020 CONTINUE
      IF(IA .NE. 1) GO TO 1040
        DO 1030 K=1,16
           BT(I,J,K) = 0.0
 1030   CONTINUE
 1040 CONTINUE
      RETURN
      END
