C
C***  SET COEFFICIENTS IN BT ARRAY
C
      L = (IA-2)*16+(IM-11)*240
      IF(IM .GT. 12) L = L+32
      IF(IA .EQ. 1) GO TO 1020
        DO 1010 K=1,16
           BT(I,J,K) = BSUP(K+L)
 1010   CONTINUE
 1020 CONTINUE
      IF(IA .NE. 1) GO TO 1040
        DO 1030 K=1,16
           BT(I,J,K) = 0.0
 1030   CONTINUE
 1040 CONTINUE
      RETURN
      END
