     *-3.5826600E-01, 2.2847071E 00,-9.0555727E-02,-1.1746924E-02/
C
C***  SET COEFFICIENTS IN BT ARRAY
C
      L = (IA-2)*16
      IF(IM .EQ. 6) L = L+288
      IF(IM .EQ. 7) L = L+464
      IF(IM .GE. 8) L = L+(IM-8)*240+656
      IF(IA .EQ. 1) GO TO 1020
        DO 1010 K=1,16
           BT(I,J,K) = BTRN(K+L)
 1010   CONTINUE
 1020 CONTINUE
      IF(IA .NE. 1) GO TO 1040
        DO 1030 K=1,16
           BT(I,J,K) = 0.0
 1030   CONTINUE
 1040 CONTINUE
      RETURN
      END
      LOGICAL FUNCTION TEST(KOL,KEY,NCHAR)
      INTEGER KOL(1) , KEY(1)
      DATA IBLNK/4H      /
C
C     ----TEST FOR NAME IN KEY = NAME IN KOL.NCHAR=NO. OF CHARACTERS
C
      DO 1000 I=1,NCHAR
         IF(KOL(I).NE.KEY(I)) GO TO 1010
 1000 CONTINUE
C
C     ----HERE IF NAME CHECKS
C
      IF(KOL(NCHAR+1).NE.IBLNK)GO TO 1010
      TEST=.TRUE.
      RETURN
C
C     ----HERE IF NAME DOES NOT CHECK
C
 1010 TEST=.FALSE.
      RETURN
      END
C ===== testor.f =====
      SUBROUTINE TESTOR(KOL,L,NAM,K,IER,LEN,LDM,NUM,NAMES)
C
C***  CHECK IF NAMELIST NAME IS LEGAL INPUT USING NMTEST
C
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
      DIMENSION KOL(1), LEN(1), LDM(1), NAMES(1)
      DIMENSION NUMBER(15)
      LOGICAL END, FLAG, ARRAY, FOUND, NMTEST
      INTEGER BLANK, EQUAL, COMMA
      DATA NUMBER / 4H0   ,4H1   ,4H2   ,4H3   ,4H4   ,
     1       4H5   ,4H6   ,4H7   ,4H8   ,4H9   ,4H+   ,4H-   ,
     2       4H.   ,4H*   ,4HE   /
      DATA END / .TRUE. /
      DATA BLANK / 4H     /, EQUAL / 4H=    /, COMMA / 4H,    /
C
      NA = 0
      NB = 0
      NC = 0
      ND = 0
      NE = 0
      NF = 0
C
C***  UNKNOWN NAMELIST NAME - WRITE CARD AND RETURN
C
      IF(IER .EQ. 0) GO TO 1010
        WRITE(6,1170) (KOL(J),J=1,80)
        GO TO 1160
 1010 CONTINUE
C
C***  END CARD - WRITE CARD AND RETURN
C
      IF(NAM .GE. 2) GO TO 1020
        WRITE(6,1180) (KOL(J),J=1,80)
        END = .TRUE.
        GO TO 1160
 1020 CONTINUE
C
C***  INSERT END CARD IF REQUIRED
C
      FLAG = (K .EQ. 1) .AND. (.NOT. END)
      IF(.NOT. FLAG) GO TO 1030
        WRITE(6,1190)  KAND
        WRITE(11,1200) KAND, (BLANK,J=1,75)
        END = .TRUE.
 1030 CONTINUE
C
C***  FIRST CARD DOES NOT CONTAIN NAMELIST NAME - WRITE CARD AND RETURN
C
      FLAG = (K .EQ. 2) .AND. END
      IF(.NOT. FLAG) GO TO 1040
        WRITE(6,1210) (KOL(J),J=1,80), KAND
        GO TO 1160
 1040 CONTINUE
C
C***  TEST FOR VALID VARIABLE NAME STARTING IN KOL(L)
C
      IF(K .EQ. 1) END = .FALSE.
      IF(KOL(L) .NE. BLANK) GO TO 1050
        L = L+1
        IF(L .GE. 81) GO TO 1150
        GO TO 1040
 1050 CONTINUE
      IF(KOL(L) .EQ. KAND) END = .TRUE.
      IF(END) GO TO 1150
      CALL VNAME(KOL,L,LEN,NUM,NAMES,I,FOUND,ARRAY,NDMS,NF,NUMBER,
     1           BLANK,EQUAL)
C
C***  NAME NOT FOUND, IF K=2 CHECK FOR NUMBER CONTINUATION
C***                  IF K=1 SEARCH FOR NEXT NAME
C
      IF(FOUND) GO TO 1090
      IF(K .EQ. 1) GO TO 1070
        NDMS = NDML
        NDML = 0
        DO 1060 J=1,14
        IF(KOL(L) .EQ. NUMBER(J)) GO TO 1120
 1060   CONTINUE
 1070 CONTINUE
      IS = I
      NA = NA+1
 1075 CONTINUE
      IF(L .GE. 81) GO TO 1150
      IF(KOL(L) .EQ. KAND) GO TO 1050
      FLAG = (KOL(L) .EQ. BLANK) .OR. (KOL(L) .EQ. EQUAL) .OR.
     1       (KOL(L) .EQ. COMMA)
      IF(FLAG) GO TO 1077
        L = L+1
        GO TO 1075
 1077 CONTINUE
      IF(L .GE. 81) GO TO 1150
      DO 1080 J=1,15
      IF(KOL(L) .EQ. NUMBER(J)) GO TO 1085
 1080 CONTINUE
      FLAG = (KOL(L) .EQ. BLANK) .OR. (KOL(L) .EQ. EQUAL) .OR.
     1       (KOL(L) .EQ. COMMA)
      IF(FLAG) GO TO 1085
      IF(NMTEST(KOL(L),TRUE,4)) L = L+3
      IF(NMTEST(KOL(L),TRUE,4)) GO TO 1085
      IF(NMTEST(KOL(L),FALSE,5)) L = L+4
      IF(NMTEST(KOL(L),FALSE,5)) GO TO 1085
      IF(KOL(L-1) .EQ. NUMBER(15)) L = L-1
      GO TO 1040
 1085 CONTINUE
      L = L+1
      GO TO 1077
C
C***  NAME FOUND - SET UP ARRAY DESIGNATION AND CHECK NAME DELIMITERS
C
 1090 CONTINUE
      IS = I
      NDM = IABS(LDM(I))
      NDML = 0
      FLAG = ARRAY .AND. (NDM .EQ. 1)
      IF (.NOT. FLAG) GO TO 1100
        ARRAY = .FALSE.
        NC = NC+1
 1100 CONTINUE
      IF(L .GE. 80) GO TO 1110
      IF(KOL(L) .NE. BLANK) GO TO 1110
        L = L+1
        GO TO 1100
 1110 CONTINUE
      IF(KOL(L) .NE. EQUAL) NB = NB+1
      IF(KOL(L) .EQ. EQUAL) L = L+1
C
C***  CHECK NUMERICAL INPUT AND THE NUMBER OF ARRAY
C***  ELEMENTS INPUT
C
 1120 CONTINUE
      I = IS
      IF(I .EQ. 0) GO TO 1075
      IF(L .GE. 81) GO TO 1150
      IF(KOL(L) .NE. BLANK) GO TO 1130
        L = L+1
        GO TO 1120
 1130 CONTINUE
      IF(LDM(I) .LT. 0) CALL LVALUE(KOL,L,NDML,NF,BLANK,
     1                             COMMA,NUMBER)
      IF(LDM(I) .GT. 0) CALL RVALUE(KOL,L,NDML,NF,BLANK,
     1                             COMMA,NUMBER)
C
C***  CHECK THE NUMBER OF VALUES LOADED TO THE VARIABLE DIMENSION
C
      IF(NDML .EQ. 0) GO TO 1077
      IF(NDM .EQ. 1 .AND. NDML .GT. 1) ND = ND+1
      NDML = NDML+NDMS
      IF(NDM .GT. 1 .AND. NDML .GT. NDM) NE = NE+1
      IF(L .LE. 80) GO TO 1040
C
C***  END OF CARD OR END OF INPUT ENCOUNTERED
C
 1150 CONTINUE
      NERR = NA+NB+NC+ND+NE+NF
      IF(NERR .EQ. 0) WRITE(6,1180) (KOL(J),J=1,80)
      IF(NERR .NE. 0) WRITE(6,1220) (KOL(J),J=1,80), NA, NB,
     1                              NC, ND, NE, NF
 1160 WRITE(11,1230) (KOL(J),J=1,80)
C
C***  FORMATS
C
 1170 FORMAT(1X,80A1,3X,33H** ERROR ** UNKNOWN NAMELIST NAME)
 1180 FORMAT(1X,80A1)
 1190 FORMAT(2X,A1,3HEND,78X,32H** MISSING NAMELIST TERMINATION ,
     1       8HADDED **)
 1200 FORMAT(1X,A1,3HEND,75A1)
 1210 FORMAT(1X,80A1,3X,39H** ERROR ** NO NAMELIST NAME FOLLOWING ,A2)
 1220 FORMAT(1X,80A1,3X,11H** ERROR **,I3,2H*A,I3,2H*B,I3,2H*C,
     1       I3,2H*D,I3,2H*E,I3,2H*F)
 1230 FORMAT(80A1)
C
      RETURN
      END
C ===== theory.f =====
      SUBROUTINE THEORY
C
C***  MAIN LOGIC ROUTINE FOR CALCULATING AIRFOIL CHARACTERISTICS
C
      COMMON /IBODY/  PB, NACA(80), BF(232), CBAR
      COMMON /FLGTCD/ FLC(93)
      COMMON / IBH /  PBH, THN(60),CAM(60),A0,XC,MCC,CLCC,XAC(20)
      COMMON /IBWH/   PBWH,AI,ALO,CLI,ASEP,CMCO4,CLA0,CLA(20)
      COMMON /IBWHV/  PBWHV, RHO,TMAX,DELTAY
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      INTEGER A4HW,A4HH,A4HV,A4HF
      LOGICAL CRIT,FLAG
      REAL MACH,MCC
      DATA A4HW,A4HH,A4HV,A4HF/4HW   ,4HH   ,4HV   ,4HF   /
C
C  CALCULATE THE SECTION AERODYNAMICS
C
      FLAG=.FALSE.
      CALL IDEAL
      MACH = 0.0
      RENN = 0.0
      CALL SLOPE(MACH,CLA0,RENN,XACO)
      WRITE(6,1020)
      IF(NACA(6).EQ.A4HW)WRITE(6,1030)
      IF(NACA(6).EQ.A4HH)WRITE(6,1040)
      IF(NACA(6).EQ.A4HV)WRITE(6,1050)
      IF(NACA(6).EQ.A4HF)WRITE(6,1060)
      WRITE(6,1070)AI,ALO,CLI,CMCO4,CLA0,RHO,TMAX,DELTAY
C
C  CALCULATE THE LIFT CURVE SLOPE AT MACH NUMBER, CM AND XAC
C
      NMACH=FLC(1) + 0.5
      CRIT=.FALSE.
      DO 1010 I=1,NMACH
         MACH=FLC(I+2)
         RENN=FLC(I+42)*CBAR
         IF(MACH .GE. MCC) CRIT=.TRUE.
         IF(CLA(I) .NE. UNUSED) GO TO 1010
         IF(MACH .GE. MCC) CLA(I)=CLCC
         IF(CRIT) GO TO 1010
         CALL SLOPE(MACH,CLA(I),RENN,XAC(I))
         IF(CLA(I).NE.UNUSED) GO TO 1000
         FLAG=.TRUE.
         WRITE(6,1110) MACH
         GO TO 1010
 1000    WRITE(6,1080) MACH,CLA(I),XAC(I)
 1010 CONTINUE
      IF(CRIT) WRITE(6,1090) MCC,XC,CLCC
      IF(FLAG) CALL EXIT
 1020 FORMAT(1H1,29X,75HAUTOMATED STABILITY AND CONTROL METHODS PER APRI
     1L 1976 VERSION OF DATCOM    )
 1030 FORMAT(1H ,55X,23HWING SECTION DEFINITION)
 1040 FORMAT(1H ,50X,34HHORIZONTAL TAIL SECTION DEFINITION)
 1050 FORMAT(1H ,51X,32HVERTICAL TAIL SECTION DEFINITION)
 1060 FORMAT(1H ,52X,30HVENTRAL FIN SECTION DEFINITION)
 1070 FORMAT(1H0,33X,23HIDEAL ANGLE OF ATTACK =,F10.5,5H DEG.//
     1   30X,27HZERO LIFT ANGLE OF ATTACK =,F10.5,5H DEG.//
     2   33X,24HIDEAL LIFT COEFFICIENT =,F10.5//
     3   18X,39HZERO LIFT PITCHING MOMENT COEFFICIENT =,F10.5//
     4   29X,28HMACH ZERO LIFT-CURVE-SLOPE =,F10.5,6H /DEG.//
     5   36X,21HLEADING EDGE RADIUS =,F10.5,15H FRACTION CHORD//
     6   30X,27HMAXIMUM AIRFOIL THICKNESS =,F10.5,15H FRACTION CHORD//
     7   48X, 9HDELTA-Y =,F10.5,14H PERCENT CHORD//)
 1080 FORMAT(1H0,25X,5HMACH=,F7.4,19H LIFT-CURVE-SLOPE =,F10.5,
     1   6H /DEG.,5X,6H XAC =,F10.5)
 1090 FORMAT(1H0,36X,43H*** CREST CRITICAL MACH NUMBER EXCEEDED ***//
     1 35X,22H CREST CRITICAL MACH =,F10.5//
     2 46X,11H LOCATION =,F10.5,15H FRACTION CHORD//
     3 38X,19H LIFT-CURVE-SLOPE =,F10.5,6H /DEG.)
 1110 FORMAT(   1X,69H     AIRFOIL MODULE UNABLE TO CALCULATE SECTION CL
     1ALPA FOR MACH NO = ,F7.3,50H  THEREFORE A VALUE MUST BE SPECIFIED
     2BY THE USER./1X,123H     SEE USERS MANUAL FOR SECTION CHARACTERIST
     3ICS INPUT.  (NOTE% CLALPA AND CLMAX SHOULD REFERENCE FOOTNOTE 1 ON
     4 PAGE 29. )/)
      RETURN
      END
C ===== tlin1x.f =====
      SUBROUTINE TLIN1X(X1,Y,NX1,XA1,YA,LX1L,LX1U,MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION FOR Y=F(X)
C
      DIMENSION Y(1),X1(1),DA(3),MESS(20),ROUT(2)
      DIMENSION MSSCL(9),RMSCL(9)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN1,NAS1,X1A,X1B,MSSG1,EX1,LG(7)
      EQUIVALENCE (NOIN1,LG(1)),(X1A,LG(2)),(X1B,LG(3)),(MSSG1,LG(4)),
     1       (EX1,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS1,LG(6))
      DATA TLIN/4H1TIN/,HOL1/4H1EXP/
      DATA MSSCL/4HTLIN,4H1X  ,2*0,1,4*0/
C
      CALL SWITCH(LG,LX1L,LX1U,XA1,X1,NX1)
      IF(LG(7))GO TO 1020
      CALL GLOOK(NX1,XA1,X1,NAS1,NOIN1,I1,T1)
      D2=Y(I1)
      IF(.NOT.NOIN1)D2=Y(I1-1)+T1*(D2-Y(I1-1))
      YA=D2
      IF(MSSG1)GO TO 1000
      RETURN
 1000 IF(ROUT(1).NE.TLIN)GO TO 1010
      ROUT(1)=HOL1
      RETURN
C
C     ----PRINT EXTRAPOLATION MESSAGE
C
 1010 MSSCL(3)=NMSS
      RMSCL(4)=YA
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
      CALL MESSGE(ROUT,MESS,X1,LG,LG,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAPOLATION
C
 1020 IF(X1B)GO TO 1050
C
C     ----HERE FOR XA1 ABOVE
C
      IF(LX1U.GT.1.AND.NX1.GT.2)GO TO 1030
C
C     ----LINEAR EXTRAPOLATION
C
      T1=(XA1-X1(NX1))/(X1(NX1)-X1(NX1-1))
      YA=Y(NX1)+T1*(Y(NX1)-Y(NX1-1))
      GO TO 1000
C
C     ----QUADRATIC EXTRAPOLATION
C
 1030 D2=Y(NX1)
      D1=Y(NX1-1)
      IX=NX1-2
      D0=Y(IX)
 1040 CALL QUAD(X1(IX),DA,XA1,YA)
      GO TO 1000
C
C     ----HERE FOR XA1 BELOW
C
 1050 IF(LX1L.GT.1.AND.NX1.GT.2)GO TO 1060
C
C     ----LINEAR EXTRAPOLATION
C
      T1=(XA1-X1(1))/(X1(2)-X1(1))
      YA=Y(1)+T1*(Y(2)-Y(1))
      GO TO 1000
 1060 D0=Y(1)
      D1=Y(2)
      D2=Y(3)
      IX=1
      GO TO 1040
      END
C ===== tlin3x.f =====
      SUBROUTINE TLIN3X(X1,X2,X3,Y,NX1,NX2,NX3,XA1,XA2,XA3,YA,LX1L,LX2L,
     1LX3L,LX1U,LX2U,LX3U,MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION FOR Y=F(X1,X2,X3)
C
      DIMENSION Y(NX1,NX2,NX3),X1(NX1),X2(NX2),X3(NX3),
     1          DA(3),MESS(20),ROUT(2)
      DIMENSION MSSCL(17),RMSCL(17)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN3,NAS3,X3A,X3B,MSSG3,EX3,LG(7)
      EQUIVALENCE (NOIN3,LG(1)),(X3A,LG(2)),(X3B,LG(3)),(MSSG3,LG(4)),
     1      (EX3,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS3,LG(6))
      DATA TLIN /4H1TIN/, HOL1 /4H1EXP/
      DATA MSSCL /4HTLIN,4H3X  ,2*0,3,12*0/
C
C     ----INITIALIZE SWITCHES.
C
      CALL SWITCH(LG,LX3L,LX3U,XA3,X3,NX3)
      IF(LG(7))GO TO 1110
 1000 CALL GLOOK(NX3,XA3,X3,NAS3,NOIN3,I3,T3)
 1010 ID=I3
      DO 1030 I=1,2
         IX=4-I
         GO TO 1140
 1020    IF(NOIN3)GO TO 1070
 1030 ID=ID-1
      IF(.NOT.EX3)GO TO 1050
      IF(NX3.LT.3)GO TO 1040
      IF(X3A.AND.LX3U.GT.1)GO TO 1120
      IF(X3B.AND.LX3L.GT.1)GO TO 1180
 1040 IF(X3A)GO TO 1190
 1050 D0=D1
 1060 D2=D0+T3*(D2-D1)
 1070 YA=D2
 1080 IF(MSSG3.OR.RO.EQ.HOL1)GO TO 1090
      RETURN
 1090 IF(ROUT(1).NE.TLIN)GO TO 1100
      ROUT(1)=HOL1
      RETURN
 1100 CONTINUE
C
C     ----PRINT EXTRAPOLATION MESSAGE.
C
      MSSCL(3)=NMSS
      RMSCL(4)=YA
C
C     ----1ST VARIABLE.
C
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
C
C     ----2ND VARIABLE.
C
      RMSCL(10)=XA2
      MSSCL(11)=NX2
      MSSCL(12)=LX2L
      MSSCL(13)=LX2U
C
C     ----3RD VARIABLE.
C
      RMSCL(14)=XA3
      MSSCL(15)=NX3
      MSSCL(16)=LX3L
      MSSCL(17)=LX3U
      CALL MESSGE(ROUT,MESS,X1,X2,X3,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAP.
C
 1110 IF(X3B)GO TO 1160
C
C     ----HERE FOR XA3 ABOVE
C
      T3=XA3-X3(NX3)
      I3=NX3
      GO TO 1170
 1120 I3=I3-2
      ID=I3
      IX=1
 1130 I=0
 1140 RO=TLIN
      CALL TLINEX(X1,X2,Y(1,1,ID),NX1,NX2,XA1,XA2,DA(IX),LX1L,LX2L,LX1U,
     1            LX2U,MESS,NMSS,RO)
      IF(I.NE.0)GO TO 1020
 1150 CALL QUAD(X3(I3),DA,XA3,YA)
      GO TO 1080
C
C     ----HERE FOR XA3 BELOW
C
 1160 T3=XA3-X3(1)
      I3=2
 1170 T3=T3/(X3(I3)-X3(I3-1))
      GO TO 1010
 1180 D0=D1
      D1=D2
      ID=3
      IX=3
      I3=1
      GO TO 1130
 1190 D0=D2
      GO TO 1060
      END
C ===== tlin4x.f =====
      SUBROUTINE TLIN4X(X1,X2,X3,X4,Y,NX1,NX2,NX3,NX4,XA1,XA2,XA3,XA4,YA
     1,LX1L,LX2L,LX3L,LX4L,LX1U,LX2U,LX3U,LX4U,MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION OF Y=F(X1,X2,X3,X4)
C     ----STRUCTURE OF Y ARRAY IS Y(NX2,NX1,NX3,NX4)
C
      DIMENSION Y(1),X1(1),X2(1),X3(1),X4(1),
     1          DA(3),MESS(20),ROUT(2)
      DIMENSION MSSCL(21),RMSCL(21)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN4,NAS4,X4A,X4B,MSSG4,EX4,LG(7)
      EQUIVALENCE (NOIN4,LG(1)),(X4A,LG(2)),(X4B,LG(3)),(MSSG4,LG(4)),
     1       (EX4,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS4,LG(6))
      DATA TLIN/4H1TIN/,HOL1/4H1EXP/
      DATA MSSCL/4HTLIN,4H4X  ,2*0,4,16*0/
C
C     ----INITIALIZE SWITCHES.
C
      CALL SWITCH(LG,LX4L,LX4U,XA4,X4,NX4)
      IF(LG(7))GO TO 1110
 1000 CALL GLOOK(NX4,XA4,X4,NAS4,NOIN4,I4,T4)
 1010 N123=NX1*NX2*NX3
      LOC=N123*(I4-1)+1
         DO 1030 I=1,2
         IX=4-I
         GO TO 1140
 1020    IF(NOIN4)GO TO 1070
         IF(I.EQ.1)LOC=LOC-N123
 1030 CONTINUE
      IF(.NOT.EX4)GO TO 1050
      IF(NX4.LT.3)GO TO 1040
      IF(X4A.AND.LX4U.GT.1)GO TO 1120
      IF(X4B.AND.LX4L.GT.1) GO TO 1180
 1040 IF(X4A)GO TO 1190
 1050 D0=D1
 1060 D2=D0+T4*(D2-D1)
 1070 YA=D2
 1080 IF(MSSG4.OR.RO.EQ.HOL1)GO TO 1090
      RETURN
 1090 CONTINUE
C
C     ----SUPRESS MESSAGE IF CALLED BY INTERX
C
      IF(ROUT(1).NE.TLIN)GO TO 1100
      ROUT(1)=HOL1
      RETURN
C
C     ----PRINT EXTRAPOLATION MESSAGE.
C
 1100 MSSCL(3)=NMSS
      RMSCL(4)=YA
C
C     ----1ST VARIABLE.
C
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
C
C     ----2ND VARIABLE.
C
      RMSCL(10)=XA2
      MSSCL(11)=NX2
      MSSCL(12)=LX2L
      MSSCL(13)=LX2U
C
C     ----3RD VARIABLE.
C
      RMSCL(14)=XA3
      MSSCL(15)=NX3
      MSSCL(16)=LX3L
      MSSCL(17)=LX3U
C
C     ----4TH VARIABLE
C
      RMSCL(18)=XA4
      MSSCL(19)=NX4
      MSSCL(20)=LX4L
      MSSCL(21)=LX4U
      CALL MESSGE(ROUT,MESS,X1,X2,X3,X4,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAPOLATION.
C
 1110 IF(X4B)GO TO 1160
C
C     ----HERE FOR XA4 ABOVE.
C
      T4=XA4-X4(NX4)
      I4=NX4
      GO TO 1170
 1120 LOC=LOC-N123
      I4=I4-2
      IX=1
 1130 I=0
 1140 RO=TLIN
      CALL TLIN3X(X1,X2,X3,Y(LOC),NX1,NX2,NX3,XA1,XA2,XA3,DA(IX),LX1L,
     1 LX2L,LX3L,LX1U,LX2U,LX3U,MESS,NMSS,RO)
      IF(I.NE.0)GO TO 1020
 1150 CALL QUAD(X4(I4),DA,XA4,YA)
      GO TO 1080
C
C     ----HERE FOR XA4 BELOW.
C
 1160 T4=XA4-X4(1)
      I4=2
 1170 T4=T4/(X4(I4)-X4(I4-1))
      GO TO 1010
 1180 D0=D1
      D1=D2
      I4=1
      LOC=LOC+2*N123
      IX=3
      GO TO 1130
 1190 D0=D2
      GO TO 1060
      END
C ===== tlinex.f =====
      SUBROUTINE TLINEX(X1,X2,Y,NX1,NX2,XA1,XA2,YA,LX1L,LX2L,LX1U,LX2U,
     1 MESS,NMSS,ROUT)
C
C***  LINEAR FOR Y=F(X1,X2)
C
      DIMENSION X1(1),X2(1),Y(NX2,NX1),ROUT(2),MESS(2),DA(3)
      DIMENSION MSSCL(13),RMSCL(13)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN1,NAS1,X1A,X1B,MSSG1,EX1,LG(7)
      EQUIVALENCE (NOIN1,LG(1)),(X1A,LG(2)),(X1B,LG(3)),(MSSG1,LG(4)),
     1      (EX1,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS1,LG(6))
      DATA TLIN /4H1TIN/, HOL1 /4H1EXP/
      DATA MSSCL /4HTLIN,4HEX  ,2*0,2,8*0/
C
      YA=1.E30
      CALL SWITCH(LG,LX1L,LX1U,XA1,X1,NX1)
      IF(LG(7))GO TO 1100
      CALL GLOOK(NX1,XA1,X1,NAS1,NOIN1,I1,T1)
 1000 ID=I1
      DO 1020 I=1,2
         IX=4-I
         GO TO 1130
 1010    IF(NOIN1)GO TO 1060
 1020 ID=ID-1
      IF(.NOT.EX1)GO TO 1040
      IF(NX1.LT.3)GO TO 1030
      IF(X1A.AND.LX1U.GT.1)GO TO 1110
      IF(X1B.AND.LX1L.GT.1)GO TO 1170
 1030 IF(X1A)GO TO 1180
 1040 D0=D1
 1050 D2=D0+T1*(D2-D1)
 1060 YA=D2
 1070 IF(MSSG1.OR.RO.EQ.HOL1)GO TO 1080
      RETURN
 1080 IF(ROUT(1).NE.TLIN)GO TO 1090
      ROUT(1)=HOL1
      RETURN
 1090 CONTINUE
C
C     ----PRINT EXTRAPOLATION MESSAGE.
C
      MSSCL(3)=NMSS
      RMSCL(4)=YA
C
C     ----1ST VARIABLE.
C
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
C
C     ----2ND VARIABLE.
C
      RMSCL(10)=XA2
      MSSCL(11)=NX2
      MSSCL(12)=LX2L
      MSSCL(13)=LX2U
      CALL MESSGE(ROUT,MESS,X1,X2,LG,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAP.
C
 1100 IF(X1B)GO TO 1150
C
C     ----HERE FOR XA1 ABOVE
C
      T1=XA1-X1(NX1)
      I1=NX1
      GO TO 1160
 1110 I1=I1-2
      ID=I1
      IX=1
 1120 I=0
 1130 RO=TLIN
      CALL TLIN1X(X2,Y(1,ID),NX2,XA2,DA(IX),LX2L,LX2U,MESS,NMSS,RO)
      IF(I.NE.0)GO TO 1010
 1140 CALL QUAD(X1(I1),DA,XA1,YA)
      GO TO 1070
C
C     ----HERE FOR XA1 BELOW
C
 1150 T1=XA1-X1(1)
      I1=2
 1160 T1=T1/(X1(I1)-X1(I1-1))
      GO TO 1000
 1170 D0=D1
      D1=D2
      ID=3
      IX=3
      I1=1
      GO TO 1120
 1180 D0=D2
      GO TO 1050
      END
C ===== tlinvs.f =====
      SUBROUTINE TLINVS(X1,X2,Y,NX1,NX2,DA1,XA2,ZA)
C
C***  INTERPOLATES BETWEEN TABLES FOR FG6115
C
      DIMENSION ROUTID(2),Q46115(2)
      DIMENSION X1(1),X2(1),Y(NX2,NX1)
      DATA ROUTID/4HTLIN,4HVS  /,Q46115/4H4.6.,4H1-30/
C
C     ----TEST FOR ZA OUTSIDE RANGE OF TABLE
C     ----TEST FOR XA2.LE.X2(1)
C
      IF(XA2.GT.X2(1))GO TO 1010
      IF(ZA.LT.Y(1,1))GO TO 1000
      GO TO 1060
 1000 IF(ZA.GT.Y(1,NX1))GO TO 1010
      GO TO 1080
C
C     ----TEST XA2.GE.X2(NX2)
C
 1010 IF(XA2.LT.X2(NX2))GO TO 1030
      IF(ZA.LT.Y(NX2,1))GO TO 1020
      GO TO 1060
 1020 IF(ZA.GT.Y(NX2,NX1))GO TO 1030
      GO TO 1080
C
C     ----XA2 WITHIN TABLE.TEST FOR ZA OUTSIDE
C
 1030 DO 1040 I=2,NX2
         IF(X2(I)-XA2)1040,1050,1090
 1040 CONTINUE
 1050 IF(ZA.LT.Y(I,1))GO TO 1070
 1060 DA1=X1(1)
      RETURN
 1070 IF(ZA.GT.Y(I,NX1))GO TO 1100
 1080 DA1=X1(NX1)
      RETURN
 1090 RAT=(XA2-X2(I-1))/(X2(I)-X2(I-1))
      ZTP=Y(I-1,1)+(Y(I,1)-Y(I-1,1))*RAT
      IF(ZA.GE.ZTP)GO TO 1060
      ZTP=Y(I-1,NX1)+(Y(I,NX1)-Y(I-1,NX1))*RAT
      IF(ZA.LE.ZTP)GO TO 1080
 1100 CONTINUE
      NX1O2=NX1/2
      DGSS=X1(NX1O2)
      KOUNT=0
 1110 CALL TLINEX(X1,X2,Y,NX1,NX2,DGSS,XA2,ZGSS,0,0,0,0,Q46115,2,ROUTID)
      KOUNT=KOUNT+1
      IF(ABS(ZGSS-ZA).LT.1.E-3)GO TO 1140
C
C     ----CUTOFF IF T00 MANY PASSES
C
      IF(KOUNT.GT.20)GO TO 1130
      DIN=DGSS*ABS(ZGSS-ZA)/ZGSS
      IF(ZGSS.GT.ZA)GO TO 1120
C
C     ----DECREASE DGSS TO INCREASE ZGSS WHICH WAS TOO SMALL.
C
      DGSS=DGSS-DIN
      IF(DGSS.LT.X1(1))DGSS=X1(1)
      GO TO 1110
C
C     ----INCREASE DGSS TO REDUCE ZGSS WHICH WAS TOO LARGE.
C
 1120 DGSS=DGSS+DIN
      IF(DGSS.GT.X1(NX1))DGSS=X1(NX1)
      GO TO 1110
 1130 CONTINUE
 1140 DA1=DGSS
      RETURN
      END
C ===== tlip1x.f =====
      SUBROUTINE TLIP1X(X1,Y,NP1,XA1,YA,LX1L,LX1U,MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION FOR A PACKED TABLE Y=F(X)
C
      DIMENSION Y(2),X1(2),DA(3),MESS(20),ROUT(2),NP1(7)
      DIMENSION MSSCL(9),RMSCL(9)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN1,NAS1,X1A,X1B,MSSG1,EX1,LG(7)
      EQUIVALENCE (NOIN1,LG(1)),(X1A,LG(2)),(X1B,LG(3)),(MSSG1,LG(4)),
     1      (EX1,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS1,LG(6))
      DATA TLIN /4H1TIN/, HOL1 /4H1EXP/
      DATA MSSCL /4HTLIP,4H1X  ,2*0,1,4*0/
C
      NX1=IABS(NP1(1))
      CALL SWITCH(LG,LX1L,LX1U,XA1,X1,NX1)
      IF(LG(7))GO TO 1030
      CALL GLOOK(NX1,XA1,X1,NAS1,NOIN1,I1,T1)
      YI1=YUP(I1,NP1,Y)
      D2=YI1
      IF(NOIN1)GO TO 1000
      YI1M1=YUP(I1-1,NP1,Y)
      D2=YI1M1+T1*(D2-YI1M1)
 1000 YA=D2
      IF(MSSG1)GO TO 1010
      RETURN
 1010 IF(ROUT(1).NE.TLIN)GO TO 1020
      ROUT(1)=HOL1
      RETURN
C
C     ----PRINT EXTRAPOLATION MESSAGE
C
 1020 MSSCL(3)=NMSS
      RMSCL(4)=YA
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
      CALL MESSGE(ROUT,MESS,X1,LG,LG,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAPOLATION
C
 1030 IF(X1B)GO TO 1060
C
C     ----HERE FOR XA1 ABOVE
C
      YNX1=YUP(NX1,NP1,Y)
      YNX1M1=YUP(NX1-1,NP1,Y)
      IF(LX1U.GT.1.AND.NX1.GT.2)GO TO 1040
C
C     ----LINEAR EXTRAPOLATION
C
      T1=(XA1-X1(NX1))/(X1(NX1)-X1(NX1-1))
      YA=YNX1+T1*(YNX1-YNX1M1)
      GO TO 1010
C
C     ----QUADRATIC EXTRAPOLATION
C
 1040 D2=YNX1
      D1=YNX1M1
      IX=NX1-2
      D0=YUP(IX,NP1,Y)
 1050 CALL QUAD(X1(IX),DA,XA1,YA)
      GO TO 1010
C
C     ----HERE FOR XA1 BELOW
C
 1060 Y1=YUP(1,NP1,Y)
      Y2=YUP(2,NP1,Y)
      IF(LX1L.GT.1.AND.NX1.GT.2)GO TO 1070
C
C     ----LINEAR EXTRAPOLATION
C
      T1=(XA1-X1(1))/(X1(2)-X1(1))
      YA=Y1+T1*(Y2-Y1)
      GO TO 1010
 1070 D0=Y1
      D1=Y2
      D2=YUP(3,NP1,Y)
      IX=1
      GO TO 1050
      END
C ===== tlip2x.f =====
      SUBROUTINE TLIP2X(X1,X2,Y,NXX,NX2,XA1,XA2,YA,LX1L,LX2L,LX1U,LX2U,
     1 MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION FOR A PACKED TABLE Y=F(X1,X2)
C
      DIMENSION X1(2),X2(2),Y(2),ROUT(2),MESS(2),NP1(7),NXX(7),DA(3)
      DIMENSION MSSCL(13),RMSCL(13)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN1,NAS1,X1A,X1B,MSSG1,EX1,LG(7)
      EQUIVALENCE (NOIN1,LG(1)),(X1A,LG(2)),(X1B,LG(3)),(MSSG1,LG(4)),
     1      (EX1,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS1,LG(6))
      DATA TLIN /4H1TIN/, HOL1 /4H1EXP/
      DATA MSSCL /4HTLIP,4H2X  ,2*0,2,8*0/
C
      IF(NXX(1).GE.0)GO TO 1010
      NX1=NXX(2)
      DO 1000 J=1,7
         NP1(J)=NXX(J)
 1000 CONTINUE
      GO TO 1020
 1010 NP1(1)=-NX2
      NX1=NXX(1)
      NP1(2)=NX1
      NP1(3)=0
      NP1(4)=0
      NP1(6)=0
      NP1(7)=0
 1020 CALL SWITCH(LG,LX1L,LX1U,XA1,X1,NX1)
      IF(LG(7))GO TO 1130
      CALL GLOOK(NX1,XA1,X1,NAS1,NOIN1,I1,T1)
 1030 ID=I1
      DO 1050 I=1,2
         IX=4-I
         GO TO 1160
 1040    IF(NOIN1)GO TO 1090
 1050 ID=ID-1
      IF(.NOT.EX1)GO TO 1070
      IF(NX1.LT.3)GO TO 1060
      IF(X1A.AND.LX1U.GT.1)GO TO 1140
      IF(X1B.AND.LX1L.GT.1)GO TO 1200
 1060 IF(X1A)GO TO 1210
 1070 D0=D1
 1080 D2=D0+T1*(D2-D1)
 1090 YA=D2
 1100 IF(MSSG1.OR.RO.EQ.HOL1)GO TO 1110
      RETURN
 1110 IF(ROUT(1).NE.TLIN)GO TO 1120
      ROUT(1)=HOL1
      RETURN
 1120 CONTINUE
C
C     ----PRINT EXTRAPOLATION MESSAGE.
C
      MSSCL(3)=NMSS
      RMSCL(4)=YA
C
C     ----1ST VARIABLE.
C
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
C
C     ----2ND VARIABLE.
C
      RMSCL(10)=XA2
      MSSCL(11)=NX2
      MSSCL(12)=LX2L
      MSSCL(13)=LX2U
      CALL MESSGE(ROUT,MESS,X1,X2,LG,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAP.
C
 1130 IF(X1B)GO TO 1180
C
C     ----HERE FOR XA1 ABOVE
C
      T1=XA1-X1(NX1)
      I1=NX1
      GO TO 1190
 1140 I1=I1-2
      ID=I1
      IX=1
 1150 I=0
 1160 RO=TLIN
      NP1(5)=ID
      CALL TLIP1X(X2,Y,NP1,XA2,DA(IX),LX2L,LX2U,MESS,NMSS,RO)
      IF(I.NE.0)GO TO 1040
 1170 CALL QUAD(X1(I1),DA,XA1,YA)
      GO TO 1100
C
C     ----HERE FOR XA1 BELOW
C
 1180 T1=XA1-X1(1)
      I1=2
 1190 T1=T1/(X1(I1)-X1(I1-1))
      GO TO 1030
 1200 D0=D1
      D1=D2
      ID=3
      IX=3
      I1=1
      GO TO 1150
 1210 D0=D2
      GO TO 1080
      END
C ===== tlip3x.f =====
      SUBROUTINE TLIP3X(X1,X2,X3,Y,NX1,NX2,NX3,XA1,XA2,XA3,YA,LX1L,LX2L,
     1LX3L,LX1U,LX2U,LX3U,MESS,NMSS,ROUT)
C
C***  LINEAR INTERPOLATION OF PACKED TABLE Y=F(X1,X2,X3)
C
      DIMENSION Y(2),X1(2),X2(2),X3(2),NP1(7),DA(3),MESS(20),ROUT(2)
      DIMENSION MSSCL(17),RMSCL(17)
      EQUIVALENCE (RMSCL(1),MSSCL(1))
      LOGICAL NOIN3,NAS3,X3A,X3B,MSSG3,EX3,LG(7)
      EQUIVALENCE (NOIN3,LG(1)),(X3A,LG(2)),(X3B,LG(3)),(MSSG3,LG(4)),
     1      (EX3,LG(5)),(DA(1),D0),(DA(2),D1),(DA(3),D2),(NAS3,LG(6))
      DATA TLIN /4H1TIN/, HOL1 /4H1EXP/
      DATA MSSCL /4HTLIP,4H3X  ,2*0,3,12*0/
C
C     ----INITIALIZE SWITCHES.
C
      CALL SWITCH(LG,LX3L,LX3U,XA3,X3,NX3)
      IF(LG(7))GO TO 1110
 1000 CALL GLOOK(NX3,XA3,X3,NAS3,NOIN3,I3,T3)
 1010 ID=I3
      DO 1030 I=1,2
         IX=4-I
         GO TO 1140
 1020    IF(NOIN3)GO TO 1070
 1030 ID=ID-1
      IF(.NOT.EX3)GO TO 1050
      IF(NX3.LT.3)GO TO 1040
      IF(X3A.AND.LX3U.GT.1)GO TO 1120
      IF(X3B.AND.LX3L.GT.1)GO TO 1180
 1040 IF(X3A)GO TO 1190
 1050 D0=D1
 1060 D2=D0+T3*(D2-D1)
 1070 YA=D2
 1080 IF(MSSG3.OR.RO.EQ.HOL1)GO TO 1090
      RETURN
 1090 IF(ROUT(1).NE.TLIN)GO TO 1100
      ROUT(1)=HOL1
      RETURN
 1100 CONTINUE
C
C     ----PRINT EXTRAPOLATION MESSAGE.
C
      MSSCL(3)=NMSS
      RMSCL(4)=YA
C
C     ----1ST VARIABLE.
C
      RMSCL(6)=XA1
      MSSCL(7)=NX1
      MSSCL(8)=LX1L
      MSSCL(9)=LX1U
C
C     ----2ND VARIABLE.
C
      RMSCL(10)=XA2
      MSSCL(11)=NX2
      MSSCL(12)=LX2L
      MSSCL(13)=LX2U
C
C     ----3RD VARIABLE.
C
      RMSCL(14)=XA3
      MSSCL(15)=NX3
      MSSCL(16)=LX3L
      MSSCL(17)=LX3U
      CALL MESSGE(ROUT,MESS,X1,X2,X3,LG,MSSCL)
      RETURN
C
C     ----HERE FOR EXTRAP.
C
 1110 IF(X3B)GO TO 1160
C
C     ----HERE FOR XA3 ABOVE
C
      T3=XA3-X3(NX3)
      I3=NX3
      GO TO 1170
 1120 I3=I3-2
      ID=I3
      IX=1
 1130 I=0
 1140 RO=TLIN
      NP1(1)=-NX2
      NP1(2)=NX1
      NP1(3)=NX3
      NP1(4)=0
      NP1(5)=0
      NP1(6)=ID
      NP1(7)=0
      CALL TLIP2X(X1,X2,Y,NP1,NX2,XA1,XA2,DA(IX),LX1L,LX2L,LX1U,
     1            LX2U,MESS,NMSS,RO)
      IF(I.NE.0)GO TO 1020
 1150 CALL QUAD(X3(I3),DA,XA3,YA)
      GO TO 1080
C
C     ----HERE FOR XA3 BELOW
C
 1160 T3=XA3-X3(1)
      I3=2
 1170 T3=T3/(X3(I3)-X3(I3-1))
      GO TO 1010
 1180 D0=D1
      D1=D2
      ID=3
      IX=3
      I3=1
      GO TO 1130
 1190 D0=D2
      GO TO 1060
      END
C ===== todec.f =====
      SUBROUTINE TODEC(ALPHA, ANS, IERR)
C
C***  CONVERT AN ALPHANUMERIC STRING INTO A FLOATING POINT CONSTANT
C
C***  INPUTS
C
C  ALPHA - ALPHANUMERIC STRING (MUST BE INTEGER)
C
C***  OUTPUTS
C
C    ANS - FLOATING POINT RESULT
C   IERR - ERROR CODE, 0=NO ERROR OR 1=CONSTANT NOT CORRECT TYPE
C
C**********************************************************************
C***  NOTE - INTEGER ARITHMETIC USED TO INCREASE NUMERICAL ACCURACY ***
C**********************************************************************
C
      INTEGER ALPHA,PLUS,PERIOD,EE,BLANK,POWER,SIGNP,PTEN,RVALUE
C
      DIMENSION ALPHA(80),NUM(10)
C
      LOGICAL FRAC
C
      DATA NUM / 4H0   ,4H1   ,4H2   ,4H3   ,4H4   ,4H5   ,4H6   ,
     1           4H7   ,4H8   ,4H9   /
      DATA PLUS, MINUS, PERIOD, EE, BLANK
     1  / 4H+   ,4H-   ,4H.   ,4HE   ,4H    /
C
C*****************************************
C***  INITIALIZE (DEFAULT ANSWER = 0.) ***
C*****************************************
C
      IERR=0
      FRAC=.FALSE.
      LVALUE=0
      RVALUE=0
      POWER=0
      SIGNV=0.
      SIGNP=0
      PTEN=0
C
C*********************
C***  GET MANTISSA ***
C*********************
C
      DO 1070 I=1,80
C
         ICOL=I
C
C ...    SKIP BLANKS
C
         IF(ALPHA(I) .EQ. BLANK)GO TO 1070
C
C ...    IF E IS DETECTED, START EXPONENT
C
         IF(ALPHA(I) .EQ. EE)GO TO 1080
C
C ...    CHECK FOR + SIGN ON NUMBER
C
         IF(ALPHA(I) .NE. PLUS)GO TO 1000
C
C ...    IF ALREADY DEFINED, EXIT
C
         IF(SIGNV .NE. 0.)GO TO 1130
C
C ...    SET PLUS SIGN
C
         SIGNV=1.
         GO TO 1070
C
C ...    CHECK FOR MINUS SIGN ON NUMBER
C
 1000    IF(ALPHA(I) .NE. MINUS)GO TO 1010
C
C ...    IF ALREADY DEFINED, EXIT
C
         IF(SIGNV .NE. 0.)GO TO 1130
C
C ...    SET MINUS SIGN
C
         SIGNV=-1.
         GO TO 1070
C
C ...    IF PERIOD, MUST DO FRACTIONAL PART OF NUMBER
C
 1010    IF(ALPHA(I) .NE. PERIOD)GO TO 1020
C
         FRAC=.TRUE.
         GO TO 1070
C
 1020    IF(FRAC)GO TO 1040
C
C ...    DECODE NUMBERS TO LEFT OF DECIMAL POINT
C
         DO 1030 J=1,10
            IF(ALPHA(I) .EQ. NUM(J))LVALUE=10*LVALUE+J-1
            IF(ALPHA(I) .EQ. NUM(J))GO TO 1070
 1030    CONTINUE
C
C ...    ERROR, CONSTANT NOT REAL OR INTEGER
C
         IERR=1
C
         GO TO 1130
C
C ...    DECODE NUMBERS TO RIGHT OF DECIMAL POINT
C
 1040    DO 1050 J=1,10
            IF(ALPHA(I) .EQ. NUM(J))RVALUE=10*RVALUE+J-1
            IF(ALPHA(I) .EQ. NUM(J))GO TO 1060
 1050    CONTINUE
C
C ...    ERROR, CONSTANT NOT REAL OR INTEGER
C
         IERR=1
C
         GO TO 1130
C
C ...    COUNT NUMBER OF DIGITS RIGHT OF DECIMAL POINT
C
 1060    PTEN=PTEN+1
C
 1070 CONTINUE
C
      GO TO 1130
C
C*********************
C***  GET EXPONENT ***
C*********************
C
 1080 ICOL=ICOL+1
      IF(ICOL .GT. 80)GO TO 1130
C
      DO 1120 I=ICOL,80
C
C ...    CHECK FOR PLUS SIGN ON EXPONENT
C
         IF(ALPHA(I) .NE. PLUS)GO TO 1090
C
C ...    IF ALREADY DEFINED, EXIT
C
         IF(SIGNP .NE. 0)GO TO 1130
C
C ...    SET POSITIVE EXPONENT
C
         SIGNP=1
         GO TO 1120
C
C ...    CHECK FOR NEGATIVE SIGN ON EXPONENT
C
 1090    IF(ALPHA(I) .NE. MINUS)GO TO 1100
C
C ...    IF ALREADY DEFINED, EXIT
C
         IF(SIGNP .NE. 0)GO TO 1130
C
C ...    SET NEGATIVE EXPONENT
C
         SIGNP=-1
         GO TO 1120
C
C ...    DECODE EXPONENT
C
 1100    DO 1110 J=1,10
            IF(ALPHA(I) .EQ. NUM(J))POWER=10*POWER+J-1
            IF(ALPHA(I) .EQ. NUM(J))GO TO 1120
 1110    CONTINUE
C
         GO TO 1130
C
 1120 CONTINUE
C
C***********************
C***  CONVERT NUMBER ***
C***********************
C
C ... VERIFY SIGN FOR MANTISSA AND EXPONENT DEFINED
C
 1130 IF(SIGNV .EQ. 0.)SIGNV=1.
      IF(SIGNP .EQ. 0 )SIGNP=1
C
      ANS=SIGNV*(FLOAT(LVALUE)+FLOAT(RVALUE)*10.**(-PTEN))
     1    *10.**(SIGNP*POWER)
C
      RETURN
      END
C ===== toint.f =====
      SUBROUTINE TOINT(ALPHA, IANS, IERR)
C
C***  CONVERT AN ALPHANUMERIC STRING INTO AN INTEGER CONSTANT
C
C***  INPUTS
C
C  ALPHA - ALPHANUMERIC STRING (MUST BE INTEGER)
C
C***  OUTPUTS
C
C   IANS - INTEGER RESULT
C   IERR - ERROR CODE, 0=NO ERROR OR 1=CONSTANT NOT CORRECT TYPE
C
      INTEGER ALPHA,PERIOD
C
      DIMENSION ALPHA(80)
C
      DATA PERIOD / 4H.    /
C
      IERR=0
      IER1=0
      IER2=0
C
      LCOL=1
C
      CALL FINDCH(ALPHA, PERIOD, LCOL)
C
      IF(LCOL .LT. 81)IER1=1
C
      CALL TODEC(ALPHA, ANS, IER2)
C
      IF(IER1 .GT. 0)IERR=1
      IF(IER2 .GT. 0)IERR=2
C
      SIGN=1
      IF(ANS .LT. 0.)SIGN=-1
      IANS=SIGN*(ABS(ANS)+0.5)
C
      RETURN
      END
C ===== tolog.f =====
      SUBROUTINE TOLOG(ALPHA, LANS, IERR)
C
C***  CONVERT AN ALPHANUMERIC STRING INTO A LOGICAL CONSTANT
C
C***  INPUTS
C
C  ALPHA - ALPHANUMERIC STRING (MUST BE INTEGER)
C
C***  OUTPUTS
C
C   LANS - LOGICAL RESULT
C   IERR - ERROR CODE, 0=NO ERROR OR 1=CONSTANT NOT CORRECT TYPE
C
      INTEGER ALPHA,POINT,BLANK
C
      DIMENSION ALPHA(80),LTRUE(4),LFALSE(5)
C
      LOGICAL LANS
C
      DATA LTRUE  / 4HT   ,4HR   ,4HU   ,4HE   /
      DATA LFALSE / 4HF   ,4HA   ,4HL   ,4HS   ,4HE   /
      DATA POINT  / 4H.    /
      DATA BLANK  / 4H     /
C
      IERR=1
      LANS=.FALSE.
C
C***  SKIP LEADING BLANKS
C
      ICOL=1
      CALL SKIPBL(ALPHA, ICOL)
C
      IF(ICOL .LT. 81)GO TO 1000
C
      GO TO 1060
C
C***  FIRST CHARACTER MUST BE POINT
C
 1000 IF(ALPHA(ICOL) .NE. POINT)GO TO 1060
C
C***  LOOK FOR TRUE
C
C ... TEST FOR .T.
C
      IF(ALPHA(ICOL) .EQ. POINT .AND. ALPHA(ICOL+1) .EQ. LTRUE(1)
     1   .AND. ALPHA(ICOL+2) .EQ. POINT)GO TO 1020
C
C ... TEST FOR .TRUE.
C
      IFIR=ICOL+1
      IMAX=IFIR+3
C
      DO 1010 I=IFIR,IMAX
         II=I
         IF(ALPHA(I) .NE. LTRUE(I-IFIR+1))GO TO 1030
 1010 CONTINUE
C
      II=II+1
      IF(ALPHA(II) .NE. POINT)GO TO 1060
C
 1020 LANS=.TRUE.
      IERR=0
C
      GO TO 1060
C
C***  LOOK FOR FALSE
C
C ... TEST FOR .F.
C
 1030 IF(ALPHA(ICOL) .EQ. POINT .AND. ALPHA(ICOL+1) .EQ. LFALSE(1)
     1   .AND. ALPHA(ICOL+2) .EQ. POINT)GO TO 1050
C
C ... TEST FOR .FALSE.
C
      IFIR=ICOL+1
      IMAX=IFIR+4
C
      DO 1040 I=IFIR,IMAX
         II=I
         IF(ALPHA(I) .NE. LFALSE(I-IFIR+1))GO TO 1060
 1040 CONTINUE
C
      II=II+1
      IF(ALPHA(II) .NE. POINT)GO TO 1060
C
 1050 LANS=.FALSE.
      IERR=0
C
 1060 CONTINUE
C
      RETURN
      END
C ===== tracm0.f =====
      SUBROUTINE TRACM0
C
C***  EXECUTIVE TRANSONIC B-W OR B-H CM0
C
      COMMON /IBW/     PBW,    BW(380)
      COMMON /IBH/     PBH,    BH(380)
      COMMON /FLGTCD/ FLC(160)
      COMMON /SUPBOD/ SBD(229)
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /WINGI/  WGIN(101)
      COMMON /HTI/    HTIN(154)
      COMMON /BDATA/  BD(762)
      COMMON /WINGD/  A(195), B(49)
      COMMON /SBETA/  STB(135), TRA(108), TRAH(108), STBH(135)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF,LF,K
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
C
      EQUIVALENCE (BW(41),CMOWB), (BH(41),CMOHB)
C
C***  WING-BODY CMO
C
      IF(.NOT. WGPL) GO TO 1010
      DB  = 2.0*(WGIN(4)-WGIN(3))
      XLN = (XW+0.5*DB*A(38))/DB
      XLA = (XW+WGIN(6)+0.5*DB*A(80))/DB
      XLA = BD(1)/DB-XLA
      RN  = FLC(I+2)*A(122)
      DBM = SBD(120)
      WL  = 0.5*ZW/DBM
      VT  = 0.0
      HD  = 0.0
      DOB = 0.5*DBM/WGIN(4)
      CALL WBCM0(A(120), A(38), WGIN(16), XLN, XLA, A(118), WGIN(62),
     1      WGIN(11), WGIN(93), WGIN(94), RN, FLC(96), WL,
     2      VT, HD, DOB, FLC(I+2), CMOWB)
      TRA(74) = CMOWB
C
C***  HORIZONTAL-BODY CMO
C
 1010 CONTINUE
      IF(.NOT. HTPL) GO TO 1020
      DB  = 2.0*(HTIN(4)-HTIN(3))
      XLN = (XH+0.5*DB*AHT(38))/DB
      XLA = (XH+HTIN(6)+0.5*DB*AHT(80))/DB
      XLA = BD(1)/DB-XLA
      RN  = FLC(I+2)*AHT(122)
      DBM = SBD(120)
      WL  = 0.5*ZW/DBM
      VT  = 0.0
      HD  = 0.0
      DOB = 0.5*DBM/HTIN(4)
      CALL WBCM0(AHT(120), AHT(38), HTIN(16), XLN, XLA, AHT(118),
     1      HTIN(62),HTIN(11), HTIN(93), HTIN(94), RN, FLC(96), WL,
     2      VT, HD, DOB, FLC(I+2), CMOHB)
      TRAH(74) = CMOHB
 1020 CONTINUE
      RETURN
      END
C ===== tranac.f =====
      SUBROUTINE TRANAC (NPT,X,Y,DYL,DYR,DELY,XVAL,YVAL)
C
C***  COMPUTES TRANSONIC PLANFORM CL BY NON-LINEAR INTERPOLATION
C
      INTEGER RP
      DIMENSION X(NPT),Y(NPT),YP(2)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
C
C   METHOD - SLOPES ARE DEFINED AT EACH DATA POINT AS A VALUE HALF WAY
C            BETWEEN THE LINEAR SLOPES TO THE RIGHT AND LEFT OF THE
C            POINT. A THIRD ORDER POLYNOMIAL IS DETERMINED FOR EACH
C            INTERVAL BETWEEN DATA POINTS BY USING THE TWO END POINTS
C            AND TWO END POINT SLOPES. THE LEFT AND RIGHT END SLOPES
C            ARE INPUT. THE RESULTING CURVE AND ITS DERIVATIVES ARE
C            CONTINUOUS.
C
C   NPT      NUMBER OF POINTS IN X AND Y ARRAYS
C   X        ABSCISSAS OF INPUT DATA
C   Y        ORDINATES OF INPUT DATA
C   DYL      LEFT END SLOPE
C   DYR      RIGHT END SLOPE
C
C   XVAL     ABSCISSA VALUE AT WHICH INTERPOLATION TO BE PERFORMED
C   YVAL     INTERPOLATED ORDINATE VALUE
C
      NPT1 = NPT-1
      DO 1000 J = 2,NPT1
        IF(XVAL .LT. X(J)) GO TO 1010
 1000 CONTINUE
      J = NPT
 1010 CONTINUE
      J = J-1
      K = J+1
C
      DO 1040 N = 1,2
        MP = J+N-1
        LP = MP-1
        RP = MP+1
C
        IF(MP .NE. 1) GO TO 1020
          YP(N)     = DYL
 1020   IF(MP .EQ. 1 .OR. MP .EQ. NPT) GO TO 1030
          SL    = (Y(LP)-Y(MP))/(X(LP)-X(MP))
          SR    = (Y(MP)-Y(RP))/(X(MP)-X(RP))
          ANGL  = ATAN(SL)
          ANGR  = ATAN(SR)
          ANGAV = (ANGL+ANGR)/2.0
          YP(N) = SIN(ANGAV)/COS(ANGAV)
          IF((NPT .EQ. 8) .AND. (MP .EQ. 5) .AND. (DELY .LT. -UNUSED))
     1      YP(N) = 0.0
          IF(SR .EQ. 0.0) GO TO 1030
            IF((SL/SR) .LT. 0.0) YP(N) = 0.0
 1030   IF(MP .NE. NPT) GO TO 1040
          YP(N) = DYR
 1040 CONTINUE
C
      IF((NPT .EQ. 8) .AND. (J .EQ. 5)) Y(J) = Y(J)+DELY
      IF((NPT .EQ. 8) .AND. (K .EQ. 5)) Y(K) = Y(K)+DELY
      X1S  = X(J)*X(J)
      X2S  = X(K)*X(K)
      X12F = X(J)-X(K)
      Y12F = Y(J)-Y(K)
      X12S = X1S-X2S
      X12C = X1S*X(J)-X2S*X(K)
      Y12P = YP(1)-YP(2)
C
      RED = 2.0*X(K)*X12F - X12S
      GRN = 3.0*X2S*X12F - X12C
      YEL = YP(2)*X12F-Y12F
      E   = 3.0*X12S*RED - 2.0*X12F*GRN
      A   = Y12P*RED - 2.0*X12F*YEL
      A   = A/E
      B   = 3.0*X12S*YEL - Y12P*GRN
      B   = B/E
      C   = (Y12F-A*X12C-B*X12S)/X12F
      D   = Y(K)-A*X2S*X(K)-B*X2S-C*X(K)
      IF((NPT .EQ. 8) .AND. (J .EQ. 5)) Y(J) = Y(J)-DELY
      IF((NPT .EQ. 8) .AND. (K .EQ. 5)) Y(K) = Y(K)-DELY
C
      YVAL = (((A*XVAL +B)*XVAL)+C)*XVAL+D
C
      RETURN
      END
C ===== trancd.f =====
      SUBROUTINE TRANCD
C
C***  CALCULATES TRANSONIC WING AND WING-BODY CD
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG,NF
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /FLGTCD/ FLC(95), TR
      COMMON /BDATA/  BD(762)
      COMMON /WINGD/  A(195)
      COMMON /HTDATA/ AHT(195), BHT(49)
      COMMON /HTI/    HTIN(154)
      COMMON /IBH/    PBH, BH(380)
      COMMON /WINGI/  WINGIN(100)
      COMMON /SYNTSS/ XCG, XW, ZW, ALIW, ZCG, XH, ZH, ALIH, XV,
     1                VERTUP, HINAX, XVF, SCALE, ZV, ZVF, YV, YF,
     2                PHIV, PHIF
      COMMON /IBW/    PBW, BW(380)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST
      REAL LN, LA
      LOGICAL NA
      DIMENSION CDL(20)
      DATA STRA / 4HSTRA /
C
C***  WING-BODY DRAG
C
      IF(NF .LT. 0) GO TO 1040
      IF(WINGIN(15) .NE. STRA .OR. .NOT. (BO .AND. WGPL)) GO TO 1020
      CD0 = BW(1)
      RN = FLC(I+42)*A(122)
      DB = 2.0*(WINGIN(4)-WINGIN(3))
      LN = (XW + 0.5*DB*A(38))/DB
      LA = (XW + WINGIN(6) + 0.5*DB*A(56))/DB
      IF(BD(2) .LT. (LN*DB)) LN = LN*DB/BD(85)
      IF(BD(2) .GT. (LA*DB)) LA = LA*DB/BD(85)
      LA = BD(1)/DB-LA
      CALL WBCDL(A(120), A(38), WINGIN(16), LN, LA, A(118),
     1          WINGIN(62), WINGIN(11), WINGIN(93), WINGIN(94), RN,
     1          TR, FLC(I+2), FLC(23), CDL, NA)
      IF(NA) GO TO 1020
        DO 1010 J=1,NALPHA
           BW(J) = CD0 + CDL(J)
           IF(CDL(J) .NE. UNUSED) GO TO 1010
           BW(J) = -UNUSED
 1010 CONTINUE
 1020 CONTINUE
C
C***  H.T.-BODY DRAG
C
      IF(HTIN(15) .NE. STRA .OR. .NOT. HTPL) GO TO 1040
      CD0 = BH(1)
      RN = FLC(I+42)*AHT(122)
      DB = 2.0*(HTIN(4)-HTIN(3))
      LN = (XH + 0.5*DB*AHT(38))/DB
      LA = (XH + HTIN(6) + 0.5*DB*AHT(56))/DB
      IF(BD(2) .LT. (LN*DB)) LN = LN*DB/BD(85)
      IF(BD(2) .GT. (LA*DB)) LA = LA*DB/BD(85)
      LA = BD(1)/DB-LA
      CALL WBCDL(AHT(120), AHT(38), HTIN(16), LN, LA, AHT(118),
     1          HTIN(62), HTIN(11), HTIN(93), HTIN(94), RN,
     1          TR, FLC(I+2), FLC(23), CDL, NA)
      IF(NA) GO TO 1040
        DO 1030 J=1,NALPHA
           BH(J) = CD0 + CDL(J)
           IF(CDL(J) .NE. UNUSED) GO TO 1030
           BH(J) = -UNUSED
 1030 CONTINUE
 1040 CONTINUE
      RETURN
      END
C ===== trancm.f =====
      SUBROUTINE TRANCM
C
C*** COMPUTES TRANSONIC WING AND WING BODY PITCHING MOMENT SLOPES
C
      DIMENSION ROUTID(2)
      DIMENSION Q225AD(3),Q222AF(3),Q14228(3)
      REAL MACH,MFB
      DIMENSION T428(14),D428(28),XM(6)
      DIMENSION VAR(4),LGH(4),VBAR(4),XMV(6),XACV(6),ZMT(8),XACP(8)
