     1               0,2,0,0,0,2,0,0,Q3246A,3,ROUTID)
         IF(SUPLE)GO TO 1080
         CNTHRY=BCNA/TANLE
         GO TO 1090
 1060    CONTINUE
C
C                        RECTANGULAR WING ANALYSIS
C
         IF(AR *BETA.GT.1.0)GO TO 1070
C
C                        FIGURE 4.1.3.2-56G(CNA/A)
C
         VAB(1)=AR *BETA
         LGB(1)=9
         CALL INTERX(1,G13246,VAB,LGB,DG3246,CNAA,9,9,
     1               0,0,0,0,0,0,0,0,Q3246G,3,ROUTID)
         CNTHRY=CNAA*AR
         GO TO 1090
 1070    BCNA= 4.-2.*(1./(AR *BETA))
 1080    CNTHRY=BCNA/BETA
 1090    CNA=CNTHRY*CNCNT     *SRSTAR     /(SW*RAD)
         CN(I) = CNA
 1100 CONTINUE
      F1 = (CN(2)*BB(2)**2-CN(1)*BB(1)**2)/(BB(2)-BB(1))
      F2 = (CN(3)*BB(3)**2-CN(1)*BB(1)**2)/(BB(3)-BB(1))
      AA  = (F2-F1)/(BB(3)-BB(2))
      B  = F1-AA*(BB(2)+BB(1))
      C  = CN(2)*BB(2)**2 - AA*BB(2)**2 - B*BB(2)
      DCNA = -B*XM(2)/BB(2)**3 - 2.0*C*XM(2)/BB(2)**4
      CNA  = CN(2)
      RETURN
      END
C ===== trapz.f =====
      SUBROUTINE TRAPZ(F,N,Y,A,NTEST)
C
C***  TRAPEZOIDAL RULE INTEGRATION ROUTINE
C
C      F IS INTEGRAND - N IS NO. OF PTS. - Y IS INDEPENDENT VARIABLE
C      A IS ARRAY OF ANS AT EACH INTERVAL IF NTEST .NE. 1
C      A(1) IS INTEGRAL OVER ENTIRE INTERVAL IF NTEST = 1
C
      COMMON /CONSNT/ PI
      DIMENSION F(1),Y(1),A(1)
      A(1) = 0.
      DO 1020 I=2,N
         TEMP = .5 * (Y(I)-Y(I-1)) * (F(I) + F(I-1))
C
C   CALCULATE VOLUME IF .LT. 0
C
         IF(NTEST.LT.0)TEMP=PI/3.*(Y(I)-Y(I-1))*(F(I)**2+F(I-1)**2
     1                     +F(I)*F(I-1))
         IF(NTEST.LT.0)GO TO 1000
         IF(NTEST-1)1010,1000,1010
 1000    A(1) = A(1) + TEMP
         GO TO 1020
 1010    A(I) = A(I-1) + TEMP
 1020 CONTINUE
      RETURN
      END
