     8  2.910,  2.400,  2.400,  2.400,  2.400,  2.400,  2.400/
C
C           ****** FIGURE 4.1.4.2-33
C
      DATA T428/
     10.,6.6,10.,14.,3*0.,
     20.,1.7,2.0,2.5,3.0,4.0,6.0/
      DATA D428/
     1  0.,     0.,     0.,     0.,     0.,     0.,     0.,     0.,
     2  0.,   0.,   -.100,  -.220,   0.,   0.,  -.210,   -.450,
     3  0.,   0.,   -.305,  -.665,   0.,   0.,  -.475,   -1.040,
     4  0.,   0.,   -.650,  -1.410/
C
C  *** WING ALONE ***
C  *** TOVC .LE.0.07 ***
C              FIGURE 4.1.4.2-30A-D (XAC/CR)
C
      VAR(1)=ARSTAR*(TOVC)**0.3333
      VAR(2)=ARSTAR*TANLE
      VAR(4)=TAPR
      LGH(1)=7
      LGH(2)=9
      LGH(3)=4
      LGH(4)=3
      VBAR(1)=-2.
      VBAR(2)=-1.
      VBAR(3)=0.
      VBAR(4)=1.
      DO 1000 I=2,5
         XMV(I)=SQRT(1.+VBAR(I-1)*TOVC**.6666)
         VAR(3)=VBAR(I-1)
 1000 CALL TLIN4X(T425AD(10 ),T425AD(1  ),T425AD(19 ),T425AD(28 ),D425AD
     1,LGH(2),LGH(1),LGH(3),LGH(4),VAR(2),VAR(1),VAR(3),VAR(4),XACV(I),
     20,0,0,0,2,1,0,1,Q225AD,3,ROUTID)
      IF(WGPL.AND.(.NOT.BO))DXCG=XCG-XW
      XMV(1)=0.60
      XMV(6)=1.40
C
C              FIGURE 4.1.4.2-26A-F
C
      LGH(1)=6
      LGH(2)=6
      LGH(3)=6
      VAR(3)=TAPR
      DO 1030 I=1,3
         ARG1=TANLE/SQRT(1.0-XM(I)**2)
         IF(ARG1.GT.1.)GO TO 1010
         VAR(1)=ARG1
         CALL INTERX(3,T422AF,VAR,LGH,SUBAF1,XACV(1),6,216,
     1               0,2,0,0,0,2,0,0,Q222AF,3,ROUTID)
         GO TO 1020
 1010    VAR(1)=1./ARG1
         CALL INTERX(3,T422AF,VAR,LGH,SUBAF2,XACV(1),6,216,
     1               0,2,0,0,0,2,0,0,Q222AF,3,ROUTID)
 1020    CONTINUE
         IF(I.EQ.1)DXAC1=XACV(1)
         IF(I.EQ.2)DXAC1=(XACV(1)-DXAC1)/0.2
 1030 CONTINUE
C
      DO 1060 I=4,6
         ARG=SQRT(XM(I)**2-1.0)/TANLE
         IF(ARG.GT.1.)GO TO 1040
         VAR(1)=ARG
         CALL INTERX(3,T422AF,VAR,LGH,SUPAF1,XACV(6),6,216,
     1               0,2,0,0,0,2,0,0,Q222AF,3,ROUTID)
         GO TO 1050
 1040    VAR(1)=1./ARG
         CALL INTERX(3,T422AF,VAR,LGH,SUPAF2,XACV(6),6,216,
     1               0,2,0,0,0,2,0,0,Q222AF,3,ROUTID)
 1050    CONTINUE
         IF(I.EQ.4)DXAC2=XACV(6)
         IF(I.EQ.5)DXAC2=(XACV(6)-DXAC2)/0.2
 1060 CONTINUE
      CALL TRANAC(6,XMV,XACV,DXAC1,DXAC2,0.0,MACH,XAC)
      IF(TOVC.LE.0.07)GO TO 1080
C
C  *** TOVC .GT.0.07 ***
C              FIGURE 4.1.4.2-33  DELTA XAC
C
      VAR(1)=TOVC*100.
      VAR(2)=ARSTAR*COSC2**2
      LGH(1)=4
      LGH(2)=7
      CALL INTERX(2,T428,VAR,LGH,D428,DELXAC,7,28,
     1            0,-1,0,0,1,0,0,0,Q14228,3,ROUTID)
      ZMT(1)=0.60
      ZMT(2)=(MFB+.6)/2.
      ZMT(3)=MFB
      ZMT(4)=MFB+.03
      ZMT(5)=MFB+.07
      ZMT(6)=MFB+.14
      ZMT(7)=XMV(5)
      IF((ZMT(6)+0.01).GE.ZMT(7))ZMT(7)=(1.4+ZMT(6))/2.0
      ZMT(8)=1.4
      LGH(1) =6
      DO 1070 I=1,8
         CALL TRANAC(6,XMV,XACV,DXAC1,DXAC2,0.0,ZMT(I),XACP(I))
 1070 CONTINUE
      CALL TRANAC(8,ZMT,XACP,DXAC1,DXAC2,DELXAC,MACH,XAC)
 1080 XACW=XAC*CRSTAR/CBARR
      CMAW=(DXCG/CBARR-XACW)*CLAW
      IF(.NOT.BO)RETURN
C
C  *** WING-BODY ***
C
      CALL HBTRAN(NZ)
      CALL WBCM1(A,WINGIN,BD,WB)
      ARG1= ABS(XACBW4-XACBW6)/0.80
      XACBW= XACBW6+ARG1*(MACH-0.60)
      CNOB=(-CMAB/CLAB*CBARR+DXCG)*CLAB/CBARR
      DNUM = CNOB+XACW*CLAWB+XACBW*CLABW
      DNOM= CLAB+CLAWB+CLABW
      XACWB=DNUM/DNOM
      CMAWB=(DXCG/CBARR-XACWB)*CLAWBD
      RETURN
      END
C ===== trimr2.f =====
      SUBROUTINE TRIMR2
C
C***  SUBROUTINE TO TRIM THE VEHICLE WITH AN ALL MOVABLE TAIL
C
      REAL KBW,KWB,KKBW,KKWB,NTRIM
      COMMON /OPTION/ SREF,CBARR,RUFF,BLREF
      COMMON /OVERLY/ NLOG,NMACH,IZ,NALPHA
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /IHT/    PHT, HT(380)
      COMMON /IVT/    PVT, VT(380)
      COMMON /POWR/   PW(293),TRM2(22)
      COMMON /IDWASH/ PDWASH, DWASH(60)
      COMMON /IBW/    PBW, BW(380)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /FLGTCD/ FLC(93)
      COMMON /BDATA/  BD(762)
      COMMON /HTI/    HTIN(154)
      COMMON /HTDATA/ AHT(195),BHT(49)
      COMMON /WBHCAL/ WBT(155)
      COMMON /WHAERO/ XXX(157), DHT(55)
C
      DIMENSION ALPH(20),ALIHT(20),ALPH1(20),ALMEP(20)
      DIMENSION CLHTRM(20),CDHTRM(20),CMHTRM(20),HMTRM(20),HMUNT(20)
     1,CLWBT(20),CDWBT(20),CMWB(20),QOQI(20),ALPHA(20),EPSLON(20)
     2,CLH(20),CLBH(20),CDH(20),CC(6),ROUTID(2)
C
      EQUIVALENCE (ALIHT(1),HT(221)),(HINAX,SYNA(11)),(XCG,SYNA(1))
     1,(CMHTRM(1),HT(281)),(HMTRM(1),HT(301)),(HMUNT(1),HT(201))
     2,(CLWBT(1),VT(221)),(CDWBT(1),VT(201)),(CLHTRM(1),TRM2(1)),
     3 (NTRIM,TRM2(21)),(TSTOP,TRM2(22)),(CDHTRM(1),HT(241))
      EQUIVALENCE (KWB,WBT(1)),(KBW,WBT(2)),(KKWB,WBT(150))
     1,(CMWB(1),BW(41)),(QOQI(1),DWASH(1)),(CLBH(1),WBT(130))
     2,(ALPHA(1),FLC(23)),(XBA,BD(63)),(ZBA,BD(64)),(AR,AHT(7))
     3,(E,DHT(30)),(EPSLON(1),DWASH(21)),(ALIH,SYNA(8)),(CLH(1),HT(21))
     4,(KKBW,WBT(151)),(SSPN,HTIN(4)),(SSPNE,HTIN(3)),(ACLMAX,BHT(43)),
     5 (CDOH,BHT(46)),(CMOH,BHT(47)),(AOH,BHT(49)),(CDOV,WBT(66))
     6,(CLAH,HT(101)),(CDH(1),HT(1))
C
      DATA ROUTID / 4HTRIM, 4HR2   /
C
      TSTOP=1.
      SRATIO=SREF/AHT(3)
      DO 1000 J=1,NALPHA
         ALMEP(J)=ALPHA(J)-EPSLON(J)
         ALPH(J)=ALPHA(J)-EPSLON(J)
 1000 ALPH1(J)=ALMEP(J)+ALIH
      NTRIM=NALPHA
      XBAR=XBA/CBARR
      ZBAR=ZBA/CBARR
      DO 1030 J=1,NALPHA
         JJ=J
         IF(ALMEP(J).GT.ACLMAX)GO TO 1040
         ARGL=-COS(ALMEP(J)/RAD)*XBAR+SIN(ALMEP(J)/RAD)*ZBAR
         ARGD=SIN(ALMEP(J)/RAD)*XBAR+COS(ALMEP(J)/RAD)*ZBAR
         CMWB(J)=BW(J+40)
      IF(CMWB(J).EQ.2.*UNUSED) GO TO 1050
C
C     CHECK TO SEE IF ALPHA IS IN DOWNWASH RANGE OF VALUES
C
         IF(ALPH1(J).GE.(-ACLMAX).AND.ALPH1(J).LE.ACLMAX) GO TO 1020
         ALIHT(J)=-1000.
         CLHTRM(J)=-1000.
         GO TO 1030
C
C     CALCULATE HORIZONTAL TAIL TRIM LIFT, DATCOM EQN. 4.5.3.2-E
C     TRIM LIFT IS RELATIVE TO LOCAL FLOW AT TAIL
C
 1020    CLHNUM=2.*((CMWB(J)+QOQI(J)*CMOH)/(ARGL*QOQI(J))+CDOH*ARGD
     1          /ARGL)
         CLHDEN=1.+SQRT((1.-4.*(ARGD/(ARGL*PI*AR*E)*SRATIO)*
     1          (CLHNUM/2.)))
         CLHTRM(J)=CLHNUM/CLHDEN
         CDHTRM(J)=CDOH+CLHTRM(J)**2/(PI*AR*E)*SRATIO
C
C     CALCULATE STABILIZER INCIDENCE TO TRIM AT ALPHA
C
         BRACKT=WBT(J+67)*WBT(J+45)*(SSPN-SSPNE)/SSPN
         IN=0
         CALL TBFUNX(ALPH(J),CLHP,CLAHP,NALPHA,BHT(23),CLH,CC,IN,MI,
     1               NG,1,1,4HCLH ,1,ROUTID)
         ALIHT(J)=(CLHTRM(J)-(KWB+KBW)*(CLHP+CLAHP*BRACKT*ALPH(J)))/
     1            ((KKWB+KKBW)*(CLAHP+BRACKT*CLAH))
C
C     CALCULATE TRIM LIFT AND DRAG RELATIVE TO BODY FREE STREAM FLOW
C
         EPS=EPSLON(J)/RAD
         ALP=ALPHA(J)/RAD
         DCLTRM=(CLHTRM(J)*COS(EPS)-CDHTRM(J)*SIN(EPS))*QOQI(J)
         DCDTRM=(CDHTRM(J)*COS(EPS)+CLHTRM(J)*SIN(EPS))*QOQI(J)
         CLHTRM(J)=DCLTRM
         CDHTRM(J)=DCDTRM
C
C     CALCULATE OTHER TRIM OUTPUT
C
         HT(J+260)=DCLTRM
         ARGL=COS(ALMEP(J)/RAD)*XBAR+SIN(ALMEP(J)/RAD)*ZBAR
         ARGD=COS(ALMEP(J)/RAD)*ZBAR-SIN(ALMEP(J)/RAD)*XBAR
         CMHTRM(J)=DCLTRM*ARGL+CDHTRM(J)*ARGD
C
C     TRIMMED AND UNTRIMMED HINGE MOMENTS
C
         ARG=(HINAX+XBA-XCG)/CBARR
         HMTRM(J)=(DCLTRM*COS(ALP)+DCDTRM*SIN(ALP))*ARG
         HMUNT(J)=(CLH(J)*COS(ALP)+CDH(J)*SIN(ALP))*ARG
C
C     WING-BODY-TAIL CL AND CD AT TRIM CONDITION
C
         CLWBT(J)=CLHTRM(J)+CLBH(J)+BW(J+20)
         CDWBT(J)=BW(J)+DCDTRM+CDOV
 1030 CONTINUE
      RETURN
 1040 TSTOP=2.
      NTRIM=JJ-1
      RETURN
 1050 TSTOP=3.
      NTRIM=JJ-1
      RETURN
      END
C ===== trimrt.f =====
      SUBROUTINE TRIMRT
C
C***  CALCULATES SUBSONIC TRIM WITH WING OR HORIZONTAL TAIL CONTROL
C
      COMMON /OVERLY/ NLOG,NMACH,IZ,NALPHA
      COMMON /FLAPIN/ F(69)
      COMMON /IHT/    PHT, HT(380)
      COMMON /IVT/    PVT, VT(380)
      COMMON /IDWASH/ PDWASH, DWASH(60)
      COMMON /IWING/  PWING, WING(400)
      COMMON /IBODY/  PBODY, BODY(400)
      COMMON /WINGD/  A(195),B(49)
      COMMON /HTDATA/ AHT(195),BHT(49)
      COMMON /POWR/   PW(293),TRM(22)
      COMMON /IBW/    PBW, BW(380)
      COMMON /IBWH/   PBWH, BWH(380)
      COMMON /IBWHV/  PBWHV, BWHV(380)
      COMMON /FLGTCD/ FLC(93)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1                HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2                TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3                HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4                VFPL,VFSC,CTAB
C
      LOGICAL  FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC,
     1         HEAD,PRPOWR,JETPOW,LOASRT,TVTPAN,SUPERS,SUBSON,
     2         TRANSN,HYPERS,SYMFP,ASYFP,TRIMC,TRIM,DAMP,
     3         HYPEF,TRAJET,BUILD,FIRST,DRCONV,PART,
     4         VFPL,VFSC,CTAB
      REAL NTRIM
      DIMENSION UTCL(20),UTCM(20),UTCD(20),ALPHA(20),DCM(10),DCL(10),
     1          DCLMAX(10),DCDMIN(10),CHD(10),CDI(200)
      DIMENSION DELTA(10)
      DIMENSION DCM2(10),DELT(10),ROUTID(2)
      DIMENSION C1(6),C2(6),C3(6),C4(6),C5(6)
      DIMENSION DELTAT(20),DCLT(20),CLMAXT(20),CDMINT(20),CHDT(20),
     1          CDIT(20)
      EQUIVALENCE (UTCL(1),HT(201)),(UTCM(1),HT(241)),(UTCD(1),HT(221))
     1         ,(ALPHA(1),TRM(1)),(DELTAT(1),VT(201)),(DCLT(1),VT(221))
     2       ,(CLMAXT(1),VT(241)),(CDMINT(1),VT(281)),(CHDT(1),VT(321))
     3       ,(CDIT(1),VT(261)),(NTRIM,TRM(21))
      EQUIVALENCE (TSTOP,TRM(22))
      EQUIVALENCE (DELTA(1),F(1))
      EQUIVALENCE (DCM(1),WING(211)),(DCL(1),WING(201))
     1,(DCDMIN(1),WING(231)),(CHD(1),WING(261)),(CDI(1),BODY(201))
     2,(DCLMAX(1),WING(221))
      DATA ROUTID/4HTRIM,4HRT  /
C
      IN=0
      I1=0
      I2=0
      I3=0
      I4=0
C
C    -----TRIM HERE WITH CONTROL DEVICE ON WING OR TAIL
C
      NDELTA=F(16)+.5
      NDELTA = NDELTA - 1
      IF(WGPL.AND.HTPL)GO TO 1030
      IF(BO)GO TO 1010
C
C    -----HERE FOR WING ALONE TRIM
C
      DO 1000 J=1,NALPHA
         UTCL(J)=WING(J+20)
         UTCM(J)=WING(J+40)
 1000 UTCD(J)=WING(J)
      ACLMAX=B(43)
      GO TO 1050
C
C    -----HERE FOR WING-BODY TRIM
C
 1010 DO 1020 J=1,NALPHA
         UTCL(J)=BW(J+20)
         UTCM(J)=BW(J+40)
 1020 UTCD(J)=BW(J)
      ACLMAX=B(43)
      GO TO 1050
C
C    -----HERE FOR WING-BODY-TAIL TRIM
C
 1030 DO 1040 J=1,NALPHA
         UTCL(J)=BWH(J+20)
         UTCM(J)=BWH(J+40)
         UTCD(J)=BWH(J)
         IF(VTPL .OR. VFPL) UTCD(J)=BWHV(J)
 1040 CONTINUE
      ACLMAX=BHT(43)
 1050 CONTINUE
      NTRIM=NALPHA
      IF(DCM(1).GT.DCM(NDELTA))GO TO 1070
      DO 1060 J=1,NDELTA
         DELT(J)=DELTA(J)
 1060 DCM2(J)=DCM(J)
      GO TO 1090
 1070 DO 1080 J=1,NDELTA
         N=NDELTA-J+1
         DELT(N)=DELTA(J)
 1080 DCM2(N)=DCM(J)
 1090 DO 1100 J=1,NALPHA
         ALPHA(J)=FLC(J+22)-DWASH(J+20)
 1100 CONTINUE
      DO 1130 J=1,NALPHA
         IF(ALPHA(J).GT.ACLMAX)GO TO 1110
         ARG=-UTCM(J)
         IF(ARG.LT.DCM2(1).OR.ARG.GT.DCM2(NDELTA))GO TO 1120
         CALL TBFUNX(ARG,DELTAT(J),DYDX,NDELTA,DCM2,DELT,C1,IN,MI,NG
     1               ,0,0,4HDELT,1,ROUTID)
         CALL TBFUNX(DELTAT(J),DCLT(J),DYDX,NDELTA,DELTA,DCL,C2,I2,
     1               MI,NG,0,0,4HDCLT,1,ROUTID)
         IF(F(17).LE.5.)CALL TBFUNX(DELTAT(J),CLMAXT(J),DYDX,NDELTA,
     1                  DELTA,DCLMAX,C3,I3,MI,NG,0,0,4HCLMT,1,ROUTID)
         IF(F(17).LE.2.)CALL TBFUNX(DELTAT(J),CDMINT(J),DYDX,NDELTA,
     1                DELTA,DCDMIN,C4,I4,MI,NG,0,0,4HCDMT,1,ROUTID)
         IF(F(17).EQ.1.)CALL TBFUNX(DELTAT(J),CHDT(J),DYDX,NDELTA,DELTA,
     1                  CHD,C5,I5,MI,NG,0,0,4HCHDT,1,ROUTID)
         IF(F(17).LE.6.)CALL TLINEX(DELTA,ALPHA,CDI,NDELTA,NALPHA
     1              ,DELTAT(J),ALPHA(J),CDIT(J),0,0,0,0,4HCDIT,1,ROUTID)
         GO TO 1130
 1110    NTRIM=J-1
         TSTOP=2.
         GO TO 1140
 1120    NTRIM=J-1
         TSTOP=1.
         GO TO 1140
 1130 CONTINUE
 1140 CONTINUE
      RETURN
      END
