C
C  *** WING ALONE ***
C *** WING LIFT CURVE SLOPE ***
C
      MACH=FLC(NZ+2)
      IF(WINGIN(15).NE.WTYPE(1))GO TO 1100
      CALL TRNHT(CLA14, DCLA14)
      K=CLAMO*RAD/(2.0*PI)
      BETA6=0.80
C
C              FIGURE 4.1.3.2-53A FORCE BREAK MACH NUMBER=MFB ( 0 SWEEP)
C
      VAR(1)=TOC*100.
      VAR(2)=ARSTAR
      LGH(1)=8
      LGH(2)=7
      CALL INTERX(2,T43A,VAR,LGH,D43A,MFB0,8,56,
     1            2,2,0,0,2,-1,0,0,Q3243A,3,ROUTID)
C
C              FIGURE 4.1.3.2-53B MFB0 CORRECTED FOR SWEEP
C
      VAR(1)=SWEPE2
      VAR(2)=MFB0
      LGH(1)=8
      LGH(2)=5
      CALL INTERX(2,T43B,VAR,LGH,D43B,MFB,8,40,
     1            0,2,0,0,2,0,0,0,Q3243B,3,ROUTID)
      IF(NF .LT. 0) RETURN
C
C              FIGURE 4.1.3.2-54B (A/C)
C
      VAR(1)=TOC*100.
      VAR(2)=ARSTAR
      LGH(1)=7
      LGH(2)=6
      CALL INTERX(2,T44B,VAR,LGH,D44B,AOC,7,42,
     1            0,2,0,0,1,2,0,0,Q3244B,3,ROUTID)
C
C              FIGURE 4.1.3.2-54A CORRECTION TO LIFT CURVE SLOPE
C
      CALL INTERX(2,T44A,VAR,LGH,D44A,CFBCT,7,42,
     1            2,1,0,0,2,2,0,0,Q3244A,3,ROUTID)
C
C
C
      BETAFB = SQRT(1.0-MFB**2)
      IF(MFB .GT. 0.98) BETAFB = 0.0
      BB   = BETAFB
      ARG1 = 2.0*PI*ARSTAR/RAD
      ARG2=(ARSTAR/K)**2
      ARG3=BB**2+TANC2**2
      ARG4 = 2.0+SQRT(ARG2*ARG3+4.0)
      CLAFBT = ARG1/ARG4
C
      BB   = 0.8
      ARG2 = (BB*ARSTAR/K)**2
      ARG3 = 0.0
      IF(ARG2 .GT. 0.0) ARG3 = 1.0+(TANC2/BB)**2
      ARG4 = 2.0+SQRT(ARG2*ARG3+4.0)
      CLAW6 = ARG1*SRSTAR/(ARG4*SR)
C
      XM = 0.75
      IF(XM .GT. (MFB-0.1)) XM = MFB-0.1
      IF(XM .GT. MACH) XM=MACH
      BB   = SQRT(1.0-XM**2)
      ARG2=(ARSTAR/K)**2
      ARG3=BB**2+TANC2**2
      ARG4 = 2.0+SQRT(ARG2*ARG3+4.0)
      CLAW7 = ARG1*SRSTAR/(ARG4*SR)
      DCLA7 = XM*ARG1*ARG2*SRSTAR/SR
      DCLA7 = DCLA7/(ARG4**2*SQRT(ARG2*ARG3+4.0))
      CLAFB=CLAFBT*CFBCT *SRSTAR/SR
      CLAA=(1.-AOC)*CLAFB
C
C              FIGURE 4.1.3.2-54C (B/C)
C
      VAR(1)=TOC*100.
      LGH(1)=6
      CALL INTERX(1,T44C,VAR,LGH,D44C,BOC,6,6,
     1            2,0,0,0,1,0,0,0,Q3244C,3,ROUTID)
      CLAB=(1.-BOC)*CLAFB
      MT(1)=XM
      MT(2)=MFB
      MT(3)=MFB+.07
      MT(4)=MFB+.14
      MT(5)=1.40
      CLAMT(1)=CLAW7
      CLAMT(2)=CLAFB
      CLAMT(3)=CLAA
      CLAMT(4)=CLAB
      CLAMT(5)=CLA14
      CALL TRANF(5, MT, CLAMT, DCLA7, DCLA14, MACH, CLA)
C
C  *** CLASSIFICATION OF ASPECT RATIO ***
C
      CALL TBFUNX(A(27), C1   ,DYDX,NP,X,Y,C,IN,MI,NG,
     1            0,0,Q34171,4,ROUTID)
      ARG1=(C1+1.)*COSLE
      ARATIO=A(128)/ARG1
C
C              FIGURE 4.1.3.4-24B (C1) AND (C2)
C
      VAR(1)=TAPR
      LGH(1)=11
      CALL INTERX(1,TR,VAR,LGH,DR,C2,11,11,
     1           0,0,0,0,0,0,0,0,Q34172,4,ROUTID)
      LOWAR=.FALSE.
      IF(ARSTAR.LT.ARATIO)LOWAR=.TRUE.
C
C  *** IF LOW ASPECT RATIO CALCULATE CLMAX AND (ALPHA)CLMAX ***
C
      IF(.NOT.LOWAR)GO TO 1070
      BU4=(C1+1.)*ARSTAR*COSLE/BETA6
      ARG=(C2+1.)*ARSTAR*TANLE
      A(160)=ARG
      CALL CLMXB1(BU4,CLMAX6,A,WINGIN)
C
C  *** CALCULATE (ALPHA)CLMAX AT MACH=0.60 ***
C              FIGURE 4.1.3.4-25A
C
      CALL TBFUNX(BU4,ACLBAS,DYDX,10,T418A,D418A,C17,I17,MI,NG,
     1            0,0,Q3418A,3,ROUTID)
      IF(ARG.LE.4.5)GO TO 1050
C
C              FIGURE 4.1.3.4-25B
C
      CALL TLINEX(T18B1,D18B1,C18B1,3,20,MT(1),ARG,DACMA6,
     1            0,0,2,1,Q34181,3,ROUTID)
      GO TO 1060
 1050 ARG1=ARSTAR*COSLE*(1.+4.*TAPR**2)
      CALL TLINEX(T18B2,D18B2,C18B2,10,10,ARG1,ARG,DACMA6,
     1            0,2,2,0,Q34182,3,ROUTID)
 1060 ALCLM6=ACLBAS+DACMA6
C
C  *** ADJUST PARAMETERS TO TRANSONIC MACH NUMBER ***
C              FIGURE 4.1.3.4-26B
C
      VAR(1)=ARG
      LGH(1)=13
      CALL INTERX(1,T419B,VAR,LGH,D419B,C3,13,13,
     1            0,0,0,0,0,0,0,0,Q3419B,3,ROUTID)
C
C              FIGURE 4.1.3.4-26C  DELTA (ALPHA)CLMAX
C
      VAR(1)=BU4*BETA6
      VAR(2)=MACH
      LGH(1)=10
      LGH(2)=13
      CALL INTERX(2,T419C,VAR,LGH,D419C,DALCM ,13,130,
     1            2,0,0,0,2,2,0,0,Q3419C,3,ROUTID)
C
C              FIGURE 4.1.3.4-26A DELTA CLMAX
C
      VAR(1)=C3*VAR(1)
      LGH(1)=7
      LGH(2)=11
      CALL INTERX(2,T419A,VAR,LGH,D419A,DCLMAX,11,77,
     1            2,0,0,0,2,2,0,0,Q3419A,3,ROUTID)
      ALCLMT=ALCLM6+DALCM
      CLMAXT=CLMAX6+DCLMAX*(SRSTAR/SR)
 1070 CONTINUE
C
C  *** ZERO ANGLE OF ATTACK DRAG,CD0 ***
C              FIGURE 4.1.5.1-27 (EQUATION FOR RLCOFF)
C
      ARG=12.*CBAR/RUFF
      CALL TBFUNX(0.6,CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,4,ROUTID)
      RLCOFF=ARG**1.0482*10.0**CEPT
      RNN=CBAR*RNFS
      IF(RLCOFF.LT.RNN)RNN=RLCOFF
      CALL FIG26(RNN,0.60,CF)
      RL=1.2
      IF(XOC.LT.0.30)RL=2.0
      CDF=CF*(1.+RL*TOC)*2.*SRSTAR/SR
      ARG=SQRT(COSC4)
      XMTD(1)=0.60/ARG
      XMTD(2)=0.65/ARG
      XMTD(3)=0.70/ARG
      XMTD(4)=0.75/ARG
      XMTD(5)=0.80/ARG
      XMTD(6)=0.85/ARG
      XMTD(7)=0.90/ARG
      XMTD(8)=0.925/ARG
      XMTD(9)=0.950/ARG
      XMTD(10)=0.975/ARG
      XMTD(11)=1.000/ARG
      XMTD(12)=1.050/ARG
      XMTD(13)=1.100/ARG
      XMTD(14)=1.200/ARG
      XMTD(15)=1.400/ARG
      ARG2=TOC**.3333
      VAR(2)=ARSTAR*ARG2
      ARG3=COSC4**2.5
      DO 1090 I=1,15
         ARG4=ABS((XMTD(I)*ARG)**2-1.)
         VAR(1)=SQRT(ARG4)/ARG2
C
C              FIGURE 4.1.5.1-29
C
         IF(XMTD(I)*ARG.LE.1.)GO TO 1080
         LGH(1)=5
         LGH(2)=7
         CALL INTERX(2,T429R,VAR,LGH,D429R,CDW1(I),7,35,
     1               0,0,0,0,0,2,0,0,Q5129R,3,ROUTID)
         GO TO 1090
 1080    LGH(1)=8
         LGH(2)=7
         CALL INTERX(2,T429L,VAR,LGH,D429L,CDW1(I),8,56,
     1               0,0,0,0,-1,2,0,0,Q5129L,3,ROUTID)
 1090 CDW2(I)=CDW1(I)*TOC**1.666*ARG3*SRSTAR/SR
      CALL TRANF(15, XMTD, CDW2, 0.0, 0.0, MACH, CDW)
      CD0W=CDW+CDF
C
C  *** BODY ALONE ***
C
 1100 IF(.NOT.BO)RETURN
C
C  ***BODY LIFT AND MOMENT SLOPES ***
C
      ARG1=(MACH-.60)/.80
      CLABD=CLABM6+(CLAB14-CLABM6)*ARG1
      CMAB=CMAB6+(CMAB14-CMAB6)*ARG1
C
C  *** BODY DRAG ***
C
      CDFB=CFB6*SS/SR
      CDPB=CD0B6-CDBB6-CDFB
      IF(MACH.GE.1.0.AND.MACH.LE.1.2)CDPB=CDPB*(1.-(MACH-1.0)/.2)
      IF(MACH.GT.1.2)CDPB=0.0
      IF(DB.LT.0.3*DMAX)DB=0.3*DMAX
      ARG=(DB/DMAX)**2
C
C              FIGURE 4.2.3.1-24 (CDBT)
C
      VAR(1)=MACH
      VAR(2)=CDBB6/ARG*4.0*SR/(PI*DMAX**2)
      LGH(1)=13
      LGH(2)=3
      CALL INTERX(2,T424,VAR,LGH,D424,CDBFIG,13,39,
     1            0,2,0,0,0,2,0,0,Q23124,3,ROUTID)
      CDBB=CDBFIG*ARG*PI*DMAX**2/(4.0*SR)
      IF(MACH.LT.1.0)GO TO 1110
      VAR(1)=XLB/DMAX
      VAR(2)=MACH
      LGH(1)= 11
      LGH(2)=5
      CALL INTERX(2,T426,VAR,LGH,D426,CDWB,11,55,
     1            0,0,0,0,2,2,0,0,Q23126,3,ROUTID)
      CDWB=CDWB*PI*DMAX**2/(4.*SR)
      GO TO 1120
 1110 CDWB=0.0
 1120 CD0B=CDFB+CDPB+CDBB+CDWB
      IF(MACH.GT.1.2)GO TO 1130
      GO TO 1140
 1130 CD0B=CD0B+(CD014-CD0B)*(MACH-1.2)/0.2
C
C  *** BODY DRAG AT ANGLE OF ATTACK ***
C
 1140 DO 1150 J=1,NALPHA
 1150 CDJB(J)=CD0B+(FLC(J+22)/RAD)**2*SB/SR
      CD0WB=CD0B+CD0W
      TRA(73)=CD0WB
      RETURN
      END
C ===== vfcdo.f =====
      SUBROUTINE VFCDO(I)
C
C***  CALCULATES VENTRAL FIN ZERO LIFT DRAG COEFFICIENT
C
      REAL MACH,LERBW,LERO,LERI,KSHARP
      DIMENSION ROUTID(2)
      DIMENSION Q15127(4)
      DIMENSION WTYPE(4),CN(20),CAV(20),CDJWB(20), CLJWB(20),CD(20)
      DIMENSION X27M(4),X27I(4),C27(6)
C
      COMMON /OVERLY/ NLOG,NMACH,M,NALPHA
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /OPTION/ SR,CBARR,RUFF,BLREF
      COMMON /VTI/    VTIN(162),CT,SPANO,SPANS,SSPN,CB,CR,SAVSI,SAVSO,
     1                CHSTAT,SWAFP,TWISTA,SSPNDD,DHDADI,DHDADO,
     2                TYPE,
     3                TOVC,DELTAY,XOVC,CLI,ALPHAI,CLALPA(20),
     4                CLMAX(20),CMO,LERI,LERO,CAMBER,TOVCO,XOVCO,CMOT,
     5               CLMAXL,CLAMO,TCEFF,KSHARP,SVWB(20),SVB(20),SVHB(20)
      COMMON /WINGD/  A(195)
      COMMON /VTDATA/ AAA(195),AVT(195)
      COMMON /WBHCAL/ STP(156)
      COMMON /IBW/    PBW, BW(380)
      COMMON /IBWV/   PBWV, BWV(380)
      COMMON /FLGTCD/ FLC(160)
C
      EQUIVALENCE (CDO,STP(156)),(CD(1),BWV(1)),(CN(1),BWV(61)),
     1            (CAV(1),BWV(81))
      EQUIVALENCE (CBARI,AVT(15)),(RNFS,A(129)),(SRSTAR,AVT(3)),
     1            (CBARO,AVT(17)),(SISTAR,AVT(1)),(SOSTAR,AVT(2)),
     2            (TANLEO,AVT(86)),(COSLEO,AVT(85)),(TANLEI,AVT(62)),
     3            (COSLE,AVT(61)),(TANTEO,AVT(104)),(CDJWB(1),BW(1)),
     4            (CLJWB(1),BW(21))
C
      DATA ROUTID /4HVFCD,4HO   /
      DATA Q15127 /4H4.1.,4H5.1-,4H27  ,4HCEPT/
      DATA WTYPE  /4HSTRA,4HDOUB,4HCRAN,4HCURV/
      DATA X27M   /0.0,1.0,2.0,3.0/
      DATA X27I   /1.57780,1.67221,1.98509,2.28874/
      DATA I27    /0/
C
      MACH=FLC(I+2 )
      BETA=SQRT(MACH**2-1.0)
C
C  ***WING SUPERSONIC ZERO-LIFT SKIN FRICTION DRAG,STRAIGHT TAPERED WING
C
      IF(TYPE.NE.WTYPE(1))GO TO 1020
      CBAR=CBARI
 1000 RNN=CBAR*RNFS
      IF(RUFF.EQ.0.0)GO TO 1010
      ARG=12.*CBAR/RUFF
C
C                   FIGURE 4.1.5.1-27 (EQUATION FOR RLCOFF)
C
      RACH = MACH
      IF(RACH.GT.3.0)RACH=3.0
      CALL TBFUNX(RACH,CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,4,ROUTID)
      RLCOFF=ARG**1.0482*10.0**CEPT
      IF(RLCOFF.LT.RNN)RNN=RLCOFF
 1010 CALL FIG26(RNN,RACH,CF)
      IF(TYPE.NE.WTYPE(1))GO TO 1030
      CDF=CF*SRSTAR/SR*2.
      GO TO 1050
C
C  ***WING SUPERSONIC ZERO-LIFT SKIN FRICTION DRAG,NON-STRAIGHT WING***
C
 1020 CONTINUE
      CBAR=CBARI
      GO TO 1000
 1030 CONTINUE
      IF(CBAR.EQ.CBARO)GO TO 1040
      RNI=RNN
      CFI=CF
      CBAR=CBARO
      GO TO 1000
 1040 RNO=RNN
      CFO=CF
      CDF=(CFI*SISTAR+CFO*SOSTAR)/SR*2.
 1050 CONTINUE
C
C   ***SUPERSONIC WING ZERO-LIFT WAVE DRAG,SHARP L.E.,ALL PLANFORMS***
C
      IF(TYPE.EQ.WTYPE(1))GO TO 1060
      TA=TANLEO
      SPANIN=SPANS-SPANO
      CRBW=CB+SPANIN*(TANLEO-TANTEO)
      SBW=(CRBW+CT)*SPANS*0.50
      S=SBW
      CA=COSLEO
      LERBW=LERO*((CR+CT+2.*CB)/4.)
      GO TO 1070
 1060 TA=TANLEI
      IF(ABS(TA) .LT. UNUSED) TA = UNUSED
      S=(CR+CT)/2.*SSPN
      CA =COSLE
      LERBW=LERI*((CR+CT)/2.)
 1070 CONTINUE
      BOVERT=BETA/TA
      IF(KSHARP.EQ.UNUSED)GO TO 1080
      ARG=KSHARP*TCEFF**2*S  /SR
      CDW=ARG/BETA
      IF(BOVERT.LT.1.)CDW=ARG/TA
      GO TO 1090
 1080 CONTINUE
C
C  ***SUPERSONIC WING ZERO-LIFT WAVE DRAG,ROUND L.E.,ALL PLANFORMS***
C
      ARG1=1.28*MACH**3*CA    **6/(1.+MACH**3*CA    **3)
      ARG2=2.* LERBW * SPANS /(SR*CA)
      CDLE=ARG1*ARG2
      ARG=     16.*TCEFF**2*S  /(3.*SR)
      IF(BOVERT.GE.1.)CDW=CDLE+ARG/BETA
      IF(BOVERT.LT.1.)CDW=CDLE+ARG/TA
 1090 CONTINUE
      CDO=CDF+CDW
      IF(TYPE.NE.WTYPE(1))RETURN
      DO 1100 J=1,NALPHA
         CD(J)=CD(J)+CDO
         COSA=COS(FLC(J+22)/RAD)
         SINA=SIN(FLC(J+22)/RAD)
         CN(J)=CLJWB(J)*COSA+CD(J)*SINA
 1100 CAV(J)=CD(J)*COSA-CLJWB(J)*SINA
      RETURN
      END
C ===== vfdrag.f =====
      SUBROUTINE VFDRAG(I)
C
C***  COMPUTES VENTRAL FIN DRAG COEFFICIENT
C
      DIMENSION ROUTID(2)
      DIMENSION Q15127(3),Q5128B(3),Q128BD(5)
      COMMON /OPTION/ SREF,CBARR,ROUGFC,BLREF
      COMMON /FLGTCD/ FLC(160)
      COMMON /WHAERO/ C2(51),D2(55),CHT2(51),DHT2(55),DVT2(55),DVT(55)
      COMMON /VTDATA/ AAA(195),AVT(195)
      COMMON /VTI/    VV(154),TVTIN(8),VT(154)
      DIMENSION D(55),A(195),B(93)
      EQUIVALENCE (A(1),AVT(1)),(D(1),DVT(1)),(B(1),FLC(1))
      DIMENSION WTYPE(4)
      DIMENSION X228BD(9),X128BD(4),Y28BD(36)
      DIMENSION X228B(11), X128B(4), Y28B(44)
      DIMENSION X27M(4),X27I(4),C27(6)
      DATA ROUTID/4HVTDR,4HAG  /
      DATA Q15127 /4H4.1.,4H5.1-,4H27  /,Q5128B/4H4.1.,4H5.1-,4H28-B/,
     1     Q128BD /4H4.1.,4H5.1-,4H28-B,4H(DAS,4HHED)/
      DATA X27M   /0.0,1.0,2.0,3.0/
      DATA X27I   /1.57780,1.67221,1.98509,2.28874/
      DATA I27    /0/
C
C---------          FIGURE 4.1.5.1-28B            ----
C----     X228B=COS(SWEEP ANGLE(T/C)MAX)   X128B= MACH NUMBER
C----     Y28B= (R)LS
C
      DATA WTYPE/ 4HSTRA ,4HDOUB ,4HCRAN ,4HCURV /
      DATA X228B/0.5,.55,.60,.65,.70,.75,.80,.85,.90,.95,1.0/
      DATA X128B/0.9,.80,.60,.25/
      DATA Y28B/ 1.1,1.13,1.17,1.20,1.24,1.27,1.3,1.33,1.34,1.35,1.36 ,
     11.0,1.04,1.08,1.11,1.15,1.18,1.21,1.23,1.25,1.25,1.26 , 0.88, .92,
     2.96,1.0,1.04,1.08,1.11,1.13,1.14,1.14,1.15 , 0.81,.85,.89,.925,
     3.96,1.0,1.03,1.05,1.06,1.06,1.07/
C
C---------          FIGURE 4.1.5.1-28B-DASHED     ---------
C----          X228BD= COS(T/C)MAX      X128BD= MACH NUMBER
C----          Y28BD= (R)LS
C
      DATA X228BD/0.45,.65,.70,.75,.80,.85,.90,.95,1.0/
      DATA X128BD/0.9,.80,.60,.25/
      DATA Y28BD/1.20,1.20,1.24,1.27,1.30,1.33,1.34,1.35,1.36 , 1.11,
     11.11,1.15,1.18,1.21,1.23,1.25,1.25,1.26 , 1.0,1.0,1.04,1.08,1.11,
     21.13,1.14,1.14,1.15 , 0.925,0.925,.96,1.0,1.03,1.05,2*1.06,1.07/
C
      D(2)=12.0*A(16)/ROUGFC
C
C---------     DETERMINE WING CONFIGURATION       ----------------------
C              IF NOT STRAIGHT-TAPERED, GO TO PAGE 3-2
C
      IF(VT(15).NE.WTYPE(1)) GO TO 1010
C
C---------          PAGE 3-1 CALCULATIONS         ----------------------
C*********     FOR STRAIGHT-TAPER WING CONFIGURATION        ************
C
C---------     COMPUTE REYNOLDS NUMBER, (RN)
C
 1000 D(17)=A(16)*A(129)
C
C---------     COMPUTE RL FROM EQUATION FOR FIG.4.1.5.1-27
C*********          FIGURE 4.1.5.1-27 EQUATION
C
      CALL TBFUNX(B(I+2),CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,3,ROUTID)
      D(14)=D(2)**1.0482*10.0**CEPT
C
C*********          FIGURE 4.1.5.1-26 EQUATIONS (SUBROUTINE FIG26 )
C
      IF( D(14).LT.D(17)) D(17)=D(14)
      CALL FIG26  (D(17),B(I+2),D(10) )
C
C*********          FIGURE 4.1.5.1-28-B
C
      CALL TLINEX(X128B,X228B,Y28B,4,11,B(I+2),A(178),D(13),
     1            0,2,0,2,Q5128B,3,ROUTID)
      CAPL=2.0
      IF(VT(18).GE.0.30) CAPL=1.20
      D(20)=D(10)*(1.+CAPL*VT(16)+100.*VT(16)**4)*D(13)*(2.*A(3)/SREF)
      GO TO 1030
C
C                  ***** INBOARD CALCUALTIONS *****
C
 1010 D(18)=A(15)*A(129)
C
C*********     FIGURE 4.1.5.1-27 EQUATION
C
      CALL TBFUNX(B(I+2),CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,3,ROUTID)
      D(15)=D(2)**1.0482*10.0**CEPT
C
C*********     IF RLI.LT.RNI  SET RNI=RLI
C
      IF( D(15).LT.D(18) ) D(18)= D(15)
C
C*********     FIGURE 4.1.5.1-26 SUBROUTINE
C
      CALL FIG26 ( D(18),B(I+2),D(11) )
C
C---------          FIGURE 4.1.5.1-28-B (DASHED)
C
      CALL TLINEX(X128BD,X228BD,Y28BD,4,9,B(I+2),A(190),D(23),
     1            0,0,0,0,Q128BD,5,ROUTID)
C
C*********     IF XTI GREATER TAN 0.30, THEN CAPL= 2.0          *
C
 1020 CAPL= 1.20
      IF(VT(18).LT.0.30) CAPL=2.00
      D(21)=D(11)*(1.+CAPL*VT(16)+100.*VT(16)**4)*D(23)*(2.*A(1)/SREF)
C
C                   ***** OUTBOARD CALCULATIONS *****
C
      D(19)=A(17)*A(129)
C
C*********     FIGURE 4.1.5.1-27 EQUATION
C
      D(16)=D(15)
C
C*********   IF RLO .LT. RNO, SET RNO= RLO
C
      IF(D(16).LT.D(19)) D(19)=D(16)
C
C*********     FIGURE 4.1.5.1-26 SUBROUTINE
C
      CALL FIG26( D(19),B(I+2),D(12) )
C
C*********     FIGURE 4.1.5.1-28-B
C
      CALL TLINEX(X128B,X228B,Y28B,4,11,B(I+2),A(184),D(24),
     1            0,2,0,2,Q5128B,3,ROUTID)
C
C*********     IF XTO GREATER THAN 0.30, THEN CAPL= 2.0
C
      CAPL=1.20
      IF(VT(66).LT.0.30) CAPL=2.00
      D(22)=D(12)*(1.+CAPL*VT(65)+100.*VT(65)**4)*D(24)*(2.*A(2)/SREF)
C
C*********     COMPUTE CDO FROM PAGE 3-2
C
      D(20)=D(21)+D(22)
 1030 CONTINUE
      RETURN
      END
C ===== vflift.f =====
      SUBROUTINE VFLIFT
C
C***  COMPUTES VENTRAL FIN LIFT COEFFICIENT
C
      REAL MACH,KSHARP
      LOGICAL SUPLE,ROUND,GLOVE
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA
      COMMON /OPTION/ SREF,CBARR,RUFF,BLREF
      COMMON /VTDATA/ ZZZ(195),AVT(195)
      COMMON /SBETA/  YYY(31),SLA(31)
      COMMON /VTI/    XXX(162),VTIN(154)
      COMMON /FLGTCD/ FLC(160)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /CONSNT/ PI,DR,UNUSED,RAD
      COMMON /WINGI/  WINGIN(101)
      DIMENSION ROUTID(2),Q3250A(3),Q3250B(3),Q3246A(3),Q3246G(3),
     1          Q246AF(4),Q13252(3),Q13253(3),Q13251(3)
      DIMENSION S13252(12),DSHP52(12),R13252(12),DRND52(12),T13253(24),
     1          D13253(140),T13251(12),D13251(12)
      DIMENSION DUMY1(184),DUMY2(184),DUMY3(184),DUMY5(184),
     1          DUMY6(184),DUMY4(184)
      DIMENSION T13246(52),D13246(1104),VAA(4),LGA(4),VAB(4),LGB(4),
     1 A1350(17), B1350(19),DA50(72),DB50(88),G13246(9),DG3246(9)
      DIMENSION WTYPE(4)
      EQUIVALENCE(CNA,SLA(31))
      EQUIVALENCE (MACH,SLA(1)),(BETA,SLA(2))
      EQUIVALENCE (SRSTAR,AVT(3))
      EQUIVALENCE (TAPEXP,AVT(27)),(TANLE,AVT(62)),(SWEPLE,AVT(58)),
     1(AR,AVT(7)),(TRATIP,AVT(25)),(COSLE,AVT(61)),(DELTAY,VTIN(17)),
     2(SPANO,VTIN(2)),(TANLEO,AVT(86)),(TANTEO,AVT(104))
     3,(CB,VTIN(5)),(CT,VTIN(1)),(SW,SREF),(TANLEI,AVT(62)),
     4(TANTEI,AVT(80)),(SWTEI,AVT(76)),(SWTEO,AVT(100)),(KSHARP,VTIN(71)
     5),(SPANS,WINGIN(3))
      EQUIVALENCE (D13246(1),DUMY1(1)),(D13246(185),DUMY2(1)),(D13246(36
     19),DUMY3(1)),(D13246(553),DUMY4(1)),(D13246(737),DUMY5(1)) ,
     2(D13246(921),DUMY6(1))
      DATA Q3250A/4H4.1.,4H3.2-,4H60A /,Q3246A/4H4.1.,4H3.2-,4H56A /,
     1     Q3250B/4H4.1.,4H3.2-,4H60B /,Q3246G/4H4.1.,4H3.2-,4H56G /,
     2     Q246AF/4H4.1.,4H3.2-,4H56A-,4HF   /,ROUTID/4HVFLI,4HFT  /,
     3     Q13253/4H4.1.,4H3.2-,4H63  /,
     4     Q13251/4H4.1.,4H3.2-,4H61  /,
     5     Q13252/4H4.1.,4H3.2-,4H62  /
C
C              FIGURE 4.1.3.2-60A (CNA/CNA)T FOR SUBSONIC L.E.
C
      DATA A1350/
     1 0.,     .3,     .4,     .5,     .6,     .7,     .8,     .9,
     2 1.0001 ,
     3 0.,     .41,    .82,    1.24,   2.12,   3.18,   6.95,   16.1 /
      DATA DA50/
     1 1.,     1.,     1.,     1.,     1.,     1.,     1.,     1.,
     2         1.,
     3 1.05,   1.05,   1.05,   1.05,   .985,   .945,   .915,   .9,
     4 .9,
     5 1.04,   1.04,   1.04,   1.04,   .965,   .908,   .87,    .85,
     6 .84,
     7 1.12,   1.12,   1.12,   1.015,  .94,    .88,    .838,   .81,
     8 .796,
     9 1.11,   1.11,   1.11,   1.,     .903,   .84,    .795,   .765,
     A .75,
     B 1.08,   1.08,   1.08,   .954,   .865,   .8,     .75,    .72,
     C .7,
     D 1.2,    1.2,    1.043,  .907,   .817,   .75,    .707,   .675,
     E .66,
     F 1.14,   1.14,   .975,    .857,  .772,   .717,   .675,   .65,
     G .632 /
C
C              FIGURE 4.1.3.2-60B (CNA/CNA)T FOR SUPERSONIC L.E.
C
      DATA B1350/
     1 0.,     .1,     .2,      .3,    .4,     .5,     .6,     .7,
     2 .8,     .9,     1.0001 ,
     3 0.,     4.,     8.,      12.,   20.,    30.,    50.,    70./
      DATA DB50/
     1 1.,     1.,     1.,      1.,    1.,     1.,     1.,     1.,
     2 1.,     1.,     1.,
     3 1.15,   1.15,   1.15,    1.15,  1.095,  1.04,   .99,    .96,
     4 .935,   .915,   .9,
     5 1.12,   1.12,   1.12,    1.12,  1.05,   .985,   .94,    .905,
     6 .88,    .857,   .84,
     7 1.15,   1.15,   1.15,    1.08,  1.005,  .945,   .902,   .87,
     8 .842,   .82,    .796,
     9 1.22,   1.14,   1.05,    .98,   .93,    .89,    .853,   .823,
     A .795,   .77,    .75,
     B 1.13,   1.05,   .98,    .925,   .88,    .845,   .81,    .782,
     C .752,   .73,    .7,
     D 1.02,   .942,   .895,   .855,   .82,    .79,    .76,    .735,
     E .71,    .685,   .66,
     F 1.,     .92,    .87,    .825,   .79,    .755,   .728,   .7,
     G .678,   .655,   .632 /
C
C              FIGURE 4.1.3.2-56G (CNA/A) FOR A*BETA LESS THAN 1.0
C
      DATA G13246/0.,.2,.4,.45,.5,.6,.8,.9,1.0/
      DATA DG3246/1.61,1.58,1.55,1.57,1.62,1.75,1.94,2.0,2.0/
