C              FIGURE 4.1.3.2-62 LEADING-EDGE-EFFECT FACTORS FOR NORMAL-
C                                FORCE-CURVE SLOPE AT SUPERSONIC SPEEDS
C              FIGURE 4.1.3.2-62 (ROUND LEADING EDGE)
C
      DATA R13252
     1 / 0., .5, .94, 1., 1.05, 1.5, 2., 2.5, 3., 3.5, 4., 20./
      DATA DRND52
     1 / 1.043, .97, .893, .89, .894, .987, 1.005, 1.02, 1.025, 1.03,
     2 1.034, 1.034 /
C
C              FIGURE 4.1.3.2-62 (SHARP LEADING EDGE)
C
      DATA S13252
     1 / 0., .5, .94, 1., 1.05, 1.5, 2., 2.5, 3., 3.5, 4., 20./
      DATA DSHP52
     1 / 1.08, 1.013, .94, .942, .948, 1.005, 1.03, 1.04, 1.048, 1.05,
     2 1.055, 1.055 /
      DATA WTYPE/4HSTRA,4HDOUB,4HCRAN,4HCURV/
C
      AR=2.*AR
      MACH=FLC(I+2)
      BETA=SQRT(MACH**2-1.)
      IF(TANLEO.EQ.0.0)TANLEO=.00001
      IF(TANLEI.EQ.0.0)TANLEI=.00001
      IF(VTIN(15).NE.WTYPE(1)) GO TO 1100
C
C       **STRAIGHT TAPERED SUPERSONIC NORMAL FORCE SLOPE**
C
      BOVERT=BETA/TANLE
      CA=COSLE
      IF( BOVERT.GT.1.0)GO TO 1000
      SUPLE=.FALSE.
      GO TO 1010
 1000 SUPLE=.TRUE.
 1010 CONTINUE
C
C                   FIGURE 4.1.3.2-60A (CNA/CNA)T FOR SUBSONIC L.E.
C
      DELTYT=DELTAY/CA
 1020 IF(SUPLE)GO TO 1030
      VAB(1)=BOVERT
      VAB(2)=DELTYT
      LGB(1)=9
      LGB(2)=8
      CALL INTERX(2,A1350,VAB,LGB,DA50,CNCNT,9,72,
     1            2,2,0,0,0,2,0,0,Q3250A,3,ROUTID)
      GO TO 1040
C
C                   FIGURE 4.1.3.2-60B (CNA/CNA)T FOR SUPERSONIC L.E.
C
 1030 CONTINUE
      ARG=DELTAY/(5.85*CA)
      DELTDT=ATAN(ARG)*RAD
      VAB(1)=1./BOVERT
      VAB(2)=DELTDT
      LGB(1)=11
      LGB(2)=8
      CALL INTERX(2,B1350,VAB,LGB,DB50,CNCNT,11,88,
     1            2,2,0,0,0,2,0,0,Q3250B,3,ROUTID)
 1040 IF(TRATIP.EQ.1.0.AND.SWEPLE.EQ.0.0) GO TO 1060
C
C                   NON-RECTANGULAR WING ANALYSIS
C                   FIGURES 4.1.3.2-56A THROUGH F
C
 1050 VAA(1)=BOVERT
      VAA(2)=AR *TANLE
      VAA(3)=TAPEXP
      LGA(1)=23
      LGA(2)=8
      LGA(3)=6
      CALL INTERX(3,T13246,VAA,LGA,D13246,BCNA,23,1104,
     1            0,2,0,0,0,2,0,0,Q3246A,3,ROUTID)
      IF(SUPLE)GO TO 1080
      CNTHRY=BCNA/TANLE
      GO TO 1090
 1060 CONTINUE
C
C                        RECTANGULAR WING ANALYSIS
C
      IF(AR *BETA.GT.1.0)GO TO 1070
C
C                        FIGURE 4.1.3.2-56G(CNA/A)
C
      VAB(1)=AR *BETA
      LGB(1)=9
      CALL INTERX(1,G13246,VAB,LGB,DG3246,CNAA,9,9,
     1            0,0,0,0,0,0,0,0,Q3246G,3,ROUTID)
      CNTHRY=CNAA*AR
      GO TO 1090
 1070 BCNA= 4.-2.*(1./(AR *BETA))
 1080 CNTHRY=BCNA/BETA
 1090 CNA=CNTHRY*CNCNT*SRSTAR/(SW*RAD)
      AR=AR/2.
      RETURN
C
C    ***SUPERSONIC NORMAL FORCE SLOPE,NON-STRAIGHT TAPERED WINGS***
C                    BASIC WING COMPONENT
C
 1100 CONTINUE
      SPANIN=SPANS-SPANO
      CRBW=CB+SPANIN*(TANLEO-TANTEO)
      SBW=(CRBW+CT)*SPANS
      ARBW=4.*SPANS**2/SBW
      TAPBW=CT/CRBW
      BOVERT=BETA/TANLEO
      SUPLE=.FALSE.
      IF(BOVERT.GT.1.)SUPLE=.TRUE.
C
C                   FIGURE 4.1.3.2-56A-F (CNABW)
C
      VAB(1)=BOVERT
      VAB(2)=ARBW*TANLEO
      VAB(3)=TAPBW
      GLOVE=.FALSE.
      TA=TANLEO
 1110 LGB(1)=23
      LGB(2)=8
      LGB(3)=6
      CALL INTERX(3,T13246,VAB,LGB,D13246,BCNA,23,1104,
     1            0,2,0,0,0,2,0,0,Q246AF,4,ROUTID)
      CNTHRY=BCNA/TA
      IF(SUPLE)CNTHRY=BCNA/BETA
C
C                   LEADING-EDGE-EFFECT PARAMETERS
C              FIGURE 4.1.3.2-62 (CLE)BW
C
      ROUND=.FALSE.
      IF(KSHARP.EQ.UNUSED)ROUND=.TRUE.
      VAB(1)=BOVERT
      LGB(1)=12
C
C              SHARP LEADING EDGE
C
      IF(ROUND)GO TO 1120
      CALL INTERX(1,S13252,VAB,LGB,DSHP52,CLE  ,12,12,
     1            0,0,0,0,0,0,0,0,Q13252,3,ROUTID)
      GO TO 1130
C
C              ROUND LEADING EDGE
C
 1120 CALL INTERX(1,R13252,VAB,LGB,DRND52,CLE  ,12,12,
     1            0,0,0,0,0,0,0,0,Q13252,3,ROUTID)
 1130 IF(GLOVE)GO TO 1160
      CNTBW=CNTHRY
      CLEBW=CLE
      IF(TANLEO.GE.TANLEI)GO TO 1140
      CNABW=CNTBW*SBW/SW *CLEBW
      GO TO 1150
 1140 CONTINUE
      S2=SPANIN**2*TANLEO
      A2=4.*SPANIN**2/S2
      VAB(2)=A2*TANLEO
      VAB(3)=0.0
      CALL INTERX(3,T13246,VAB,LGB,D13246,BCNA,23,1104,
     1            0,2,0,0,0,2,0,0,Q246AF,4,ROUTID)
      CNT2=BCNA/BETA
      IF(VAB(1).GT.1.)CNT2  =BCNA/TANLEO
      CNABW=(CNTHRY*SBW/SW-CNT2  *  S2/SW )*CLEBW
 1150 CONTINUE
C
C                        GLOVE COMPONENT
C
      CRGLV=TANLEI*SPANIN
      SGLV=CRGLV*SPANIN
      ARGLV=4.*SPANIN**2/SGLV
      VAB(1)=BETA/TANLEI
      VAB(2)=ARGLV*TANLEI
      VAB(3)=0.0
      GLOVE=.TRUE.
      BOVERT=VAB(1)
      SUPLE=.FALSE.
      TA=TANLEI
      IF(BOVERT.GT.1.)SUPLE=.TRUE.
      GO TO 1110
 1160 CONTINUE
      CLEGLV=CLE
      CNAGLV=CNTHRY*CLEGLV*SGLV/SW
C
C              FIGURE 4.1.3.2-63 (CN1=CNA/A)
C                        EXTENSION COMPONENT
C
      IF(ABS(SWTEI-SWTEO).LT.4.)GO TO 1170
      BE= 2.*SPANIN
      VAB(1)=BETA/TANLEI
      VAB(2)=TANTEI/TANLEI
      LGB(1)=14
      LGB(2)=10
      CALL INTERX(2,T13253,VAB,LGB,D13253,CN1,14,140,
     1            2,2,0,0,2,2,0,0,Q13253,3,ROUTID)
      VAB(2)=TANTEO/TANLEI
      CALL INTERX(2,T13253,VAB,LGB,D13253,CN2,14,140,
     1            2,2,0,0,2,2,0,0,Q13253,3,ROUTID)
      CNAE=(CN1-CN2)*BE**2/SW
      GO TO 1180
 1170 CNAE=0.0
C
C   **SUPERSONIC NORMAL FORCE SLOPE,NON-STRAIGHT TAPERED WINGS,TOTAL WIN
C
 1180 CONTINUE
C
C              FIGURE 4.1.3.2-61
C
      VAB(1)=CNAGLV/(CLEGLV*BETA)
      LGB(1)= 12
      CALL INTERX(1,T13251,VAB,LGB,D13251,RKL,12,12,
     1            2,0,0,0,2,0,0,0,Q13251,3,ROUTID)
      CNA=RKL*(CNABW+CNAGLV+CNAE)/RAD
      AR=AR/2.
      RETURN
      END
C ===== vname.f =====
      SUBROUTINE VNAME(KOL,L,LEN,NUM,NAMES,I,FOUND,ARRAY,
     1            NDMS,NF,NUMBER,BLANK,EQUAL)
      DIMENSION KOL(1), LEN(1), NAMES(1), NUMBER(1)
      INTEGER  PARL, PARR, EQUAL, BLANK
      LOGICAL FOUND, ARRAY, NMTEST, FLAG
      DATA PARL, PARR /4H(   ,4H)    /
C
C***  TEST FOR VARIABLE NAME
C
      J = 1
      DO 1010 I=1,NUM
      IF(.NOT. NMTEST(KOL(L),NAMES(J),LEN(I))) GO TO 1000
      K = L+LEN(I)
      FLAG = (KOL(K) .EQ. BLANK) .OR. (KOL(K) .EQ. EQUAL) .OR.
     1       (KOL(K) .EQ. PARL)
      IF(FLAG) GO TO 1020
 1000 J = J+LEN(I)
 1010 CONTINUE
      FOUND = .FALSE.
      I = 0
      GO TO 1080
C
C***  DETERMINE IF NAME IS AN ARRAY, CHECK FOR ARRAY ELEMENT
C***  DESIGNATION, AND CHECK NAME DELIMITERS
C
 1020 CONTINUE
      FOUND = .TRUE.
      ARRAY = .FALSE.
      L = L+LEN(I)
      NDMS = 0
      IF(KOL(L) .NE. PARL) GO TO 1080
        ARRAY = .TRUE.
        L = L+1
 1030   DO 1040 J=1,10
        IF(L .GE. 79) GO TO 1065
        IF(KOL(L) .EQ. NUMBER(J)) GO TO 1060
        IF(KOL(L) .EQ. PARR)      GO TO 1070
 1040   CONTINUE
        NF = NF+1
 1050   L = L+1
        IF(KOL(L) .EQ. EQUAL) GO TO 1080
        GO TO 1050
 1060   NDMS = 10*NDMS+J-1
        L = L+1
        GO TO 1030
 1065   CONTINUE
        IF(KOL(L) .NE. PARR) NF = NF+1
 1070   CONTINUE
        L = L+1
        NDMS = NDMS-1
        IF(NDMS .GE. 0) GO TO 1080
        NF = NF+1
        NDMS = 0
 1080 CONTINUE
      RETURN
      END
C ===== vrtcdo.f =====
      SUBROUTINE VRTCDO(I)
C
C *** CALCULATES SUPERSONIC VERTICAL TAIL ZERO LIFT DRAG COEFFICIENT
C
      REAL MACH,LERBW,LERO,LERI,KSHARP
      DIMENSION ROUTID(2)
      DIMENSION Q15127(4)
      DIMENSION WTYPE(4),CN(20),CAV(20),CDJWB(20), CLJWB(20),CD(20)
      DIMENSION X27M(4),X27I(4),C27(6)
C
      COMMON /OVERLY/ NLOG,NMACH,M,NALPHA
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /OPTION/ SR,CBARR,RUFF,BLREF
      COMMON /VTI/    CT,SPANO,SPANS,SSPN,CB,CR,SAVSI,SAVSO,
     1                CHSTAT,SWAFP,TWISTA,SSPNDD,DHDADI,DHDADO,TYPE,
     2                TOVC,DELTAY,XOVC,CLI,ALPHAI,CLALPA(20),
     3                CLMAX(20),CMO,LERI,LERO,CAMBER,TOVCO,XOVCO,CMOT,
     4                CLMAXL,CLAMO,TCEFF,KSHARP,SVWB(20),SVB(20),
     5                SVHB(20),TVTIN(8)
      COMMON /WINGD/  A(195)
      COMMON /VTDATA/ AVT(195)
      COMMON /WBHCAL/ STP(156)
      COMMON /IBW/    PBW, BW(380)
      COMMON /IBWV/   PBWV, BWV(380)
      COMMON /FLGTCD/ FLC(160)
C
      EQUIVALENCE (CDO,STP(1)),(CD(1),BWV(1)),(CN(1),BWV(61)),
     1            (CAV(1),BWV(81))
      EQUIVALENCE (CBARI,AVT(15)),(RNFS,A(129)),(SRSTAR,AVT(3)),
     1(CBARO,AVT(17)),(SISTAR,AVT(1)),(SOSTAR,AVT(2)),
     2(TANLEO,AVT(86)),(COSLEO,AVT(85)),(TANLEI,AVT(62)),
     3(COSLE,AVT(61)),(TANTEO,AVT(104)),(CDJWB(1),BW(1)),
     4(CLJWB(1),BW(21))
C
      DATA ROUTID /4HVRTC,4HDO  /
      DATA Q15127 /4H4.1.,4H5.1-,4H27  ,4HCEPT/
      DATA WTYPE  /4HSTRA,4HDOUB,4HCRAN,4HCURV/
      DATA X27M   /0 .0,1.0,2.0,3.0/
      DATA X27I   /1.57780,1.67221,1.98509,2.28874/
      DATA I27    /0/
C
      MACH=FLC(I+2 )
      BETA=SQRT(MACH**2-1.0)
C
C  ***WING SUPERSONIC ZERO-LIFT SKIN FRICTION DRAG,STRAIGHT TAPERED WING
C
      IF(TYPE.NE.WTYPE(1))GO TO 1020
      CBAR=CBARI
 1000 RNN=CBAR*RNFS
      IF(RUFF.EQ.0.0)GO TO 1010
      ARG=12.*CBAR/RUFF
C
C                   FIGURE 4.1.5.1-27 (EQUATION FOR RLCOFF)
C
      RACH = MACH
      IF(RACH.GT.3.0)RACH=3.0
      CALL TBFUNX(RACH,CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,4,ROUTID)
      RLCOFF=ARG**1.0482*10.0**CEPT
      IF(RLCOFF.LT.RNN)RNN=RLCOFF
 1010 CALL FIG26(RNN,RACH,CF)
      IF(TYPE.NE.WTYPE(1))GO TO 1030
      CDF=CF*SRSTAR/SR*2.
      GO TO 1050
C
C  ***WING SUPERSONIC ZERO-LIFT SKIN FRICTION DRAG,NON-STRAIGHT WING***
C
 1020 CONTINUE
      CBAR=CBARI
      GO TO 1000
 1030 CONTINUE
      IF(CBAR.EQ.CBARO)GO TO 1040
      RNI=RNN
      CFI=CF
      CBAR=CBARO
      GO TO 1000
 1040 RNO=RNN
      CFO=CF
      CDF=(CFI*SISTAR+CFO*SOSTAR)/SR*2.
 1050 CONTINUE
C
C   ***SUPERSONIC WING ZERO-LIFT WAVE DRAG,SHARP L.E.,ALL PLANFORMS***
C
      IF(TYPE.EQ.WTYPE(1))GO TO 1060
      TA=TANLEO
      SPANIN=SPANS-SPANO
      CRBW=CB+SPANIN*(TANLEO-TANTEO)
      SBW=(CRBW+CT)*SPANS*0.50
      S=SBW
      CA=COSLEO
      LERBW=LERO*((CR+CT+2.*CB)/4.)
      GO TO 1070
 1060 TA=TANLEI
      IF(ABS(TA) .LT. UNUSED) TA = UNUSED
      S=(CR+CT)/2.*SSPN
      CA =COSLE
      LERBW=LERI*((CR+CT)/2.)
 1070 CONTINUE
      BOVERT=BETA/TA
      IF(KSHARP.EQ.UNUSED)GO TO 1080
      ARG=KSHARP*TCEFF**2*S  /SR
      CDW=ARG/BETA
      IF(BOVERT.LT.1.)CDW=ARG/TA
      GO TO 1090
 1080 CONTINUE
C
C  ***SUPERSONIC WING ZERO-LIFT WAVE DRAG,ROUND L.E.,ALL PLANFORMS***
C
      ARG1=1.28*MACH**3*CA    **6/(1.+MACH**3*CA    **3)
      ARG2=2.* LERBW * SPANS /(SR*CA)
      CDLE=ARG1*ARG2
      ARG=     16.*TCEFF**2*S  /(3.*SR)
      IF(BOVERT.GE.1.)CDW=CDLE+ARG/BETA
      IF(BOVERT.LT.1.)CDW=CDLE+ARG/TA
 1090 CONTINUE
      CDO=CDF+CDW
      IF(TYPE.NE.WTYPE(1))RETURN
      DO 1100 J=1,NALPHA
         CD(J)=CD(J)+CDO
         COSA=COS(FLC(J+22)/RAD)
         SINA=SIN(FLC(J+22)/RAD)
         CN(J)=CLJWB(J)*COSA+CD(J)*SINA
 1100 CAV(J)=CD(J)*COSA-CLJWB(J)*SINA
      RETURN
      END
C ===== vtarea.f =====
      SUBROUTINE VTAREA(VTIN,AVT,VERTUP,XV,ZV)
C
C *** EXECUTIVE TO COMPUTE VERTICAL TAIL AREA SHADOWED BY MACH LINES
C
      COMMON /OVERLY/ NLOG,NMACH,I,NALPHA,IG
      COMMON /WINGD/  A(195)
      COMMON /HTDATA/ AHT(195)
      COMMON /WINGI/  WINGIN(100)
      COMMON /HTI/    HTIN(154)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD
      COMMON /FLGTCD/ FLC(73)
      COMMON /SYNTSS/ SYNA(19)
      COMMON /FLOLOG/ FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      LOGICAL EFFECT,VERTUP
      LOGICAL HTAIL,FLIP,ANGCHG
      DIMENSION XP(5),YP(5),XX(4),YY(4),AA(3),XI(4),YI(4),SVWB(2),
     1          SVHB(2),AREA(2),X(5),Y(5)
      LOGICAL FLTC,OPTI,BO,WGPL,WGSC,SYNT,HTPL,HTSC,VTPL,VTSC
      DIMENSION VTIN(154),AVT(195)
      DATA STRA/4HSTRA/
C
      HTAIL=.FALSE.
      ANGCHG=.FALSE.
      NCON=0
      SVWB(1)=0.
      SVWB(2)=0.
      SVHB(1)=0.
      SVHB(2)=0.
C
C     COORDINATES OF INBOARD VT PANEL
C
 1000 XP(1)=XV+(VTIN(4)-VTIN(3))*AVT(62)
      YP(1)=VTIN(4)-VTIN(3)+ZV
      IF(.NOT.VERTUP) YP(1)=VTIN(4)-VTIN(3)-ZV
      XP(2)=XV+AVT(21)*AVT(62)
      YP(2)=AVT(21)
      XP(3)=XP(2)+VTIN(5)
      YP(3)=AVT(21)
      XP(4)=XP(1)+AVT(10)
      YP(4)=YP(1)
      XP(5)=XP(1)
      YP(5)=YP(1)
      XMACH=FLC(I+2)
C
C     TEST FOR VT POSITION
C
      IF(VERTUP) GO TO 1020
      DO 1010 N=1,5
 1010 YP(N)=-YP(N)
      XMACH=-XMACH
 1020 AMUU=ATAN(1./SQRT(XMACH**2-1.))
C
C     CALCULATE LE AND TE MACH LINE INTERSECTIONS WITH VT PANEL
C
      DO 1220 J=1,2
         FLIP=.FALSE.
         IF(HTAIL) GO TO 1030
         AA(1)=SYNA(2)+(WINGIN(4)-WINGIN(3))*A(62)*COS(SYNA(4)/RAD)
         AA(2)=SYNA(3)-(AA(1)-SYNA(2))*SIN(SYNA(4)/RAD)/
     1         COS(SYNA(4)/RAD)
         AA(3)=SYNA(4)
         IF(J.EQ.1) GO TO 1050
         AA(1)=AA(1)+A(10)*COS(SYNA(4)/RAD)
         AA(2)=AA(2)-A(10)*SIN(SYNA(4)/RAD)
         GO TO 1050
 1030    IF(SYNA(4).EQ.SYNA(8).OR.ANGCHG) GO TO 1040
C
C     CALCULATE XH AND ZH FOR HT WITH INCIDINCE ANGLE EQUAL TO THAT OF
C     WING  (ROTATION ABOUT 1/4 MAC)
C
         HACLE=(HTIN(4)-HTIN(3))*AHT(62)+AHT(30)-AHT(16)/4.
         XHAC=SYNA(6)+HACLE*COS(SYNA(8)/RAD)
         ZHAC=SYNA(7)-HACLE*SIN(SYNA(8)/RAD)
         SYNA(6)=XHAC-HACLE*COS(SYNA(4)/RAD)
         SYNA(7)=ZHAC+HACLE*SIN(SYNA(4)/RAD)
         ANGCHG=.TRUE.
 1040    AA(1)=SYNA(6)+(HTIN(4)-HTIN(3))*AHT(62)*COS(SYNA(4)/RAD)
         AA(2)=SYNA(7)-(AA(1)-SYNA(6))*SIN(SYNA(4)/RAD)/
     1         COS(SYNA(4)/RAD)
         AA(3)=SYNA(4)
         IF(J.EQ.1) GO TO 1050
         AA(1)=AA(1)+AHT(10)*COS(SYNA(4)/RAD)
         AA(2)=AA(2)-AHT(10)*SIN(SYNA(4)/RAD)
 1050    CALL PTINT1(XP,YP,AA,AMUU,X,Y,XI,YI,NSUM,EFFECT,KK,J,NCON
     1              ,VERTUP)
C
C     CHECK FOR MACH LINE NOT INTERSECTING VT
C
         IF(J.NE.1) GO TO 1060
         IF(EFFECT) GO TO 1070
         GO TO 1230
 1060    IF(EFFECT) GO TO 1070
         AREA(J)=0.
         IF(KK.EQ.1) AREA(J)=AVT(1+NCON)-AREA(J)
         GO TO 1200
 1070    IF(NSUM.NE.0) GO TO 1080
         AREA(J)=0.
         IF(J.NE.1) FLIP=.TRUE.
         GO TO 1180
 1080    CONTINUE
         GO TO (1090,1100,1110,1120,1130,1150,1160) NSUM
 1090    CONTINUE
 1100    CONTINUE
C
C     HERE FOR MACH LINE INTERSECTING LE AND TIP CHORD
C
 1110    XX(1)=XI(1)
         XX(2)=X(2)
         XX(3)=XI(2)
         YY(1)=YI(1)
         YY(2)=Y(2)
         YY(3)=YI(2)
         GO TO 1170
C
C     HERE FOR MACH LINE INTERSECTING LE AND TE
C
 1120    XX(1)=XI(1)
         XX(2)=X(2)
         XX(3)=X(3)
         XX(4)=XI(3)
         YY(1)=YI(1)
         YY(2)=Y(2)
         YY(3)=Y(3)
         YY(4)=YI(3)
         IF(ABS(XI(1)).GT.ABS(XI(3))) FLIP=.TRUE.
         GO TO 1170
 1130    IF(KK.EQ.4) GO TO 1140
C
C     HERE FOR MACH LINE INTERSECTING TE AND TIP CHORD
C
         XX(1)=XI(2)
         XX(2)=X(3)
         XX(3)=XI(3)
         YY(1)=YI(2)
         YY(2)=Y(3)
         YY(3)=YI(3)
         FLIP=.TRUE.
         GO TO 1170
C
C     HERE FOR MACH LINE INTERSECTING ROOT CHORD AND LE
C
 1140    XX(1)=X(1)
         XX(2)=XI(1)
         XX(3)=XI(4)
         YY(1)=Y(1)
         YY(2)=YI(1)
         YY(3)=YI(4)
         GO TO 1170
C
C     HERE FOR MACH LINE INTERSECTING ROOT CHORD AND TIP CHORD
C
 1150    XX(1)=X(1)
         XX(2)=X(2)
         XX(3)=XI(2)
         XX(4)=XI(4)
         YY(1)=Y(1)
         YY(2)=Y(2)
         YY(3)=YI(2)
         YY(4)=YI(4)
         GO TO 1170
C
C     HERE FOR MACH LINE INTERSECTING ROOT CHORD AND TE
C
 1160    XX(1)=XI(3)
         XX(2)=X(4)
         XX(3)=XI(4)
         YY(1)=YI(3)
         YY(2)=Y(4)
         YY(3)=YI(4)
         FLIP=.TRUE.
 1170    CALL AREA1 (XX,YY,SAREA,NSUM)
         AREA(J)=SAREA
 1180    IF(J.NE.1) GO TO 1190
         IF(.NOT.FLIP) GO TO 1220
         AREA(1)=AVT(1+NCON)-AREA(1)
         GO TO 1220
 1190    IF(FLIP) GO TO 1200
         AREA(2)=AVT(1+NCON)-AREA(2)
 1200    IF(.NOT.HTAIL) GO TO 1210
         SVHB(1+NCON)=AVT(1+NCON)-(AREA(1)+AREA(2))
         GO TO 1220
 1210    SVWB(1+NCON)=AVT(1+NCON)-(AREA(1)+AREA(2))
 1220 CONTINUE
      IF(NCON.EQ.1) GO TO 1230
      NCON=1
C
C     TEST FOR NON-STRAIGHT TAPERED VT
C
      IF(VTIN(15).EQ.STRA) GO TO 1230
C
C     COORDINATES OF OUTBOARD VT PANEL
C
      XP(1)=XP(2)
      YP(1)=YP(2)
      XP(2)=XP(2)+VTIN(2)*AVT(86)
      YP(2)=VTIN(4)
      XP(3)=XP(2)+VTIN(1)
      YP(3)=VTIN(4)
      XP(4)=XP(1)+VTIN(5)
      YP(4)=YP(1)
      XP(5)=XP(1)
      YP(5)=YP(1)
      GO TO 1020
 1230 IF(.NOT.HTAIL) GO TO 1240
      VTIN(134+I)=SVHB(1)+SVHB(2)
      GO TO 1250
 1240 VTIN(94+I)=SVWB(1)+SVWB(2)
 1250 CONTINUE
      IF(HTAIL) GO TO 1260
C
C     TEST FOR HT
C
      IF(.NOT.HTPL) GO TO 1260
      HTAIL=.TRUE.
      NCON=0
      GO TO 1000
 1260 VTIN(114+I)=AVT(3)-(VTIN(94+I)+VTIN(134+I))
      RETURN
      END
C ===== vtdrag.f =====
      SUBROUTINE VTDRAG(I)
C
C *** CALCULATES VERTICAL DRAG COEFFICIENT
C
      DIMENSION ROUTID(2)
      DIMENSION Q15127(3),Q5128B(3),Q128BD(5)
      COMMON /OPTION/ SREF,CBARR,ROUGFC,BLREF
      COMMON /FLGTCD/ FLC(93)
      COMMON /WHAERO/ C2(51),D2(55),CHT2(51),DHT2(55),DVT(55)
      COMMON /VTDATA/ AVT(195)
      COMMON /VTI/    VT(100)
      DIMENSION D(55),A(195),B(93)
      EQUIVALENCE (A(1),AVT(1)),(D(1),DVT(1)),(B(1),FLC(1))
      DIMENSION WTYPE(4)
      DIMENSION X228BD(9),X128BD(4),Y28BD(36)
      DIMENSION X228B(11), X128B(4), Y28B(44)
      DIMENSION X27M(4),X27I(4),C27(6)
      DATA ROUTID/4HVTDR,4HAG  /
      DATA Q15127/4H4.1.,4H5.1-,4H27  /,Q5128B/4H4.1.,4H5.1-,4H28-B/,
     1     Q128BD/4H4.1.,4H5.1-,4H28-B,4H(DAS,4HHED)/
      DATA X27M /0.0,1.0,2.0,3.0/
      DATA X27I /1.57780,1.67221,1.98509,2.28874/
      DATA I27  /0/
C
C---------          FIGURE 4.1.5.1-28B            ----
C----     X228B=COS(SWEEP ANGLE(T/C)MAX)   X128B= MACH NUMBER
C----     Y28B= (R)LS
C
      DATA WTYPE / 4HSTRA ,4HDOUB ,4HCRAN ,4HCURV /
      DATA X228B /0.5,.55,.60,.65,.70,.75,.80,.85,.90,.95,1.0/
      DATA X128B /0.9,.80,.60,.25/
      DATA Y28B/ 1.1,1.13,1.17,1.20,1.24,1.27,1.3,1.33,1.34,1.35,1.36 ,
     11.0,1.04,1.08,1.11,1.15,1.18,1.21,1.23,1.25,1.25,1.26 , 0.88, .92,
     2.96,1.0,1.04,1.08,1.11,1.13,1.14,1.14,1.15 , 0.81,.85,.89,.925,
     3.96,1.0,1.03,1.05,1.06,1.06,1.07/
C
C---------          FIGURE 4.1.5.1-28B-DASHED     ---------
C----          X228BD= COS(T/C)MAX      X128BD= MACH NUMBER
C----          Y28BD= (R)LS
C
      DATA X228BD /0.45,.65,.70,.75,.80,.85,.90,.95,1.0/
      DATA X128BD /0.9,.80,.60,.25/
      DATA Y28BD  /1.20,1.20,1.24,1.27,1.30,1.33,1.34,1.35,1.36 , 1.11,
     11.11,1.15,1.18,1.21,1.23,1.25,1.25,1.26 , 1.0,1.0,1.04,1.08,1.11,
     21.13,1.14,1.14,1.15 , 0.925,0.925,.96,1.0,1.03,1.05,2*1.06,1.07/
C
      D(2)=12.0*A(16)/ROUGFC
C
C---------     DETERMINE WING CONFIGURATION       ----------------------
C              IF NOT STRAIGHT-TAPERED, GO TO PAGE 3-2
C
      IF(VT(15).NE.WTYPE(1)) GO TO 1010
C
C---------          PAGE 3-1 CALCULATIONS         ----------------------
C*********     FOR STRAIGHT-TAPER WING CONFIGURATION        ************
C---------     COMPUTE REYNOLDS NUMBER, (RN)
C
 1000 D(17)=A(16)*A(129)
C
C---------     COMPUTE RL FROM EQUATION FOR FIG.4.1.5.1-27
C*********          FIGURE 4.1.5.1-27 EQUATION
C
      CALL TBFUNX(B(I+2),CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,3,ROUTID)
      D(14)=D(2)**1.0482*10.0**CEPT
C
C*********          FIGURE 4.1.5.1-26 EQUATIONS (SUBROUTINE FIG26 )
C
      IF( D(14).LT.D(17)) D(17)=D(14)
      CALL FIG26  (D(17),B(I+2),D(10) )
C
C*********          FIGURE 4.1.5.1-28-B
C
      CALL TLINEX(X128B,X228B,Y28B,4,11,B(I+2),A(178),D(13),
     1            0,2,0,2,Q5128B,3,ROUTID)
      CAPL=2.0
      IF(VT(18).GE.0.30) CAPL=1.20
      D(20)=D(10)*(1.+CAPL*VT(16)+100.*VT(16)**4)*D(13)*(2.*A(3)/SREF)
      GO TO 1030
C
C                  ***** INBOARD CALCUALTIONS *****
C
 1010 D(18)=A(15)*A(129)
C
C*********     FIGURE 4.1.5.1-27 EQUATION
C
      CALL TBFUNX(B(I+2),CEPT,DYDX,4,X27M,X27I,C27,I27,MI,NG,
     1            0,0,Q15127,3,ROUTID)
      D(15)=D(2)**1.0482*10.0**CEPT
