      EQUIVALENCE (DCLTB(1,1,1),DCAR(1))
      EQUIVALENCE (CLOCL(1,1),CLL(1)) ,(DACLMX(1,1),DACLL(1))
C
      LOGICAL ITYPTT
      LOGICAL LOARAT
C
      DATA ROUTID /4HWTLI,4HFT  /
      DATA Q3417B /4H4.1.,4H3.4-,4H24B /,
     1     Q13242 /4H4.1.,4H3.2-,4H52  /,
