     1,11.,12.,13.,14.,15. , 0.,.2,.4,.7,1.2,1.7,2.4,3.,3.7,4.6,5.2,6.,
     26.9,7.8,8.6,9.5,10.4,11.4,12.3,13.5 , 0.,0.,.1,.2,.5,.7,1.,1.3,1.6
     3,2.,2.5,3.,3.6,4.3,4.9,5.5,6.2,7.,7.6,8.5/
      DATA ACLE /0.,2.,3.,4.,5.,6.,7.,8.,9.,30./
      DATA DACLO /                                    10.,8.5,6.9,5.5,4.
     1,2.6,1.5,.7,.1,0. , 8.7,7.3,5.3,4.2,2.6,1.4,0.5,-.2,-.5,0. , 7.5,
     25.9,4.2,2.5,1.2,0.,-.7,-1.1,-.8,0. , 5.5,3.4,1.6,0.,-1.3,-2.1,-2.5
     3,-2.,-.8,0. , 3.,.7,-1.4,-3.3,-4.3,-4.3,-3.1,-2.,-.8,0. , .3,-2.5,
     4-4.7,-5.8,-5.3,-4.3,-3.1,-2.,-.8,0. ,-2.2,-5.,-6.7,-6.3,-5.3,-4.3,
     5-3.1,-2.,-0.8,0. , -3.3,-6.6,-7.2,-6.3,-5.3,-4.3,-3.1,-2.,-.8,0.,
     6  -4.2,-7.,-7.2,-6.3,-5.3,-4.3,-3.1,-2.,-.8,0. , -8.5,-7.9,-7.2,
     7 -6.3,-5.3,-4.3,-3.1,-2.,-.8,0. /
      DATA C1TABO /.0,.5,1.,1.5,2.,2.5,3.,3.5,4.,4.5/
C
C     ----4.1.3.2-52
C
      DATA BA/1.15,1.4,2.,2.2,3.,3.6,4.,5.,6.,7.,8.,9./
      DATA CLOVCL /1.25,1.2,1.12,1.1,1.04,1.,.985,.96,.95,3*.94/
      DATA IN4132 /0/
      DATA WTYPE /4HSTRA ,4HDOUB ,4HCRAN ,4HCURV /
C
C     ----INITIALIZATION ENTRY
C
      ITYPTT = .TRUE.
      LOARAT = .FALSE.
      IF(A(7).LT.A(125)) LOARAT = .TRUE.
      TYPE = AIN(15)
C
C     ----COMPUTE CLA0 + CLAI FOR OTHER THAN STRAIGHT TAPERED
C
      IF(TYPE.EQ.WTYPE(1)) GO TO 1000
C
C     ----CLA0
C
      TEMP1 = 2.*PI*A(168)*DEG
      TEMP2 =(A(168)*DEG*2.*PI/A(131))**2
      TEMP3 = A(98)**2
      TEMP4=B(2)**2
      A(172)=TEMP1/(2.+SQRT(TEMP2*(1.+TEMP3/TEMP4)+4.))
C
C     ----CLAI
C
      TEMP1 = 2.*PI*A(5)*DEG
      TEMP2 = (A(5)*DEG*2.*PI/A(131))**2
      TEMP3 = A(74)**2
      A(171)=TEMP1/(2.+SQRT(TEMP2*(1.+TEMP3/TEMP4)+4.))
 1000 CONTINUE
C
C     ----CURVED WING TEST
C
      IF(TYPE.EQ.WTYPE(4)) GO TO 1070
      ITYPTT = .FALSE.
C
C     ----4.1.3.4-24(B)
C
      CALL TBFUNX(A(27),A(159),DCDT,11,TR,C2,C,IN,MI,NG,
     1            0,0,Q3417B,3,ROUTID)
      A(160) = (A(159)+1.)*A(38)*A(7)
C
C     ----COMPUTE BETA*S
C
      TEMP1 = 2.*PI*A(7)*DEG
      TEMP2=A(7)*DEG*2.*PI/A(131)
      TEMP2 = TEMP2**2
      TEMP3 = A(50)**2
      CALL TLINEX(DELTAY, SALE,CLL,7,13,AIN(17),A(34),A(145),
     1           -1,0,-1,2,Q3414A,3,ROUTID)
      CALL TLINEX(DY,SALE,DACLL,4,13,AIN(17),A(34),A(144),
     1           -1,0,-1,2,Q3414B,3,ROUTID)
 1010 IF(ITYPTT) GO TO 1070
      TEMP4 = B(2)**2
      AOUT(101)=(TEMP1/(2.+SQRT(TEMP2*(1.+TEMP3/TEMP4)+4.)))*A(3)/
     1          SREF
      IF(TYPE.NE.WTYPE(3)) GO TO 1020
C
C     ----HERE FOR CRANKED HIGH ASPECT RATIO WING-FINISH CLA COMPUTATION
C     ----FIGURE 4.1.3.2-52
C
      BAARG = A(7)* B(2)
      CALL TBFUNX(BAARG,CLRAT,DYDX,12,BA,CLOVCL,CBA ,IN4132,M4132,N4132,
     1            2,0,Q13242,3,ROUTID)
      AOUT(101) = CLRAT * AOUT(101)
 1020 CONTINUE
      IF(LOARAT) GO TO 1030
      CALL TLIN3X(DYA,AMACH,SALE4,DCAR,6,5,4,AIN(17),B(1),A( 34),TEMP5
     1            ,0,-1,0,2,2,2,Q13415,3,ROUTID)
      A(146)=A(145)*A(132)
      B(44)=(A(145)*A(132)+TEMP5)*A(3)/SREF
      B(43) = B(44)/AOUT(101)+B(49)+A(144)
      GO TO 1060
C
C     ----HERE FOR LOW ASPECT RATIO
C
 1030 C1P1AC = A(7)*A(124)/B(2)
      CALL CLMXBS(C1P1AC,B(44),A,B,AIN)
C
C     ----4.1.3.4-25(A)
C
      CALL TBFUNX(C1P1AC,ACLBAS,DYDX,10,C1ABCS,ACLMX,C17,I17,MI,NG,
     1            0,0,Q3418A,3,ROUTID)
      IF(A(160).LE.4.5) GO TO 1040
      CALL TLINEX(DMN,C1TAB,DACL,3,20,B(1),A(160),DACMAX,
     1            -1,0,2,0,Q3418B,3,ROUTID)
      GO TO 1050
 1040 TMP=A(7)*A(37)*(1.+4.*A(27)**2)
      CALL TLINEX(ACLE,C1TABO,DACLO,10,10,TMP,A(160),DACMAX,
     1            0,0,2,0,Q3418B,3,ROUTID)
 1050 B(43)=ACLBAS+DACMAX
 1060 CONTINUE
      RETURN
 1070 WRITE(6,1080) TYPE,LOARAT
 1080 FORMAT(33H NO CLALPHA COMPUTATION- WING IS  ,A4,18H LOW ASPECT RAT
     1IO= ,L1)
      RETURN
      END
C ===== xnam1.f =====
      SUBROUTINE XNAM1(IOP)
C
C***  READ OR WRITE NAMELIST FLTCON
C
      COMMON /FLGTCD/ A2(160)
      COMMON /FLOLOG/ FLO(19)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
C
      INTEGER FLTCON
      LOGICAL EOF
C
      DIMENSION LEN2(18),LDM2(18),FLTCON(81),LOC2(18),A2A(161)
      DIMENSION NLNAME(6)
C
      DATA NLNAME / 4HF   ,4HL   ,4HT   ,4HC   ,4HO   ,4HN   /
      DATA LEN2 / 5,4,6,6,5,3*6,2,3,3*4,2,5,4,4,5 /
      DATA LDM2 / 1,20,1,20,20,-1,3*1,4*20,4*1,20 /
      DATA LOC2 / 1,3,2,23,43,161,94,95,96,97,74,117,137,157,158
     1            ,159,160,23 /
      DATA FLTCON /   4HN   ,4HM   ,4HA   ,4HC   ,4HH   ,4HM   ,
     1  4HA   ,4HC   ,4HH   ,4HN   ,4HA   ,4HL   ,4HP   ,4HH   ,
     2  4HA   ,4HA   ,4HL   ,4HS   ,4HC   ,4HH   ,4HD   ,4HR   ,
     3  4HN   ,4HN   ,4HU   ,4HB   ,4HH   ,4HY   ,4HP   ,4HE   ,
     4  4HR   ,4HS   ,4HS   ,4HT   ,4HM   ,4HA   ,4HC   ,4HH   ,
     5  4HT   ,4HS   ,4HM   ,4HA   ,4HC   ,4HH   ,4HT   ,4HR   ,
     6  4HA   ,4HL   ,4HT   ,4HP   ,4HI   ,4HN   ,4HF   ,4HT   ,
     7  4HI   ,4HN   ,4HF   ,4HV   ,4HI   ,4HN   ,4HF   ,4HW   ,
     8  4HT   ,4HG   ,4HA   ,4HM   ,4HM   ,4HA   ,4HN   ,4HA   ,
     9  4HL   ,4HT   ,4HL   ,4HO   ,4HO   ,4HP   ,4HA   ,4HL   ,
     A  4HP   ,4HH   ,4HA   /
C
      DO 1000 I=1,160
         A2A(I)=A2(I)
 1000 CONTINUE
      A2A(161)=FLO(19)
C
C**   IF IOP EQUAL ZERO READ NAMELIST FLTCON
C**   IF IOP EQUAL ONE WRITE NAMELIST FLTCON
C
      IF(IOP .EQ. 0)
     1 CALL NAMER(KAND,9,NLNAME,6,FLTCON,81,LEN2,18,LDM2,A2A,161,
     2            LOC2,EOF)
      IF(IOP .EQ. 1)
     1 CALL NAMEW(KAND,6,NLNAME,6,FLTCON,81,LEN2,18,LDM2,A2A,161,LOC2)
C
      DO 1010 I=1,160
         A2(I)=A2A(I)
 1010 CONTINUE
      FLO(19)=A2A(161)
C
      RETURN
      END
C ===== xnam10.f =====
      SUBROUTINE XNAM10(IOP)
C
C***  READ OR WRITE NAMELIST VTSCHR
C
      COMMON /VTI/ A9(162)
      COMMON /IBV/ A9B(363)
      COMMON /CONSNT/ PI,DEG,UNUSED,RAD,KAND
C
      INTEGER SCHR
      LOGICAL EOF
C
      DIMENSION LENVTS(34),LDMVTS(34),SCHR(160),LOCVTS(34),VTS(314)
      DIMENSION NLNAME(6)
      DATA NLNAME / 4HV   ,4HT   ,4HS   ,4HC   ,4HH   ,4HR   /
      DATA LENVTS / 4,6,4,3,6,6,5,6,3,5,4,4,4,5,3,4,5,6,5,5,4,6,3*3,
     1            6,4,5,6,6,4,5,6,6 /
      DATA LDMVTS / 5*1,20,20,-1,16*1,20,1,1,5*50,1,1 /
      DATA LOCVTS / 16,17,18,19,20,21,41,64,61,66,67,62,63,65,61,
     1            67,70,71,69,69,92,68,155,155,72,314,163,
     2            164,214,264,214,264,10,10 /
      DATA SCHR /     4HT   ,4HO   ,4HV   ,4HC   ,4HD   ,4HE   ,
     1 4HL   ,4HT   ,4HA   ,4HY   ,4HX   ,4HO   ,4HV   ,4HC   ,
     2 4HC   ,4HL   ,4HI   ,4HA   ,4HL   ,4HP   ,4HH   ,4HA   ,
     3 4HI   ,4HC   ,4HL   ,4HA   ,4HL   ,4HP   ,4HA   ,4HC   ,
     4 4HL   ,4HM   ,4HA   ,4HX   ,4HC   ,4HA   ,4HM   ,4HB   ,
     5 4HE   ,4HR   ,4HC   ,4HM   ,4H0   ,4HX   ,4HO   ,4HV   ,
     6 4HC   ,4HO   ,4HC   ,4HM   ,4H0   ,4HT   ,4HL   ,4HE   ,
     7 4HR   ,4HI   ,4HL   ,4HE   ,4HR   ,4HO   ,4HT   ,4HO   ,
     8 4HV   ,4HC   ,4HO   ,4HC   ,4HM   ,4HO   ,4HC   ,4HM   ,
     9 4HO   ,4HT   ,4HT   ,4HC   ,4HE   ,4HF   ,4HF   ,4HK   ,
     A 4HS   ,4HH   ,4HA   ,4HR   ,4HP   ,4HC   ,4HL   ,4HA   ,
     B 4HM   ,4H0   ,4HC   ,4HL   ,4HA   ,4HM   ,4HO   ,4HA   ,
     C 4HR   ,4HC   ,4HL   ,4HC   ,4HL   ,4HM   ,4HA   ,4HX   ,
     D 4HL   ,4HY   ,4HC   ,4HM   ,4HC   ,4HL   ,4HD   ,4HX   ,
     E 4HA   ,4HC   ,4HT   ,4HY   ,4HP   ,4HE   ,4HI   ,4HN   ,
     F 4HN   ,4HP   ,4HT   ,4HS   ,4HX   ,4HC   ,4HO   ,4HR   ,
     G 4HD   ,4HY   ,4HU   ,4HP   ,4HP   ,4HE   ,4HR   ,4HY   ,4HL   ,
     H 4HO   ,4HW   ,4HE   ,4HR   ,4HM   ,4HE   ,4HA   ,4HN   ,
     I 4HT   ,4HH   ,4HI   ,4HC   ,4HK   ,4HA   ,4HL   ,4HP   ,
     J 4HH   ,4HA   ,4HO   ,4HA   ,4HL   ,4HP   ,4HH   ,4HA   ,4H0   /
C
      DO 1000 I=1,162
         VTS(I)=A9(I)
 1000 CONTINUE
      VTS(314)=A9B(132)
      DO 1010 I=163,313
         VTS(I)=A9B(I+50)
 1010 CONTINUE
C
C**   IOP EQUAL ZERO READ NAMELIST VTSCHR
C**   IOP EQUAL ONE WRITE NAMELIST VTSCHR
C
      IF(IOP .EQ. 0)
     1 CALL NAMER(KAND,9,NLNAME,6,SCHR,160,LENVTS,34,LDMVTS,VTS,314,
     2            LOCVTS,EOF)
      IF(IOP .EQ. 1)
     1 CALL NAMEW(KAND,6,NLNAME,6,SCHR,160,LENVTS,34,LDMVTS,VTS,314,
     2            LOCVTS)
C
C     PUT THE VARIABLES IN THE APPROPRIATE COMMON BLOCK
C
      DO 1020 I=1,162
         IF(I .EQ. 155)GO TO 1020
         A9(I)=VTS(I)
 1020 CONTINUE
      A9B(132)=VTS(314)
      DO 1030 I=163,313
         A9B(I+50)=VTS(I)
 1030 CONTINUE
C
      RETURN
      END
